void draw_car_field(void);
void draw_car_field__t6502(void);

/* Defined with the object-plotter fixtures further down; draw_car_field reaches the same plotter
   through draw_track_object, so it needs the same legal-table setup and the same cell names. */
static int force_shape_tables(uint8_t* pre);
#define DCF_HORIZ_HALF     0x62FC
#define DCF_HORIZ_EXTENT   0x001F
#define DCF_LINE_CEILING   0x62FD

/* ==========================================================================
   $66DF  draw_car_field — THE OTHER-CAR DRAW PASS                (twin #180)
   --------------------------------------------------------------------------
   Fully live (A/X/Y and all four flags): the shim publishes the last draw's exit registers, and
   Y/V/C thread from one draw_track_object to the next inside the routine, so a dropped thread is
   a real defect and the fixture must be able to see it.

   Three structural pins:

     - car_order is a permutation of the twenty slots, and car_behind is a position in 0..19.  The
       walk steps car_index_inc from zp_scratch_index until it lands on car_behind, so any
       position in range terminates it; a car_behind of $FF would spin forever, and the game never
       produces one (find_player_neighbours writes a ring position).
     - car_heading ($0A/$0B) is the camera the twin marshals in ONCE instead of per car.  It is
       randomised, not pinned — that is the thing being compared.
     - The three object groups all have to DRAW, not just be skipped.  draw_track_object rejects a
       slot whose car_flags_shape bit 7 is set and one whose bearing leaves the visibility window,
       so half the cases clear bit 7 across the board and park every object's bearing high byte at
       $00 with the camera at 0 — which puts the whole field in view and makes the paint ORDER
       itself observable in the frame buffer.
   ========================================================================== */
static int test_draw_car_field(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("draw_car_field");
    if (!want("draw_car_field")) return 0;

    setenv("REVS_SMC_CONTINUE", "1", 1);

    int cases = 3000 * scale;
    int sawDraw = 0, sawSkip = 0, sawNegCursor = 0, sawSmcTrap = 0, closing = 0;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                                    /* not a SED site (static-map §Decimal mode) */
        c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
        c.N = xs() & 1u; c.Z = xs() & 1u; c.V = xs() & 1u; c.C = xs() & 1u;

        { uint8_t ord[20]; int i;
          for (i = 0; i < 20; i++) ord[i] = (uint8_t)i;
          for (i = 19; i > 0; i--) { int j = (int)(xs() % (unsigned)(i + 1));
                                     uint8_t tmp = ord[i]; ord[i] = ord[j]; ord[j] = tmp; }
          for (i = 0; i < 20; i++) pre[0x013Cu + i] = ord[i]; }

        pre[0x0003u] = (uint8_t)(xs() % 20u);       /* zp_scratch_index — the walk's start */
        pre[0x004Du] = (uint8_t)(xs() % 20u);       /* car_behind — and its stop */

        /* $1FE9 is plot_object's per-circuit SMC extent, reached through draw_track_object.
           Sweep both real arms (Silverstone's `LDX horizon_extent` and an expansion circuit's
           `LDX #imm`) and, one case in ten, the trap-and-return that an unrecognised opcode
           takes — exactly as test_plot_object does. */
        if (xs() % 10) {
            if (xs() & 1u) pre[0x1FE9u] = 0xA6u;
            else         { pre[0x1FE9u] = 0xA2u; pre[0x1FEAu] = (uint8_t)(xs() % 0x50u); }
        } else { pre[0x1FE9u] = 0x00u; sawSmcTrap = 1; }

        /* One case in eight starts the cursor NEGATIVE, which is the only way $66E3's
           fall-through draw is reached.  The game never does it (a ring position is 0..19) but
           the branch is in the routine, so the fixture covers it. */
        if ((t & 7) == 3) { pre[0x0003u] = (uint8_t)(0x80u | (xs() % 20u)); sawNegCursor = 1; }

        if (xs() & 1u) {                            /* everything in view, everything drawable */
            int i;
            closing += force_shape_tables(pre) ? 1 : 0;        /* legal, terminating edge walks */
            pre[0x000Au] = 0x00u; pre[0x000Bu] = 0x00u;        /* camera heading at 0 */
            pre[DCF_HORIZ_HALF]   = (uint8_t)(xs() % 0x80u);
            pre[DCF_HORIZ_EXTENT] = (uint8_t)(xs() % 0x50u);
            pre[DCF_LINE_CEILING] = (uint8_t)(xs() % 0x50u);
            for (i = 0; i < 0x17; i++) {
                /* bit 7 clear = a real shape.  ⚠⚠ SHAPE 9 IS EXCLUDED, and not for convenience:
                   plot_object re-enters below its own clamp, so a plot_shape of exactly 9 keeps
                   rewriting 9 into object_shape_clamped and $2021's `CMP #$09` never stops
                   agreeing — BOTH models hang, identically.  It is unreachable in the game (9 is
                   the "stand-in drawn" marker, never a shape); test_plot_object excludes it for
                   the same reason, and this fixture hung on it before it did. */
                { unsigned pick = xs() % 15u;
                  pre[0x018Cu + i] = (uint8_t)(pick < 9u ? pick : pick + 1u); }
                pre[0x0380u + i] = (uint8_t)xs();              /* bearing lo */
                pre[0x0398u + i] = 0x00u;                      /*         hi -> inside the window */
                pre[0x03B0u + i] = (uint8_t)(xs() % 0x50u);    /* object scan line */
                pre[0x03C8u + i] = (uint8_t)(xs() % 0x80u);    /* projected width */
            }
            sawDraw = 1;
        } else {
            int i;                                  /* ...and the all-rejected control */
            for (i = 0; i < 0x17; i++) pre[0x018Cu + i] |= 0x80u;
            sawSkip = 1;
        }

        fail += diff_run("draw_car_field", pre, c, draw_car_field,
                         draw_car_field__t6502,
                         LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS, t, &printed);
    }
    if (!sawDraw || !sawSkip || !sawNegCursor || !sawSmcTrap) {
        printf("  draw_car_field: VACUOUS (draw=%d skip=%d negCursor=%d smcTrap=%d)\n",
               sawDraw, sawSkip, sawNegCursor, sawSmcTrap);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  (%d closing-arm setups)\n",
           "draw_car_field", cases, fail, closing);
    return fail;
}

/* ==========================================================================
   $2637 move_and_draw_cars — THE OTHER-CAR PASS  (twin #179)
   --------------------------------------------------------------------------
   Result-only (LIVE_NONE): the body's next call reloads every register.

   Three structural pins, all of them the game's own invariants rather than fixture convenience:

     - car_order is a PERMUTATION of the twenty slots and player_car is one of them.  That is what
       sort_cars_by_key produces, and it is what makes the routine terminate: find_player_neighbours
       leaves the player's ring position in zp_scratch_index, and FUN_66df walks the ring forward
       from there until it reaches car_behind.  With player_car missing from car_order the slot is
       $FF and that walk never meets its stop.
     - place_car_world_coords' per-circuit SMC seam ($298D) is steered to the unhandled-opcode
       early return, exactly as test_stage_nearby_car does, so the six staging calls terminate fast.
     - lap_length is $7FFF so car_gap_tail's near/wrapped split is decided by the distances the
       fixture sets rather than by a random 16-bit modulus.

   Coverage: both session arms (the race pass and the practice DELAY loop), both track directions
   (which decides whether the ring is walked forward or backward), and a quarter of the cases with
   the six staged cars pulled deliberately close to the reference car so the staging path — not
   just the reject path — runs.
   ========================================================================== */
static int test_move_and_draw_cars(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("move_and_draw_cars");
    if (!want("move_and_draw_cars")) return 0;

    setenv("REVS_SMC_CONTINUE", "1", 1);

    int cases = 600 * scale;
    int sawRace = 0, sawPractice = 0, sawFwd = 0, sawBack = 0, sawNear = 0, sawDraw = 0, sawDraw2 = 0;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                                    /* not a SED site (static-map §Decimal mode) */
        c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();

        /* car_order = a random permutation of the twenty slots; the player is one of them. */
        { uint8_t ord[20]; int i;
          for (i = 0; i < 20; i++) ord[i] = (uint8_t)i;
          for (i = 19; i > 0; i--) { int j = (int)(xs() % (unsigned)(i + 1));
                                     uint8_t tmp = ord[i]; ord[i] = ord[j]; ord[j] = tmp; }
          for (i = 0; i < 20; i++) pre[0x013Cu + i] = ord[i]; }
        pre[0x006Fu] = (uint8_t)(xs() % 20u);       /* player_car */

        pre[0x0003u] = (uint8_t)(xs() % 20u);       /* zp_scratch_index: check_car_pair's start
                                                       position, which it walks BACKWARD — the
                                                       routine only overwrites it later, at $2652 */
        /* place_car_world_coords' per-circuit SMC seam.  Most cases steer it to the
           unhandled-opcode early return (as test_stage_nearby_car does) so the six staging calls
           are cheap; a fifth run Silverstone's REAL instruction there ($29 $1F, AND #$1F) so the
           staging path completes, clears car_flags_shape bit 7, and FUN_66df's draw queue is
           actually reachable — without those, skipping the draw entirely is undetectable. */
        if ((t % 5) == 1) { pre[0x298Du] = 0x29u; pre[0x298Eu] = 0x1Fu; sawDraw = 1; }
        else                pre[0x298Du] = 0x00u;
        /* check_car_pair's own per-circuit SMC seam ($2771): a CMP most of the time, the
           trap-and-return opcode occasionally, exactly as test_check_car_pair sweeps it. */
        pre[0x2771u] = (t % 7 == 0) ? 0x00u : 0xC9u;
        pre[0x2772u] = (uint8_t)xs();
        pre[0x59FCu] = 0xFFu; pre[0x59FDu] = 0x7Fu; /* lap_length = $7FFF */

        if (xs() & 1u) { pre[0x0025u] |= 0x80u; sawFwd = 1; }   /* track_direction */
        else           { pre[0x0025u] &= 0x7Fu; sawBack = 1; }

        /* ⭐ Reaching the DRAW.  draw_track_object skips any slot whose car_flags_shape bit 7 is
           set, and this routine clears that bit for exactly one slot — the car AHEAD's — before
           re-rejecting everything else.  So a draw happens only when the six-position ring walk
           does NOT visit the car ahead and that slot's object is in view range.  Set both up
           deliberately in a fifth of the cases: walk BACKWARD (away from the car ahead), park the
           view origin at 0 and put the slot's object coordinates inside the +/-$2000 window.
           Without this, deleting the whole draw queue is invisible. */
        if ((t % 5) == 2) {
            int playerSlot = 0, i;
            for (i = 0; i < 20; i++) if (pre[0x013Cu + i] == pre[0x006Fu]) playerSlot = i;
            uint8_t aheadSlot = pre[0x013Cu + ((playerSlot + 1) % 20)];
            pre[0x0025u] &= 0x7Fu;                  /* backward: the walk misses the car ahead */
            pre[0x000Au] = 0x00u; pre[0x000Bu] = 0x00u;        /* view origin at 0 */
            pre[0x0380u + aheadSlot] = (uint8_t)xs();          /* object x, lo */
            pre[0x0398u + aheadSlot] = 0x00u;                  /*           hi -> in range */
            pre[0x018Cu + aheadSlot] = (uint8_t)(xs() & 0x0Fu);/* bit7 clear, a real shape index */
            sawDraw2 = 1;
        }

        if (xs() & 1u) { pre[0x5F3Bu] &= 0x7Fu; sawRace = 1; }  /* qualify_minutes: the race pass */
        else           { pre[0x5F3Bu] |= 0x80u; sawPractice = 1; }

        if ((t & 3) == 0) {
            /* Pull every car within staging range of the reference car $17, so the six calls
               take the staged path rather than all rejecting. */
            uint16_t base = 0x4000u; int i;
            pre[0x08D0u + 0x17u] = (uint8_t)base; pre[0x08E8u + 0x17u] = (uint8_t)(base >> 8);
            for (i = 0; i < 20; i++) {
                uint16_t d = (uint16_t)(base - (xs() % 0x20u));
                pre[0x08D0u + i] = (uint8_t)d; pre[0x08E8u + i] = (uint8_t)(d >> 8);
            }
            sawNear = 1;
        }

        fail += diff_run("move_and_draw_cars", pre, c, move_and_draw_cars,
                         move_and_draw_cars__t6502, LIVE_NONE, t, &printed);
    }

    if (!sawRace || !sawPractice || !sawFwd || !sawBack || !sawNear || !sawDraw || !sawDraw2) {
        printf("[VACUOUS] move_and_draw_cars: race %d practice %d fwd %d back %d near %d draw %d inview %d\n",
               sawRace, sawPractice, sawFwd, sawBack, sawNear, sawDraw, sawDraw2);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only\n",
           "move_and_draw_cars", cases, fail);
    return fail;
}

void reject_all_object_slots(void);
void reject_all_object_slots__t6502(void);

/* ---------------------------------------------------------------------------
   $261F  reject_all_object_slots  (twin #178)
   ---------------------------------------------------------------------------
   23 slots, no input but the flags bytes themselves, no register argument.  Random memory IS the
   domain here, so the fixture only has to prove the extent: a defect that walks 22 slots or 24,
   or that sets the wrong bit, changes mem[].  Exit is dead at both callers (LIVE_NONE), but the
   A/X residue the shim publishes is still compared through the cpu diff.
   --------------------------------------------------------------------------- */
static int test_reject_all_object_slots(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    register_fixture("reject_all_object_slots");
    if (!want("reject_all_object_slots")) return 0;

    for (t = 0; t < 400 * scale; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
        /* half the cases start from all-clear flags, so a wrong bit shows as plainly as a
           wrong extent */
        if (t & 1) { unsigned k; for (k = 0; k < 0x18u; k++) pre[0x018Cu + k] = 0x00u; }
        fail += diff_run("reject_all_object_slots", pre, c, reject_all_object_slots,
                         reject_all_object_slots__t6502, LIVE_NONE, t, &printed);
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only\n",
           "reject_all_object_slots", 400 * scale, fail);
    return fail;
}

void update_lap_timers(void);
void update_lap_timers__t6502(void);

/* ---------------------------------------------------------------------------
   $0FFE  update_lap_timers  (twin #177)
   ---------------------------------------------------------------------------
   Both session arms, and inside each the three lap-flag ways on and the four qualifying-deadline
   outcomes.  Three things have to be authored rather than randomised or the routine never
   returns / never reaches its own code:

     - the TEXT SCRIPTS.  print_message_pair, print_message_upper_row and the readout printers all
       end in text_script_interp, which is a byte-stream interpreter that RECURSES on a $C8+
       command.  Random bytes there are an unbounded recursion, so every script index points at
       one authored leaf that terminates ($FF) and carries no recurse command — the same
       construction test_irq1v_release uses, for the same reason.
     - player_car and car_behind must index inside the 20-driver arrays.
     - race_lap_total and car_lap_count are pinned into 0..$13 so position_to_bcd sees the domain
       it converts (it is a 0..19 -> BCD routine) rather than a random byte.

   D = 0 on entry: race_main_loop's body runs this with decimal clear, and the two SED users it
   reaches (add_frame_time, update_position_display) bracket their own SED/CLD
   (docs/static-map.md §Decimal mode).  Exit is dead at the only caller, so LIVE_NONE — but the
   $1017 PHP's stack residue and the hardware-write log are both in the diff.
   --------------------------------------------------------------------------- */
static int test_update_lap_timers(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    const unsigned LEAF = 0x0D00u;          /* the one terminating script every index points at */
    int cases = 4000 * scale;
    int sawRace = 0, sawPractice = 0, sawCredit = 0, sawFlag = 0;
    int sawCountdown = 0, sawNewLap = 0, sawQuiet = 0;
    int sawEqual = 0, sawPast = 0, sawEarly = 0, sawNoLimit = 0;

    register_fixture("update_lap_timers");
    if (!want("update_lap_timers")) return 0;

    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                              /* see the header */
        c.S = 0xFFu;
        c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
        c.I = (uint8_t)(xs() & 1u);           /* ambient — the PHP composes it */
        c.V = (uint8_t)(xs() & 1u);
        c.C = (uint8_t)(xs() & 1u);

        /* ---- the text scripts: every index at one authored terminating leaf ---- */
        { unsigned k; for (k = 0; k <= 0x40u; k++) {
            pre[0x3AD0u + k] = (uint8_t)(LEAF & 0xFFu);
            pre[0x3B50u + k] = (uint8_t)(LEAF >> 8);
        } }
        { unsigned p = LEAF;
          pre[p++] = (uint8_t)(0x41u + (xs() % 0x20u));   /* one printable, then stop */
          pre[p++] = (uint8_t)(0xA1u + (xs() % 7u));
          pre[p++] = 0xFFu; }
        { int r; for (r = 0; r < 8; r++) pre[0x3B06 + r] = 0x58u; }   /* rows -> screen RAM */
        pre[0x0064u] = (uint8_t)((xs() & 1u) ? 0x80u : 0x00u);        /* text_out_via_mos: both arms */
        pre[0x62CDu] &= 0x3Fu;                                        /* vdu_char_row 0..$3F */
        pre[0x62CCu] = (uint8_t)(xs() & 0x1Fu);                       /* vdu_char_column */
        pre[0x0070u] = 0x00u; pre[0x0071u] = 0x7Eu;                   /* plot_ptr in screen RAM */

        /* ---- the indices ---- */
        pre[0x006Fu] = (uint8_t)(xs() % 0x14u);       /* player_car */
        pre[0x004Du] = (uint8_t)(xs() % 0x14u);       /* car_behind */
        pre[0x005Bu] = (uint8_t)(xs() % 0x14u);       /* car_ahead */
        /* laps done / laps in the session.  Three quarters of the cases use the real 0..19
           domain; the rest span 0..99, because inside 0..19 the laps-left byte is either
           0..$13 or $ED..$FF and its bits 6 and 7 are then always EQUAL — which makes the
           $1017 PHP's N bit unfalsifiable (a sabotage taking N from bit 6 passed until the
           wider quarter was added). */
        { unsigned span = (xs() % 4u) ? 0x14u : 0x64u;
          pre[0x04B4u + pre[0x006Fu]] = (uint8_t)(xs() % span);   /* car_lap_count[player] */
          pre[0x006Eu] = (uint8_t)(xs() % span); }                /* race_lap_total */

        /* ---- the session arm and the lap flag ($1000, $1004, $1039/$103B) ---- */
        if (xs() & 1u) { pre[0x006Cu] |= 0x80u; sawRace = 1; }
        else           { pre[0x006Cu] &= 0x7Fu; sawPractice = 1; }
        { uint32_t r = xs() % 3u;
          pre[0x0066u] = (uint8_t)(r == 0u ? 0x40u : r == 1u ? 0x80u : 0x00u);
          if (pre[0x006Cu] & 0x80u) { if (r == 1u) sawCredit = 1; else sawFlag = 1; }
          else { if (r == 0u) sawCountdown = 1; else if (r == 1u) sawNewLap = 1; else sawQuiet = 1; } }
        pre[0x000Fu] = (uint8_t)((xs() & 1u) ? 0x00u : (uint8_t)xs());  /* session_end_countdown */
        pre[0x62EFu] = (uint8_t)((xs() % 4u) ? (uint8_t)xs() : 0x00u);  /* lap_time_show_timer */

        /* ---- the qualifying deadline ($1072, $1077, $1079) ---- */
        { uint8_t elapsed = (uint8_t)(xs() % 0x60u);
          pre[0x06E4u] = elapsed;                        /* race_clock_hi[0], BCD minutes */
          switch (xs() % 4u) {
            case 0: pre[0x5F3Bu] = 0x80u; sawNoLimit = 1; break;             /* qualify_minutes */
            case 1: pre[0x5F3Bu] = elapsed; sawEqual = 1; break;
            case 2: pre[0x5F3Bu] = (uint8_t)(elapsed > 0u ? elapsed - 1u : 0u);
                    if (elapsed > 0u) sawPast = 1; break;
            default: pre[0x5F3Bu] = (uint8_t)((elapsed + 1u) & 0x7Fu); sawEarly = 1; break;
          } }
        pre[0x0065u] = (uint8_t)((xs() & 1u) ? 0x00u : (uint8_t)(xs() | 0x40u)); /* qualify_msg_flags */

        /* ---- add_frame_time's own inputs: BCD clock 1 and the tick divider ---- */
        pre[0x06B4u + 1] = (uint8_t)(xs() % 0x60u);
        pre[0x06CCu + 1] = (uint8_t)(xs() % 0x60u);
        pre[0x06E4u + 1] = (uint8_t)(xs() % 0x60u);
        pre[0x5A19u] = (uint8_t)(1u + (xs() % 0x30u));   /* time_tick_period, non-zero */
        pre[0x0046u] = (uint8_t)(xs() % 0x31u);          /* time_tick_countdown */

        fail += diff_run("update_lap_timers", pre, c, update_lap_timers,
                         update_lap_timers__t6502, LIVE_NONE, t, &printed);
    }

    if (!sawRace || !sawPractice || !sawCredit || !sawFlag
        || !sawCountdown || !sawNewLap || !sawQuiet) {
        printf("[VACUOUS] update_lap_timers: arms race %d practice %d credit %d flag %d "
               "countdown %d newlap %d quiet %d\n", sawRace, sawPractice, sawCredit, sawFlag,
               sawCountdown, sawNewLap, sawQuiet);
        fail++;
    }
    if (!sawEqual || !sawPast || !sawEarly || !sawNoLimit) {
        printf("[VACUOUS] update_lap_timers: deadline equal %d past %d early %d nolimit %d\n",
               sawEqual, sawPast, sawEarly, sawNoLimit);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only "
           "(the $1017 PHP residue and the hw-write log are in the diff)\n",
           "update_lap_timers", cases, fail);
    return fail;
}

/* ---------------------------------------------------------------------------
   $4F23 irq1v_release / $4F39 enter_mos_text_mode — twin #175
   ---------------------------------------------------------------------------
   Result-only (LIVE_NONE) for both: each caller does `JSR / RTS` — $17BF in the transliterated
   race body and race_main_loop_core's last statement — so no exit register or flag is read.
   ⭐ The interesting half of the differential is NOT mem[]: irq1v_release's three stores are two
   vector-page bytes and one User VIA register, and the VIA write is invisible to a mem[] diff.
   REVS_HW_TRACE's hardware-write log is what compares it, as a SEQUENCE, and the $FE6E write has
   to land in the right place in that sequence relative to sound_stop_all's OSBYTEs.

   ⚠ Script $2E has to be BUILT.  fill_random leaves text_script_ptr_lo/hi random, which would
   send the interpreter off a wild pointer and recurse away; the pins below are the same ones the
   text_script_interp fixture derived (see its header for why every index must stay <= $35 and
   why the bitmap arm needs plot_ptr parked near the top of screen RAM).
   --------------------------------------------------------------------------- */
static int test_irq1v_release(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); }
      list[2] = {
        { "irq1v_release",       irq1v_release,       irq1v_release__t6502       },
        { "enter_mos_text_mode", enter_mos_text_mode, enter_mos_text_mode__t6502 },
      };
    const unsigned TOP  = 0x0C00u;               /* script $2E's bytes */
    const unsigned LEAF = 0x0D00u;               /* the one leaf every sub-script index points at */
    const uint8_t  SCRIPT_IDX = 0x2Eu;           /* $4F3D LDX #$2E — hard-coded, not an argument */

    for (i = 0; i < 2; i++) register_fixture(list[i].name);
    for (i = 0; i < 2; i++) {
        int cases = 2000 * scale;
        int subFail = 0, sawIdle = 0, sawPlaying = 0, sawBmp = 0, sawMos = 0;
        if (!want(list[i].name)) continue;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.D = 0;                              /* neither is a SED site (static-map §Decimal) */
            c.S = 0xFFu;
            c.Y = (uint8_t)xs();                  /* the ambient Y sound_stop_all's OSBYTEs carry */
            c.X = (uint8_t)xs();                  /* dead: $4F3D reloads it with the script index */
            c.A = (uint8_t)xs();

            /* IRQ1V as the game left it, plus the bytes it is about to restore. */
            pre[0x0204u] = 0x5Cu; pre[0x0205u] = 0x4Eu;    /* irq1v_band_schedule, still claimed */
            pre[0x4F1Du] = (uint8_t)xs();                  /* saved_irq1v lo */
            pre[0x4F1Eu] = (uint8_t)xs();                  /* ...and hi */

            /* sound_chan_state: sound_stop_all skips a channel already marked idle, so force the
               idle arm on half the cases rather than waiting for a random zero byte. */
            { int ch; for (ch = 0; ch < 4; ch++) {
                if (xs() & 1) { pre[0x62BDu + ch] = 0; sawIdle = 1; }
                else          { pre[0x62BDu + ch] = 0x07u; sawPlaying = 1; }
            } }

            /* ---- script $2E, built so it terminates (see the header) ---- */
            { int r; for (r = 0; r < 8; r++) pre[0x3B06 + r] = 0x58u; }   /* rows -> screen RAM */
            pre[0x62CDu] &= 0x3Fu;                        /* vdu_char_row 0..7 */
            pre[0x62CCu] = (uint8_t)(xs() & 0x1Fu);       /* vdu_char_column */
            pre[0x0070u] = 0x00u; pre[0x0071u] = 0x7Eu;   /* plot_ptr near the top of screen RAM */
            { unsigned k; for (k = 0; k <= 0x34u; k++) {
                pre[0x3AD0u + k] = (uint8_t)(LEAF & 0xFFu);
                pre[0x3B50u + k] = (uint8_t)(LEAF >> 8);
            } }
            pre[0x3AD0u + SCRIPT_IDX] = (uint8_t)(TOP & 0xFFu);
            pre[0x3B50u + SCRIPT_IDX] = (uint8_t)(TOP >> 8);
            { int r; for (r = 0; r < 8; r++) pre[0x3B06 + r] = 0x58u; }   /* re-assert after the fill */
            { unsigned p = LEAF;
              pre[p++] = (uint8_t)(0x41u + (xs() % 0x20u));
              pre[p++] = (uint8_t)(0xA1u + (xs() % 7u));
              pre[p++] = 0xFFu; }
            /* ⚠ Every case must set text_out_via_mos itself: enter_mos_text_mode's whole job is
               to WRITE it $80, so a random start value would leave the arm it picks up to chance
               on the second (nested) script only.  Every 8th case takes the bitmap arm. */
            { unsigned p = TOP;
              if ((t % 8u) == 0u) {                       /* bitmap arm — short, non-recursive */
                  pre[0x0064u] = 0x00u; sawBmp = 1;
                  pre[p++] = (uint8_t)(0x41u + (xs() % 0x20u));
                  pre[p++] = 0xA2u;
                  pre[p++] = 0xFFu;
              } else {                                    /* OSWRCH arm — recursion is safe here */
                  pre[0x0064u] = 0x80u; sawMos = 1;
                  pre[p++] = (uint8_t)(0x20u + (xs() % 0x60u));
                  /* ⚠ sub must never be $2E — that is THIS script, and a recurse into it is
                     unbounded (it cost a stack-overflow segfault with no output at all before the
                     exclusion; the text_script_interp fixture reserves its own top index the same
                     way).  Legal subs are 0..$34, so shift $2E onto the spare $34. */
                  { uint8_t sub = (uint8_t)(xs() % 0x34u);      /* 0..$33 */
                    if (sub == SCRIPT_IDX) sub = 0x34u;
                    pre[p++] = (uint8_t)(0xC8u + sub); }
                  pre[p++] = (uint8_t)(0xA1u + (xs() % 7u));
                  pre[p++] = 0xFFu;
              } }

            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                LIVE_NONE, t, &printed);
        }
        fail += subFail;
        if (i == 0 && (!sawIdle || !sawPlaying)) {
            printf("[VACUOUS] irq1v_release: sound_stop_all arms (idle %d playing %d)\n",
                   sawIdle, sawPlaying);
            fail++;
        }
        if (!sawBmp || !sawMos) {
            printf("[VACUOUS] %s: only one output arm ran (bitmap %d, OSWRCH %d)\n",
                   list[i].name, sawBmp, sawMos);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  result-only%s\n",
               list[i].name, cases, subFail,
               i == 0 ? " (VIA + vector writes compared through the hw-write log)" : "");
    }
    return fail;
}

void update_horizon_band(void);
void update_horizon_band__t6502(void);

static int test_update_horizon_band(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("update_horizon_band");
    if (!want("update_horizon_band")) return 0;

    /* Result-only (LIVE_NONE): exit A/X/Y/flags are dead at both callers (the race body flows
       straight to the 22nd call).  Every observable effect is in mem[] and reproduced byte-exact
       — math_hi ($75, the campaign's target: its 6502 exit value is still written so the cell
       stays pinned until relocation), band1_duration_lo/hi, and, on the completed path, the P
       byte the PHP at $4F5B leaves as stack residue at $0100+S ($01FF with S=0xFF).  That residue
       is dead scratch (the PLP at $4F63 pops it right back and nothing reads $01FF; determinism
       skips the $01B8..$01FF window), so it is the one address ignored here. */
    static const uint16_t ig[1] = { 0x01FFu };
    unsigned mask = LIVE_NONE;

    /* The two per-circuit SMC seams ($4F54/$4F58) are real code in BOTH models: an unrecognised
       opcode traps through platform_smc_unhandled and returns, and that unwind has to match.  So
       it is TESTED, not avoided — which means the trap must count rather than abort, and the count
       is asserted below so the trap arm cannot pass vacuously. */
    setenv("REVS_SMC_CONTINUE", "1", 1);
    g_smcUnhandled = 0;

    int cases = 4000 * scale;
    set_ignore(ig, 1);
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();                       /* S=0xFF -> the PHP residue lands at $01FF */
        fill_random(pre);
        c.D = 0;                                      /* not a SED site (static-map §Decimal mode) */

        /* horizon_extent ($1F): the 0..79 scan-line reach.  Sweep the whole byte so both the
           negative-difference floor path and the positive per-circuit ceiling paths are hit. */
        pre[0x001F] = (uint8_t)xs();
        if (t % 3 == 0) pre[0x001F] = (uint8_t)(0x40u + (xs() % 0x40u));  /* force $3C-ext negative */

        /* The two SMC seams: unpatched Silverstone opcodes for most cases (so the completed
           wide-value path runs), randomised ~1/16 each to exercise the trap-and-return arms. */
        pre[0x4F54] = ((t & 15) == 3) ? (uint8_t)xs() : 0xC9u;
        pre[0x4F58] = ((t & 15) == 7) ? (uint8_t)xs() : 0xA9u;
        pre[0x4F55] = (uint8_t)xs();                  /* per-circuit CMP ceiling */
        pre[0x4F59] = (uint8_t)xs();                  /* per-circuit clamp value */

        fail += diff_run("update_horizon_band", pre, c, update_horizon_band,
                         update_horizon_band__t6502, mask, t, &printed);
    }
    set_ignore(0, 0);
    unsetenv("REVS_SMC_CONTINUE");

    if (g_smcUnhandled == 0) {
        printf("[VACUOUS] update_horizon_band: 0 SMC traps — the trap arms never ran, so the "
               "per-circuit dispatch was not tested\n");
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only, %lu SMC traps ($01FF residue ignored)\n",
           "update_horizon_band", cases, fail, g_smcUnhandled);
    return fail;
}

void draw_corner_markers(void);
void draw_corner_markers__t6502(void);

/* ==========================================================================
   $1B12 draw_corner_markers — THE CORNER-MARKER CONSUMER  (twin #151)
   --------------------------------------------------------------------------
   Draws the up-to-three markers build_track_geometry queued, then zeroes the list.  Like the
   draw_track_object fixture it drives the object plotter (plot_object) through a randomised
   pre-state, and the twin's job is to hand it the same argument block off the same cells — a
   wrong wide-value shows up as a mem[] avalanche once plot_object runs on it.

   ⭐ draw_corner_markers has NO self-modifying site of its own; the only trap arm reachable is
   plot_object's $1FE9, so — exactly as in test_body_drivers — the pre-state PLANTS it with
   Silverstone's own byte ($A6) so plot_object runs to completion in both models rather than
   trapping out with nothing to compare.  plot_shape is HARDCODED to 6 here, so plot_object's
   shape-9 outer-loop spin (the hazard the draw_track_object arm has to steer around) cannot
   arise.  plant_plotter_chains zeros the span-plotters' branch-offset tables so plot_shape_edges
   terminates.  Result-only: exit regs/flags are dead at the native caller (race_main_loop). */
static void plant_plotter_chains(uint8_t* pre);   /* defined with the geometry fixtures below */

static int marker_high_byte(const uint8_t* pre, unsigned y)
{
    uint8_t  idx   = pre[0x62B4u + y];                         /* marker_edge_index */
    unsigned off   = pre[0x62B7u + y] | (pre[0x62BAu + y] << 8);
    unsigned q     = (off << 1) & 0xFFFFu;
    unsigned edgeX = pre[0x5E40u + idx] | (pre[0x5E90u + idx] << 8);
    return (int)(((q + edgeX) >> 8) & 0xFFu);
}

static int test_draw_corner_markers(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("draw_corner_markers");
    if (!want("draw_corner_markers")) return 0;

    unsigned mask = LIVE_NONE;
    setenv("REVS_SMC_CONTINUE", "1", 1);
    unsigned long smc_before = g_smcUnhandled;

    int cases = 3000 * scale;
    int drawLow = 0, drawHigh = 0, skip = 0, patchSet = 0, patchClear = 0;
    int haveEmpty = 0, haveFull = 0, drawnMarkers = 0;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        plant_plotter_chains(pre);
        pre[0x1FE9] = 0xA6;                       /* plot_object's SMC seam — unpatched Silverstone */
        c.D = 0;                                  /* render path (static-map §Decimal mode) */

        /* 0..3 markers, so both the empty routine ($1B14 CPY takes the exit at once) and the
           full three-marker loop are covered; the per-marker data stays random. */
        uint8_t count = (uint8_t)(xs() % 4);
        pre[0x0057] = count;                      /* marker_count */
        if (count == 0) haveEmpty = 1; else haveFull = 1;

        for (unsigned y = 0; y < count; y++) {
            int phi = marker_high_byte(pre, y);
            if (phi < 0x18) { drawLow++; drawnMarkers++; }
            else if (phi >= 0xE8) { drawHigh++; drawnMarkers++; }
            else skip++;
            if (pre[0x6299u + y] & 0x20u) patchSet++; else patchClear++;
        }

        fail += diff_run("draw_corner_markers", pre, c, draw_corner_markers,
                         draw_corner_markers__t6502, mask, t, &printed);
    }
    unsetenv("REVS_SMC_CONTINUE");

    /* Non-vacuity: the wide-value branch must go all three ways, the colour patch both ways, the
       loop must run empty and full, and — the point of the whole fixture — the DRAW path (which
       actually consumes the wide value into plot_object) must be reached. */
    if (drawLow == 0 || drawHigh == 0 || skip == 0) {
        printf("[VACUOUS] draw_corner_markers: the range branch did not go all three ways "
               "(%d draw-low, %d draw-high, %d skip)\n", drawLow, drawHigh, skip);
        fail++;
    }
    if (patchSet == 0 || patchClear == 0) {
        printf("[VACUOUS] draw_corner_markers: the $38FE colour patch went only one way "
               "(%d set, %d clear)\n", patchSet, patchClear);
        fail++;
    }
    if (!haveEmpty || !haveFull) {
        printf("[VACUOUS] draw_corner_markers: the marker loop was never both empty and non-empty "
               "(%d empty seen, %d non-empty seen)\n", haveEmpty, haveFull);
        fail++;
    }
    if (drawnMarkers == 0) {
        printf("[VACUOUS] draw_corner_markers: not one marker was drawn — plot_object never ran\n");
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only  "
           "(%d drawn: %d low / %d high, %d skipped, %lu SMC traps)\n",
           "draw_corner_markers", cases, fail, drawnMarkers, drawLow, drawHigh, skip,
           g_smcUnhandled - smc_before);
    return fail;
}

void mirrors_update(void);
void mirrors_update__t6502(void);

/* mirrors_update's segment selector (shared_temp_76) — replica of the core, so the fixture can
   both steer a match and count which loop arm each case takes. */
static int mirror_heading(const uint8_t* pre)
{
    uint8_t slot = pre[0x013Cu + pre[0x005Bu]];       /* car_order[car_ahead] */
    uint8_t flag = pre[0x018Cu + slot];               /* car_flags_shape[slot] */
    if (flag & 0x80u) return flag;                    /* skip path: the raw flag byte */
    return (int)(((uint8_t)((uint8_t)(pre[0x0398u + slot] - pre[0x000Bu]) - 4u)) >> 3);
}

/* ==========================================================================
   $7B00 mirrors_update — THE WING-MIRROR UPDATE  (twin #152)
   --------------------------------------------------------------------------
   A math_lo ($74) reader-nativization: the mirror car block's half-height (object_width>>3) was
   6502 scratch in math_lo; the core lifts it to a C local and math_lo keeps its 6502 exit value
   (written ONLY on the drawable path).  Result-only (LIVE_NONE): exit regs/flags are dead at the
   sole native caller (race_main_loop $1739).  The per-segment loop and the mirror_draw_car calls
   stay in the shim; mirror_draw_car is a transliterated plotter shared by BOTH differential sides,
   so its writes CANCEL as long as the twin hands it the same A (value) and Y (segment) per call —
   a wrong bracket or a wrong segment set shows up as a mem[] avalanche once it plots.

   ⚠ mirror_draw_car's inner loop runs while Y >= shared_temp_77 (= $3EFA[seg]); a ZERO entry there
   spins forever (Y wraps $00->$FF, never < 0).  Random mem hits that 1/256 per drawn segment, so
   the fixture PLANTS $3EFA[0..5] nonzero, and points its plot_ptr source ($3B9E[seg]) at page $80
   so the plotter's own $138-stepped writes stay in $5900..$81FF and can never zero a $3EFA entry
   of a not-yet-processed segment. */
static int test_mirrors_update(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("mirrors_update");
    if (!want("mirrors_update")) return 0;

    unsigned mask = LIVE_NONE;
    int cases = 3000 * scale;
    int drawable = 0, skip = 0, matchArm = 0, eraseArm = 0, emptyArm = 0, drawCalls = 0;

    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                                   /* in-race, not a SED site */

        for (unsigned y = 0; y < 6; y++) {
            pre[0x3EFAu + y] = (uint8_t)((xs() % 0xFEu) + 1u);  /* 1..255 — terminate the plotter */
            pre[0x3B9Eu + y] = 0x80u;                            /* keep plotter writes off $3EFA */
        }

        /* Force the slot flag both ways so the drawable bracket and the erase-only skip both run. */
        uint8_t slot = pre[0x013Cu + pre[0x005Bu]];
        if (t & 1) pre[0x018Cu + slot] |= 0x80u;    /* skip: car behind / rejected */
        else       pre[0x018Cu + slot] &= 0x7Fu;    /* drawable */

        /* Steer a "match" (the draw arm inside the loop) for a quarter of cases. */
        int heading = mirror_heading(pre);
        if (t % 4 == 0) pre[0x3BA4u + (t % 6u)] = (uint8_t)heading;

        /* Count which arm each segment takes (pre-run; independent per index). */
        int drawableCase = !(pre[0x018Cu + slot] & 0x80u);
        if (drawableCase) drawable++; else skip++;
        for (unsigned y = 0; y < 6; y++) {
            if (heading == pre[0x3BA4u + y]) { matchArm++; drawCalls++; }
            else if (pre[0x6293u + y] != 0)  { eraseArm++; drawCalls++; }
            else                              emptyArm++;
        }

        fail += diff_run("mirrors_update", pre, c, mirrors_update,
                         mirrors_update__t6502, mask, t, &printed);
    }

    /* Non-vacuity: both entry paths, all three loop arms, and at least one real plotter call. */
    if (drawable == 0 || skip == 0) {
        printf("[VACUOUS] mirrors_update: the slot-flag branch went only one way "
               "(%d drawable, %d skip)\n", drawable, skip);
        fail++;
    }
    if (matchArm == 0 || eraseArm == 0 || emptyArm == 0) {
        printf("[VACUOUS] mirrors_update: the segment loop did not take all three arms "
               "(%d match, %d erase, %d empty)\n", matchArm, eraseArm, emptyArm);
        fail++;
    }
    if (drawCalls == 0) {
        printf("[VACUOUS] mirrors_update: mirror_draw_car was never called\n");
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only  "
           "(%d drawable / %d skip; arms %d match / %d erase / %d empty)\n",
           "mirrors_update", cases, fail, drawable, skip, matchArm, eraseArm, emptyArm);
    return fail;
}

void dial_needle_angle(void);
void dial_needle_angle__t6502(void);

/* dial_needle_angle's octant selector — a replica of the core, so the fixture can count which
   octants/mirror-bits each engine_revs value reaches. */
static void needle_octant(uint8_t engineRevs, uint8_t* octant, uint8_t* mirror, uint8_t* quadrant)
{
    uint8_t revs = engineRevs >= 0x1Eu ? engineRevs : 0x1Eu;
    unsigned v9 = (unsigned)revs + (revs >> 1);
    uint8_t angle0 = (uint8_t)((v9 >> 1) & 0xFFu);
    uint8_t rot = angle0 >= 0x4Cu ? (uint8_t)(angle0 - 0x4Cu) : (uint8_t)(angle0 + 0x4Cu);
    uint8_t q = (uint8_t)(rot / 0x26u), rem = (uint8_t)(rot % 0x26u);
    uint8_t m = rem >= 0x13u ? 1u : 0u;
    *quadrant = (uint8_t)(q & 3u);
    *mirror   = m;
    *octant   = (uint8_t)(((q & 3u) << 1) | m);
}

/* ==========================================================================
   $51A8 dial_needle_angle — THE REV-COUNTER NEEDLE  (twin #153)
   --------------------------------------------------------------------------
   A math_lo ($74) reader-nativization: the clamped-revs scratch becomes a C local, math_lo keeps
   its 6502 exit value (the folded angle offset).  Result-only (LIVE_NONE): exit regs/flags are
   dead at draw_dash_needles ($513D).  The routine falls through into plot_line_octant, a
   self-modifying line plotter shared by both differential sides — so it runs under
   REVS_SMC_CONTINUE=1 (its two SMC seams a compared, counted channel) and the fixture plants valid
   octant step-opcodes so the plotter body actually draws.  The DDA lengths are planted small and
   the needle origin high byte at its real page ($75) so the plotter's own writes stay off the
   control cells; correctness does not depend on that (both sides run the same plotter) — it only
   keeps the test easy to reason about.  ⚠ The self-write case is covered by test_plot_line_octant,
   which plants it deliberately; do not add it here. */
static int test_dial_needle_angle(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("dial_needle_angle");
    if (!want("dial_needle_angle")) return 0;

    unsigned mask = LIVE_NONE;
    setenv("REVS_SMC_CONTINUE", "1", 1);
    unsigned long smc_before = g_smcUnhandled;

    static const uint8_t STEP_OPS[4] = { 0x88, 0xC8, 0xCA, 0xE8 };  /* DEY/INY/DEX/INX */
    int cases = 3000 * scale;
    int octSeen[8] = {0}, mirror0 = 0, mirror1 = 0;

    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                                   /* dash path, not a SED site */

        /* Valid step opcodes for both of plot_line_octant's SMC seams, all 8 octants. */
        for (unsigned k = 0; k < 8; k++) {
            pre[0x3B86u + k] = STEP_OPS[(t + k) & 3u];
            pre[0x3B8Eu + k] = STEP_OPS[(t + k + 1u) & 3u];
        }
        /* Bounded, varied DDA line lengths; needle origin at its real screen page. */
        for (unsigned i = 0; i <= 0x13u; i++) pre[0x3100u + i] = (uint8_t)((xs() % 0x20u) + 1u);
        for (unsigned q = 0; q < 4; q++)      pre[0x397Cu + q] = 0x75u;

        uint8_t oct, mir, quad;
        needle_octant(pre[0x003Cu], &oct, &mir, &quad);
        octSeen[oct & 7]++;
        if (mir) mirror1++; else mirror0++;

        fail += diff_run("dial_needle_angle", pre, c, dial_needle_angle,
                         dial_needle_angle__t6502, mask, t, &printed);
    }
    unsetenv("REVS_SMC_CONTINUE");

    /* Non-vacuity: every octant reached and both mirror bits.  The plotter always runs
       (planted DDA lengths are >= 1 and the step opcodes are valid), so its execution is
       guaranteed by construction rather than counted. */
    int missing = 0;
    for (int i = 0; i < 8; i++) if (octSeen[i] == 0) missing++;
    if (missing) {
        printf("[VACUOUS] dial_needle_angle: %d of 8 octants never reached (", missing);
        for (int i = 0; i < 8; i++) printf("%d%s", octSeen[i], i < 7 ? "/" : "");
        printf(")\n");
        fail++;
    }
    if (mirror0 == 0 || mirror1 == 0) {
        printf("[VACUOUS] dial_needle_angle: the fold mirror bit went only one way "
               "(%d unfolded, %d folded)\n", mirror0, mirror1);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only  "
           "(octants %d/%d/%d/%d/%d/%d/%d/%d, %d folded, %lu SMC traps)\n",
           "dial_needle_angle", cases, fail,
           octSeen[0], octSeen[1], octSeen[2], octSeen[3],
           octSeen[4], octSeen[5], octSeen[6], octSeen[7],
           mirror1, g_smcUnhandled - smc_before);
    return fail;
}

