static int test_menu_draw_gfx_bars(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("menu_draw_gfx_bars");
    if (!want("menu_draw_gfx_bars")) return 0;

    /* Result-only (LIVE_NONE): the sole caller front_end_menus reloads X the instant it returns,
       so exit A/X/Y/flags are all dead.  Every effect is in mem[] — the two graphics bars in the
       MODE 7 page ($7C79..) and math_lo ($74, the campaign's target — its 6502 exit value is still
       written until relocation).  No PHA/PHP, so no stack residue; NO set_ignore needed. */
    unsigned mask = LIVE_NONE;

    int realRows = 0, randRows = 0, wrapCase = 0;
    int cases = 3000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;

        /* menu_bar_start_tbl ($3A6F) / menu_bar_end_tbl ($3A71): two rows each.  The in-game
           values are start {$00,$78}, end {$23,$9B}.  Reproduce those 1/4 of the time; otherwise
           randomise within a screen row with start < end so the do-while terminates promptly. */
        if (t % 4 == 0) {
            pre[0x3A6Fu + 0] = 0x00u; pre[0x3A71u + 0] = 0x23u;   /* row 0 */
            pre[0x3A6Fu + 1] = 0x78u; pre[0x3A71u + 1] = 0x9Bu;   /* row 1 */
            realRows++;
        } else {
            for (int r = 0; r < 2; r++) {
                uint8_t start = (uint8_t)(xs() % 0x60u);              /* 0..$5F */
                uint8_t end   = (uint8_t)(start + 1u + (xs() % 0x40u)); /* start+1 .. start+$40 */
                pre[0x3A6Fu + r] = start;
                pre[0x3A71u + r] = end;
            }
            randRows++;
        }

        /* 1/8: a start==end row.  The 6502 CPX matches only after X wraps through 256 (a full-row
           fill); both models do the identical writes, so it still matches — and it exercises the
           do{}while's post-test, which a for-loop would run zero times. */
        if (t % 8 == 3) { pre[0x3A6Fu + 0] = 0x40u; pre[0x3A71u + 0] = 0x40u; wrapCase++; }

        fail += diff_run("menu_draw_gfx_bars", pre, c, menu_draw_gfx_bars,
                         menu_draw_gfx_bars__t6502, mask, t, &printed);
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only  (%d real/%d rand rows, %d wrap)\n",
           "menu_draw_gfx_bars", cases, fail, realRows, randRows, wrapCase);
    return fail;
}

void parse_two_digit_ascii(void);
void parse_two_digit_ascii__t6502(void);

static int test_parse_two_digit_ascii(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("parse_two_digit_ascii");
    if (!want("parse_two_digit_ascii")) return 0;

    /* Exit C is the validity/range flag the sole caller ($3EE0) branches on; A carries the value
       (reconstructed faithfully though dead there).  math_lo ($74) keeps its per-path 6502 exit
       value, so it is diffed like any other cell — NO set_ignore.  D pinned 0: the routine's *10 is
       ASL-based (binary by construction) and it is not one of the 8 SED sites. */
    unsigned mask = LIVE_A | LIVE_C;

    int badC0 = 0, singleDigit = 0, badC1 = 0, twoDigit = 0, ge41 = 0;
    int cases = 4000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;

        /* Steer math_lo ($74, char0) / math_hi ($75, char1) through every exit arm: a space in
           char0 ('0'), an invalid char0, a space in char1 (single digit), an invalid char1, and
           two real digits (both value<41 and value>=41), plus fully random pairs. */
        uint8_t char0, char1;
        switch (t % 8) {
            case 0: char0 = 0x20u;                       char1 = (uint8_t)(0x30u + xs() % 10u); break; /* space->'0' */
            case 1: char0 = (uint8_t)(0x3Au + xs() % 6u); char1 = (uint8_t)xs(); break;                /* char0 not a digit */
            case 2: char0 = (uint8_t)(0x30u + xs() % 10u); char1 = 0x20u; break;                       /* single digit */
            case 3: char0 = (uint8_t)(0x30u + xs() % 10u); char1 = (uint8_t)(0x3Au + xs() % 6u); break;/* char1 not a digit */
            case 4: char0 = (uint8_t)(0x30u + xs() % 5u);  char1 = (uint8_t)(0x30u + xs() % 10u); break;/* value 0..49 — spans the CMP #$29 (41) boundary, incl. exactly 40/41 */
            case 5: char0 = (uint8_t)(0x35u + xs() % 5u);  char1 = (uint8_t)(0x30u + xs() % 10u); break;/* value >= 41 (>=50) */
            default: char0 = (uint8_t)xs();               char1 = (uint8_t)xs(); break;                /* anything */
        }
        pre[0x0074u] = char0;      /* math_lo */
        pre[0x0075u] = char1;      /* math_hi */

        /* Path bookkeeping (the core's own arithmetic, mirrored) for non-vacuity. */
        uint8_t c0 = (char0 == 0x20u) ? 0x30u : char0;
        uint8_t d0 = (uint8_t)(c0 - 0x30u);
        if (d0 >= 0x0Au) badC0++;
        else if (char1 == 0x20u) singleDigit++;
        else {
            uint8_t d1 = (uint8_t)(char1 - 0x30u);
            if (d1 >= 0x0Au) badC1++;
            else { twoDigit++; if ((uint8_t)(d0 * 10u + d1) >= 0x29u) ge41++; }
        }

        fail += diff_run("parse_two_digit_ascii", pre, c, parse_two_digit_ascii,
                         parse_two_digit_ascii__t6502, mask, t, &printed);
    }

    if (badC0 == 0 || singleDigit == 0 || badC1 == 0 || twoDigit == 0 || ge41 == 0) {
        printf("[VACUOUS] parse_two_digit_ascii: an exit arm was never reached "
               "(%d badC0, %d single, %d badC1, %d two, %d >=41)\n",
               badC0, singleDigit, badC1, twoDigit, ge41);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  (%d badC0/%d single/%d badC1/%d two [%d >=41])\n",
           "parse_two_digit_ascii", cases, fail, badC0, singleDigit, badC1, twoDigit, ge41);
    return fail;
}

void seed_car_track_position(void);
void seed_car_track_position__t6502(void);
void platform_test_via_t2(unsigned char v);

static int test_seed_car_track_position(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("seed_car_track_position");
    if (!want("seed_car_track_position")) return 0;

    /* $635D — place one car on the grid from a USRVIA_T2CL ($FE68) entropy byte.  X (the
       decremented car_seed_index cursor) is the sole live exit — the caller FUN_4d4d loops on
       it.  Everything else is mem[]: math_lo ($74, the campaign's target — its per-path 6502
       exit value is still written until relocation), car_track_position[x] ($0128+x, the
       result), car_seed_index ($4A, stored back), and the PHP/PLP residue byte at
       mem[$0100+S] (the pushed P from the LDA $FE68's N/Z plus the entry V/D/I/C — the twin's
       shim reproduces it, since the oracle's JSRs are C calls that never touch the emulated
       stack).  D pinned 0: the ADC $5F40 at $6396 is binary and this is the (re)start path,
       not one of the 8 SED sites (docs/static-map.md §Decimal mode). */
    unsigned mask = LIVE_X;

    int novice = 0, amateur = 0, pro = 0, signSet = 0, loop2 = 0, wrapX = 0, entZero = 0;
    int cases = 4000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;
        /* Entry V/I/C feed the PHP residue byte (the LDA overwrites only N/Z); randomise them
           so a shim bug in any of those residue bits is caught. */
        c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.I = xs() & 1; c.C = xs() & 1;

        /* car_seed_index ($4A): 0..19, including 0 so car_index_dec's 0->19 wrap is exercised. */
        uint8_t x = (uint8_t)(xs() % 20u);
        pre[0x004Au] = x;
        if (x == 0u) wrapX++;

        /* car_grid_base[x] ($04A0+x): subtracted from the doubled jitter — random. */
        pre[0x04A0u + x] = (uint8_t)xs();
        /* track_scale_saved ($5F40): added at the tail — random. */
        pre[0x5F40u] = (uint8_t)xs();

        /* race_class ($5F3A): cycle 0/1/2 so all three scaling arms run (Novice x2 / Amateur
           x1 / Pro asr1), plus fully-random values a twelfth of the time. */
        uint8_t rc = (t % 4 == 3) ? (uint8_t)xs() : (uint8_t)(t % 3);
        pre[0x5F3Au] = rc;
        if (rc == 0u)      novice++;
        else if (rc == 1u) amateur++;
        else               pro++;   /* rc >= 2 all take the Pro arm */

        /* The entropy byte through $FE68.  Force each arm: sign bit (bit7 -> abs8 negate),
           loop2 (raw & $7F >= 64 -> loop1 exhausts y), small values, and zero (residue Z). */
        uint8_t ent;
        switch (t % 5) {
            case 0: ent = 0u; break;                              /* zero: residue Z, no jitter */
            case 1: ent = (uint8_t)(0x80u | (xs() & 0x7Fu)); break;/* sign set */
            case 2: ent = (uint8_t)(0x40u + xs() % 0x40u); break; /* raw&$7F in 64..127 -> loop2 */
            case 3: ent = (uint8_t)(xs() % 0x40u); break;         /* small: loop1 exits early */
            default: ent = (uint8_t)xs(); break;                  /* anything */
        }
        platform_test_via_t2(ent);
        if (ent == 0u) entZero++;
        if (ent & 0x80u) signSet++;
        if ((ent & 0x7Fu) >= 64u) loop2++;

        fail += diff_run("seed_car_track_position", pre, c, seed_car_track_position,
                         seed_car_track_position__t6502, mask, t, &printed);
    }
    platform_test_via_t2(0);

    if (!novice || !amateur || !pro || !signSet || !loop2 || !wrapX || !entZero) {
        printf("[VACUOUS] seed_car_track_position: an arm was never reached "
               "(%d novice, %d amateur, %d pro, %d sign, %d loop2, %d wrapX, %d entZero)\n",
               novice, amateur, pro, signSet, loop2, wrapX, entZero);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=X  "
           "(%d nov/%d ama/%d pro, %d sign, %d loop2, %d wrapX, %d ent0)\n",
           "seed_car_track_position", cases, fail,
           novice, amateur, pro, signSet, loop2, wrapX, entZero);
    return fail;
}

void FUN_27ed(void);
void FUN_27ed__t6502(void);

/* --------------------------------------------------------------------------
   $27ED FUN_27ed — the per-frame per-car UPDATE ENGINE  (twin #159)

   Runs once a frame over cars X=19..0 (skipping player_car): target speed from the segment
   ahead, a braking-proximity gap, gap*4 integrated into the 16-bit car speed, the speed added
   into car_state_1 twice (each carry stepping the car one offset unit via track_pos_advance),
   then car_state_2 steered toward centre.  Exit ABI is dead (both callers JSR $2692 next), so
   only mem[] is compared — including the campaign's targets math_lo/math_hi ($74/$75), which the
   twin writes inline at their 6502 exit values.  D=0 (per-frame sim; not one of the 8 SED sites).

   fill_random covers every branch of the speed/gap/steering trees across the 20 cars over many
   cases.  What it CANNOT reach on its own is the case that justifies writing math_lo/math_hi
   INLINE rather than caching: a mid-routine LAP WRAP, where the inner-loop track_pos_advance
   fires lap_complete (twin #136), which overwrites $74/$75 with a BCD lap time while FUN_27ed is
   still running.  Both differential sides call the identical native track_pos_advance_core ->
   lap_complete_core, so the effect is byte-exact by construction — but only a twin that does NOT
   cache $74/$75 stays byte-exact.  So a slice of cases FORCES that wrap for one car. */
static int test_FUN_27ed(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("FUN_27ed");
    if (!want("FUN_27ed")) return 0;

    unsigned mask = LIVE_NONE;   /* both callers JSR $2692 immediately — no live exit register */

    int earlyRet = 0, bodyRun = 0, raceMode = 0, practiceMode = 0;
    int lapForced = 0, decelSeen = 0, brakeSeen = 0, shapeSteer = 0;
    int cases = 6000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;
        /* dead exit flags, but randomise the live entry ones so a shim that leaked one is caught */
        c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.I = xs() & 1; c.C = xs() & 1;

        /* start lights ($6D): mostly clear so the body runs; 1-in-8 set to hit the early return */
        uint8_t sl = (t % 8 == 0) ? (uint8_t)(0x80u | (xs() & 0x7Fu)) : (uint8_t)(xs() & 0x7Fu);
        pre[0x006Du] = sl;
        if (sl & 0x80u) earlyRet++; else bodyRun++;

        /* player_car ($6F): random 0..19 baseline (exercises the CPX-skip at any index) */
        uint8_t player = (uint8_t)(xs() % 20u);

        /* session mode ($6C bit7): both ways — gates FUN_27ed's $284B race offset and, via
           lap_complete, whether a forced lap's TIME is recorded */
        int race = (t & 1);
        pre[0x006Cu] = race ? (uint8_t)(0x80u | (xs() & 0x7Fu)) : (uint8_t)(xs() & 0x7Fu);
        if (race) raceMode++; else practiceMode++;

        /* count some pre-state arms for the vacuity guard (sampled across all 20 cars) */
        for (int i = 0; i < 20; i++) {
            if (pre[0x0100u + i] & 0x80u) decelSeen++;           /* car_race_flags bit7 -> L_decel */
            uint8_t seg = pre[0x06E8u + i];
            if (!(pre[0x5900u + seg] & 0x80u) && !(pre[0x5900u + seg] & 0x01u)) brakeSeen++;
            if (!(pre[0x018Cu + i] & 0xC0u)) shapeSteer++;       /* steering tree reachable */
        }

        /* FORCED LAP WRAP — 1-in-3 cases.  Drive one non-player car down L_decel with a known
           moderate speed so both inner-loop iterations overflow car_state_1 and call
           track_pos_advance; seed its distance one short of a full lap so the first advance fires
           lap_complete; open lap_complete's gates so it reaches the math_lo/math_hi writes. */
        if (t % 3 == 0) {
            player = 19u;                                        /* so any tc<=18 records in practice */
            pre[0x006Cu] = (uint8_t)(xs() & 0x7Fu);             /* practice: record = (tc <= player) */
            practiceMode++; if (race) raceMode--;               /* keep the tallies honest */
            race = 0;
            pre[0x006Du] = (uint8_t)(xs() & 0x7Fu);            /* lights clear so the body runs */
            if (sl & 0x80u) { earlyRet--; bodyRun++; }

            uint8_t tc = (uint8_t)(1u + (t % 18u));             /* 1..18, never the player (19) */
            pre[0x0100u + tc] = (uint8_t)(0x80u | (pre[0x0100u + tc] & 0x7Fu)); /* bit7 -> L_decel */
            pre[0x0150u + tc] = 0x10u;                          /* car_speed_scaled: +$FC00 -> $0C */
            pre[0x3850u + tc] = 0x00u;                          /* car_speed_frac */
            pre[0x0164u + tc] = 0xFFu;                          /* car_state_1: +$0C overflows twice */
            pre[0x08D0u + tc] = 0xFFu;                          /* car_distance_lo */
            pre[0x08E8u + tc] = 0x00u;                          /* car_distance_hi = $00FF */
            pre[0x59FCu] = 0x00u; pre[0x59FDu] = 0x01u;         /* lap_length = $0100 -> ++dist wraps */
            pre[0x62F8u] = (uint8_t)(pre[0x62F8u] & 0x7Fu);     /* track_scan_active clear -> book it */
            pre[0x018Cu + tc] = (uint8_t)(pre[0x018Cu + tc] & 0xBFu); /* flags_shape bit6 clear */
            pre[0x04B4u + tc] = (uint8_t)(xs() & 0x7Fu);        /* lap count < $80 so it increments */
            lapForced++;
        }

        pre[0x006Fu] = player;

        fail += diff_run("FUN_27ed", pre, c, FUN_27ed, FUN_27ed__t6502, mask, t, &printed);
    }

    if (!earlyRet || !bodyRun || !raceMode || !practiceMode || !lapForced ||
        !decelSeen || !brakeSeen || !shapeSteer) {
        printf("[VACUOUS] FUN_27ed: an arm was never reached "
               "(%d early, %d body, %d race, %d prac, %d lap, %d decel, %d brake, %d steer)\n",
               earlyRet, bodyRun, raceMode, practiceMode, lapForced, decelSeen, brakeSeen, shapeSteer);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=none  "
           "(%d early/%d body, %d race/%d prac, %d lapwrap)\n",
           "FUN_27ed", cases, fail, earlyRet, bodyRun, raceMode, practiceMode, lapForced);
    return fail;
}

void sort_cars_by_key(void);
void sort_cars_by_key__t6502(void);

/* --------------------------------------------------------------------------
   $0F64 sort_cars_by_key — bubble-sort the 21-entry car order array by a 3-byte
   BCD key (src/gen/revs_native.c twin #160).

   ⚠ ONE OF THE EIGHT SED SITES.  The routine forces SED itself, so entry D is
   irrelevant — but the key compares are BCD, so the diff scratch bytes ($75/$79
   exit values) differ from a binary subtract even though the ORDERING (the binary
   borrow) does not.  fill_random gives mostly-invalid-BCD key bytes, which is
   exactly what makes a binary-diff-byte sabotage diverge.  D is NOT pinned.

   The order entries are seeded to 0..19 so the key lookups stay in the intended
   tables and the sort is meaningful (random swaps and multi-pass convergence).
   Three constructed populations guarantee coverage the byte diff cannot infer:
     * the selector (cpu.A) cycles keyA (bits 6,7 clear) / keyB (bit6) / keyC (bit7);
     * 1-in-5 forces the whole active key table equal -> NO swap, math_lo ($74) left
       untouched (the reader-nat's most fragile case) and every compare a tie;
     * 1-in-7 forces one adjacent pair equal -> the tie-shift path with swaps around it.
   Exit ABI dead (CLD; JSR find_player_neighbours; RTS) -> LIVE_NONE. */
static int test_sort_cars_by_key(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("sort_cars_by_key");
    if (!want("sort_cars_by_key")) return 0;

    unsigned mask = LIVE_NONE;   /* CLD; JSR; RTS — no live exit register or flag */

    /* the three key tables, keyed to the selector arm they belong to */
    const uint16_t KA[3] = { 0x06A0u, 0x06B8u, 0x06D0u };  /* car_best_lap lo/mid/hi (keyA) */
    const uint16_t KB[3] = { 0x3864u, 0x39E4u, 0x04F0u };  /* car_lap        lo/mid/hi (keyB) */
    const uint16_t KC[3] = { 0x0898u, 0x08ACu, 0x04DCu };  /* car_lap_start  lo/mid/hi (keyC) */

    int keyA = 0, keyB = 0, keyC = 0, forcedEqual = 0, forcedTie = 0, randomOrder = 0;
    int cases = 6000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        /* randomise every entry flag INCLUDING D — the routine's own SED must win */
        c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.I = xs() & 1; c.C = xs() & 1; c.D = xs() & 1;

        /* seed the order array ($13B..$14F, 21 entries) with car slots 0..19 so the key
           lookups land inside the intended per-car tables */
        for (int j = 0; j <= 0x14; j++) pre[0x013Bu + j] = (uint8_t)(xs() % 20u);

        /* selector: cycle the three key arms by construction */
        int mode = t % 3;
        uint8_t base = (uint8_t)(xs() & 0x3Fu);
        const uint16_t* tbl;
        if (mode == 1)      { c.A = (uint8_t)(base | 0x40u); tbl = KB; keyB++; }  /* BVS */
        else if (mode == 2) { c.A = (uint8_t)(base | 0x80u); tbl = KC; keyC++; }  /* BMI */
        else                { c.A = (uint8_t)(base & 0x3Fu); tbl = KA; keyA++; }  /* keyA */

        /* 1-in-5: make the whole active key table equal across all cars -> no swap ever,
           math_lo left untouched, every compare a tie */
        if (t % 5 == 0) {
            uint8_t vlo = (uint8_t)xs(), vmid = (uint8_t)xs(), vhi = (uint8_t)xs();
            for (int i = 0; i < 20; i++) {
                pre[tbl[0] + i] = vlo; pre[tbl[1] + i] = vmid; pre[tbl[2] + i] = vhi;
            }
            forcedEqual++;
        } else {
            randomOrder++;
            /* 1-in-7 of the remaining: force one adjacent car pair's key equal (tie-shift) */
            if (t % 7 == 0) {
                uint8_t s = pre[0x013Bu + 1 + (xs() % 0x13u)];   /* a seeded slot */
                uint8_t d = pre[0x013Cu + 1 + (xs() % 0x13u)];   /* its neighbour's slot */
                pre[tbl[0] + d] = pre[tbl[0] + s];
                pre[tbl[1] + d] = pre[tbl[1] + s];
                pre[tbl[2] + d] = pre[tbl[2] + s];
                forcedTie++;
            }
        }

        fail += diff_run("sort_cars_by_key", pre, c, sort_cars_by_key,
                         sort_cars_by_key__t6502, mask, t, &printed);
    }

    if (!keyA || !keyB || !keyC || !forcedEqual || !forcedTie || !randomOrder) {
        printf("[VACUOUS] sort_cars_by_key: an arm was never reached "
               "(%d keyA, %d keyB, %d keyC, %d equal, %d tie, %d rand)\n",
               keyA, keyB, keyC, forcedEqual, forcedTie, randomOrder);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=none  "
           "(%d keyA/%d keyB/%d keyC, %d equal/%d tie)\n",
           "sort_cars_by_key", cases, fail, keyA, keyB, keyC, forcedEqual, forcedTie);
    return fail;
}

void shift_key_commands(void);
void shift_key_commands__t6502(void);
void platform_test_key_set_clear(void);   /* mode-3 held-SET: start empty */
void platform_test_key_set_add(unsigned char code);  /* ...then mark each code held */

/* --------------------------------------------------------------------------
   $0EE5 shift_key_commands — the in-race command keys (src/gen/revs_native.c twin #161).

   The reader-nat target is math_lo ($74), used ONLY as the scan-index save slot; the
   fixture must therefore make the scan STOP at a variety of indices, which means holding
   SHIFT ($FF) together with a specific scan-table key — impossible with the old all-or-one
   keyboard backend, so this fixture drives the mode-3 held-SET (platform_test_key_set_*).

   THE HANG HAZARD, and how every class provably avoids it.  A negative pause_request at
   $0F11 spins in clear_surface_buffers until key $A6 is down; a static held-set cannot
   "press $A6 later", so any case that reaches a negative pause_request MUST already hold
   $A6.  The scan-apply writes pause_request negative only for scan index 7 (action $83),
   and the scan picks the HIGHEST held index — so index 7 can win only when index 8 ($A6)
   is NOT held, which is exactly the hanging case.  The classes are built to never do that:
     * EARLY   — SHIFT not held -> returns at $0EEC (math_lo left = entry $0B).
     * SAFE    — SHIFT + a random subset of scan keys EXCLUDING $96 (idx7) and $A6 (idx8),
                 so no winner touches pause_request and it stays the non-negative preset:
                 no spin.  Winner in {0-6,9-11} or none -> the widest math_lo coverage.
     * IDX8    — SHIFT + $A6 as the top held key -> winner 8 writes pause_request=$40
                 (positive nudge, no spin); covers the idx8 action.
     * SPIN    — SHIFT + $A6 + $8A(idx11, action idx4, does NOT touch pause) so idx11 wins
                 and leaves pause_request at the preset $80; the negative-pause spin then
                 runs and exits at once because $A6 is held.
   ⚠ The "index 7 wins -> writes $80 -> spins for $A6" scenario is unreachable by
   construction (see above) and needs no coverage: the store LINE is exercised by every
   other winner, and the negative-pause spin is exercised by the SPIN class.

   D is pinned 0 (docs/static-map.md §Decimal mode: this is not one of the eight SED sites,
   so it is entered with D=0; the one ADC #$01 in the volume step is therefore binary).
   Exit ABI dead (RTS with no consumed register) -> LIVE_NONE. */
static int test_shift_key_commands(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("shift_key_commands");
    if (!want("shift_key_commands")) return 0;

    unsigned mask = LIVE_NONE;   /* RTS, no live exit register or flag */

    /* the two real tables, seeded so the fixture can predict which key is which */
    static const uint8_t SCAN[12]   = {0x86,0x8E,0x8D,0x8D,0xEB,0x8B,0xDF,0x96,0xA6,0xE9,0x8C,0x8A};
    static const uint8_t ACTION[12] = {0x80,0x01,0xC1,0x81,0xC2,0x42,0xC0,0x83,0x43,0x20,0x04,0x84};

    int early = 0, safeEnter = 0, idx8 = 0, spin = 0, volEven = 0, volOdd = 0;
    int cases = 6000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.N = xs()&1; c.V = xs()&1; c.Z = xs()&1; c.I = xs()&1; c.C = xs()&1;
        c.D = 0;                             /* not a SED site — entered with D=0 */
        c.Y = 0x0B;                          /* the caller's Y at both call sites */

        /* seed the two tables (fill_random would have scrambled them) */
        for (int i = 0; i < 12; i++) { pre[0x3DE2u + i] = SCAN[i]; pre[0x39D4u + i] = ACTION[i]; }

        platform_test_key_set_clear();       /* mode 3, nothing held */

        int cls = t % 6;
        if (cls == 0) {
            /* EARLY: SHIFT not held -> immediate return */
            early++;
        } else if (cls == 4) {
            /* SPIN: idx11 wins (leaves pause alone), pause_request negative, $A6 held to exit */
            platform_test_key_set_add(0xFF);
            platform_test_key_set_add(0xA6);
            platform_test_key_set_add(0x8A);
            pre[0x05F7u] = 0x80u;            /* pause_request negative -> real pause spin */
            spin++;
        } else if (cls == 5) {
            /* IDX8: $A6 the top held key -> winner 8, positive pause nudge */
            platform_test_key_set_add(0xFF);
            platform_test_key_set_add(0xA6);
            pre[0x05F7u] = (uint8_t)(xs() & 0x7Fu);   /* non-negative regardless */
            idx8++;
        } else {
            /* SAFE: SHIFT + random subset excluding idx7 ($96) and idx8 ($A6) -> no spin */
            platform_test_key_set_add(0xFF);
            unsigned r = xs();
            for (int i = 0; i < 12; i++) {
                if (i == 7 || i == 8) continue;
                if (r & (1u << i)) platform_test_key_set_add(SCAN[i]);
            }
            pre[0x05F7u] = (uint8_t)(xs() & 0x7Fu);   /* pause non-negative -> nudge or nothing */
            safeEnter++;
        }

        /* volume path: force both frame parities.  On even frames the sound_volume/request-sign
           pairs are chosen DETERMINISTICALLY to sit on the ceiling (0 -> silent) and floor ($F1 =
           -15) edges — a random sound_volume hits $FF or $F1 only ~1/256 of the time, which left
           the ceiling/floor commit conditions untested (a real coverage hole). */
        static const uint8_t VOL_EDGE[8]  = { 0xFF, 0x00, 0xF1, 0xF2, 0xF0, 0x80, 0x7F, 0x01 };
        static const uint8_t VCR_SIGN[8]  = { 0x80, 0x80, 0x01, 0x01, 0x01, 0x80, 0x80, 0x01 };
        if (t % 2 == 0) {
            int k = (t / 2) % 8;
            pre[0x006Au] = (uint8_t)(xs() & 0xFEu);          /* loop_counter even -> step runs */
            pre[0x05F6u] = VCR_SIGN[k];                      /* negative = quieter (toward 0), positive = louder */
            pre[0x05FEu] = VOL_EDGE[k];                      /* $FF/$00 ceiling, $F1/$F2/$F0 floor, mid values */
            volEven++;
        } else {
            pre[0x006Au] = (uint8_t)(xs() | 1u);             /* loop_counter odd -> step skipped, vcr cleared */
            pre[0x05F6u] = (uint8_t)xs();
            volOdd++;
        }

        fail += diff_run("shift_key_commands", pre, c, shift_key_commands,
                         shift_key_commands__t6502, mask, t, &printed);
    }

    if (!early || !safeEnter || !idx8 || !spin || !volEven || !volOdd) {
        printf("[VACUOUS] shift_key_commands: an arm was never reached "
               "(%d early, %d safe, %d idx8, %d spin, %d volEven, %d volOdd)\n",
               early, safeEnter, idx8, spin, volEven, volOdd);
        fail++;
    }
    platform_test_key_set_clear();   /* leave the backend in a known state */
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=none  "
           "(%d early/%d safe/%d idx8/%d spin, %d volEven/%d volOdd)\n",
           "shift_key_commands", cases, fail, early, safeEnter, idx8, spin, volEven, volOdd);
    return fail;
}

void view_paint_lines(void);
void view_paint_lines__t6502(void);
extern unsigned long g_viewTableCollisions;   /* asserted below; see revs_native.c */

/* --------------------------------------------------------------------------
   $7BE2 view_paint_lines — the 40-unit column chain (src/gen/revs_native.c).

   ⚠⚠ fill_random() ALONE CANNOT TEST THIS ROUTINE, and the reason is the point of the
   fixture.  The chain is self-modifying code: forty `STA (zp),Y` opcode slots that are
   switched between $91 and $60, three `JSR` operands and three store operands that are
   rewritten with a computed low byte, and one terminator at $7EEE that toggles $E0/$60.
   A uniformly random byte in any of those is neither legal value, so the FIRST thing both
   models do is trap through platform_smc_unhandled — agreeing with each other about
   nothing.  So the pre-state is BUILT: random everywhere, legal where the operand
   encoding says it must be.

   WHERE EACH CONSTRAINT COMES FROM — every one is read off the code, none is a guess:

     * the 29 reachable opcode slots start as `STA` ($91) and $7EEE as `CPX` ($E0),
       because $7BBF restores exactly those on the way out of every real call;
     * the fixed HIGH operand byte of each patched store/call is what pins it to one
       page ($7C for chain A, $7E for chain B), so those bytes are set, not randomised;
     * $3150,X names a chain-A opcode slot, so it is one of the fifteen $0F+$11k lows;
     * $30D0,X names a chain-B ENTRY, so it is one of the twenty-eight unit / unit+$05
       lows in page $7E;
     * $3080,X names a chain-B opcode slot AND, through `$F1 - it`, chain A's entry —
       and $F1 - ($0F+$11k) is exactly $11*(13-k)+5, so ONE value satisfies both.  That
       identity is why the table can serve both purposes at all.

   ⭐ AND THE MEMORY MAP FALLS OUT OF IT.  Each $80-spaced block holds $50 source bytes
   (one per column, X = $03..$4F) and $30 spare; every control table above lives in a
   spare — $3050/$3080/$30D0/$3150, $3350, $33D0, $38D0, $38FC, $3950.  The one
   exception is $3080,X for phase 3's columns X = $03..$1B, which IS unit 1's source
   range, and that is consistent rather than a clash: phase 3 enters chain A at unit
   13-k, so units 0 and 1 are never drawn for those columns and their source bytes are
   free.  It also bounds the fixture: k <= 11 keeps the entry at unit 2 or below, and a
   larger k would have the chain zero $3080,X between its two reads.  Both models then
   trap identically — the "illegal" case below proves that rather than assuming it.

   ⭐ SABOTAGE RECORD (2026-08-16) — thirteen deliberate defects, all caught:
   the dirty source not cleared (700/700), a planted RTS ignored (508 + the trap count
   moved 196 → 314), the row offset off by one cell (700), chain B storing through $70
   (700), the sweep terminator off by one (700), the restore dropping chain B's un-plant
   (602), the carry into $73 lost in the advance (700) and again in phase 3 (656), the
   forced entry taking the dirty test anyway (697), phase 2 not arming $7EEE (701), the
   background byte from the wrong table (387), the unpatchable page-$7D slots dispatched
   as if they were patchable (701), and — caught by NOTHING BUT THE FLAG COMPARISON — the
   $7EF3 pointer advance written as plain C instead of the ADC macros (11 cases, V only).
   ⚠ That last one is why the flags are declared live: V and C are the two the chain can
   leak, and they only become visible when a trap cuts the driver short before its own
   `SBC` overwrites them.  ⚠⚠ And sabotage #7 first reported #6's number because its patch
   had failed to apply and `make` had nothing to rebuild — a stale object reading as a
   result, for the second time on this project.  Every sabotage must change the source.

   TWO INPUT SHAPES, because the real one is not the random one.  With random sources
   ~255 of every 256 units are dirty; the measured sweep is 96% CLEAN (2093 units, ~83
   stores — docs/direct-bitplane-plan.md §7a), and a clean unit is the path where A
   carries down the column from the cell above.  The `sparse` cases put the sources back
   at roughly that density so that path is the one under test.
   -------------------------------------------------------------------------- */
enum { DASH_SLOT_N = 15, DASH_ENTRYB_N = 28 };

static void dash_pre(uint8_t* pre, int sparse, int illegal)
{
    /* the fifteen chain-A opcode-slot low bytes; chain B uses the first fourteen */
    uint8_t slotLow[DASH_SLOT_N];
    uint8_t entryB[DASH_ENTRYB_N];
    int k, x;

    for (k = 0; k < DASH_SLOT_N; k++)   slotLow[k] = (uint8_t)(0x0F + 0x11 * k);
    for (k = 0; k < 14; k++) { entryB[2*k] = (uint8_t)(0x11 * k);
                               entryB[2*k+1] = (uint8_t)(0x11 * k + 5); }

    fill_random(pre);

    /* the source blocks: dense by default, ~1 in 20 non-zero for the measured shape */
    if (sparse)
        for (k = 0; k < 40; k++)
            for (x = 0; x < 0x50; x++)
                if (xs() % 20) pre[0x3000 + 0x80 * k + x] = 0;

    /* every reachable opcode slot unpatched, and the sweep's terminator armed */
    for (k = 0; k < 15; k++) pre[0x7C0F + 0x11 * k] = 0x91;
    for (k = 0; k < 14; k++) pre[0x7E0F + 0x11 * k] = 0x91;
    pre[0x7EEE] = 0xE0;

    /* the fixed high operand bytes — what pins each writer to one page */
    pre[0x7BD5] = 0x7C; pre[0x7BD8] = 0x7C; pre[0x7BDB] = 0x7E;
    pre[0x7D25] = 0x7C; pre[0x7D30] = 0x7C; pre[0x7D4E] = 0x7E;
    pre[0x7F25] = 0x7C; pre[0x7F30] = 0x7C; pre[0x7F69] = 0x7C;
    pre[0x7F7E] = 0x7E; pre[0x7F89] = 0x7E; pre[0x7F9C] = 0x7E;

    /* the three "where did I last plant" records, and the chain-B call operand that is
       reused verbatim when a column's plant is skipped */
    pre[0x7D24] = slotLow[xs() % DASH_SLOT_N];
    pre[0x7F24] = slotLow[xs() % DASH_SLOT_N];
    pre[0x7F7D] = slotLow[xs() % 14];
    pre[0x7D4D] = entryB[xs() % DASH_ENTRYB_N];

    /* the per-scan-line control tables */
    for (x = 0x03; x <= 0x2B; x++) {
        pre[0x3150 + x] = slotLow[xs() % DASH_SLOT_N];
        pre[0x30D0 + x] = entryB[xs() % DASH_ENTRYB_N];
    }
    for (x = 0x03; x <= 0x1B; x++)
        pre[0x3080 + x] = (uint8_t)(0x0F + 0x11 * (xs() % 12));

    /* one column given a low byte that is not a unit boundary: both models must trap at
       the same site with the same value and unwind the same way */
    if (illegal) pre[0x30D0 + 0x03 + (xs() % 0x29)] = 0x08;
}

void stage_nearby_car(void);
void stage_nearby_car__t6502(void);

/* ==========================================================================
   $28F2 stage_nearby_car — THE PER-NEARBY-CAR VIEW STAGER  (twin #162)
   --------------------------------------------------------------------------
   Result-only (LIVE_NONE): move_and_draw_cars reloads X from $1D and Y from $62F4 after the first
   call and reads nothing from the second (it returns), so every exit register/flag is dead.  Every
   observable effect is in mem[]: math_lo ($74, the campaign target — its 6502 exit value is still
   written until relocation), the car_flags_0 curve copy, and whatever place_car_world_coords /
   reject_object_slot write (the SAME native functions in both models).

   place_car_world_coords is steered to its early SMC-unhandled return (mem[$298D] != $29) so it
   terminates fast and deterministically — but it still runs axis-0, whose section-origin index is
   mem[SECTION_DIR_INDEX + Y]: a wrong slot->X (car_state_1/2[X]) or a wrong Y diverges mem[] on
   the very first axis, so the fixture is still sensitive to this twin's two register outputs.

   Coverage.  car_gap_tail treats D = dist[$17]-dist[slot] with a ZERO high byte as a near pair
   (gap = D) and anything else as wrapped (gap = lap_length-|D|).  So a controlled POSITIVE small D
   with a huge lap_length gives a known in-range magnitude — that carries the $28 range boundary,
   the 3*|gap| and +$78 wrap, the wrong-side gate, and the curve-copy $32/bit4 boundaries.  A
   random quarter (with a small lap_length half the time) samples the far and wrapped-near exits
   and both signs of the returned gap byte (the abs8-negate path). */
static int test_stage_nearby_car(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("stage_nearby_car");
    if (!want("stage_nearby_car")) return 0;

    unsigned mask = LIVE_NONE;

    /* place_car_world_coords' per-circuit SMC seam ($298D) is real code in BOTH models: an
       unrecognised opcode traps through platform_smc_unhandled and returns.  Steer it there (opcode
       $00, not the $29 AND) so place terminates on its first axis; the trap must count rather than
       abort, and equal counts on both sides are asserted by diff_run.  Nonzero total is checked
       below so the staged (non-reject) path — the only one that reaches place — cannot go untested. */
    setenv("REVS_SMC_CONTINUE", "1", 1);
    g_smcUnhandled = 0;

    int cases = 6000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                                          /* not a SED site (static-map §Decimal mode) */
        /* move_and_draw_cars loads X from $1D, a car_order POSITION (0..19), and the entry it
           reads is a car SLOT (0..19) — both domains are structural: car_order is 20 bytes at
           $013C and there are 20 racing cars.  Pin both, so the slot this twin indexes the
           per-car arrays with is a slot that exists (car_distance is 24 words, $00-$17). */
        for (int i = 0; i < 20; i++) pre[0x013Cu + i] = (uint8_t)(xs() % 20u);  /* car_order */
        c.X = (uint8_t)(xs() % 20u);                      /* the car_order position input */

        pre[0x298D] = 0x00;                               /* SMC_MASK_OPCODE != $29 -> place early-returns */

        uint8_t slot = pre[0x013Cu + c.X];                /* car_order[X] */

        if ((t & 3) != 0) {
            /* Controlled near pair: dist[$17] - dist[slot] = +gap, huge lap_length (no wrap). */
            pre[0x59FC] = 0xFFu; pre[0x59FD] = 0x7Fu;     /* lap_length = $7FFF */
            uint16_t base = 0x4000u;
            uint8_t gap;
            switch (t % 6) {
                case 0:  gap = 0x27u; break;              /* just inside range -> stage */
                case 1:  gap = 0x28u; break;              /* the boundary    -> reject */
                case 2:  gap = 0x29u; break;              /* just outside    -> reject */
                case 3:  gap = (uint8_t)(xs() % 0x28u); break;   /* anywhere in range */
                case 4:  gap = 0x00u; break;              /* coincident */
                default: gap = (uint8_t)(xs() & 0x7Fu); break;   /* 0..$7F: mixes in/out of range */
            }
            uint16_t dslot = (uint16_t)(base - gap);
            pre[0x08D0u + 0x17u] = (uint8_t)base;   pre[0x08E8u + 0x17u] = (uint8_t)(base >> 8);
            pre[0x08D0u + slot]  = (uint8_t)dslot;  pre[0x08E8u + slot]  = (uint8_t)(dslot >> 8);

            /* track_direction bit7 = 0 so a positive gap PASSES the wrong-side gate; flip it 1/4
               of the time to exercise the wrong-side reject.  Only bit7 gates; keep the rest. */
            if (t % 4 == 1) pre[0x0025] |= 0x80u; else pre[0x0025] &= 0x7Fu;

            /* section_cursor: small forces the Y = -3*|gap| negative wrap (+$78); large avoids it. */
            pre[0x0024] = (t & 1) ? 0x02u : (uint8_t)(0x60u + (xs() & 0x1Fu));

            /* the curve-copy gate: car_race_flags bit4 and car_speed_scaled around the $32 edge. */
            if (t % 5 == 0) pre[0x0100u + slot] |= 0x10u; else pre[0x0100u + slot] &= 0xEFu;
            switch (t % 4) {
                case 0:  pre[0x0150u + slot] = 0x31u; break;   /* just below -> no copy */
                case 1:  pre[0x0150u + slot] = 0x32u; break;   /* at threshold -> copy */
                case 2:  pre[0x0150u + slot] = 0x33u; break;   /* above -> copy */
                default: pre[0x0150u + slot] = (uint8_t)xs(); break;
            }
        } else if (t & 1) {
            /* random distances but a SMALL lap_length -> wrapped gaps fit a byte, so the wrapped-near
               exits (both signs of the returned gap byte, the abs8-negate path) get sampled. */
            pre[0x59FC] = (uint8_t)(0x40u + (xs() & 0x7Fu));
            pre[0x59FD] = 0x00u;
        }
        /* the rest keep fully random distances + lap_length -> the far exits and random everything. */

        fail += diff_run("stage_nearby_car", pre, c, stage_nearby_car,
                         stage_nearby_car__t6502, mask, t, &printed);
    }
    unsetenv("REVS_SMC_CONTINUE");

    if (g_smcUnhandled == 0) {
        printf("[VACUOUS] stage_nearby_car: 0 SMC traps — no case reached place_car_world_coords, "
               "so the staged (non-reject) path was never tested\n");
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only, %lu place traps\n",
           "stage_nearby_car", cases, fail, g_smcUnhandled);
    return fail;
}

void check_car_pair(void);
void check_car_pair__t6502(void);

/* ==========================================================================
   $2692 check_car_pair — THE PER-FRAME OVERTAKING / POSITION-CHANGE PASS  (twin #163)
   --------------------------------------------------------------------------
   Result-only (LIVE_NONE): both callers ($1181, $264C) reload X immediately after, and every exit
   register/flag is dead, so the whole observable effect is in mem[] — car_order (on a swap),
   position_swap_flag ($62FE), pass_count_bcd ($2F), car_race_flags ($0100), car_flags_0 ($0114),
   the mem[$0083] magnitude scratch, and the reader-nat cell math_lo ($74) which keeps its 6502
   exit value until relocation.  car_gap / car_order_swap / car_index_dec/inc are the SAME native
   cores in both models, so a wrong dispatch or a cached-instead-of-inline $74 diverges mem[].

   Coverage.  The routine walks all 20 car_order positions, comparing each car to the one behind:
     - EQUAL distance high bytes (slices 0,1) make every pair a direct near pair, so the gap is the
       low-byte distance difference — many land gap<5 in the PROXIMITY arm, sweeping the c4 (gap>=4),
       rf (car_race_flags bit6), fs-bit7 (car_flags_shape) and the diff >= $50/$64 boundaries, plus
       the $2771 SMC compare against a random operand.
     - A wrapped ring (slice 2) tuned so the in-range complement lands gap >= $F6 with N set drives
       the SWAP arm: with the player forced into the order and lap counts levelled it reaches the
       player sub-branches and the bracketed-SED same-lap BCD add into pass_count_bcd.
     - Fully random (slice 3) samples the far exits and the wrapped-far tail.
   T2 entropy ($FE68) is pinned per case to sweep the ent & $1F == 0 / != 0 split in the fs-bit7 arm,
   and a seventh of cases plant a non-$C9 opcode at $2771 so the trap-and-return unwind is compared
   too (equal trap counts asserted by diff_run; nonzero total checked below). */
static int test_check_car_pair(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("check_car_pair");
    if (!want("check_car_pair")) return 0;

    unsigned mask = LIVE_NONE;

    setenv("REVS_SMC_CONTINUE", "1", 1);
    g_smcUnhandled = 0;

    int cases = 12000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                                          /* only the pass-count ADC is BCD (bracketed SED) */

        for (int i = 0; i < 20; i++) pre[0x013Cu + i] = (uint8_t)(xs() % 20u);  /* car_order: slots 0..19 */
        pre[0x006Fu] = (uint8_t)(xs() % 20u);             /* player_car */
        pre[0x0003u] = (uint8_t)(xs() % 20u);             /* zp_scratch_index: the start position */

        if (t % 7 == 0) pre[0x2771u] = 0x00u;             /* SMC seam: trap-and-return path */
        else            pre[0x2771u] = 0xC9u;             /*           CMP #imm — the compare runs */
        pre[0x2772u] = (uint8_t)xs();                     /* sweep the diff >= operand boundary */

        uint8_t ent = (t % 3 == 0) ? 0x00u : (uint8_t)((xs() % 0x1Fu) + 1u);  /* &$1F == 0 vs != 0 */
        platform_test_via_t2(ent);

        int slice = t % 4;
        if (slice == 0 || slice == 1) {
            /* NEAR / PROXIMITY: equal distance high bytes -> direct near pairs, gap = low diff. */
            for (int i = 0; i < 20; i++) pre[0x08E8u + i] = 0x00u;   /* dist_hi all equal */
            /* dist_lo ($08D0) and state_1 ($0164) stay random -> assorted small gaps and signs */
        } else if (slice == 2) {
            /* SWAP: a wrapped ring where complement = lap_length - |D| ~ 0x100 - k lands gap>=$F6. */
            pre[0x59FDu] = 0x01u;                                  /* lap_length_hi = 1 */
            pre[0x59FCu] = (uint8_t)((xs() % 0x0Au) + 1u);         /* lap_length_lo = 1..$0A */
            for (int i = 0; i < 20; i++) {
                pre[0x08E8u + i] = (uint8_t)(i & 1u);              /* alternate hi 0/1 -> wrapped pairs */
                pre[0x08D0u + i] = 0x00u;                          /* equal lo -> |D| low byte 0 */
                pre[0x0164u + i] = 0x00u;                          /* state_1 equal -> carryIn = 1 */
            }
            pre[0x013Cu + (xs() % 20u)] = pre[0x006Fu];            /* seed the player into the order */
            pre[0x013Cu + (xs() % 20u)] = pre[0x006Fu];
            if (t & 8) for (int i = 0; i < 20; i++) pre[0x04B4u + i] = 0x00u;   /* level laps -> BCD add */
            pre[0x002Fu] = (uint8_t)(((xs() % 10u) << 4) | (xs() % 10u));       /* valid BCD counter */
        }
        /* slice 3: fully random distances / lap_length -> the far exits and wrapped-far tail. */

        if (t % 5 == 0) {
            /* NEAR-EQUAL SPEEDS: fully random 16-bit speeds make the $26ed-$26f7 subtract's
               carry-out boundary (a difference of exactly 1) a 1-in-65536 event, so pin the high
               lanes equal and sweep the low ones through it. */
            uint8_t base = (uint8_t)xs();
            for (int i = 0; i < 20; i++) {
                pre[0x0150u + i] = base;                  /* car_speed_scaled: equal high lanes */
                pre[0x3850u + i] = (uint8_t)(xs() % 4u);  /* car_speed_frac: differences -3..+3 */
            }
        }

        fail += diff_run("check_car_pair", pre, c, check_car_pair,
                         check_car_pair__t6502, mask, t, &printed);
    }
    unsetenv("REVS_SMC_CONTINUE");

    if (g_smcUnhandled == 0) {
        printf("[VACUOUS] check_car_pair: 0 SMC traps — no case reached the $2771 trap arm\n");
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only, %lu smc traps\n",
           "check_car_pair", cases, fail, g_smcUnhandled);
    return fail;
}

void plot_line_octant(void);
void plot_line_octant__t6502(void);

/* ==========================================================================
   $5204 plot_line_octant — THE SELF-MODIFYING OCTANT LINE PLOTTER  (twin #164)
   --------------------------------------------------------------------------
   Result-only (LIVE_NONE): both callers (dial_needle_angle's fall-through at $51E3 and
   draw_dash_needles at $517C) reload immediately and no exit register/flag is live, so every
   observable effect is in mem[] — the eight pixels ORed into the screen page through ($70),Y,
   the undo list it appends (plot_undo_byte/ptr_lo/ptr_hi at $0780/$07A8/$07D0, count $69),
   plot_ptr_lo/hi as the walk left them, shared_temp_76/77 and bearing_lo scratch, and the
   reader-nat cell math_hi ($75) which keeps its 6502 exit value ($FF) until relocation.

   ⚠⚠ THE DDA INCREMENT ($74) AND THE PIXEL COUNTER ($75) ARE NOT CACHEABLE, and the header that
   used to stand here argued they were ("plot_line_octant is a LEAF, so nothing in the loop
   rewrites zero page").  Being a leaf is not the property that matters: this plotter is one of
   its OWN writers.  It walks +/-8 a pixel and +/-$140 a row from whatever $70/$71 hold, so a
   pointer near page $00 lands its pixel store on $74/$75 — after which the oracle's increment
   changes under it and a cached local's does not.  The twin now re-reads $74 per pixel and
   decrements $75 in place.  Found by PLANTING the case below, not by reading the code.

   SMC seams.  The major- and minor-axis STEP OPCODES are patched into the routine from the two
   octant tables ($3B86 -> $5220, $3B8E -> $529B) indexed by the octant in shared_temp_76.  The
   twin DISPATCHES ON THE CELLS $5220/$529B (not a cached copy): a line that walked its own code
   would be visible only that way, and the trap arm (an opcode that is not DEY/INY/DEX/INX) is
   real code in both models, so it is exercised rather than avoided — which needs
   Platform::smcUnhandled to count, not abort.

   Coverage.  All 8 octants are planted through shared_temp_76 with valid step opcodes in both
   tables; a bounded pixel count ($75 = 1..$14) and undo-count base (0..8) keep the undo append
   inside the 40-entry tables; the minor delta (point_delta_hi $83) is varied so the DDA takes
   both the carry (major-step) and no-carry paths; the entry x/y (shared_temp_77 / c.Y, 0..7)
   and plot_ptr sweep the column/row wrap branches; hypot_min_hi is 0 or 4 to fold the MODE 5
   pixel index onto both halves of the keep/colour tables.  A final slice plants an ILLEGAL
   opcode in the MINOR table entry (always executed) so the trap-and-return unwind is compared. */
static int test_plot_line_octant(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("plot_line_octant");
    if (!want("plot_line_octant")) return 0;

    unsigned mask = LIVE_NONE;
    setenv("REVS_SMC_CONTINUE", "1", 1);
    g_smcUnhandled = 0;

    static const uint8_t STEP_OPS[4] = { 0x88, 0xC8, 0xCA, 0xE8 };  /* DEY/INY/DEX/INX */
    int legal   = 6000 * scale;
    int illegal = 800  * scale;
    int octSeen[8] = {0}, fold0 = 0, fold1 = 0;
    unsigned long smcLegal;

    for (t = 0; t < legal + illegal; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                                   /* plotter path, not a SED site */
        c.Y = (uint8_t)(xs() & 7u);                /* entry scanline 0..7 */

        uint8_t oct = (uint8_t)(t & 7u);
        pre[0x0076u] = oct;                        /* shared_temp_76 = octant */
        for (unsigned k = 0; k < 8; k++) {
            pre[0x3B86u + k] = STEP_OPS[(t + k) & 3u];      /* major-axis step opcodes */
            pre[0x3B8Eu + k] = STEP_OPS[(t + k + 1u) & 3u]; /* minor-axis step opcodes */
        }
        pre[0x0077u] = (uint8_t)(xs() & 7u);       /* shared_temp_77 = entry x 0..7 */
        pre[0x0074u] = (uint8_t)xs();              /* math_lo = DDA increment */
        pre[0x0075u] = (uint8_t)((xs() % 0x14u) + 1u);      /* math_hi = pixel count 1..$14 */
        pre[0x0083u] = (uint8_t)((xs() % 0x40u) + 1u);      /* point_delta_hi = minor delta */
        pre[0x0079u] = (t & 1) ? 0x04u : 0x00u;    /* hypot_min_hi fold base */
        pre[0x0069u] = (uint8_t)(xs() % 9u);       /* plot_undo_count base 0..8 */
        pre[0x0070u] = (uint8_t)xs();              /* plot_ptr_lo */
        pre[0x0071u] = (uint8_t)(0x60u + (xs() % 8u));      /* plot_ptr_hi mid-RAM, off ZP/HW */
        /* ⭐⭐ ...EXCEPT ONE CASE IN EIGHT, WHICH PLANTS THE PLOTTER ON ITS OWN POINTER.
           This is a SELF-MODIFYING plotter: it stores through $70/$71 and, walking ±8 a pixel
           and ±$140 a row for up to $14 pixels, a pointer that starts near page $00 lands its
           own pixel store ON $70/$71 — after which the oracle (which re-reads the pointer from
           mem[] at every dereference) and a relocated uint16_t part company.  The FIFTH
           eligibility test, and the same plant the four span arms carry
           (docs/wide-value-cleanup.md).  Without it plot_store_resync here is untested: the
           original `$60 + …` line kept the pointer off zero page BY CONSTRUCTION, so dropping
           the guard entirely passed all 6800 cases.
           ⚠ These cases really do overwrite the fixture's own zero-page inputs mid-run.  That
           is the point, and it is sound: both sides do it from identical memory. */
        if ((t & 7u) == 3u) {
            pre[0x0071u] = (uint8_t)(xs() % 2u);                   /* page $00 or $01 */
            /* ...and half of those aimed AT the lanes.  A uniform low byte reaches the danger
               window ($006A..$0071, where ($70),Y covers $70 or $71) in 8 draws of 256, which
               was too thin: a sabotage that skipped the lane refresh on ONE of the four steps
               survived until this line existed. */
            if (pre[0x0071u] == 0u) pre[0x0070u] = (uint8_t)(0x50u + (xs() % 0x40u));
        }

        if (t >= legal)                            /* illegal slice: trap the ALWAYS-run minor step */
            pre[0x3B8Eu + oct] = 0x00u;            /* BRK — not a step opcode */
        else {
            octSeen[oct]++;
            if (pre[0x0079u]) fold1++; else fold0++;
        }

        fail += diff_run("plot_line_octant", pre, c, plot_line_octant,
                         plot_line_octant__t6502, mask, t, &printed);
        if (t == legal - 1) smcLegal = g_smcUnhandled;
    }
    unsigned long smcIllegal = g_smcUnhandled - smcLegal;
    unsetenv("REVS_SMC_CONTINUE");

    /* Non-vacuity.  Every octant reached with a valid step in both seams (so the plotter runs
       to completion, not into a trap); both fold bases seen; zero traps over the legal cases
       (a trapping pre-state would compare almost nothing) and non-zero over the illegal ones. */
    int missing = 0;
    for (int i = 0; i < 8; i++) if (octSeen[i] == 0) missing++;
    if (missing) {
        printf("[VACUOUS] plot_line_octant: %d of 8 octants never reached (", missing);
        for (int i = 0; i < 8; i++) printf("%d%s", octSeen[i], i < 7 ? "/" : "");
        printf(")\n");
        fail++;
    }
    if (fold0 == 0 || fold1 == 0) {
        printf("[VACUOUS] plot_line_octant: the pixel-index fold went only one way "
               "(%d base 0, %d base 4)\n", fold0, fold1);
        fail++;
    }
    if (smcLegal != 0) {
        printf("[VACUOUS] plot_line_octant: %lu SMC traps over the %d LEGAL cases — a step "
               "opcode planted was not DEY/INY/DEX/INX\n", smcLegal, legal);
        fail++;
    }
    if (smcIllegal == 0) {
        printf("[VACUOUS] plot_line_octant: 0 SMC traps over the %d ILLEGAL cases — the "
               "trap-and-return unwind was never reached\n", illegal);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only  "
           "(octants %d/%d/%d/%d/%d/%d/%d/%d, %lu traps in %d illegal)\n",
           "plot_line_octant", legal + illegal, fail,
           octSeen[0], octSeen[1], octSeen[2], octSeen[3],
           octSeen[4], octSeen[5], octSeen[6], octSeen[7],
           smcIllegal, illegal);
    return fail;
}

void mirror_draw_car(void);
void mirror_draw_car__t6502(void);

/* ⭐ TWIN #165c — mirror_draw_car ($7FB6).  Paint one wing-mirror segment: walk its run of scan
   lines writing the $F0 reflection pattern, ANDed with the engine-shudder term only between the
   block's top (span_line_cursor) and bottom (A) bounds.

   The fixture has to drive four things the routine branches on and one it reads from hardware:
     * the bounds, so that BOTH shudder-gate arms and BOTH bound tests are exercised — including
       the erase case (bottom = 0, which never gates) mirrors_update actually passes;
     * a run long enough to WRAP the scan-line cursor past $00, because the character-row step
       back ($138) happens only in the wrapped range and is where the 6502's two-byte SBC pair
       became one 16-bit subtract;
     * engine_running both 0 and $FF, since it gates the shudder to nothing when the engine is off;
     * the User VIA read at $FE68, compared through the harness's hardware channel.
   ⚠ Segment addresses are planted in the frame buffer ($5800-$7BFF, clear of the $7C00 dashcode
   page the routine's own bytes live in).  That is the twin's aliasing argument under test: it
   keeps the destination in a uint16_t and writes plot_ptr $70/$71 once, which is equivalent only
   because a store through a screen address can never land on zero page. */
static int test_mirror_draw_car(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("mirror_draw_car");
    if (!want("mirror_draw_car")) return 0;

    unsigned mask = LIVE_NONE;              /* mirrors_update reloads A and Y per segment */
    int cases = 2000 * scale;
    int shud = 0, plain = 0, wrapped = 0, engineOn = 0, erase = 0;

    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;

        uint8_t seg = (uint8_t)(t % 6u);    /* mirrors_update only ever passes segments 0..5 */
        c.Y = seg;

        /* A run of 4..40 lines starting anywhere, so roughly a third of them walk past $00 into
           the wrapped range where the character-row step back lives. */
        uint8_t start = (uint8_t)(xs() % 0x30u);
        uint8_t len   = (uint8_t)((xs() % 0x25u) + 4u);
        uint8_t end   = (uint8_t)(start - len);
        /* ⚠ end = 0 is excluded because it does not terminate — on either seam.  The 6502's
           CPY #$00 always sets carry, so the run would walk all 256 lines and start again; the
           real table never holds 0 for the same reason. */
        if (end == 0u) end = 1u;
        pre[0x40FAu + seg] = start;
        pre[0x3EFAu + seg] = end;
        if (end > start) wrapped++;

        uint16_t addr = (uint16_t)(0x5800u + (xs() % 0x2400u));
        pre[0x3B26u + seg] = (uint8_t)addr;
        pre[0x3B9Eu + seg] = (uint8_t)(addr >> 8);

        int doErase = (t % 4u == 0u);
        uint8_t bottom = doErase ? 0x00u : (uint8_t)(xs() % 0x40u);
        uint8_t top    = doErase ? (uint8_t)xs() : (uint8_t)(xs() % 0x40u);
        c.A = bottom;
        pre[0x007Fu] = top;                                  /* span_line_cursor */
        if (doErase) erase++;
        /* a line is shuddered only when top <= line < bottom */
        if (!doErase && top < bottom) shud++; else plain++;

        pre[0x0061u] = (t & 1) ? 0xFFu : 0x00u;              /* engine_running */
        if (t & 1) engineOn++;

        fail += diff_run("mirror_draw_car", pre, c, mirror_draw_car,
                         mirror_draw_car__t6502, mask, t, &printed);
    }

    /* Non-vacuity: both shudder arms, both engine states, the erase call mirrors_update makes,
       and enough wrapped runs that the $138 character-row step is actually compared. */
    if (shud == 0 || plain == 0) {
        printf("[VACUOUS] mirror_draw_car: the shudder gate went only one way (%d gated, "
               "%d plain)\n", shud, plain);
        fail++;
    }
    if (wrapped == 0) {
        printf("[VACUOUS] mirror_draw_car: no run wrapped past $00, so the $138 character-row "
               "step back was never reached\n");
        fail++;
    }
    if (engineOn == 0 || engineOn == cases) {
        printf("[VACUOUS] mirror_draw_car: engine_running was %s in every case\n",
               engineOn ? "set" : "clear");
        fail++;
    }
    if (erase == 0) {
        printf("[VACUOUS] mirror_draw_car: the erase call (bottom bound 0) was never made\n");
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only  "
           "(%d shuddered, %d plain, %d wrapped, %d engine on, %d erase)\n",
           "mirror_draw_car", cases, fail, shud, plain, wrapped, engineOn, erase);
    return fail;
}

void undraw_plot_lines(void);
void undraw_plot_lines__t6502(void);

/* ⭐ TWIN #165b — undraw_plot_lines ($511E).  The erase half of the dash needles: replay the undo
   list top entry down, writing each saved background byte back through its saved address, then
   empty the list.  Randomises the count across the whole list ($00-$28, including the empty-list
   early return at $5120) and plants each entry's address in the MODE 5 frame buffer ($3000-$7FFF),
   which is where the plotter's own pointers always point.

   ⚠ That address range is not decoration, it is the twin's correctness argument under test: the
   core keeps the walk's pointer in a uint16_t and writes plot_ptr $70/$71 only once, with entry
   0's address, so a saved pointer that ALIASED $70 or $71 would make the two seams diverge.  It
   cannot: plot_undo_ptr is plot_ptr ORed with a Y offset and plot_ptr is a screen address.  A
   slice deliberately plants entries that alias EACH OTHER so the replay order is compared too --
   restoring top-down is what makes overlapping strokes come back in the right order. */
static int test_undraw_plot_lines(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("undraw_plot_lines");
    if (!want("undraw_plot_lines")) return 0;

    /* A/X/Y and N/Z are the loop's residue and the shim reproduces them: the one shipping caller
       falls straight into dial_needle_angle's 6502 entry. */
    unsigned mask = LIVE_A | LIVE_X | LIVE_Y | LIVE_N | LIVE_Z;
    int cases = 3000 * scale, empty = 0, full = 0, aliased = 0;

    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;

        uint8_t count = (t % 7u == 0u) ? 0u : (uint8_t)((xs() % 0x28u) + 1u);
        pre[0x0069u] = count;                      /* plot_undo_count */
        if (count == 0u) empty++; else if (count >= 0x20u) full++;

        int alias = (t % 5u == 0u);                /* a slice with entries writing the same cell */
        uint16_t shared = (uint16_t)(0x5000u + (xs() % 0x0800u));
        for (unsigned k = 0; k < 0x28u; k++) {
            uint16_t a = (alias && (k & 1u)) ? shared
                                             : (uint16_t)(0x3000u + (xs() % 0x5000u));
            pre[0x07A8u + k] = (uint8_t)a;         /* plot_undo_ptr_lo */
            pre[0x07D0u + k] = (uint8_t)(a >> 8);  /* plot_undo_ptr_hi */
            pre[0x0780u + k] = (uint8_t)xs();      /* plot_undo_byte */
        }
        if (alias && count >= 2u) aliased++;

        fail += diff_run("undraw_plot_lines", pre, c, undraw_plot_lines,
                         undraw_plot_lines__t6502, mask, t, &printed);
    }

    /* Non-vacuity: both arms of the $5120 branch, long lists, and the overlap slice. */
    if (empty == 0 || empty == cases) {
        printf("[VACUOUS] undraw_plot_lines: the empty-list early return at $5120 was taken "
               "%d of %d times\n", empty, cases);
        fail++;
    }
    if (full == 0) {
        printf("[VACUOUS] undraw_plot_lines: no case replayed a list of $20+ entries\n");
        fail++;
    }
    if (aliased == 0) {
        printf("[VACUOUS] undraw_plot_lines: the overlapping-entry slice never had 2+ entries, "
               "so replay ORDER was never compared\n");
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+NZ  "
           "(%d empty lists, %d long, %d overlapping)\n",
           "undraw_plot_lines", cases, fail, empty, full, aliased);
    return fail;
}

void text_script_interp(void);
void text_script_interp__t6502(void);

/* twin #165 — run a $FF-terminated text script.  Bytes: $00..$9F a character (vdu_char_def),
   $A0..$C7 N spaces (print_spaces, N=byte-$A0), $C8..$FD recurse into sub-script byte-$C8,
   $FE run select_text_variant, $FF end.  math_lo ($74) is the command operand (reader-nat).
   The oracle recurses via the PLAIN name (native), so ONLY its top frame pushes X/Y to the 6502
   mem-stack — with entry S=$FF that is exactly $01FE/$01FF, which the differential ignores.
   Every script index (0..$36, plus $21 that select_text_variant enters) points at a LEAF script
   (chars + spaces + $FF) so recursion is bounded at depth 2.  The TOP script carries every byte
   class each case, so char / space / recurse-command / variant-command / terminate all run. */
static int test_text_script_interp(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("text_script_interp");
    if (!want("text_script_interp")) return 0;

    unsigned mask = LIVE_NONE;                    /* both callers return straight after — regs dead */
    static const uint16_t IGN[] = { 0x01FEu, 0x01FFu };  /* top oracle frame's PHA/PHA residue */

    const unsigned TOP     = 0x0C00u;            /* the top script bytes */
    const unsigned LEAF    = 0x0D00u;            /* the one leaf every sub-script index points at */
    const unsigned LEAF_NS = 0x0E00u;            /* a no-space leaf (index $10) — leaves math_lo == sub */
    /* ⚠ text_script_ptr_lo ($3AD0) physically OVERLAPS char_row_addr_hi ($3B06) from index $36 on:
       $3AD0+$36 == $3B06.  The engine only ever looks up script indices 0..$35 (a command byte is
       $C8..$FD -> sub 0..$35; $FE is the special variant), so the overlap is dead in the real
       binary.  The fixture must respect it — every script index it seeds MUST stay <= $35, or its
       pointer-table byte lands on char_row_addr_hi[0..7] ($3B06..$3B0D), the emitter reads a $00
       base, plots into zero page, and the glyph writes corrupt the tables (a fixture-only runaway
       the real routine never has).  So TOP_IDX and every recurse target live in 0..$35. */
    const uint8_t  TOP_IDX = 0x35u;              /* the top-script index — the HIGHEST legal one, and
                                                    reserved: recurse-commands pick 0..$34, never it */

    int sawChar = 0, sawSpace = 0, sawCmd = 0, sawVariant = 0, sawMos = 0, sawBmp = 0;

    int cases = 3000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                                  /* text path, not a SED site */
        c.S = 0xFFu;                              /* pin the stack so the oracle's PHA lands at $01FE/$01FF */
        c.X = TOP_IDX;                            /* the script index (entry ABI: X) */

        /* MODE-5 cursor into real screen RAM so the bitmap emitter never walks into scratch
           (see the print_spaces fixture — a stray plot_ptr would clobber math_lo). */
        { int r; for (r = 0; r < 8; r++) pre[0x3B06 + r] = 0x58u; }  /* char_row_addr_hi -> screen */
        pre[0x62CDu] &= 0x3Fu;                     /* vdu_char_row 0..7 */
        pre[0x62CCu] = (uint8_t)(xs() & 0x1Fu);    /* vdu_char_column, leave room to advance */
        /* The bitmap emitter writes through plot_ptr ($70/$71) and backs it DOWN $0140 per char
           it emits.  The pointer tables ($3AD0/$3B50) sit at a FIXED low address the routine
           hard-codes, so a long enough emit run drifts plot_ptr down onto them, turns a benign
           script byte into a command, and recursion runs away — a fixture hazard the real routine
           never hits (its screen and scripts don't overlap like this).  So the bitmap arm runs
           only NON-RECURSIVE scripts with a tiny emit budget, and pins plot_ptr near the top of
           screen RAM; the OSWRCH arm (no screen writes at all) carries the recursive variety. */
        pre[0x0070u] = 0x00u; pre[0x0071u] = 0x7Eu;   /* plot_ptr = $7E00 */
        int viaMos = (t % 8u) != 0u;                  /* mostly OSWRCH; every 8th case is bitmap */
        if (viaMos) { pre[0x0064u] |= 0x80u; sawMos = 1; }   /* text_out_via_mos bit 7: OSWRCH arm */
        else        { pre[0x0064u] &= 0x7Fu; sawBmp = 1; }   /* ...or the bitmap arm */

        /* Point every legal script index (0..$34 — a recurse-command's sub range, and $21 that
           select_text_variant enters) at the leaf, so any recursion is one level and terminates.
           $34 is the ceiling: index $35 is TOP, and $36+ would collide with char_row_addr_hi. */
        { unsigned i; for (i = 0; i <= 0x34u; i++) {
            pre[0x3AD0u + i] = (uint8_t)(LEAF & 0xFFu);
            pre[0x3B50u + i] = (uint8_t)(LEAF >> 8);
        } }
        /* ...but the TOP index ($35) points at the top script.  Its LO byte is $3B05, one below
           char_row_addr_hi[0] ($3B06), so it does not disturb the emitter's row table. */
        pre[0x3AD0u + TOP_IDX] = (uint8_t)(TOP & 0xFFu);
        pre[0x3B50u + TOP_IDX] = (uint8_t)(TOP >> 8);
        /* Re-assert char_row_addr_hi[0..7] AFTER the fill, in case a future index change overlaps. */
        { int r; for (r = 0; r < 8; r++) pre[0x3B06 + r] = 0x58u; }

        /* The leaf: a couple of chars and a short space run, terminated. */
        { unsigned p = LEAF;
          pre[p++] = (uint8_t)(0x41u + (xs() % 0x20u));   /* a char */
          pre[p++] = (uint8_t)(0xA1u + (xs() % 7u));      /* 1..7 spaces (never $A0 = 256, which via
                                                             the bitmap arm would emit 256 chars) */
          pre[p++] = (uint8_t)(0x41u + (xs() % 0x20u));   /* another char */
          pre[p++] = 0xFFu; }

        /* A no-space leaf, and index $10 points at it.  A char run touches nothing in math_lo
           ($74), so a command that recurses HERE leaves math_lo holding its sub — the only way to
           make the command's `math_lo = sub` write the FINAL value (a space run resets it to 0),
           which is what proves the reader-nat cell is byte-exact (drop the write -> mismatch). */
        pre[0x3AD0u + 0x10u] = (uint8_t)(LEAF_NS & 0xFFu);
        pre[0x3B50u + 0x10u] = (uint8_t)(LEAF_NS >> 8);
        { unsigned p = LEAF_NS;
          pre[p++] = (uint8_t)(0x41u + (xs() % 0x20u));   /* a char, no space run */
          pre[p++] = (uint8_t)(0x41u + (xs() % 0x20u));   /* another char */
          pre[p++] = 0xFFu; }

        if (!viaMos) {
            /* Bitmap arm: a SHORT, non-recursive script — char, 1 space, char, end.  Exercises the
               core's plain-char bitmap branch (`else vdu_char_def_core`) and a small space run with
               a bounded ~3-emit descent that never reaches the tables. */
            unsigned p = TOP;
            pre[p++] = (uint8_t)(0x41u + (xs() % 0x20u));   /* a char (< $A0) */
            pre[p++] = 0xA2u;                               /* 1 space */
            pre[p++] = (uint8_t)(0x41u + (xs() % 0x20u));   /* a char */
            pre[p++] = 0xFFu;
            sawChar = 1; sawSpace = 1;
        } else {
            /* OSWRCH arm: one of every byte class, order shuffled a little by t, terminated —
               char (< $A0), spaces ($A0..$C7), recurse-command ($C8..$FC, sub 0..$34), and on
               some cases the variant command $FE.  No screen writes, so recursion is safe. */
            unsigned p = TOP;
            if ((t % 4u) == 0u) {
                /* math_lo-final shape: a command into the no-space leaf, then end.  Exit math_lo
                   == the command's sub ($10), so the reader-nat cell's exit value is under test. */
                pre[p++] = (uint8_t)(0xC8u + 0x10u);                  /* recurse into LEAF_NS */
                pre[p++] = 0xFFu;
                sawCmd = 1;
            } else {
                uint8_t ch    = (uint8_t)(0x20u + (xs() % 0x60u));    /* $20..$7F */
                uint8_t spc   = (uint8_t)(0xA1u + (xs() % 7u));       /* 1..7 spaces */
                uint8_t rsub  = (uint8_t)(xs() % 0x35u);              /* 0..$34 (never $35=TOP) */
                uint8_t rcmd  = (uint8_t)(0xC8u + rsub);              /* recurse into leaf */
                int variant   = (t & 2) ? 1 : 0;
                switch (t & 3) {
                  case 1: pre[p++] = spc; pre[p++] = rcmd; pre[p++] = ch;  break;
                  case 2: pre[p++] = rcmd; pre[p++] = ch;  pre[p++] = spc; break;
                  default:pre[p++] = ch;  pre[p++] = rcmd; pre[p++] = spc; break;
                }
                if (variant) { pre[p++] = 0xFEu; sawVariant = 1; }
                pre[p++] = 0xFFu;
                sawChar = 1; sawSpace = 1; sawCmd = 1;
            }
        }

        set_ignore(IGN, 2);
        fail += diff_run("text_script_interp", pre, c, text_script_interp,
                         text_script_interp__t6502, mask, t, &printed);
        set_ignore(0, 0);
    }

    /* Non-vacuity: every byte class actually ran, and both output arms were exercised. */
    if (!sawChar || !sawSpace || !sawCmd) {
        printf("[VACUOUS] text_script_interp: a byte class never ran (char %d space %d cmd %d)\n",
               sawChar, sawSpace, sawCmd);
        fail++;
    }
    if (!sawVariant) {
        printf("[VACUOUS] text_script_interp: the $FE variant command never ran\n");
        fail++;
    }
    if (!sawMos || !sawBmp) {
        printf("[VACUOUS] text_script_interp: only one output arm ran (OSWRCH %d bitmap %d)\n",
               sawMos, sawBmp);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  result-only  "
           "(char/space/cmd/variant %d/%d/%d/%d, arms mos %d bmp %d)\n",
           "text_script_interp", cases, fail,
           sawChar, sawSpace, sawCmd, sawVariant, sawMos, sawBmp);
    return fail;
}

void menu_wait_key(void);
void menu_wait_key__t6502(void);
void platform_test_key_schedule(const unsigned char* codes, int n);  /* mode-4 clock schedule */

/* --------------------------------------------------------------------------
   $6571 menu_wait_key — the front-end menu selector (src/gen/revs_native.c twin #166).

   The reader-nat target is math_hi ($75): `count` arrives in X, is stored there, and is read
   back twice (the scan's start index, the highlight loop's ceiling) ACROSS the child calls
   FUN_3261 and text_script_interp — so the twin reads the cell directly, never caching, the
   #159-CRUX-safe form.  This is the LAST shipping reader in the wide-value cleanup.

   THE MULTI-FRAME POLL, and how a static keyboard cannot drive it.  menu_wait_key renders and
   polls in a loop and only returns when SPACE (menu_key_tbl[0]) is held AFTER a non-zero row was
   already selected (shared_temp_77 latched to $1E on the first pick).  A one-shot key set can
   never "press a second key later", so the fixture drives the mode-4 CLOCK SCHEDULE
   (platform_test_key_schedule + the tick clock): keyDown reports held iff the code matches this
   phase's schedule slot, indexed by the tick clock, which advances one per loop iteration.  The
   clock cell lives in mem[] and diff_run resets mem[] from `pre` before each model run, so both
   models see the identical phase sequence.

   Two hazards pinned by construction:
     * FUN_3261 (called every iteration) does TXS + re-enter front_end_menus when mem[$1C] bit 7 is
       CLEAR (the SHIFT+f0 restart) — an unbounded re-entry the fixture must not trigger, so $1C
       bit 7 is pinned SET (FUN_327d, the no-op arm).  SHIFT ($FF) and f0 ($86) must also never be
       reported held; the schedule only ever holds a menu_key_tbl code or the 0x01 "nothing" slot.
     * text_script_interp($1E) runs once on the first pick; script $1E is pointed at a lone $FF
       byte so it returns immediately (no glyph plotting, no char_row setup) — a safe no-op.

   Exit ABI: X is live (every caller reads the confirmed selection) -> LIVE_X. */
static int test_menu_wait_key(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("menu_wait_key");
    if (!want("menu_wait_key")) return 0;

    unsigned mask = LIVE_X;                       /* exit X = confirmed selection - 1 */

    const uint16_t CLOCK = 0x0080u;              /* the phase clock: scratch zero page, untouched by the loop */
    /* menu_key_tbl codes: distinct, and none is $FF (SHIFT) or $86 (f0), which FUN_3261 tests. */
    static const uint8_t KEYTBL[4] = { 0xA0u, 0xA1u, 0xA2u, 0xA3u };

    platform_test_clock_addr(CLOCK);
    platform_test_tick_clock(1);

    int shape0 = 0, shape1 = 0, count2 = 0, count3 = 0;
    int selSeen[4] = {0,0,0,0};

    int cases = 4000 * scale;
    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;                                  /* not a SED site */
        c.N = xs()&1; c.V = xs()&1; c.Z = xs()&1; c.I = xs()&1; c.C = xs()&1;

        uint8_t count = (t & 1) ? 3u : 2u;        /* menu_key_tbl has 4 slots -> count in {2,3} */
        uint8_t sel   = (uint8_t)(1u + (xs() % count));  /* the row to pick, 1..count */
        c.X = count;                              /* entry ABI: count in X */
        if (count == 3u) count3++; else count2++;
        selSeen[sel]++;

        pre[CLOCK] = 0x00u;                       /* phase clock starts at 0 (scan sees it at 1) */
        pre[0x0075u] = 0xAAu;                     /* math_hi != count, so a dropped entry-store shows */
        pre[0x001Cu] |= 0x80u;                    /* FUN_3261 -> FUN_327d no-op (avoid the TXS restart) */

        /* menu_key_tbl ($39E0) */
        for (int i = 0; i < 4; i++) pre[0x39E0u + i] = KEYTBL[i];

        /* script $1E -> a lone $FF byte at $2000, so text_script_interp($1E) is a no-op */
        pre[0x3AD0u + 0x1Eu] = 0x00u;             /* text_script_ptr_lo[$1E] */
        pre[0x3B50u + 0x1Eu] = 0x20u;             /* text_script_ptr_hi[$1E] -> $2000 */
        pre[0x2000u] = 0xFFu;

        /* the shared scratch/latch cells the routine drives, seeded to known values */
        pre[0x0076u] = (uint8_t)xs();             /* shared_temp_76 (overwritten by the scan) */
        pre[0x0077u] = (uint8_t)xs();             /* shared_temp_77 (cleared at entry) */
        pre[0x0078u] = (uint8_t)xs();             /* hypot_min_lo (set on the first pick) */

        unsigned char sched[4];
        int shape = t % 2;
        if (shape == 0) {
            /* pick then confirm: iter1 (clock 1) picks row `sel`, iter2 (clock 2) confirms */
            sched[0] = 0x01u;                     /* clock 0 (unused — scan first sees clock 1) */
            sched[1] = KEYTBL[sel];               /* clock 1: pick the row */
            sched[2] = KEYTBL[0];                 /* clock 2: SPACE -> confirm */
            platform_test_key_schedule(sched, 3);
            shape0++;
        } else {
            /* space-first: iter1 SPACE with nothing shown -> redraw ($6591-$6593), then pick, then confirm */
            sched[0] = 0x01u;
            sched[1] = KEYTBL[0];                 /* clock 1: SPACE, shared_temp_77==0 -> redraw */
            sched[2] = KEYTBL[sel];               /* clock 2: pick the row */
            sched[3] = KEYTBL[0];                 /* clock 3: SPACE -> confirm */
            platform_test_key_schedule(sched, 4);
            shape1++;
        }

        fail += diff_run("menu_wait_key", pre, c, menu_wait_key,
                         menu_wait_key__t6502, mask, t, &printed);
    }

    /* Non-vacuity: both counts, both schedule shapes, and every selectable row were exercised. */
    if (!shape0 || !shape1 || !count2 || !count3 || !selSeen[1] || !selSeen[2] || !selSeen[3]) {
        printf("[VACUOUS] menu_wait_key: an arm never ran "
               "(shape0 %d shape1 %d, count2 %d count3 %d, sel1 %d sel2 %d sel3 %d)\n",
               shape0, shape1, count2, count3, selSeen[1], selSeen[2], selSeen[3]);
        fail++;
    }
    platform_test_tick_clock(0);
    platform_test_key_set_clear();                /* leave the backend in a known state */
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=X  "
           "(shape %d/%d, count %d/%d, sel %d/%d/%d)\n",
           "menu_wait_key", cases, fail, shape0, shape1, count2, count3,
           selSeen[1], selSeen[2], selSeen[3]);
    return fail;
}

static int test_view_paint_lines(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    unsigned long smcLegal, smcIllegal;
    int fail = 0, printed = 0, t;
    const int dense = 300, sparse = 300, illegal = 100;

    register_fixture("view_paint_lines");
    if (!want("view_paint_lines")) return 0;

    /* The trap path is real code in BOTH models and has to unwind identically, so it gets
       tested rather than avoided — which means Platform::smcUnhandled must count instead of
       abort.  The counter is then asserted below, both directions: zero over the legal
       cases (a pre-state that traps at once would compare nothing) and non-zero over the
       illegal ones (or they are not testing what they claim). */
    setenv("REVS_SMC_CONTINUE", "1", 1);
    g_smcUnhandled = 0;

    for (t = 0; t < dense + sparse; t++) {
        Cpu6502 c = zero_cpu();
        dash_pre(pre, t >= dense, 0);
        c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
        c.S = (uint8_t)(0xC0 + (xs() & 0x3F));
        c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1; c.I = xs() & 1;
        /* ⚠ D IS NOT RANDOMISED, and the reason is a real finding rather than convenience:
           $7F51's `SEC / SBC $3080,X` is BCD in decimal mode, and $F1 - $97 then computes
           $54 instead of $5A — a low byte that is not a unit boundary, so BOTH models trap
           and the case tests the trap instead of the sweep.  The 6502 never runs this in
           decimal mode (the MOS clears D on reset and every IRQ entry CLDs), and both
           models go through the same SBC macro, so nothing is being papered over. */
        c.D = 0;
        fail += diff_run("view_paint_lines", pre, c,
                         view_paint_lines, view_paint_lines__t6502, liveMask, t, &printed);
    }
    smcLegal = g_smcUnhandled;

    for (t = dense + sparse; t < dense + sparse + illegal; t++) {
        Cpu6502 c = zero_cpu();
        dash_pre(pre, t & 1, 1);
        c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
        c.S = (uint8_t)(0xC0 + (xs() & 0x3F));
        c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1; c.I = xs() & 1;
        c.D = 0;
        fail += diff_run("view_paint_lines", pre, c,
                         view_paint_lines, view_paint_lines__t6502, liveMask, t, &printed);
    }
    smcIllegal = g_smcUnhandled - smcLegal;
    unsetenv("REVS_SMC_CONTINUE");

    if (smcLegal != 0) {
        printf("[VACUOUS] view_paint_lines: %lu SMC traps over the %d LEGAL cases — the "
               "pre-state is not a legal overlay state, so those cases compared little\n",
               smcLegal, dense + sparse);
        fail++;
    }
    if (smcIllegal == 0) {
        printf("[VACUOUS] view_paint_lines: 0 SMC traps over the %d ILLEGAL cases — the "
               "trap path was never reached\n", illegal);
        fail++;
    }
    /* The twin answers "is this address a unit / a unit+$05 / an opcode slot" out of two
       256-byte tables instead of the oracle's forty-entry search, which is only equivalent
       while no address means two things.  The twin counts every clash as it builds them; a
       counter nobody reads is not a safeguard, so the harness asserts it. */
    if (g_viewTableCollisions != 0) {
        printf("[BROKEN] view_paint_lines: %lu address-table collisions — a unit start and "
               "another unit's +$05 (or slot) share an address, so the one-answer lookup is "
               "not equivalent to the oracle's first-match search\n", g_viewTableCollisions);
        fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXYS+flags  "
           "(%lu traps in %d illegal cases)\n",
           "view_paint_lines", dense + sparse + illegal, fail, smcIllegal, illegal);
    return fail;
}

/* ==========================================================================
   $24F6 build_track_geometry and $1A20 draw_road — THE VIEW PIPELINE'S PRODUCERS
   --------------------------------------------------------------------------
   Both are short DRIVERS over long transliterated subtrees (road_edge_start / road_edge_walk
   / project_point, and fill_line_attr / draw_surface_spans / mark_line_surfaces /
   interp_edge), so a randomised pre-state exercises far more code than the twin itself —
   which is the point: the twin's whole job is to hand those callees the same registers, in
   the same order, off the same cells.  A wrong argument shows up as a mem[] avalanche.

   ⚠ build_track_geometry is SELF-MODIFYING at $2538 and $2542, and both sites are EXITS on
   an unrecognised byte.  Random bytes there would trap in almost every case and compare
   almost nothing, so the instruction shapes are planted: Silverstone's own bytes, an
   expansion circuit's `JSR <hook>` rewrite, and — deliberately — garbage, so the trap path
   is tested rather than avoided.
   ========================================================================== */
void build_track_geometry(void);
void build_track_geometry__t6502(void);
void draw_road(void);
void draw_road__t6502(void);

enum { GEO_SILVERSTONE = 0, GEO_HOOKED = 1, GEO_GARBAGE = 2 };

/* ⭐⭐ AND THE SECOND THING: the geometry subtree is self-modifying too, and a random byte at
   one of ITS sites is not a hang but an EXIT — road_edge_start traps at $231A and returns
   without ever reaching the projection loop, so horizon_extent comes back 0 and the whole
   horizon half of build_track_geometry is never exercised.  (Measured: extent was $00 in
   every case of the first attempt, and two sabotages passed because of it.)  These are the
   disassembly's own bytes for the sites road_edge_start / road_edge_walk dispatch on. */
static void plant_geometry_smc(uint8_t* pre)
{
    pre[0x231A] = 0xF0; pre[0x231B] = 0x0F;                      /* BEQ $232B */
    pre[0x248B] = 0xB0; pre[0x248C] = 0x2B;                      /* BCS $24B8 */
    pre[0x248D] = 0x4C;                                          /* JMP $2403 */
    pre[0x24DE] = 0x20; pre[0x24DF] = 0xF3; pre[0x24E0] = 0x12;  /* JSR $12F3 */
    pre[0x24E9] = 0xC9; pre[0x24EA] = 0x0E;                      /* CMP #$0E  */
    pre[0x24F2] = 0x20; pre[0x24F3] = 0x0B; pre[0x24F4] = 0x14;  /* JSR $140B */
    /* ⭐ ADDED with the road_edge_* fixtures below, and it is a coverage fix for THIS fixture
       too: emit_edge_width_offset runs on to $261E, so its own SMC site is reachable from
       every walk — and an unplanted one is a trap, i.e. an early return in both models with
       nothing left to compare.  `STA $1F / STY $51`, the frame's horizon record. */
    pre[0x261A] = 0x85; pre[0x261B] = 0x1F;                      /* STA horizon_extent */
    pre[0x261C] = 0x84; pre[0x261D] = 0x51;                      /* STY horizon_index  */
}

/* ⭐ THE ONE THING A RANDOM PRE-STATE MUST NOT BE ALLOWED TO DO, and it is not about these
   twins: the span plotters at $2C00-$2FFF are self-modifying CHAINS whose backward branch
   offsets they load out of the tables at $3E50 and $40D0 ($2D17/$2D9A: `LDA table,X / STA
   <branch operand>`).  A random byte there is a branch to ITSELF — the oracle spins forever
   inside FUN_2d17 and the harness never returns.  (Found by sampling a hung run, not by
   reading: case 5 of the first draw_road attempt.)  Both offset tables are therefore planted
   with $00, i.e. "run the chain from the top", which is legal by construction: every target
   is forward, so every chain terminates.  Everything else stays random — the plotters are
   identical code in both models and are not what these fixtures compare. */
static void plant_plotter_chains(uint8_t* pre)
{
    memset(pre + 0x3E50, 0x00, 0x100);
    memset(pre + 0x40D0, 0x00, 0x100);
}

static void geometry_pre(uint8_t* pre, int shape)
{
    fill_random(pre);
    plant_plotter_chains(pre);

    plant_geometry_smc(pre);
    /* ⭐ BOUNDARY STEERING, and both halves of it are load-bearing:

       horizon_index reaches the twin's own arithmetic straight out of the pre-state, so its
       two boundaries ($28, where the wrap fires, and $4F, where the extent is clamped) are
       drawn explicitly rather than left to 1-in-256 luck.  A uniform byte let an off-by-one
       wrap threshold PASS 400 cases.

       horizon_index_prev is held to 0..8 in a third of the cases because road_edge_start
       clamps the extent down to 7 whenever it is larger ($23B2) — with a uniform byte that
       happens 248 times in 256 and the extent is 7 in every single case, which is what hid
       the $4F clamp and the second edge_y store. */
    { static const uint8_t edge[] = { 0x00, 0x27, 0x28, 0x29, 0x4E, 0x4F, 0x50, 0xFF };
      pre[0x51] = edge[xs() % (sizeof edge)];
      if (xs() % 3 == 0) pre[0x52] = (uint8_t)(xs() % 9); }
    /* edge_nearest's LOW lane, which $24FD-$24FF deliberately does NOT arm — only the high one
       gets $FF, so the low lane enters the walk holding the previous frame's value.  Drawn at the
       extremes rather than left uniform.  ⚠ This does NOT make the surviving low lane observable
       and is not claimed to: see the measurement at the relocation in revs_native.c. */
    { static const uint8_t low[] = { 0x00, 0x01, 0x7F, 0x80, 0xFE, 0xFF };
      pre[0x10] = low[xs() % (sizeof low)]; }
    if (shape == GEO_SILVERSTONE) {
        pre[0x2538] = 0x99; pre[0x2539] = 0x48; pre[0x253A] = 0x5F;  /* STA $5F48,Y */
        pre[0x2542] = 0x20; pre[0x2543] = 0x50; pre[0x2544] = 0x34;  /* JSR abs8    */
        pre[0x2545] = 0x4A;                                          /* LSR A       */
    } else if (shape == GEO_HOOKED) {
        /* what an expansion circuit's ModifyGameCode leaves behind: a call into its own
           hook block in place of each site, and a NOP where the LSR was */
        pre[0x2538] = 0x20; pre[0x2539] = 0x22; pre[0x253A] = 0x5A;  /* JSR $5A22 */
        pre[0x2542] = 0x20; pre[0x2543] = 0x50; pre[0x2544] = 0x34;
        pre[0x2545] = 0xEA;
    }
    /* GEO_GARBAGE: whatever fill_random left — the trap arms */
}

/* $253B-$2549 recomputed from the POST state, which is the only end-to-end proof that the
   twin reached its tail: nothing but the tail writes horizon_half_width, and nothing writes
   the edge arrays after it reads them. */
static int geometry_tail_ran(const uint8_t* post)
{
    unsigned p    = post[0x0052];                       /* horizon_index_prev = the point */
    unsigned diff = (post[0x5E90 + p] - post[0x5EB8 + p]) & 0xFF;
    if (diff & 0x80) diff = (diff ^ 0xFF) + 1;          /* abs8 */
    return post[0x62FC] == (uint8_t)((diff & 0xFF) >> 1);
}

static int test_view_producers(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t;
    /* ⚠ The case counts are SMALL by the standards of the other fixtures (twin #2 runs 700)
       and the reason is measured, not arbitrary: a randomised pre-state sends the span walks
       into their worst case, so one case here costs milliseconds rather than microseconds.
       $REVS_VALIDATE_CASES scales all four for a deeper soak. */
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    const int legal = 200 * scale, hooked = 100 * scale, garbage = 100 * scale,
              road = 200 * scale;
    int tailRan = 0;

    register_fixture("build_track_geometry");
    register_fixture("draw_road");
    setenv("REVS_SMC_CONTINUE", "1", 1);

    if (want("build_track_geometry")) {
        for (t = 0; t < legal + hooked + garbage; t++) {
            int shape = t < legal ? GEO_SILVERSTONE
                      : t < legal + hooked ? GEO_HOOKED : GEO_GARBAGE;
            Cpu6502 c = zero_cpu();
            geometry_pre(pre, shape);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;   /* the 6502 never runs the engine in decimal mode — see twin #2 */
            /* build_track_geometry's exit N/V/Z/C are byproducts, not results: the last thing it
               does is horizon_half_width_at, whose subtract/LSR leave them, and the caller at
               $1710 opens LDA/SEC/SBC reading none.  The real outputs are all in mem[] (the edge
               arrays, horizon_extent/index, horizon_half_width) plus A/X/Y — those stay compared. */
            fail += diff_run("build_track_geometry", pre, c, build_track_geometry,
                             build_track_geometry__t6502, liveMask & ~LIVE_FLAGS, t, &printed);
            if (shape == GEO_SILVERSTONE && geometry_tail_ran((const uint8_t*)mem)) tailRan++;
        }
        if (tailRan == 0) {
            printf("[VACUOUS] build_track_geometry: not one of the %d Silverstone cases "
                   "reached the horizon_half_width tail — the SMC arm exited first\n", legal);
            fail++;
        }
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY (flags=byproduct)  "
               "(%d/%d reached the tail)\n", "build_track_geometry",
               legal + hooked + garbage, fail, tailRan, legal);
    }

    if (want("draw_road")) {
        int roadFail = 0;
        for (t = 0; t < road; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            plant_plotter_chains(pre);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            roadFail += diff_run("draw_road", pre, c, draw_road, draw_road__t6502,
                                 liveMask, t, &printed);
        }
        fail += roadFail;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags\n",
               "draw_road", road, roadFail);
    }

    unsetenv("REVS_SMC_CONTINUE");
    return fail;
}

/* ==========================================================================
   $46A1 apply_driving_model, $2AD1 draw_track_object, $1E15 fill_dash_edge_columns
   --------------------------------------------------------------------------
   The body's three remaining SHORT DRIVERS.  Like the view producers above, each one is a
   handful of instructions over a long transliterated subtree, so a randomised pre-state
   exercises far more code than the twin — and that is the point: the twin's job is to hand
   its callees the same registers off the same cells in the same order.

   ⭐ NONE OF THE THREE HAS A SELF-MODIFYING SITE OF ITS OWN, so there are no trap arms to
   test here.  What the pre-state has to do instead is stop the CALLEES from trapping, because
   an SMC trap is an early RETURN in both models and a returned-early pair compares almost
   nothing.  Three sites are reachable and all three are planted with Silverstone's own bytes:
   $1FE9 inside plot_object, and $44D5 / $45CB inside the last sub-model of the driving chain.
   ========================================================================== */
void apply_driving_model(void);
void apply_driving_model__t6502(void);
void draw_track_object(void);
void draw_track_object__t6502(void);
void fill_dash_edge_columns(void);
void fill_dash_edge_columns__t6502(void);

#define PRE_CAR_FLAGS_SHAPE   0x018C
#define PRE_OBJECT_BEARING_LO 0x0380
#define PRE_OBJECT_BEARING_HI 0x0398

static void plant_body_driver_smc(uint8_t* pre)
{
    pre[0x1FE9] = 0xA6;                       /* LDX horizon_extent — plot_object   */
    pre[0x44D5] = 0xB9;                       /* LDA abs,Y         — the $44EA tail */
    pre[0x45CB] = 0x0A; pre[0x45CC] = 0x26;   /* ASL A / ROL $77   — likewise       */
}

/* $46B8-$46CD recomputed from the POST state: road_speed and road_speed_frac have exactly
   ONE writer each in the whole engine ($46C0 and $46C4) and wheel_spin_rate's other two
   writers are not in this subtree, so this relation holding is proof the routine reached
   the speed split rather than exiting in a callee. */
static int speed_split_ran(const uint8_t* post)
{
    unsigned want = post[0x0063] ? post[0x0063] : (unsigned)(post[0x002E] & 0xF0);
    return post[0x0000] == want;
}

/* The four cells the object plotter is driven through, recomputed from the PRE state — the
   twin's whole output on the drawn path.  plot_object rewrites proj_width ($1FF4) and
   proj_width_shift but never plot_x / plot_line / plot_shape, which is why only those three
   are checked. */
static int object_block_ran(const uint8_t* pre, const uint8_t* post, uint8_t slot)
{
    unsigned lo   = (pre[PRE_OBJECT_BEARING_LO + slot] - pre[0x000A]) & 0x1FF;
    unsigned hi   = (pre[PRE_OBJECT_BEARING_HI + slot] - pre[0x000B] - (lo > 0xFF ? 1 : 0)) & 0xFF;
    unsigned row  = ((hi << 8) | (lo & 0xFF)) << 2;
    return post[0x0037] == (pre[PRE_CAR_FLAGS_SHAPE + slot] & 0x0F)
        && post[0x0035] == (uint8_t)(((row >> 8) & 0xFF) + 0x50)
        && post[0x0036] == pre[0x03B0 + slot];
}

/* Which of draw_track_object's three paths a case takes, decided from the PRE state: nothing
   the routine calls writes car_flags_shape, object_bearing or car_heading before the test. */
enum { OBJ_EMPTY = 0, OBJ_OFFSCREEN = 1, OBJ_DRAWN = 2 };
static int object_path(const uint8_t* pre, uint8_t slot)
{
    if (pre[PRE_CAR_FLAGS_SHAPE + slot] & 0x80) return OBJ_EMPTY;
    unsigned lo = (pre[PRE_OBJECT_BEARING_LO + slot] - pre[0x000A]) & 0x1FF;
    unsigned hi = (pre[PRE_OBJECT_BEARING_HI + slot] - pre[0x000B] - (lo > 0xFF ? 1 : 0)) & 0xFF;
    if (hi & 0x80) return hi >= 0xE0 ? OBJ_DRAWN : OBJ_OFFSCREEN;
    return hi < 0x20 ? OBJ_DRAWN : OBJ_OFFSCREEN;
}

/* Both of fill_dash_edge_columns' passes ran to completion: plot_ptr2 still holds the SECOND
   boundary table, and fill_edge_column_run's own two cells stopped where the second run's
   arguments said they would ($42 is the limit it was handed, $85 the column it stopped at). */
static int edge_columns_ran(const uint8_t* post)
{
    return post[0x0072] == 0x00 && post[0x0073] == 0x44
        && post[0x0042] == 0x22 && post[0x0085] == 0x22;
}

static int test_body_drivers(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    const int model = 200 * scale, object = 300 * scale, edges = 600 * scale;

    register_fixture("apply_driving_model");
    register_fixture("draw_track_object");
    register_fixture("fill_dash_edge_columns");
    setenv("REVS_SMC_CONTINUE", "1", 1);

    if (want("apply_driving_model")) {
        int subFail = 0, splitRan = 0, offPower = 0, onPower = 0;
        /* ⭐ model_accum_entry ($38/$39) is relocated out of mem[] into a native uint16_t
           (wide-value cleanup, mechanism B), but the cells are NOT ignored here: this routine's
           6502-ABI shim marshals the value back out, so the twin and the oracle still agree on
           them byte for byte.  Blunting the gate was the old way round. */
        for (t = 0; t < model; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            plant_plotter_chains(pre);
            plant_body_driver_smc(pre);
            /* ⭐ STEERED, and the reason is the twin's only branch: drive_state decides
               whether model_state elements 5..7 are zeroed, and it is compared against 2.
               A uniform byte takes the >= 2 arm 254 times in 256, so the ONE case that
               matters — a car under power — would be luck.  The three values the engine
               itself writes are 0, 1 and $7F. */
            { static const uint8_t st[] = { 0x00, 0x01, 0x02, 0x7F };
              pre[0x002D] = st[xs() % (sizeof st)]; }
            if (pre[0x002D] >= 2) offPower++; else onPower++;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;   /* the 6502 never runs the engine in decimal mode — see twin #2 */
            subFail += diff_run("apply_driving_model", pre, c, apply_driving_model,
                                apply_driving_model__t6502, liveMask, t, &printed);
            if (speed_split_ran((const uint8_t*)mem)) splitRan++;
        }
        set_ignore(0, 0);
        fail += subFail;
        if (splitRan == 0) {
            printf("[VACUOUS] apply_driving_model: not one of %d cases reached the speed "
                   "split — a callee trapped out first\n", model);
            fail++;
        }
        if (offPower == 0 || onPower == 0) {
            printf("[VACUOUS] apply_driving_model: the drive_state branch went only one way "
                   "(%d off power, %d on)\n", offPower, onPower);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d reached the speed split, %d/%d off power)\n", "apply_driving_model",
               model, subFail, splitRan, offPower, model);
    }

    if (want("draw_track_object")) {
        int subFail = 0, paths[3] = { 0, 0, 0 }, blockRan = 0;
        for (t = 0; t < object; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            plant_plotter_chains(pre);
            plant_body_driver_smc(pre);
            uint8_t slot = (uint8_t)(xs() % 24);   /* the 24 real object slots */
            /* Two thirds of the cases get an OCCUPIED slot: a uniform flag byte is empty
               half the time, and the empty path is three instructions long. */
            if (xs() % 3) pre[PRE_CAR_FLAGS_SHAPE + slot] &= 0x7F;
            /* ⭐⭐ AND SHAPE 9 IS EXCLUDED, WHICH IS NOT A CONVENIENCE.  plot_object's outer
               loop at $2002-$2027 repeats while $62F3 came back as 9 and mem[$0025] is
               positive, and $62F3 is re-stored from plot_shape at the top of every pass — so
               with plot_shape == 9 the pass is IDENTICAL each time round and the only way out
               is FUN_202a returning carry set.  On the real shape tables it does; on random
               bytes it need not, and the ORACLE spins forever with the twin never reached.
               (Found by sampling a 12-minute run, the same way the plotter chains were.)
               $0025 has exactly one writer in the engine and it is not in this subtree, so
               nothing inside the loop can break it. */
            if ((pre[PRE_CAR_FLAGS_SHAPE + slot] & 0x0F) == 0x09)
                pre[PRE_CAR_FLAGS_SHAPE + slot] ^= 0x01;
            int path = object_path(pre, slot);
            paths[path]++;
            c.A = (uint8_t)xs(); c.X = slot; c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            static uint8_t preCopy[65536];
            memcpy(preCopy, pre, sizeof preCopy);
            subFail += diff_run("draw_track_object", pre, c, draw_track_object,
                                draw_track_object__t6502, liveMask, t, &printed);
            if (path == OBJ_DRAWN && object_block_ran(preCopy, (const uint8_t*)mem, slot))
                blockRan++;
        }
        fail += subFail;
        if (paths[OBJ_EMPTY] == 0 || paths[OBJ_OFFSCREEN] == 0 || paths[OBJ_DRAWN] == 0) {
            printf("[VACUOUS] draw_track_object: one of the three paths was never taken "
                   "(%d empty, %d offscreen, %d drawn)\n",
                   paths[OBJ_EMPTY], paths[OBJ_OFFSCREEN], paths[OBJ_DRAWN]);
            fail++;
        }
        if (blockRan != paths[OBJ_DRAWN]) {
            printf("[BROKEN] draw_track_object: %d of %d drawn cases left the plotter's "
                   "argument block holding something other than what the pre-state says it "
                   "should — the twin and the oracle agree but both are wrong, or a callee "
                   "writes plot_x/plot_line/plot_shape after all\n",
                   paths[OBJ_DRAWN] - blockRan, paths[OBJ_DRAWN]);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d empty / %d offscreen / %d drawn, %d block-checked)\n",
               "draw_track_object", object, subFail,
               paths[OBJ_EMPTY], paths[OBJ_OFFSCREEN], paths[OBJ_DRAWN], blockRan);
    }

    if (want("fill_dash_edge_columns")) {
        int subFail = 0, ran = 0;
        for (t = 0; t < edges; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            plant_plotter_chains(pre);
            plant_body_driver_smc(pre);
            /* ⭐⭐ STEERED, AND THIS ONE IS WORTH READING.  Each column's walk runs from the
               scan line it is handed DOWN to dash_block_starts[column], and Y wraps: with a
               uniform byte there the start offset is above the first line 83% of the time, the
               walk goes all the way round 256, and it therefore covers the SAME SET of scan
               lines whatever line it started from — one write per line, each to its own
               address, so a WRONG START LINE produces byte-identical mem[].  A one-line
               sabotage of the second pass' start survived 60 cases and needed 480 to die.
               The real table is what fixes it, not more cases: dash_block_starts holds
               offsets into an $80-byte block and the data always ends at offset $4F
               (symbols.csv), so two thirds of the cases get a start in 0..$4F and the walk
               stops where it does in a real frame.  The rest stay uniform, which is what
               keeps the wrap path covered. */
            if (xs() % 3)
                for (int col = 0x03; col <= 0x22; col++)
                    pre[0x3900 + col] = (uint8_t)(xs() % 0x50);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            subFail += diff_run("fill_dash_edge_columns", pre, c, fill_dash_edge_columns,
                                fill_dash_edge_columns__t6502, liveMask, t, &printed);
            if (edge_columns_ran((const uint8_t*)mem)) ran++;
        }
        fail += subFail;
        /* ⚠ THE CASE COUNT IS A COMPROMISE IN BOTH DIRECTIONS.  Downward: each case walks up
           to 256 source bytes per column, for seventeen columns, twice over, through
           surface_colour_at.  Upward: this routine's output is SELF-HEALING.  Each of the
           eight iterations of a run writes one byte per scan line into the SAME boundary
           table, so only the last write to a line survives — and as soon as any later
           iteration's walk wraps past a line an earlier iteration got wrong, the two models
           reconverge.  The one-line start-of-run sabotage therefore shows up in ~3% of cases
           even with the table steered, which is what 600 is sized for. */
        if (ran != edges) {
            printf("[VACUOUS] fill_dash_edge_columns: %d of %d cases did not run both "
                   "passes to completion\n", edges - ran, edges);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d/%d ran both passes)\n",
               "fill_dash_edge_columns", edges, subFail, ran, edges);
    }

    unsetenv("REVS_SMC_CONTINUE");
    return fail;
}

void copy_dash_data(void);
void copy_dash_data__t6502(void);

/* ==========================================================================
   $18EA copy_dash_data — THE SECOND UNPACK / STOW  (twin #115)
   --------------------------------------------------------------------------
   No callees and no self-modifying site: it just swaps the tails of the 41 $80-spaced source
   blocks at $3000 with the $7768-$7FFF overlay page, forward to ASSEMBLE and (A bit7 set) in
   reverse to STOW BACK.  So the fixture randomises the BYTES being moved (all of $3000-$7FFF
   is left as fill_random left it), the per-block run lengths, and the direction; the whole
   output is mem[].

   ⭐ STEERED, and the reason is the address range, not a branch.  The two pointers are seeded
   from dash_ptr_init ($192F); a random seed would send the walk anywhere, including the
   $FC00-$FEFF hardware window, where the oracle's bus_write is logged on the hardware trace and
   the twin's direct mem[] store is not — a divergence that measures the seed, not the copy.  The
   real seed is fixed data (src $3000 / dst $7FB0) and dash_block_starts is static data always
   below $4F (symbols.csv), so both are planted with legal values and the copy provably stays in
   RAM.  A start offset >= $4F wraps the 6502's Y register through 256 offsets — reproduced
   faithfully by the twin's uint8_t counter — but is not a state real data can reach, so it is a
   DECLARED coverage limit rather than a case fed here.

   ⭐ SABOTAGE RECORD: direction not flipped (assemble writes the block, not the overlay);
   `dst -= bytes` -> `+=`; `src += $80` -> `+= $7F`; loop bound off by one (wrong byte count +
   wrong shared_temp_76); seed pointers not read; exit X left at $28.  Each must FAIL.
   ========================================================================== */
static int test_copy_dash_data(void)
{
    static uint8_t pre[65536];
    /* mem[] is the whole output; A/X/Y and flags are dead at both call sites (race_main_loop
       overwrites them immediately) but reproduced and checked anyway. */
    const unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS;
    const int cases = 800;
    int fail = 0, printed = 0;

    register_fixture("copy_dash_data");
    if (!want("copy_dash_data")) return 0;

    for (int t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        /* the engine's own seed: src $3000, dst base $7FB0 (block 0's last byte -> $7FFF) */
        pre[0x192F] = 0x00; pre[0x1930] = 0x30;
        pre[0x1931] = 0xB0; pre[0x1932] = 0x7F;
        /* legal per-block start offsets 0..$4E, so every run stays inside $3000-$7FFF */
        for (int b = 0; b < 0x29; b++) pre[0x3900 + b] = (uint8_t)(xs() % 0x4F);
        /* both directions each ~half the cases; low 7 bits random to prove only bit 7 matters */
        c.A = (uint8_t)((xs() & 0x7F) | ((t & 1) << 7));
        c.D = 0;
        fail += diff_run("copy_dash_data", pre, c, copy_dash_data,
                         copy_dash_data__t6502, liveMask, t, &printed);
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags\n",
           "copy_dash_data", cases, fail);
    return fail;
}

/* ==========================================================================
   $22FF road_edge_start, $23D2 road_edge_walk, $254A road_edge_side, $3450 abs8
   --------------------------------------------------------------------------
   build_track_geometry's OWN callees — the rest of the road-geometry producer.  Unlike the
   drivers above, three of these four carry real arithmetic: the near-slot bookkeeping and the
   horizon maximum (road_edge_start), the running nearest and the midpoint interpolation
   (road_edge_walk), the side/direction seeds (road_edge_side).

   ⚠ TWO SELF-MODIFYING SITES, and both are unlike the ones above: $231A is a BRANCH OFFSET,
   not an opcode, so the transliteration dispatches it into a switch over ~200 in-function
   targets while the twin recognises the only two bytes any circuit actually writes ($0F,
   Silverstone's skip, and $00, which every expansion circuit rewrites it to — `make
   track-patch`).  The offset is therefore PLANTED with one of those two in every case: a
   random third byte would send the two models to different addresses, which is a difference
   in the twin's declared coverage rather than in its behaviour.  The site's OPCODE is left
   random in a share of cases, because that arm traps identically in both models and is worth
   testing.  $248B is an ordinary extent and gets Silverstone's bytes, a circuit's `JMP
   <hook>` rewrite, and garbage.

   ⚠ AND THE PRE-STATE HAS TO BE STEERED, for the reason the view producers' note gives: the
   near-slot cells are compared against 6 as a sentinel, so a uniform byte takes the
   "nothing to do" arm 1 time in 256 and the re-base loop runs at most once in 249 of 256.
   Both are drawn from small sets instead.
   ========================================================================== */
void road_edge_start(void);
void road_edge_start__t6502(void);
void road_edge_walk(void);
void road_edge_walk__t6502(void);
void road_edge_side(void);
void road_edge_side__t6502(void);
void abs8(void);
void abs8__t6502(void);

enum { EDGE_SILVERSTONE = 0, EDGE_HOOKED = 1, EDGE_GARBAGE = 2 };

/* The near-slot cells: 0..5 are real slots, 6 is the "nothing to do" sentinel, and anything
   above is what a random byte would have given. */
static const uint8_t NEAR_SLOTS[] = { 0, 1, 2, 3, 4, 5, 6, 7, 0xFF };

static void edge_pre(uint8_t* pre, int shape)
{
    fill_random(pre);
    plant_plotter_chains(pre);
    plant_geometry_smc(pre);

    /* the $231A offset — see the header.  The opcode is left to the shape. */
    pre[0x231B] = (xs() & 1) ? 0x0F : 0x00;
    if (shape == EDGE_HOOKED) {
        pre[0x248B] = 0x4C; pre[0x248C] = 0xBC; pre[0x248D] = 0x56;   /* JMP $56BC */
    } else if (shape == EDGE_GARBAGE) {
        pre[0x231A] = (uint8_t)xs();                                  /* not a BEQ: trap */
        pre[0x248B] = (uint8_t)xs();
    }

    pre[0x0005] = NEAR_SLOTS[xs() % (sizeof NEAR_SLOTS)];   /* near_edge_first  */
    pre[0x0006] = NEAR_SLOTS[xs() % (sizeof NEAR_SLOTS)];   /* near_edge_last   */
    pre[0x0008] = NEAR_SLOTS[xs() % (sizeof NEAR_SLOTS)];   /* near_edge_cursor */
    /* near_edge_scroll_pending is non-zero in 255 bytes of 256, so the un-scrolled path
       needs drawing explicitly. */
    if (xs() % 3 == 0) pre[0x62F5] = 0x00;
    /* the $23B2 clamp compares horizon_index_prev against 7 — both sides of it, explicitly. */
    { static const uint8_t prev[] = { 0x00, 0x06, 0x07, 0x08, 0x40, 0xFF };
      pre[0x0052] = prev[xs() % (sizeof prev)]; }
    /* road_side_index indexes $306C/$306E/$3076 inside emit_edge_width_offset: 0 and 1 are
       the only values road_edge_side can produce, and a random byte reads unrelated bytes. */
    pre[0x0049] = (uint8_t)(xs() & 1);
    pre[0x0057] = (uint8_t)(xs() % 4);                      /* marker_count, 0..3 */
    /* the two seeds build_track_geometry hands the walk, half the time. */
    if (xs() % 2) pre[0x0011] = 0xFF;                       /* edge_nearest_hi      */
    if (xs() % 2) pre[0x0013] = 0x0D;                       /* edge_nearest_section */
    { static const uint8_t wrap[] = { 0x00, 0x78 };
      if (xs() % 3) pre[0x000E] = wrap[xs() & 1]; }         /* section_wrap_limit   */
}

/* ⭐⭐ TWO OF THESE TWINS HAVE A BOUNDARY A RANDOM PRE-STATE CANNOT REACH, and both were found
   by SABOTAGE passing, not by reading:

     road_edge_start's horizon tie-break fires only when the new point's projected line EQUALS
     horizon_extent and its slot EQUALS horizon_index.  ($238E BCC / $2390 BNE / $2392 CPX.)
     A `point > horizon_index` defect passed 200 cases.

     road_edge_walk's off-axis test compares |edge_x_hi[cursor]| against exactly $14, and that
     value is COMPUTED — emit_edge_bearing writes `bearing - car_heading`.  A $14 -> $15 defect
     passed 200 cases.

   Both are steered the same way, and it is legitimate because the quantity is a LINEAR
   function of one pre-state cell that nothing else in the subtree reads: run the ORACLE once
   on the pre-state, see where the value came out, then shift that cell so the real comparison
   runs with the boundary exactly on it.  (car_heading_hi appears only in emit_edge_bearing's
   subtraction; projected_line has one writer in the whole engine.) */
static void probe_oracle(const uint8_t* pre, Cpu6502 c, void (*t6502)(void))
{
    memcpy((void*)mem, pre, 65536);
    cpu = c;
    t6502();
}

static void steer_horizon_tie(uint8_t* pre, Cpu6502 c)
{
    pre[0x62F5] = 0x00;                             /* no scroll: the slot stays put */
    /* ⚠ AND THE RE-BASE PASS HAS TO BE OFF TOO.  rebase_edge_point writes horizon_extent AND
       horizon_index itself, so with it running the planted pair is gone by the time the
       tie-break reads them — the first version of this steer left it on and the sabotage
       still passed.  near_edge_last = 6 skips the pass; near_edge_first must then not be 6,
       or the routine returns before the projection. */
    pre[0x0006] = 0x06;
    if (pre[0x0005] == 0x06) pre[0x0005] = 0x00;
    if (pre[0x0008] > 0x05)  pre[0x0008] = (uint8_t)(xs() % 6);

    probe_oracle(pre, c, road_edge_start__t6502);
    pre[0x001F] = mem[0x008D];          /* horizon_extent = the line the new point projects to */
    /* horizon_index EITHER exactly the slot the point projects at, or one either side.  Both
       are needed: on the exact tie the store writes the values already in the cells and is
       unobservable (which is why `>=` -> `>` is not a defect at all), so it takes an index the
       tie-break must REJECT for the comparison's direction to show up in mem[]. */
    { int d = (int)(xs() % 3) - 1;
      pre[0x0051] = (uint8_t)(pre[0x0008] + d); }
}

/* The backward-direction ($2338) segment wrap adds segment_count_x8 back only when the
   subtraction borrows — i.e. exactly when (player_seg + 8) < span.  A `<` -> `<=` defect
   differs solely on the (player_seg + 8) == span boundary, which a random player_seg lands on
   once in 256 and the fixed stream never does.  Steer it there: force the backward branch, skip
   the re-base loop, and plant player_seg so base == span exactly, with a non-zero track length
   so the erroneous add is observable in near_segment_index. */
static void steer_segment_wrap(uint8_t* pre)
{
    pre[0x0025] |= 0x80u;                              /* track_direction: running backwards   */
    pre[0x0006]  = 0x06;                               /* near_edge_last = 6: skip the re-base  */
    if (pre[0x0005] == 0x06) pre[0x0005] = 0x00;       /* near_edge_first != 6: do not bail out */
    if (pre[0x59FA] == 0x00) pre[0x59FA] = 0x50;       /* segment_count_x8 != 0: the add shows  */
    unsigned span = (((6u - pre[0x0008]) & 0xFFu) << 3) & 0xFFu;
    pre[0x06FF]  = (uint8_t)((span - 8u) & 0xFFu);     /* (player_seg + 8) == span exactly      */
}

static void steer_off_axis(uint8_t* pre, Cpu6502 c, uint8_t firstPoint, uint8_t want)
{
    probe_oracle(pre, c, road_edge_walk__t6502);
    pre[0x000B] = (uint8_t)((int)pre[0x000B] + (int)mem[0x5E90 + firstPoint] - (int)want);
}

/* $23DB-$23E5 is a 16-bit compare and its LOW half only decides anything on an exact tie.
   Same trick from the other end: seed the running nearest with $FF — build_track_geometry's own
   value, so every point beats it — probe, and plant the minimum the walk actually found.  The
   point that found it then ties both bytes exactly. */
static void steer_nearest_tie(uint8_t* pre, Cpu6502 c)
{
    pre[0x0011] = 0xFF;
    probe_oracle(pre, c, road_edge_walk__t6502);
    pre[0x0010] = mem[0x0010];
    pre[0x0011] = mem[0x0011];
}

/* $235C `STY $04` is the ONLY writer of near_segment_index in the whole engine, so a post
   value that differs from the pre one proves the run got past both sentinels and the re-base
   loop into the segment arithmetic.  Equal values are a 1-in-256 false negative, which is why
   this is a counter and not a per-case assertion. */
static int start_reached_segment(const uint8_t* pre, const uint8_t* post)
{
    return post[0x0004] != pre[0x0004];
}

/* $2490 `STX $14` is likewise the only writer of walk_prev_section: it proves the walk
   emitted at least one point rather than subdividing or clipping out on the first. */
static int walk_emitted(const uint8_t* pre, const uint8_t* post)
{
    return post[0x0014] != pre[0x0014];
}

static int test_geometry_callees(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    /* ⭐ RESULTS, NOT DEAD EXIT FLAGS.  road_edge_start and road_edge_walk answer entirely in
       mem[] — the two edge lists, the marker list, edge_cursor, the horizon extent.  Their sole
       callers both overwrite the registers immediately (build_track_geometry does LDA #$FF at
       $24FD after road_edge_start, LDA $12 at $250F after road_edge_walk) and read no exit flag,
       so A/X/Y/N/V/Z/C on return are the interpreter's bookkeeping, not the routine's answer.
       They previously validated green only because the transliterated project_point they call
       LEFT those flags in cpu as a side effect; the clean project_point core returns a struct and
       no longer does, which is correct.  Keep S live — a stack leak is a real defect. */
    const unsigned resultMask = LIVE_S;
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    /* Sized like the view producers' for the same measured reason: a randomised pre-state
       sends the projection subtree into its worst case, so a case costs milliseconds. */
    const int startCases = 200 * scale, walkCases = 200 * scale,
              sideCases  = 400 * scale, absCases  = 800 * scale;

    register_fixture("road_edge_start");
    register_fixture("road_edge_walk");
    register_fixture("road_edge_side");
    register_fixture("abs8");
    setenv("REVS_SMC_CONTINUE", "1", 1);

    if (want("road_edge_start")) {
        int subFail = 0, reached = 0;
        for (t = 0; t < startCases; t++) {
            Cpu6502 c = zero_cpu();
            int shape = (t % 5 == 4) ? EDGE_GARBAGE : EDGE_SILVERSTONE;
            edge_pre(pre, shape);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            if (shape == EDGE_SILVERSTONE && t % 2 == 0)
                steer_horizon_tie(pre, c);                /* see the note above */
            else if (shape == EDGE_SILVERSTONE)
                steer_segment_wrap(pre);                  /* the backward-wrap boundary */
            subFail += diff_run("road_edge_start", pre, c, road_edge_start,
                                road_edge_start__t6502, resultMask, t, &printed);
            if (start_reached_segment(pre, (const uint8_t*)mem)) reached++;
        }
        fail += subFail;
        if (reached == 0) {
            printf("[VACUOUS] road_edge_start: not one of the %d cases reached the segment "
                   "arithmetic — every run took a sentinel or an SMC exit\n", startCases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=S (mem-only result)  "
               "(%d/%d reached the new point)\n",
               "road_edge_start", startCases, subFail, reached, startCases);
    }

    if (want("road_edge_walk")) {
        int subFail = 0, emitted = 0;
        /* road_edge_walk_subdivide's PHP/PLP (the arithmetic-shift sign stash) leaves a dead P
           byte at $01FF that its own PLP immediately discards; the clean core no longer performs
           the push, so ignore that residue as dead stack — same as the bearing leaves below. */
        static const uint16_t walkIgnore[] = { 0x01FFu };
        set_ignore(walkIgnore, 1);
        /* the two cursors build_track_geometry really passes, plus a random one */
        static const uint8_t FIRST[] = { 0x06, 0x2E };
        for (t = 0; t < walkCases; t++) {
            Cpu6502 c = zero_cpu();
            int shape = (t % 5 == 3) ? EDGE_HOOKED : (t % 5 == 4) ? EDGE_GARBAGE
                                                                  : EDGE_SILVERSTONE;
            edge_pre(pre, shape);
            c.A = (xs() % 3) ? FIRST[xs() & 1] : (uint8_t)xs();   /* the walk's firstPoint */
            c.X = (uint8_t)(xs() % 0xF0);                         /* ...and its section    */
            c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            /* a quarter of the cases put the FIRST emitted point's angle exactly on the $14
               off-axis boundary (the value the second point's test reads) and another quarter
               put the running nearest exactly on a point's distance.  See the note above. */
            if (shape == EDGE_SILVERSTONE && t % 4 == 0)
                steer_off_axis(pre, c, c.A, (xs() & 1) ? 0x14 : 0xEB);
            else if (shape == EDGE_SILVERSTONE && t % 4 == 2)
                steer_nearest_tie(pre, c);
            subFail += diff_run("road_edge_walk", pre, c, road_edge_walk,
                                road_edge_walk__t6502, resultMask, t, &printed);
            if (walk_emitted(pre, (const uint8_t*)mem)) emitted++;
        }
        fail += subFail;
        if (emitted == 0) {
            printf("[VACUOUS] road_edge_walk: not one of the %d cases emitted a point — "
                   "every run clipped out or subdivided on its first\n", walkCases);
            fail++;
        }
        set_ignore(0, 0);
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=S (mem-only result)  "
               "(%d/%d emitted a point)\n",
               "road_edge_walk", walkCases, subFail, emitted, walkCases);
    }

    if (want("road_edge_side")) {
        int subFail = 0, farSide = 0;
        for (t = 0; t < sideCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            /* the two values build_track_geometry passes are $00 and $80, and the arm taken is
               (A ^ track_direction) bit 7 — so both must be drawn, not left to a random A. */
            c.A = (xs() % 3) ? (uint8_t)((xs() & 1) ? 0x80 : 0x00) : (uint8_t)xs();
            c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            subFail += diff_run("road_edge_side", pre, c, road_edge_side,
                                road_edge_side__t6502, liveMask, t, &printed);
            if (mem[0x0049] != 0) farSide++;
        }
        fail += subFail;
        if (farSide == 0 || farSide == sideCases) {
            printf("[VACUOUS] road_edge_side: %d of %d cases took the far-side arm — one of "
                   "the two arms was never run\n", farSide, sideCases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d/%d far side)\n", "road_edge_side", sideCases, subFail, farSide, sideCases);
    }

    if (want("abs8")) {
        int subFail = 0, negated = 0, disagreed = 0;
        for (t = 0; t < absCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            /* ⭐ THE WHOLE POINT: the `BPL` at $3450 tests the CALLER's N, not bit 7 of A.
               A third of the cases DECORRELATE them, which is the only way that shows up. */
            c.N = (xs() % 3) ? (uint8_t)(c.A >> 7) : (uint8_t)(xs() & 1);
            c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            if (c.N != (c.A >> 7)) disagreed++;
            if (c.N) negated++;
            subFail += diff_run("abs8", pre, c, abs8, abs8__t6502,
                                liveMask, t, &printed);
        }
        /* ⭐ Deterministic negate boundaries: the CLC;ADC carry differs from a >=/> boundary
           slip ONLY at A==0x01 (sum lands exactly on 0xFF), and V only at A==0x80.  Both are
           ~0.5-expected in the random draw, so pin them (with N forced set → the negate runs).
           ⚠ ZERO xs() consumption here — no fill_random, no xs() for registers: abs8 touches only
           A and the flags, so pre[] carries over harmlessly, and the span fixtures downstream are
           stream-position-sensitive (see div16by8's note $ — perturbing xs() reshuffles the cases
           they draw and surfaces a road_span_plot A-liveness corner).  Fixed regs keep the stream. */
        {
            static const uint8_t edges[] = { 0x00, 0x01, 0x02, 0x7F, 0x80, 0x81, 0xFE, 0xFF };
            for (size_t e = 0; e < sizeof edges; e++) {
                Cpu6502 c = zero_cpu();
                c.A = edges[e]; c.X = 0; c.Y = 0;
                c.N = 1; c.V = (uint8_t)(e & 1); c.Z = (uint8_t)((e >> 1) & 1);
                c.C = (uint8_t)((e >> 2) & 1); c.D = 0;
                negated++; if (c.N != (c.A >> 7)) disagreed++;
                subFail += diff_run("abs8", pre, c, abs8, abs8__t6502,
                                    liveMask, absCases + (int)e, &printed);
            }
        }
        fail += subFail;
        if (negated == 0 || disagreed == 0) {
            printf("[VACUOUS] abs8: %d of %d cases negated, %d had N disagree with bit 7 — "
                   "both must be non-zero or the twin is untested\n",
                   negated, absCases, disagreed);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d negated, %d with N vs bit 7 decorrelated)\n",
               "abs8", absCases, subFail, negated, disagreed);
    }

    unsetenv("REVS_SMC_CONTINUE");
    return fail;
}

/* ==========================================================================
   $0C47 div16by8 — THE ENGINE'S DIVIDE
   --------------------------------------------------------------------------
   A leaf, and the whole of project_point's and bearing_to_section's callee set.  Its inputs
   are three bytes (A, math_lo, shared_temp_76) and its outputs are one byte plus A and the
   flags, so unlike every fixture above the pre-state that matters is TINY — which is exactly
   why it has to be STEERED rather than left uniform.  Four domains, and uniform bytes reach
   only the first:

     DIV_ENGINE    divisor with bit 7 set and a dividend high byte below it — the only shape
                   the game ever produces, because both callers normalise the divisor left
                   until it is >= $80 and branch to their degenerate arm on equal magnitudes.
     DIV_OVERFLOW  dividend high byte >= divisor.  The 8-bit quotient overflows and the
                   remainder invariant breaks, so the ninth-bit path ($0C4A `BCS`, which
                   subtracts WITHOUT comparing) runs repeatedly — untested otherwise, because
                   the engine's own shape reaches it at most once per call.
     DIV_ZERO      divisor 0.  Every step "fits", nothing is subtracted, the quotient is $FF.
                   ⚠ This is the case a `DIVU.W` implementation would TRAP on, so it is not a
                   hypothetical: it is the reason the twin is a loop.
     DIV_UNIFORM   fully random bytes, as the control.

   ⭐ AND THE DECIMAL FLAG IS RANDOMISED HERE, which no other fixture in this file does.  The
   subtract is an `SBC`, so in decimal mode the 6502 hands back a BCD-corrected byte that then
   feeds the next shift — the divide computes something else entirely, and the twin has to
   agree.  It can only do that by routing the subtract through the real SBC, which is the
   property this arm exists to pin down.
   ========================================================================== */
void div16by8(void);
void div16by8__t6502(void);

enum { DIV_ENGINE = 0, DIV_OVERFLOW = 1, DIV_ZERO = 2, DIV_UNIFORM = 3 };

static int test_div16by8(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    /* A leaf with no subtree — a case is microseconds, so this one is sized to sweep the
       input space rather than to fit a time budget. */
    const int divCases = 4000 * scale;
    int shaped[4] = { 0, 0, 0, 0 };
    int decimal = 0, restored = 0, unreduced = 0;

    register_fixture("div16by8");

    if (want("div16by8")) {
        int subFail = 0;
        for (t = 0; t < divCases; t++) {
            Cpu6502 c = zero_cpu();
            int shape = t % 4;
            uint8_t divisor, hi;

            fill_random(pre);
            switch (shape) {
            case DIV_ENGINE:
                divisor = (uint8_t)(0x80u | (xs() & 0x7Fu));
                hi      = (uint8_t)(xs() % divisor);          /* strictly below: no overflow */
                break;
            case DIV_OVERFLOW:
                divisor = (uint8_t)(1u + (xs() % 0xFFu));     /* 1..$FF */
                hi      = (uint8_t)(divisor + (xs() % (0x100u - divisor)));
                break;
            case DIV_ZERO:
                divisor = 0x00;
                hi      = (uint8_t)xs();
                break;
            default:
                divisor = (uint8_t)xs();
                hi      = (uint8_t)xs();
                break;
            }
            shaped[shape]++;

            pre[0x0076] = divisor;                            /* shared_temp_76 — the divisor */
            pre[0x0074] = (uint8_t)xs();                      /* math_lo — the dividend's low half */
            c.A = hi;                                         /* ...and its high half */
            c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            /* D = 0 always: div16by8 is on the render/geometry path, entered only with D clear
               (docs/static-map.md §Decimal mode), and its twin is now plain binary C.  The RNG
               draw that used to pick D is kept (result discarded) so pinning it does not shift
               the shared xs() stream for the stream-position-sensitive span fixtures that run
               after this group (road_span_plot_2). */
            (void)(xs() % 4);
            c.D = 0;
            (void)decimal;

            subFail += diff_run("div16by8", pre, c, div16by8, div16by8__t6502,
                                liveMask, t, &printed);

            /* Two behavioural counters, both about arms a byte diff alone would not name:
               `restored` is a case where one of the first seven steps subtracted, i.e. where
               the exit V flag has a source at all; `unreduced` is a case whose returned
               remainder is >= the divisor, which is only possible because the eighth step
               skips its restore. */
            if (cpu.V != c.V) restored++;
            if (divisor != 0 && cpu.A >= divisor) unreduced++;
        }
        fail += subFail;
        if (shaped[DIV_ENGINE] == 0 || shaped[DIV_OVERFLOW] == 0 || shaped[DIV_ZERO] == 0 ||
            restored == 0 || unreduced == 0) {
            printf("[VACUOUS] div16by8: engine=%d overflow=%d zero=%d "
                   "V-written=%d unreduced-remainder=%d — every one must be non-zero or an "
                   "arm of the divide was never run\n",
                   shaped[DIV_ENGINE], shaped[DIV_OVERFLOW], shaped[DIV_ZERO],
                   restored, unreduced);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d engine, %d overflow, %d div-by-0; %d wrote V, "
               "%d left an unreduced remainder)\n",
               "div16by8", divCases, subFail, shaped[DIV_ENGINE], shaped[DIV_OVERFLOW],
               shaped[DIV_ZERO], restored, unreduced);
    }

    return fail;
}


/* ==========================================================================
   $2147 bearing_to_section_from — THE BEARING   (twin #14)
   $2287 project_point_from      — THE PERSPECTIVE DIVIDE   (twin #15)
   --------------------------------------------------------------------------
   The road pass's two coordinate transforms.  Their inputs are as small as div16by8's — two
   registers and four table bytes each — so like that fixture these have to be STEERED, and
   for the same reason: uniform random 16-bit coordinates put almost every case in one arm.

   What has to be reached, and would not be by accident:

     bearing_to_section_from
       BEAR_A / BEAR_B    which of the two ground components is the larger, i.e. which OCTANT
                          arm runs.  Uniform bytes do reach both, but not the boundary.
       BEAR_EQUAL         |component 0| == |component 2| exactly — the 45-degree arm, which
                          takes the PHP/PLP door at $21B8 and never divides at all.
       BEAR_TIGHT         magnitudes within a few counts of each other, which is what makes
                          the normalised dividend catch up with the divisor and take the OTHER
                          door into the same arm ($21D1 / $2249).
       BEAR_UNIFORM       fully random coordinates, as the control.

     project_point_from
       PROJ_NEAR          height well inside point_dist: the surviving path, the divide, and
                          the reciprocal/exponent pair the width scale is made of.
       PROJ_CLIP_HI       height's high byte above point_dist's — the far clip's first door.
       PROJ_CLIP_LO       high bytes EQUAL and the low byte deciding — its second door, which
                          a uniform fixture reaches about once in 256.
       PROJ_ZERO_DIST     point_dist 0, which clips everything.  ⚠ It is also the case that
                          would spin forever in the normalise loop if the clip ever let it
                          through, so it is the fixture's proof that it cannot.
       PROJ_UNIFORM       the control.

   ⭐ BOTH RANDOMISE THE VIEW ORIGIN between the camera (Y = 0) and the road sign's displaced
   viewpoint (Y = 6), because that offset is the whole difference between these entries and
   the two-byte ones above them.

   ⭐ AND BOTH RANDOMISE DECIMAL MODE, for twin #13's reason one level up: the abs, the negate
   and the two closing adjustments are all ADC/SBC, so in decimal mode every one of them hands
   back a different byte.  It is also where the exit V comes from, and V is compared here even
   though no real call site reads it.
   ========================================================================== */
void bearing_to_section_from(void);
void bearing_to_section_from__t6502(void);
void project_point_from(void);
void project_point_from__t6502(void);

enum { BEAR_A = 0, BEAR_B = 1, BEAR_EQUAL = 2, BEAR_TIGHT = 3, BEAR_UNIFORM = 4, BEAR_SHAPES = 5 };
enum { PROJ_NEAR = 0, PROJ_CLIP_HI = 1, PROJ_CLIP_LO = 2, PROJ_ZERO_DIST = 3,
       PROJ_UNIFORM = 4, PROJ_SHAPES = 5 };

/* A section byte index the engine could really produce: one of the 40 sections' three-byte
   triples, or one of the two scratch slots past them. */
static uint8_t random_section_byte(void)
{
    unsigned r = xs() % 10u;
    if (r == 0) return 0xFAu;                    /* road_edge_walk's midpoint scratch */
    if (r == 1) return 0xFDu;                    /* road_edge_start's near-point scratch */
    return (uint8_t)(3u * (xs() % 40u));
}

/* Write one 16-bit section coordinate component, and the matching view-origin component, so
   that the delta the routine computes is exactly `delta`. */
static void stage_component(uint8_t* pre, uint8_t sectionByte, unsigned component,
                            uint8_t origin, int delta)
{
    unsigned org = (unsigned)(xs() & 0xFFFFu);
    unsigned sec = (unsigned)((int)org + delta) & 0xFFFFu;

    pre[0x6280 + origin + component] = (uint8_t)org;
    pre[0x6283 + origin + component] = (uint8_t)(org >> 8);
    pre[0x0900 + sectionByte + component] = (uint8_t)sec;
    pre[0x0A00 + sectionByte + component] = (uint8_t)(sec >> 8);
}

static int test_road_transforms(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    /* ⭐ RESULTS, NOT IMPLEMENTATION DETAILS.  Both routines are observed purely through the
       mem[] cells they fill (bearing_lo/hi, hypot_min/max, proj_width, projected_line, …); the
       6502 flags they leave behind are dead at every production call site (each core is called
       core-to-core, void or via a typed struct).  So neither declares N/V/Z/A/X/Y live — those
       are the interpreter's bookkeeping, not the routine's answer, and validating them would
       pin the twin to the transliteration's shape instead of its result.
         bearing_to_section: answer entirely in mem[] -> nothing but the stack-balance check.
         project_point:      answer in mem[] PLUS the clip decision the caller reads as carry. */
    const unsigned bearMask = LIVE_S;
    const unsigned projMask = LIVE_S | LIVE_C;

    register_fixture("bearing_to_section_from");
    register_fixture("project_point_from");

    if (want("bearing_to_section_from")) {
        const int cases = 4000 * scale;
        /* ⚠ THE ONE IGNORED CELL IN THIS FILE, and it is an idiom C does not have.  The
           oracle's sort brackets its four stores in PHP/PLP to carry the deciding compare's
           flags across them; the twin carries them in a variable, so the oracle leaves a
           status byte at $01FF that the twin does not.  S is $FF on entry and $FF on exit, so
           that byte is BELOW the stack pointer on return and provably dead — nothing reads it
           before the next push.  S itself stays declared live, so a real stack leak still
           fails, and the ignore is scoped to this fixture. */
        static const uint16_t bearIgnore[] = { 0x01FFu };
        int shaped[BEAR_SHAPES];
        int decimal = 0, diagonal = 0, tightDoor = 0, armA = 0, armB = 0, sixth = 0;
        int subFail = 0;
        for (t = 0; t < BEAR_SHAPES; t++) shaped[t] = 0;
        set_ignore(bearIgnore, 1);

        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            int shape = t % BEAR_SHAPES;
            uint8_t sectionByte, origin;
            int d0, d2, mag;

            fill_random(pre);
            sectionByte = random_section_byte();
            origin      = (xs() & 1) ? 0x06u : 0x00u;
            /* ⭐ THE ORIGIN IS ONE OF EXACTLY TWO ROWS, and that is structural, not incidental:
               view_origin holds two origins six bytes apart (origin 0 the camera, origin 6 the
               road sign) and all eleven production call sites pass either 0 or VIEW_ORIGIN_STRIDE
               — build_road_sign the 6, everything else the 0.  This fixture used to draw a fully
               random origin one case in eight, which merely read PAST the twelve bytes into
               $63xx in both models; with view_origin relocated to view_origin_16[9] the same case
               is out of bounds.  Dropping the arm narrows the fixture to the domain the engine
               actually has — the same call as constraining road_span_plot's random pointer to
               the screen buffers (docs/validation-harness.md).  The draw is kept so the shared
               PRNG stream stays aligned. */
            (void)xs();
            if (origin == 0x06u) sixth++;
            shaped[shape]++;

            switch (shape) {
            case BEAR_A:                       /* |component 2| strictly the smaller */
                mag = 1 + (int)(xs() % 0x4000u);
                d0  = (xs() & 1) ? mag : -mag;
                d2  = (int)(xs() % (unsigned)mag);
                if (xs() & 1) d2 = -d2;
                break;
            case BEAR_B:                       /* |component 0| strictly the smaller */
                mag = 1 + (int)(xs() % 0x4000u);
                d2  = (xs() & 1) ? mag : -mag;
                d0  = (int)(xs() % (unsigned)mag);
                if (xs() & 1) d0 = -d0;
                break;
            case BEAR_EQUAL:                   /* the 45-degree arm, all four diagonals */
                mag = (int)(xs() % 0x4000u);
                d0  = (xs() & 1) ? mag : -mag;
                d2  = (xs() & 1) ? mag : -mag;
                break;
            case BEAR_TIGHT:                   /* within a few counts — the other degenerate door */
                mag = 0x40 + (int)(xs() % 0x3F00u);
                d0  = mag;
                d2  = mag - (int)(xs() % 5u);
                if (xs() & 1) d0 = -d0;
                if (xs() & 1) d2 = -d2;
                break;
            default:
                d0 = (int)(short)(xs() & 0xFFFFu);
                d2 = (int)(short)(xs() & 0xFFFFu);
                break;
            }

            stage_component(pre, sectionByte, 0, origin, d0);
            stage_component(pre, sectionByte, 2, origin, d2);

            c.X = sectionByte;
            c.Y = origin;
            c.A = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            /* ⚠ D=0 BY THE GAME'S REGIME.  The perspective transform never runs in decimal
               mode — BCD coordinate math would garbage the view — so the twin computes in
               binary and the fixture pins D=0.  The real-trajectory proof is make
               determinism-drive, which drives Silverstone through this exact code. */
            c.D = 0;

            subFail += diff_run("bearing_to_section_from", pre, c, bearing_to_section_from,
                                bearing_to_section_from__t6502, bearMask, t, &printed);

            /* The census.  Which OCTANT arm ran is a property of the inputs — whichever ground
               magnitude is the larger becomes the divisor — so it is counted from the staged
               deltas rather than from the angle: the quadrant base would have separated the two
               arms only until the negate pushes an angle past $80.
               Whether the 45-degree arm ran is a property of the OUTPUT, because it has two
               doors: equal magnitudes, or a normalised dividend that caught the divisor.  The
               second is the one BEAR_TIGHT exists for, and `tightDoor` is the count that proves
               that door was actually opened. */
            {
                unsigned m0 = (unsigned)(d0 < 0 ? -d0 : d0);
                unsigned m2 = (unsigned)(d2 < 0 ? -d2 : d2);
                if (m2 < m0) armA++; else if (m2 > m0) armB++;
                if (mem[0x007E] == 0xFFu) {
                    diagonal++;
                    if (m0 != m2) tightDoor++;
                }
            }
        }
        set_ignore(0, 0);
        fail += subFail;
        (void)decimal;
        if (shaped[BEAR_EQUAL] == 0 || diagonal == 0 || tightDoor == 0 || armA == 0 ||
            armB == 0 || sixth == 0) {
            printf("[VACUOUS] bearing_to_section_from: diagonal=%d (of which %d by the "
                   "dividend-caught-divisor door) armA=%d armB=%d origin6=%d — "
                   "every one must be non-zero or an arm never ran\n",
                   diagonal, tightDoor, armA, armB, sixth);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=S (mem-only result)  "
               "(%d octant-A, %d octant-B, %d 45-degree of which %d not by equal magnitudes, "
               "%d off the sign origin)\n",
               "bearing_to_section_from", cases, subFail, armA, armB, diagonal, tightDoor,
               sixth);
    }

    if (want("project_point_from")) {
        const int cases = 4000 * scale;
        int shaped[PROJ_SHAPES];
        int decimal = 0, clipped = 0, survived = 0, overflowed = 0, below = 0, sixth = 0;
        int doorHi = 0, doorLo = 0;
        int subFail = 0;
        for (t = 0; t < PROJ_SHAPES; t++) shaped[t] = 0;

        /* ⚠ math_lo ($0074) is the quotient byte, and it is dead scratch on the clip path.  The
           real answer is projected_line ($008D) plus the clip carry; math_lo only feeds the line
           math on the SURVIVED path, where the twin's DIVU and the oracle's restoring divide
           agree bit-for-bit (quotient < $80).  On a QUOTIENT-OVERFLOW clip (a point at the far-
           clip boundary dividing to 256+), the two diverge — DIVU keeps the true value, the 6502
           divide left a saturated garbage byte — but the point is dropped and nothing reads the
           quotient of a dropped point before the next divide overwrites $0074.  The clip DECISION
           (carry) is checked and matches; the dead scratch byte is an implementation detail. */
        static const uint16_t projIgnore[] = { 0x0074u };
        set_ignore(projIgnore, 1);

        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            int shape = t % PROJ_SHAPES;
            uint8_t sectionByte, origin;
            unsigned dist, height;
            int d1;

            fill_random(pre);
            sectionByte = random_section_byte();
            origin      = (xs() & 1) ? 0x06u : 0x00u;
            (void)xs();          /* the off-domain arm is gone — see bearing_to_section above */
            if (origin == 0x06u) sixth++;
            shaped[shape]++;

            /* The height is compared and divided AFTER a >> 3, so the fixture picks the
               post-shift magnitude it wants and scales back up by 8. */
            /* ⚠ EVERY ARM STAYS UNDER $2000, because the delta staged below is height * 8 and
               has to fit in 16 bits.  Clamping AFTERWARDS instead — which is what this fixture
               did first — silently unpicks the relationship each arm was built to create, and
               the census read 25% clipped where the shapes asked for 60%. */
            switch (shape) {
            case PROJ_NEAR:
                dist   = 0x0100u + (xs() % 0x1F00u);
                height = xs() % dist;                        /* strictly inside: survives */
                break;
            case PROJ_CLIP_HI:                               /* high byte alone decides */
                dist   = 1u + (xs() % 0x1E00u);
                height = (dist & 0xFF00u) + 0x100u + (xs() % 0x100u);
                break;
            case PROJ_CLIP_LO:                               /* high bytes EQUAL, low decides */
                dist   = 0x0100u + (xs() % 0x1F00u);
                height = (dist & 0xFF00u) | ((dist & 0xFFu)
                                             + (xs() % (0x100u - (dist & 0xFFu))));
                break;
            case PROJ_ZERO_DIST:
                dist   = 0u;
                height = xs() % 0x2000u;
                break;
            default:
                dist   = xs() % 0x2000u;
                height = xs() % 0x2000u;
                break;
            }

            d1 = (int)(height * 8u + (xs() % 8u));
            if (xs() & 1) { d1 = -d1; below++; }
            stage_component(pre, sectionByte, 1, origin, d1);
            pre[0x007C] = (uint8_t)dist;                      /* point_dist_lo */
            pre[0x007D] = (uint8_t)(dist >> 8);               /* point_dist_hi */

            c.X = sectionByte;
            c.Y = origin;
            c.A = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;   /* binary regime — see bearing_to_section_from above */

            subFail += diff_run("project_point_from", pre, c, project_point_from,
                                project_point_from__t6502, projMask, t, &printed);

            /* The exit carry IS the routine's answer, so the census reads it directly.  An
               overflow exit is a carry-set case that still got as far as writing proj_width. */
            if (cpu.C) {
                clipped++;
                /* proj_width is only written past the clip, so a carry-set case that moved it
                   was rejected by the QUOTIENT rather than by the far clip. */
                if (mem[0x002A] != pre[0x002A]) overflowed++;
                /* Which far-clip door — the staged delta IS the delta the routine computes,
                   now that the regime is binary. */
                else {
                    if ((height >> 8) == (dist >> 8)) doorLo++; else doorHi++;
                }
            } else {
                survived++;
            }
        }
        set_ignore(0, 0);
        fail += subFail;
        (void)decimal;
        if (clipped == 0 || survived == 0 || overflowed == 0 || below == 0 ||
            sixth == 0 || doorHi == 0 || doorLo == 0) {
            printf("[VACUOUS] project_point_from: clipped=%d (%d by the high byte, %d by the "
                   "low) survived=%d quotient-overflow=%d below-eye-level=%d "
                   "origin6=%d — every one must be non-zero\n",
                   clipped, doorHi, doorLo, survived, overflowed, below, sixth);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=S+C (mem + clip carry)  "
               "(%d survived, %d clipped: %d on the high byte, %d on the low, %d on the "
               "quotient; %d below eye level, %d off the sign origin)\n",
               "project_point_from", cases, subFail, survived, clipped, doorHi, doorLo,
               overflowed, below, sixth);
    }

    return fail;
}


/* ==========================================================================
   $12A0 shift_near_edge_points, $12C8 clamp_near_edge_window,
   $12DC clamp_near_edge_cursor, $0BA2 rebase_edge_point, $1208 load_section_triple,
   $0CA5 point_distance_hypot, $23C0 emit_edge_bearing,
   $23BB emit_edge_bearing_at_cursor, $2565 emit_edge_width_offset
   --------------------------------------------------------------------------
   THE REST OF THE ROAD-GEOMETRY PASS (twins #16-#24).  Nine leaves, and their fixtures are
   cheap for the reason div16by8's is: the input that matters is a handful of zero-page cells,
   so the pre-state can be steered onto every boundary instead of hoping a random 64 KB lands
   on one.  What each one needs steering for:

     * THE NEAR-SLOT CELLS are compared against the sentinel 6 and clamped into [first, 5], so
       a uniform byte takes the interesting arm about once in 256.  Drawn from NEAR_SLOTS.
     * point_distance_hypot picks between two whole approximations on shared_temp_7e against
       $67.  A uniform byte takes the far arm 152 times in 256 and the near arm 104 — usable,
       but the boundary itself never comes up, so it is drawn explicitly.
     * emit_edge_width_offset needs FOUR things at once: shared_counter_42 on both sides of 3
       (under it the routine does almost nothing), road_side_index in {0,1} (a random byte
       indexes unrelated bytes of block 0's tail), marker_count in 0..3, and its OWN SMC site
       at $261A planted — an unplanted one traps, which is an early return in both models with
       the horizon record never written.
     * ...and its shift count, which is what the twin actually changes: the 6502 loops one
       place per iteration and the twin does a range test plus one 68000 shift, so the
       fixture draws proj_width_shift so that the count lands on 0, on 1, inside 1..15, on 16
       (the first count that shifts everything out) and past it, in both directions.
   ========================================================================== */
void shift_near_edge_points(void);
void shift_near_edge_points__t6502(void);
void clamp_near_edge_window(void);
void clamp_near_edge_window__t6502(void);
void clamp_near_edge_cursor(void);
void clamp_near_edge_cursor__t6502(void);
void rebase_edge_point(void);
void rebase_edge_point__t6502(void);
void load_section_triple(void);
void load_section_triple__t6502(void);
void point_distance_hypot(void);
void point_distance_hypot__t6502(void);
void emit_edge_bearing(void);
void emit_edge_bearing__t6502(void);
void emit_edge_bearing_at_cursor(void);
void emit_edge_bearing_at_cursor__t6502(void);
void emit_edge_width_offset(void);
void emit_edge_width_offset__t6502(void);

/* A pre-state for the three near-slot routines: the window cells drawn from the small set
   that actually decides their branches, everything else random. */
static void near_slot_pre(uint8_t* pre)
{
    fill_random(pre);
    pre[0x0005] = NEAR_SLOTS[xs() % (sizeof NEAR_SLOTS)];   /* near_edge_first  */
    pre[0x0006] = NEAR_SLOTS[xs() % (sizeof NEAR_SLOTS)];   /* near_edge_last   */
    pre[0x0008] = NEAR_SLOTS[xs() % (sizeof NEAR_SLOTS)];   /* near_edge_cursor */
    /* near_edge_shift is how many sections the car crossed: 0..7 in the engine (the value is
       ANDed with 7 at $128E), and 6 - it is what near_edge_first becomes. */
    pre[0x0007] = (xs() % 4) ? (uint8_t)(xs() % 8) : (uint8_t)xs();
}

/* emit_edge_width_offset's own pre-state.  ⚠ The SMC site is planted in every case except the
   deliberate garbage shape — see plant_geometry_smc's note: an unplanted $261A is a trap on
   the FIRST case that would have written the horizon, i.e. a fixture that compares nothing. */
static void width_pre(uint8_t* pre, int shape)
{
    fill_random(pre);
    plant_geometry_smc(pre);
    if (shape == EDGE_HOOKED) {
        pre[0x261A] = 0x4C; pre[0x261B] = 0xAF; pre[0x261C] = 0x56;   /* JMP $56AF — all four
                                                                         expansion circuits */
    } else if (shape == EDGE_GARBAGE) {
        pre[0x261A] = (uint8_t)xs();
    }
    pre[0x0049] = (uint8_t)(xs() & 1);                      /* road_side_index */
    pre[0x0057] = (uint8_t)(xs() % 4);                      /* marker_count 0..3, 3 = full */
    /* shared_counter_42 against the CMP #3 gate, both sides drawn. */
    { static const uint8_t n[] = { 0x00, 0x01, 0x02, 0x03, 0x04, 0x11, 0xFF };
      pre[0x0042] = n[xs() % (sizeof n)]; }
    pre[0x0012] = (uint8_t)(xs() % 0x50);                   /* edge_cursor, a real slot */
    /* THE SHIFT COUNT.  It is proj_width_shift - edge_width_shift_tbl[feature] - 1, and the
       table entry is whatever the block-0 tail holds, so the count is steered by picking
       proj_width_shift relative to the entry the masked flags will select.  Cheaper and more
       honest than solving for the flags: draw the whole set of interesting counts against a
       RANDOM table entry, which covers each one about an eighth of the time. */
    { static const int8_t want[] = { 0, 1, 2, 8, 15, 16, 17, -1, -2, -15, -16, -17 };
      unsigned feature = (unsigned)(xs() & 7);
      int      steps   = want[xs() % (sizeof want)];
      pre[0x002B] = (uint8_t)(pre[0x3076 + feature] + steps + 1); }
    pre[0x002A] = (uint8_t)xs();                            /* proj_width, the mantissa */
    pre[0x008D] = (uint8_t)(xs() % 0x60);                   /* projected_line around the $50 top */
    if (xs() % 3 == 0) pre[0x001F] = pre[0x008D];           /* ...exactly on the horizon */
}

static int test_geometry_leaves(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    /* point_distance_hypot and the two emit_edge_bearing entries that tail-call it leave DEAD
       N/V/Z/C: proven statically at all four call sites ($2374/$23d8/$2452/$2ab3) — N and Z are
       clobbered by the first instruction, C by an intervening CPX/CPY/CMP before the first
       BCS/BCC, and V is never read (the whole road pass $2145-$2b62 has no BVS/BVC).  So their
       twins keep only A live and no longer reproduce the exit flags. */
    const unsigned distMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S;
    /* load_section_triple answers entirely in mem[] — the six coordinate bytes of the scratch
       section triple.  All three callers overwrite the registers immediately ($1230 LDA, $2367
       JSR, $4CEB LDY) and read no exit flag, so its A/N/Z are dead; the clean core no longer
       spends a load_a to reproduce them.  Keep S live for the stack-balance check. */
    const unsigned resultMask = LIVE_S;
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    register_fixture("shift_near_edge_points");
    register_fixture("clamp_near_edge_window");
    register_fixture("clamp_near_edge_cursor");
    register_fixture("rebase_edge_point");
    register_fixture("load_section_triple");
    register_fixture("point_distance_hypot");
    register_fixture("emit_edge_bearing");
    register_fixture("emit_edge_bearing_at_cursor");
    register_fixture("emit_edge_width_offset");
    setenv("REVS_SMC_CONTINUE", "1", 1);

    /* ---- the three near-slot routines ------------------------------------------------ */
    {
        struct { const char* name; void (*n)(void); void (*o)(void); } W[] = {
            { "shift_near_edge_points", shift_near_edge_points, shift_near_edge_points__t6502 },
            { "clamp_near_edge_window", clamp_near_edge_window, clamp_near_edge_window__t6502 },
            { "clamp_near_edge_cursor", clamp_near_edge_cursor, clamp_near_edge_cursor__t6502 },
        };
        int i;
        const int cases = 1000 * scale;
        for (i = 0; i < 3; i++) {
            int subFail = 0, moved = 0;
            if (!want(W[i].name)) continue;
            for (t = 0; t < cases; t++) {
                Cpu6502 c = zero_cpu();
                near_slot_pre(pre);
                c.A = (uint8_t)xs();
                /* clamp_near_edge_cursor is ENTERED with the candidate slot in X, and
                   road_edge_start's own call passes near_edge_cursor - 1. */
                c.X = (xs() % 3) ? NEAR_SLOTS[xs() % (sizeof NEAR_SLOTS)] : (uint8_t)xs();
                c.Y = (uint8_t)xs();
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
                c.D = 0;   /* the road pass is never decimal (static-map.md §Decimal mode); the
                              $12C0 subtract is now a plain binary 6 - near_edge_shift and the
                              clamps are CPX */
                /* shift_near_edge_points' subtract V is a dead byproduct — its only caller reads
                   near_edge_first with an immediate CMP before touching V — so drop it (i==0). */
                unsigned m = (i == 0) ? (liveMask & ~LIVE_V) : liveMask;
                subFail += diff_run(W[i].name, pre, c, W[i].n, W[i].o, m, t, &printed);
                if (mem[0x0008] != pre[0x0008] || mem[0x0006] != pre[0x0006]) moved++;
            }
            fail += subFail;
            if (moved == 0) {
                printf("[VACUOUS] %s: the window never moved in %d cases\n", W[i].name, cases);
                fail++;
            }
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+%s  "
                   "(%d/%d moved the window)\n", W[i].name, cases, subFail,
                   (i == 0) ? "NZC (V byproduct, D=0)" : "flags", moved, cases);
        }
    }

    /* ---- rebase_edge_point: one surviving point, slot in Y ---------------------------- */
    if (want("rebase_edge_point")) {
        int subFail = 0, tookHorizon = 0;
        const int cases = 1000 * scale;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            /* the slot: the six near slots of either half are the only ones road_edge_start
               ever passes, and the horizon test is against horizon_extent, drawn onto the
               post value a third of the time so the >= boundary is really exercised. */
            c.Y = (xs() % 4) ? (uint8_t)((xs() % 6) + ((xs() & 1) ? 0x28 : 0)) : (uint8_t)xs();
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;   /* render path is binary — the two subtracts are native 16-bit now
                          (docs/static-map.md §Decimal mode) */
            if (xs() % 3 == 0)
                pre[0x001F] = (uint8_t)(pre[0x5F20 + c.Y] - pre[0x004E]);   /* exactly on it */
            /* RESULTS, NOT DEAD EXIT FLAGS.  rebase_edge_point answers entirely in mem[] — the
               two edge cells and the horizon pair; its sole caller (road_edge_start's re-base
               loop) reads no exit register or flag before looping.  The clean core builds its
               16-bit subtract from sbc_value (decimal-honouring) and leaves cpu untouched, so
               A/N/V/Z/C on return are not its answer.  Keep S live for the stack-balance check. */
            subFail += diff_run("rebase_edge_point", pre, c, rebase_edge_point,
                                rebase_edge_point__t6502, resultMask, t, &printed);
            if (mem[0x0051] != pre[0x0051] || mem[0x001F] != pre[0x001F]) tookHorizon++;
        }
        fail += subFail;
        if (tookHorizon == 0) {
            printf("[VACUOUS] rebase_edge_point: the horizon never moved in %d cases\n", cases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=S (mem-only result)  "
               "(%d/%d beat the horizon)\n",
               "rebase_edge_point", cases, subFail, tookHorizon, cases);
    }

    /* ---- load_section_triple: track file -> a live section slot ----------------------- */
    if (want("load_section_triple")) {
        int subFail = 0;
        const int cases = 1000 * scale;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            /* X is a byte index into the 120-byte live list plus its two scratch slots ($FA
               and $FD); Y is a segment's 8-byte record.  Both are drawn from what the engine
               passes AND from anywhere, because neither index wraps. */
            { static const uint8_t dst[] = { 0x00, 0x03, 0x75, 0x78, 0xFA, 0xFD };
              c.X = (xs() % 3) ? dst[xs() % (sizeof dst)] : (uint8_t)xs(); }
            c.Y = (xs() % 3) ? (uint8_t)((xs() % 0x20) * 8) : (uint8_t)xs();
            c.A = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            subFail += diff_run("load_section_triple", pre, c, load_section_triple,
                                load_section_triple__t6502, resultMask, t, &printed);
        }
        fail += subFail;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=S (mem-only result)\n",
               "load_section_triple", cases, subFail);
    }

    /* ---- point_distance_hypot: the two approximations --------------------------------- */
    if (want("point_distance_hypot")) {
        int subFail = 0, nearArm = 0, farArm = 0;
        const int cases = 2000 * scale;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            /* the arm selector, drawn ON the boundary as well as either side of it */
            { static const uint8_t a[] = { 0x00, 0x40, 0x66, 0x67, 0x68, 0xC0, 0xFF };
              pre[0x007E] = (xs() % 3) ? a[xs() % (sizeof a)] : (uint8_t)xs(); }
            /* bearing_to_section always hands this routine min <= max; a random pre-state
               does not, so half the cases are sorted and half are left as they fell. */
            if (xs() & 1) {
                unsigned lo = (unsigned)pre[0x0078] | ((unsigned)pre[0x0079] << 8);
                unsigned hi = (unsigned)pre[0x007A] | ((unsigned)pre[0x007B] << 8);
                if (lo > hi) { unsigned s = lo; lo = hi; hi = s; }
                pre[0x0078] = (uint8_t)lo; pre[0x0079] = (uint8_t)(lo >> 8);
                pre[0x007A] = (uint8_t)hi; pre[0x007B] = (uint8_t)(hi >> 8);
            }
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;   /* the render path is always binary (docs/static-map.md §Decimal mode:
                          no SED reaches build_track_geometry), so the twin's 16-bit +/- IS the
                          6502's here; determinism-drive is the backstop that D=0 truly holds. */
            if (pre[0x007E] < 0x67) nearArm++; else farArm++;
            subFail += diff_run("point_distance_hypot", pre, c, point_distance_hypot,
                                point_distance_hypot__t6502, distMask, t, &printed);
        }
        fail += subFail;
        if (nearArm == 0 || farArm == 0) {
            printf("[VACUOUS] point_distance_hypot: only one approximation ran "
                   "(near=%d far=%d)\n", nearArm, farArm);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY (flags proven dead)  "
               "(%d near arm, %d far arm)\n",
               "point_distance_hypot", cases, subFail, nearArm, farArm);
    }

    /* ---- emit_edge_bearing, and the five-byte entry that takes the bearing first ------- */
    {
        struct { const char* name; void (*n)(void); void (*o)(void); } E[] = {
            { "emit_edge_bearing", emit_edge_bearing, emit_edge_bearing__t6502 },
            { "emit_edge_bearing_at_cursor", emit_edge_bearing_at_cursor,
              emit_edge_bearing_at_cursor__t6502 },
        };
        int i;
        const int cases = 1000 * scale;
        for (i = 0; i < 2; i++) {
            int subFail = 0;
            if (!want(E[i].name)) continue;
            for (t = 0; t < cases; t++) {
                Cpu6502 c = zero_cpu();
                fill_random(pre);
                { static const uint8_t a[] = { 0x00, 0x40, 0x66, 0x67, 0x68, 0xC0, 0xFF };
                  pre[0x007E] = (xs() % 3) ? a[xs() % (sizeof a)] : (uint8_t)xs(); }
                /* the slot: emit_edge_bearing is entered with it in Y, the cursor entry reads
                   it out of edge_cursor and is entered with the SECTION byte in X instead. */
                c.Y = (xs() % 3) ? (uint8_t)(xs() % 0x50) : (uint8_t)xs();
                pre[0x0012] = (uint8_t)(xs() % 0x50);
                c.X = (uint8_t)(xs() % 0xF0);
                c.A = (uint8_t)xs();
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
                c.D = 0;   /* render path is binary; and the tail-called point_distance_hypot is
                              now native 16-bit (docs/static-map.md §Decimal mode) */
                subFail += diff_run(E[i].name, pre, c, E[i].n, E[i].o, distMask, t, &printed);
            }
            fail += subFail;
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY (flags proven dead)\n",
                   E[i].name, cases, subFail);
        }
    }

    /* ---- emit_edge_width_offset ------------------------------------------------------- */
    if (want("emit_edge_width_offset")) {
        int subFail = 0, scored = 0, marked = 0, horizon = 0;
        const int cases = 2000 * scale;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            int shape = (t % 6 == 4) ? EDGE_HOOKED : (t % 6 == 5) ? EDGE_GARBAGE
                                                                  : EDGE_SILVERSTONE;
            width_pre(pre, shape);
            /* X is the section byte index, and $78 is where the routine switches from
               section_flags to its wrapped alias — both sides drawn. */
            { static const uint8_t s[] = { 0x00, 0x03, 0x77, 0x78, 0x79, 0xEF, 0xFF };
              c.X = (xs() % 3) ? s[xs() % (sizeof s)] : (uint8_t)xs(); }
            c.A = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;      /* render path is binary — docs/static-map.md §Decimal mode */
            subFail += diff_run("emit_edge_width_offset", pre, c, emit_edge_width_offset,
                                emit_edge_width_offset__t6502, liveMask, t, &printed);
            if (mem[0x5E50 + pre[0x0012]] != pre[0x5E50 + pre[0x0012]] ||
                mem[0x0074] != pre[0x0074]) scored++;
            if (mem[0x0057] != pre[0x0057]) marked++;
            if (mem[0x001F] != pre[0x001F]) horizon++;
        }
        fail += subFail;
        if (scored == 0 || marked == 0 || horizon == 0) {
            printf("[VACUOUS] emit_edge_width_offset: width=%d markers=%d horizon=%d — "
                   "one of the three outputs was never produced in %d cases\n",
                   scored, marked, horizon, cases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d computed a width, %d appended a marker, %d moved the horizon)\n",
               "emit_edge_width_offset", cases, subFail, scored, marked, horizon);
    }

    return fail;
}


/* ==========================================================================
   $0E40 abs16_math, $2FEE road_span_advance, $2F45/$2F87 the span plotters,
   $2FC0/$2FD7 the two end markers — THE SPAN RASTERISER'S LEAVES
   --------------------------------------------------------------------------
   These are the bottom of the view pipeline: the four routines that actually touch a buffer
   cell, plus the predicate they share and the 16-bit absolute value interp_edge calls.

   ⚠⚠ FOUR OF THE SIX ARE SELF-MODIFYING AND EVERY SITE IS AN EXIT ON AN UNRECOGNISED BYTE,
   so a uniform pre-state compares almost nothing: both models trap on the first instruction
   and return.  The opcode slots are therefore PLANTED with one of the legal values, and a
   tenth of the cases plant garbage on purpose so the trap path is tested rather than avoided.

   ⚠ And the interesting arms are all rare under uniform bytes, so four things are steered:
     * the buffer cell is forced to $00 (empty), to $55 (the "all four columns" value) or
       left random, a third each — otherwise the empty-cell arm runs 1 case in 256;
     * mem[$82] is forced to the stepped Y in a fifth of the cases, which is the ONLY way to
       reach the abandon path (`TSX/INX/INX/TXS`, the two-level return) and the surface cap
       behind it;
     * Y is held below $2C in half the cases, because at or above it road_span_advance is
       never called at all;
     * X is forced to $80 in a third of the marker cases — the value that decides whether a
       terminator gets written.
   ========================================================================== */
void abs16_math(void);
void abs16_math__t6502(void);
void road_span_advance(void);
void road_span_advance__t6502(void);
void road_span_plot(void);
void road_span_plot__t6502(void);
void road_span_plot_2(void);
void road_span_plot_2__t6502(void);
void span_end_marker_p1(void);
void span_end_marker_p1__t6502(void);
void span_end_marker_p2(void);
void span_end_marker_p2__t6502(void);

/* The three opcodes a Y-step slot may legally hold, and the two an end-marker slot may. */
static const uint8_t STEP_OPCODES[3]   = { 0xC8, 0x88, 0xEA };   /* INY / DEY / NOP */
static const uint8_t MARKER_OPCODES[2] = { 0xE0, 0x60 };         /* CPX #$80 / RTS  */

/* How far a planted step slot moves Y, for working out which cell the call will touch. */
static int step_delta(uint8_t opcode)
{
    return opcode == 0xC8 ? 1 : opcode == 0x88 ? -1 : 0;
}

/* Plant one Y-step slot; one case in ten gets a byte the model cannot execute. */
static uint8_t plant_step(uint8_t* pre, unsigned slot)
{
    uint8_t op = (xs() % 10 == 0) ? (uint8_t)xs() : STEP_OPCODES[xs() % 3];
    pre[slot] = op;
    return op;
}

/* $2F19's per-circuit site, reached from the abandon path.  Silverstone's own bytes, an
   expansion circuit's hook, or garbage — the same three shapes build_track_geometry uses. */
static void plant_cap_smc(uint8_t* pre)
{
    unsigned shape = xs() % 10;
    if (shape < 6)      { pre[0x2F23] = 0xB9; pre[0x2F24] = 0x60; pre[0x2F25] = 0x5F; }
    else if (shape < 9) { pre[0x2F23] = 0x20; pre[0x2F24] = 0x22; pre[0x2F25] = 0x5A; }
    /* else: whatever fill_random left — the trap arm */
}

/* ⭐⭐ KEEP EVERY PLOTTER POINTER OUT OF THE I/O WINDOW, and this is a correctness fix, not
   tidiness: a random high byte puts the cell READ at $FC00-$FEFF once in about eighty cases,
   `platform_hw_read` is not a pure function of mem[], and diff_run runs the oracle first —
   so the two models legitimately read different bytes and the twin looks wrong.  (Measured:
   82 of 2000 cases, all with A or a flag differing and mem[] byte-exact.)  The engine's own
   pointers are always RAM, so holding the three high bytes below $80 measures the twin
   rather than the clock. */
/* ⭐⭐ AND KEEP EVERY DESTINATION HIGH BYTE OUT OF ZERO PAGE, for a second and subtler
   correctness reason.  road_span_plot parks its incoming accumulator in $008A ($2F45),
   works in A, and RESTORES it from $008A at $2F5E just before RTS, so the DDA accumulator
   the caller threads column-to-column comes back unchanged.  A destination pointing into
   zero page lets one of the routine's own stores ((cellPtr),Y / (linePtr),Y / the surface
   operand) land on $008A and overwrite the parked A BEFORE that restore — the oracle then
   exits with the clobbered value while the twin echoes the input, a divergence at ~1/20000
   fixture inputs.  The engine's pointers are always screen buffers ($30-$5F), never zero
   page, so mapping every high byte into $20..$7F keeps them RAM, out of the I/O window
   ($FC00-$FEFF), and clear of the zero-page scratch the routine relies on ($82/$85/$8A/$8B).
   (This subsumes the old &0x7F I/O-window mask.) */
static void plant_ram_pointers(uint8_t* pre)
{
    pre[0x0071] = (uint8_t)(pre[0x0071] % 0x60 + 0x20);   /* plot_ptr_hi  */
    pre[0x0073] = (uint8_t)(pre[0x0073] % 0x60 + 0x20);   /* plot_ptr2_hi */
    pre[0x008F] = (uint8_t)(pre[0x008F] % 0x60 + 0x20);   /* plot_ptr3_hi */
    pre[0x2F50] = (uint8_t)(pre[0x2F50] % 0x60 + 0x20);   /* the patched dest operands, both plotters */
    pre[0x2F92] = (uint8_t)(pre[0x2F92] % 0x60 + 0x20);
}

/* Steer the cell the plotter is about to touch, and (sometimes) the end line it compares
   against.  `ptrCell` is the zero-page pointer the colour cell is read through. */
static void steer_plot_case(uint8_t* pre, Cpu6502* c, unsigned ptrCell, uint8_t stepIn,
                            int* emptyCell, int* abandoned)
{
    unsigned yAfter = (unsigned)((c->Y + step_delta(stepIn)) & 0xFF);
    unsigned addr   = ((unsigned)(pre[ptrCell] | (pre[(uint8_t)(ptrCell + 1)] << 8)) + yAfter)
                      & 0xFFFF;

    if (xs() % 5 == 0) { pre[0x0082] = (uint8_t)yAfter; *abandoned = 1; }   /* the abort path */
    else if (pre[0x0082] == (uint8_t)yAfter) *abandoned = 1;

    if (addr < 0xFC00 || addr >= 0xFF00) {           /* never plant into the I/O window */
        unsigned pick = xs() % 3;
        if (pick == 0) { pre[addr] = 0x00; *emptyCell = 1; }
        else if (pick == 1) pre[addr] = 0x55;
    }
}

static int test_span_leaves(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    const int absCases = 2000 * scale, advCases = 1000 * scale,
              plotCases = 2000 * scale, markCases = 1000 * scale;

    register_fixture("abs16_math");
    register_fixture("road_span_advance");
    register_fixture("road_span_plot");
    register_fixture("road_span_plot_2");
    register_fixture("span_end_marker_p1");
    register_fixture("span_end_marker_p2");
    setenv("REVS_SMC_CONTINUE", "1", 1);

    if (want("abs16_math")) {
        int subFail = 0, negated = 0, disagreed = 0;
        for (t = 0; t < absCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            /* Same trap as abs8: the `BPL` reads the CALLER's N, so a third of the cases
               decorrelate it from bit 7 of A deliberately. */
            c.N = (xs() % 3) ? (uint8_t)(c.A >> 7) : (uint8_t)(xs() & 1);
            c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            /* ⭐ D IS PINNED TO 0: the idiomatic core is a plain binary 16-bit negate, and
               abs16_math's callers are all on the per-frame driving-model / steering path.  Decimal
               mode lives ENTIRELY in race-stats / marker-draw / front-end menu, each SED…CLD
               bracketed locally (docs/static-map.md §Decimal mode, settled — the per-frame sim is
               D=0).  make determinism-drive is the empirical backstop. */
            c.D = 0;
            if (c.N != (c.A >> 7)) disagreed++;
            if (c.N) negated++;
            subFail += diff_run("abs16_math", pre, c, abs16_math, abs16_math__t6502,
                                liveMask, t, &printed);
        }
        fail += subFail;
        if (negated == 0 || disagreed == 0) {
            printf("[VACUOUS] abs16_math: %d negated, %d decorrelated of %d — "
                   "both must be non-zero\n", negated, disagreed, absCases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d negated, %d with N vs bit 7 decorrelated, D=0 pinned)\n",
               "abs16_math", absCases, subFail, negated, disagreed);
    }

    if (want("road_span_advance")) {
        int subFail = 0, atStart = 0;
        /* The pure-C core sets only C; the transliteration also spills A/X into math_lo/math_hi
           and leaves N/Z from the restored A.  Both are 6502 implementation detail — the one
           computed fact is the carry — so drop N/V/Z and ignore the two scratch cells. */
        static const uint16_t ig[] = { 0x0074, 0x0075 };
        unsigned mask = LIVE_A | LIVE_X | LIVE_Y | LIVE_C;
        set_ignore(ig, 2);
        for (t = 0; t < advCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            pre[0x0085] = (uint8_t)xs();
            /* The whole routine is one compare, so its EQUAL case has to be planted or it
               happens once in 256 and the CLC is never exercised. */
            if (xs() % 3 == 0) pre[0x3900 + pre[0x0085]] = c.Y;
            if (pre[0x3900 + pre[0x0085]] == c.Y) atStart++;
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            subFail += diff_run("road_span_advance", pre, c, road_span_advance,
                                road_span_advance__t6502, mask, t, &printed);
        }
        set_ignore(0, 0);
        fail += subFail;
        if (atStart == 0) {
            printf("[VACUOUS] road_span_advance: no case reached the block's first line\n");
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+C  "
               "(%d on the block boundary)\n",
               "road_span_advance", advCases, subFail, atStart);
    }

    {
        struct { const char* name; void (*nat)(void); void (*ref)(void);
                 unsigned ptrCell, stepIn, stepOut; } plotters[2] = {
            { "road_span_plot",   road_span_plot,   road_span_plot__t6502,
              0x0072, 0x2F47, 0x2F60 },
            { "road_span_plot_2", road_span_plot_2, road_span_plot_2__t6502,
              0x0070, 0x2F89, 0x2FA2 },
        };
        int p;
        /* bearing_lo ($8A) is the DDA accumulator's 6502 parking slot, written every call by the
           transliteration and never by the pure-C core; math_lo ($74) is the abandon-cap's flatten
           spill (FUN_2f19).  Both are implementation detail — ignore them. */
        static const uint16_t ig[] = { 0x008A, 0x0074 };
        for (p = 0; p < 2; p++) {
            int subFail = 0, empty = 0, abandoned = 0, nearTop = 0;
            if (!want(plotters[p].name)) continue;
            set_ignore(ig, 2);
            for (t = 0; t < plotCases; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t stepIn;
                int isEmpty = 0, isAbandon = 0;
                unsigned mask;
                fill_random(pre);
                c.A = (uint8_t)xs(); c.X = (uint8_t)(xs() % 4); c.Y = (uint8_t)xs();
                if (xs() % 2) { c.Y = (uint8_t)(xs() % 0x2C); nearTop++; }
                plant_ram_pointers(pre);
                stepIn = plant_step(pre, plotters[p].stepIn);
                plant_step(pre, plotters[p].stepOut);
                plant_cap_smc(pre);
                steer_plot_case(pre, &c, plotters[p].ptrCell, stepIn, &isEmpty, &isAbandon);
                empty += isEmpty; abandoned += isAbandon;
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
                c.D = 0;
                /* On abandon the plotter's caller unwinds immediately, so A/X/Y/C are all dead
                   (the transliteration's TSX/INX clobbers X and DEY changes Y).  On every other
                   path A=accumulator, X=column, Y=stepped, C=carry all stand — N/V/Z do not. */
                mask = isAbandon ? LIVE_NONE : (LIVE_A | LIVE_X | LIVE_Y | LIVE_C);
                subFail += diff_run(plotters[p].name, pre, c, plotters[p].nat,
                                    plotters[p].ref, mask, t, &printed);
            }
            set_ignore(0, 0);
            fail += subFail;
            if (empty == 0 || abandoned == 0 || nearTop == 0) {
                printf("[VACUOUS] %s: %d empty cells, %d abandons, %d near the top of %d — "
                       "all three arms must be reached\n",
                       plotters[p].name, empty, abandoned, nearTop, plotCases);
                fail++;
            }
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXYC (none on abandon)  "
                   "(%d empty cell, %d abandoned the chain, %d below line $2C)\n",
                   plotters[p].name, plotCases, subFail, empty, abandoned, nearTop);
        }
    }

    {
        struct { const char* name; void (*nat)(void); void (*ref)(void);
                 unsigned slot, ptrCell; } markers[2] = {
            { "span_end_marker_p1", span_end_marker_p1, span_end_marker_p1__t6502,
              0x2FC0, 0x0070 },
            { "span_end_marker_p2", span_end_marker_p2, span_end_marker_p2__t6502,
              0x2FD7, 0x0072 },
        };
        int m;
        /* The pure-C marker sets colMark ($80) and carry (0) on the work path and touches
           nothing on RTS; A is preserved and Y only read.  N/V/Z are CPX detail, so drop them. */
        unsigned mask = LIVE_A | LIVE_X | LIVE_Y | LIVE_C;
        for (m = 0; m < 2; m++) {
            int subFail = 0, live = 0, wrote = 0;
            if (!want(markers[m].name)) continue;
            for (t = 0; t < markCases; t++) {
                Cpu6502 c = zero_cpu();
                uint8_t op = (xs() % 10 == 0) ? (uint8_t)xs() : MARKER_OPCODES[xs() % 2];
                fill_random(pre);
                plant_ram_pointers(pre);
                pre[markers[m].slot] = op;
                c.A = (uint8_t)xs(); c.Y = (uint8_t)xs();
                if (xs() % 2) c.Y = (uint8_t)(xs() % 0x2C);
                /* X == $80 is "this column never plotted", the only value that writes a
                   terminator — a uniform byte reaches it once in 256. */
                c.X = (xs() % 3) ? 0x80 : (uint8_t)xs();
                pre[0x0085] = (uint8_t)xs();
                if (op == 0xE0) live++;
                if (op == 0xE0 && c.X == 0x80) wrote++;
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
                c.D = 0;
                subFail += diff_run(markers[m].name, pre, c, markers[m].nat,
                                    markers[m].ref, mask, t, &printed);
            }
            fail += subFail;
            if (live == 0 || wrote == 0 || live == markCases) {
                printf("[VACUOUS] %s: %d live of %d cases, %d reached the terminator — "
                       "both opcode shapes and both X arms must run\n",
                       markers[m].name, live, markCases, wrote);
                fail++;
            }
            printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXYC  "
                   "(%d switched on, %d reached the terminator)\n",
                   markers[m].name, markCases, subFail, live, wrote);
        }
    }

    unsetenv("REVS_SMC_CONTINUE");
    return fail;
}


/* ==========================================================================
   $2D17 / $2D9A / $2E20 / $2E99 — THE FOUR SPAN-WALK ARMS
   --------------------------------------------------------------------------
   Each is an eight-column chain, unrolled once and entered partway through by a computed
   jump, looping one scan line at a time until plot_ptr2_hi reaches its bound.

   ⚠⚠ A RANDOM PRE-STATE DOES NOT TERMINATE HERE, and that is the fixture's main job:
     * the entry offset is a branch target.  A random byte is a branch to the middle of an
       instruction — which the oracle traps on too, so it is a legal case and one in eight is
       planted deliberately — but a byte that lands BACKWARD inside the chain makes the oracle
       spin forever.  The eight legal offsets come out of the image's own tables.
     * the two Y-step slots must be the SAME direction.  Opposite ones make Y oscillate, so
       the abandon test (Y == the span's end line) is never reached.
     * plot_ptr2_hi starts within a few lines of the bound, or the walk runs 256 scan lines of
       eight plots each.
     * the STEEP arms repeat a column until the DDA carries, so their delta is held above $20:
       with a random small one that inner loop runs 256 times per column per line.
   None of this weakens the comparison — it is what makes there BE one.
   ========================================================================== */
void draw_span_shallow_fwd(void);
void draw_span_shallow_fwd__t6502(void);
void draw_span_shallow_rev(void);
void draw_span_shallow_rev__t6502(void);
void draw_span_steep_fwd(void);
void draw_span_steep_fwd__t6502(void);
void draw_span_steep_rev(void);
void draw_span_steep_rev__t6502(void);

/* The image's own entry-offset tables — the eight values each arm's phase index can produce. */
static const uint8_t ARM_OFF_SHALLOW_FWD[8] = { 0x08,0x13,0x1E,0x29,0x39,0x44,0x4F,0x5A };
static const uint8_t ARM_OFF_SHALLOW_REV[8] = { 0x5A,0x4F,0x44,0x39,0x29,0x1E,0x13,0x08 };
static const uint8_t ARM_OFF_STEEP_FWD[8]   = { 0x00,0x0B,0x16,0x21,0x2E,0x39,0x44,0x4F };
static const uint8_t ARM_OFF_STEEP_REV[8]   = { 0x4F,0x44,0x39,0x2E,0x21,0x16,0x0B,0x00 };

static int test_span_arms(void)
{
    static uint8_t pre[65536];
    /* ⭐ LIVE_NONE — validate the DRAWN RESULT (mem[]), not the exit ABI.  span_walk is now
       pure C: it takes the phase and start line as arguments and returns nothing, and its exit
       A/X/Y/S/flags are dead at every real call site.  interp_edge__t6502 (the sole caller of
       the draw_span_* oracles) overwrites A with `LDA span_swapped` and reloads X/Y from the
       saved point indices the instant each arm returns, so no register these arms leave is ever
       read.  Comparing them would validate an implementation detail; the pixels are what count. */
    unsigned liveMask = LIVE_NONE;
    int fail = 0, printed = 0, t, a;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    const int armCases = 400 * scale;

    struct Arm {
        const char* name; void (*nat)(void); void (*ref)(void);
        unsigned table; const uint8_t* offsets; int rev, steep; uint8_t bound;
    } arms[4] = {
        { "draw_span_shallow_fwd", draw_span_shallow_fwd, draw_span_shallow_fwd__t6502,
          0x3E50, ARM_OFF_SHALLOW_FWD, 0, 0, 0x44 },
        { "draw_span_shallow_rev", draw_span_shallow_rev, draw_span_shallow_rev__t6502,
          0x40D0, ARM_OFF_SHALLOW_REV, 1, 0, 0x2F },
        { "draw_span_steep_fwd",   draw_span_steep_fwd,   draw_span_steep_fwd__t6502,
          0x3ED0, ARM_OFF_STEEP_FWD,   0, 1, 0x44 },
        { "draw_span_steep_rev",   draw_span_steep_rev,   draw_span_steep_rev__t6502,
          0x3ED8, ARM_OFF_STEEP_REV,   1, 1, 0x2F },
    };

    for (a = 0; a < 4; a++) register_fixture(arms[a].name);
    setenv("REVS_SMC_CONTINUE", "1", 1);

    /* The descending arms' cap is the transliterated FUN_2f12→FUN_2f19 in the oracle, which
       spills through math_lo ($74) on its off-axis flatten; the pure-C span_walk_cap does not.
       That one scratch cell is the only mem[] divergence — ignore it (harmless on the fwd arms,
       which never reach the cap). */
    static const uint16_t ig[] = { 0x0074 };
    set_ignore(ig, 1);

    for (a = 0; a < 4; a++) {
        int subFail = 0, midChain = 0, trapped = 0, multiLine = 0, markerTrap = 0,
            carryIn = 0;
        if (!want(arms[a].name)) continue;
        for (t = 0; t < armCases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t step = (xs() & 1) ? 0xC8 : 0x88;      /* INY or DEY, the SAME both ends */
            unsigned phase = xs() % 8;
            int lines = 1 + (int)(xs() % 4);
            fill_random(pre);
            plant_ram_pointers(pre);
            plant_cap_smc(pre);

            pre[0x2F47] = pre[0x2F60] = pre[0x2F89] = pre[0x2FA2] = step;
            /* ⭐ One case in six plants a marker opcode the model cannot execute.  Without it
               three sabotages SURVIVED: on the steep arms an end marker is a NO-OP by
               construction (X is always a column 0-3 there, never the $80 that writes a
               terminator, and its `LDX #$80 / CLC` tail is overwritten by the loop test), so
               only the TRAP distinguishes an arm that calls one from an arm that does not. */
            { int trapMarker = (xs() % 6 == 0);
              uint8_t mop = trapMarker ? 0x12 : ((xs() & 1) ? 0xE0 : 0x60);
              pre[0x2FC0] = pre[0x2FD7] = mop;
              if (trapMarker) markerTrap++; }

            /* The three screen pointers as interp_edge would leave them: page-aligned inside
               the view's source blocks, with plot_ptr3 one page up.  ⚠ Random ones let a
               plotter store land on plot_ptr2_hi itself, and the walk then runs 256 scan
               lines instead of the four this case is trying to measure. */
            pre[0x0070] = pre[0x0072] = pre[0x008E] = 0x00;
            /* ...and both plotters' patched destinations at a real surface_edge buffer, for
               the same reason. */
            pre[0x2F4F] = pre[0x2F91] = 0x54;
            pre[0x2F50] = pre[0x2F92] = 0x05;

            /* One case in eight plants an offset that is not an instruction boundary, so the
               trap arm is tested rather than avoided; both models must take it. */
            if (xs() % 8 == 0) { pre[arms[a].table + phase] = 0xFF; trapped++; }
            else               { pre[arms[a].table + phase] = arms[a].offsets[phase];
                                 if (arms[a].offsets[phase] != arms[a].offsets[0]) midChain++; }

            /* ⭐ One ASCENDING case in twelve starts ABOVE its bound, and it is the only way
               the DDA's carry-in is ever 1: the loop test is `CPX #bound`, and its carry
               reaches the first `ADC` of the next line.  Below the bound — which is the only
               shape the game itself produces, since interp_edge derives plot_ptr_hi from a
               block index under $28 — that carry is always 0, and a twin that hard-codes it
               PASSES.  The walk then runs the long way round to the bound, which is why it is
               one case in twelve and not one in two. */
            if (!arms[a].rev && xs() % 12 == 0) {
                pre[0x0073] = (uint8_t)(arms[a].bound + 1 + (xs() % 3));
                carryIn++;
            } else {
                pre[0x0073] = (uint8_t)(arms[a].rev ? arms[a].bound + lines
                                                    : arms[a].bound - lines);
            }
            pre[0x0071] = pre[0x0073];
            pre[0x008F] = (uint8_t)(pre[0x0073] + 1);
            if (lines > 1) multiLine++;
            pre[0x0083] = (uint8_t)(0x20 + xs() % 0xC0);   /* both deltas well away from 0 */
            pre[0x0084] = (uint8_t)(0x20 + xs() % 0xC0);
            pre[0x0085] = (uint8_t)(xs() % 0x2C);          /* the source block */

            c.A = (uint8_t)xs(); c.X = (uint8_t)phase; c.Y = (uint8_t)(xs() % 0x50);
            /* Half the cases guarantee the abandon path: the end line is an even number of
               single steps away, and both slots step the same way. */
            if (xs() & 1)
                pre[0x0082] = (uint8_t)(c.Y + (step == 0xC8 ? 2 : -2) * (1 + (int)(xs() % 6)));
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            subFail += diff_run(arms[a].name, pre, c, arms[a].nat, arms[a].ref,
                                liveMask, t, &printed);
        }
        fail += subFail;
        if (midChain == 0 || trapped == 0 || multiLine == 0 || markerTrap == 0
            || (!arms[a].rev && carryIn == 0)) {
            printf("[VACUOUS] %s: %d mid-chain entries, %d trap offsets, %d multi-line, "
                   "%d marker traps, %d carry-in of %d — all must be non-zero\n",
                   arms[a].name, midChain, trapped, multiLine, markerTrap, carryIn, armCases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=none  "
               "(%d entered mid-chain, %d trap offsets, %d ran >1 scan line, "
               "%d unexecutable markers, %d with a carry into the DDA)\n",
               arms[a].name, armCases, subFail, midChain, trapped, multiLine, markerTrap,
               carryIn);
    }

    set_ignore(0, 0);
    unsetenv("REVS_SMC_CONTINUE");
    return fail;
}


/* ==========================================================================
   $2B26 interp_edge, $1933 edge_x_offscreen, $193E fill_line_attr,
   $19AF draw_surface_spans, $1A98 mark_line_surfaces — THE REST OF THE ROAD PASS
   --------------------------------------------------------------------------
   interp_edge is the span rasteriser's setup and the three others are draw_road's stages.
   All but edge_x_offscreen drive the whole subtree below them, so a randomised pre-state
   exercises far more code than the twin — which is the point, and also why the pre-state has
   to be steered into a shape that TERMINATES.  `plant_span_world` is that shape: the four
   entry tables as the image holds them, both plotters' destinations at a real surface_edge
   buffer, page-aligned screen pointers, and the per-circuit sites at Silverstone's own bytes
   or a hook.  Everything the routines themselves compute is left random.
   ========================================================================== */
void interp_edge(void);
void interp_edge__t6502(void);
void edge_x_offscreen(void);
void edge_x_offscreen__t6502(void);
void fill_line_attr(void);
void fill_line_attr__t6502(void);
void draw_surface_spans(void);
void draw_surface_spans__t6502(void);
void mark_line_surfaces(void);
void mark_line_surfaces__t6502(void);

static void plant_span_world(uint8_t* pre)
{
    memcpy(pre + 0x3E50, ARM_OFF_SHALLOW_FWD, 8);
    memcpy(pre + 0x40D0, ARM_OFF_SHALLOW_REV, 8);
    memcpy(pre + 0x3ED0, ARM_OFF_STEEP_FWD,   8);
    memcpy(pre + 0x3ED8, ARM_OFF_STEEP_REV,   8);
    pre[0x2F4F] = pre[0x2F91] = 0x54;          /* surface_edge_0 — a real destination */
    pre[0x2F50] = pre[0x2F92] = 0x05;
    pre[0x0070] = pre[0x0072] = pre[0x008E] = 0x00;
    pre[0x0071] = pre[0x0073] = 0x40;
    pre[0x008F] = 0x41;
    pre[0x2F47] = pre[0x2F60] = pre[0x2F89] = pre[0x2FA2] = 0xC8;
    pre[0x2FC0] = pre[0x2FD7] = 0xE0;
    pre[0x1971] = 0x04;                        /* line_attr's fixed page */
    plant_cap_smc(pre);
}

/* $1946 — fill_line_attr's per-circuit site: Silverstone's own call, a circuit hook, or
   garbage so the trap arm is tested. */
static void plant_line_attr_smc(uint8_t* pre)
{
    unsigned shape = xs() % 10;
    if (shape < 7)      { pre[0x1946] = 0x20; pre[0x1947] = 0x33; pre[0x1948] = 0x19; }
    else if (shape < 9) { pre[0x1946] = 0x20; pre[0x1947] = 0x22; pre[0x1948] = 0x5A; }
    else                  pre[0x1946] = (uint8_t)xs();
}

static int test_road_pass(void)
{
    static uint8_t pre[65536];
    /* edge_x_offscreen / fill_line_attr / mark_line_surfaces return a real value to draw_road
       in a register or a flag — their caller reads it, so the exit ABI is validated. */
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    /* ⭐ interp_edge's CARRY is now an explicit argument and its exit A and flags are dead, so
       what remains live is only X and Y — and those are not a computed result: they are the
       caller's own far/near indices, restored so the transliterated caller can step them.  A
       is validated as dead, the flags too; the RESULT is mem[] + the hw/mos traces. */
    const unsigned liveEdge = LIVE_X | LIVE_Y;
    /* ⭐ draw_surface_spans returns NOTHING: its caller (draw_road) never reads its exit
       A/X/Y/flags, so the whole exit register state is an implementation detail. */
    const unsigned liveNone = LIVE_NONE;
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    const int offCases = 2000 * scale, interpCases = 600 * scale,
              attrCases = 800 * scale, spanCases = 300 * scale, markCases = 800 * scale;

    register_fixture("edge_x_offscreen");
    register_fixture("interp_edge");
    register_fixture("fill_line_attr");
    register_fixture("draw_surface_spans");
    register_fixture("mark_line_surfaces");
    setenv("REVS_SMC_CONTINUE", "1", 1);

    if (want("edge_x_offscreen")) {
        int subFail = 0, off = 0;
        for (t = 0; t < offCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            /* ⭐ D=0: draw_road's subtree is never entered in decimal mode (docs/static-map.md
               §Decimal mode — the 8 SED sites are race-stats / marker-draw / front-end, each
               bracketed by its own CLD), so the twin's `+ $14` is plain binary.  fill_line_attr,
               the only routine that calls this one, has pinned D=0 on the same citation all
               along; determinism-drive is the backstop that it truly holds. */
            c.D = 0;
            if ((uint8_t)(pre[0x5E90 + c.X] + 0x14) >= 0x28) off++;
            subFail += diff_run("edge_x_offscreen", pre, c, edge_x_offscreen,
                                edge_x_offscreen__t6502, liveMask, t, &printed);
        }
        fail += subFail;
        if (off == 0 || off == offCases) {
            printf("[VACUOUS] edge_x_offscreen: %d of %d off axis — both answers must occur\n",
                   off, offCases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  (%d off axis)\n",
               "edge_x_offscreen", offCases, subFail, off);
    }

    if (want("interp_edge")) {
        int subFail = 0, drew = 0, published = 0, swapped = 0, solid = 0;
        for (t = 0; t < interpCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            plant_span_world(pre);
            /* The endpoint's x decides whether a span is drawn at all: the block index it
               yields has to stay under $28, which is x in $30..$CF.  Two thirds of the cases
               are inside that window and the rest test the "off the side" exit. */
            if (xs() % 3) pre[0x007E] = (uint8_t)(0x30 + xs() % 0xA0);
            /* ⭐ Steer a handful of cases onto the block==$28 boundary ($7E in $D0..$D3), the
               tightest off-side value.  The 6502 test is CMP #$28 / BCS (>= $28); the fixed PRNG
               stream never rolls this exact window on its own, so the sabotage that weakens the
               test to > $28 would otherwise survive as a pure coverage gap. */
            if (t % 40 == 0) pre[0x007E] = (uint8_t)(0xD0 + (xs() & 3));
            pre[0x0083] = (uint8_t)(0x20 + xs() % 0xC0);
            pre[0x0084] = (uint8_t)(0x20 + xs() % 0xC0);
            pre[0x0027] = (uint8_t)(xs() % 4);          /* the pass number */
            pre[0x004B] = (uint8_t)(xs() % 0x50);       /* the side's end cursor */
            pre[0x004F] = (uint8_t)(xs() % 0x50);
            pre[0x007F] = (uint8_t)(xs() % 0x50);       /* the span's start line */
            c.A = (uint8_t)(xs() % 0x20);               /* the style record index */
            /* ⭐ A style whose first byte is $00 is the "all four columns" case: the routine
               substitutes $55 and WRITES IT BACK into the record.  With a random byte that
               happens twice in 600 and the sabotage that drops the substitution PASSED. */
            if (xs() % 8 == 0) { pre[0x5FD0 + c.A] = 0x00; solid++; }
            c.X = (uint8_t)(xs() % 0x50);
            c.Y = (uint8_t)(xs() % 0x50);
            pre[0x5F20 + c.Y] = (uint8_t)(xs() % 0x60);
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1;
            c.C = (uint8_t)(xs() % 4 == 0);             /* the publish-only argument */
            c.D = 0;
            if (c.C) published++;
            /* ⚠ The oracle (interp_edge__t6502) still does PHP on entry to capture the caller's
               carry; the twin takes it as a parameter and never touches the stack.  The only
               mem[] that PHP writes is the one 6502-stack byte at $01FF, which nothing reads —
               ignore it so the RESULT is compared, not a dead push. */
            { static const uint16_t ig[] = { 0x01FF }; set_ignore(ig, 1); }
            subFail += diff_run("interp_edge", pre, c, interp_edge, interp_edge__t6502,
                                liveEdge, t, &printed);
            set_ignore(0, 0);
            if (mem[0x0085] < 0x28 && !c.C) drew++;
            if (mem[0x001E] & 0x80) swapped++;
        }
        fail += subFail;
        if (drew == 0 || published == 0 || swapped == 0 || solid == 0) {
            printf("[VACUOUS] interp_edge: %d drew, %d publish-only, %d swapped, %d solid of "
                   "%d — all four must be non-zero\n",
                   drew, published, swapped, solid, interpCases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=XY ($01FF ignored)  "
               "(%d reached a span walk, %d publish-only, %d swapped the endpoints, "
               "%d solid patterns)\n",
               "interp_edge", interpCases, subFail, drew, published, swapped, solid);
    }

    if (want("fill_line_attr")) {
        int subFail = 0, clamped = 0, marked = 0;
        for (t = 0; t < attrCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            plant_span_world(pre);
            plant_line_attr_smc(pre);
            { int i; for (i = 0; i < 0x50; i++) pre[0x5F20 + i] = (uint8_t)(xs() % 0x60); }
            pre[0x001F] = (uint8_t)(xs() % 0x50);       /* horizon_extent — the start line */
            pre[0x0050] = (uint8_t)(xs() % 0x50);       /* road_split_index */
            c.A = (xs() & 1) ? 0x00 : 0x50;             /* which line_attr buffer */
            c.Y = (uint8_t)(xs() % 0x50);               /* the side's end cursor */
            c.X = (uint8_t)(xs() % 0x50);               /* the first edge point */
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            subFail += diff_run("fill_line_attr", pre, c, fill_line_attr,
                                fill_line_attr__t6502, liveMask, t, &printed);
            if (mem[0x007F] == 0) clamped++;
            { int i, m = 0;
              for (i = 0; i < 0x50; i++) if (mem[0x5EE0 + i] & 0x80) m++;
              if (m) marked++; }
        }
        fail += subFail;
        if (clamped == 0 || marked == 0) {
            printf("[VACUOUS] fill_line_attr: %d clamped, %d marked a point of %d\n",
                   clamped, marked, attrCases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d filled to line 0, %d marked at least one point)\n",
               "fill_line_attr", attrCases, subFail, clamped, marked);
    }

    if (want("draw_surface_spans")) {
        int subFail = 0, ran = 0, movedSplit = 0;
        for (t = 0; t < spanCases; t++) {
            Cpu6502 c = zero_cpu();
            uint8_t splitBefore;
            fill_random(pre);
            plant_span_world(pre);
            { int i; for (i = 0; i < 0x50; i++) pre[0x5F20 + i] = (uint8_t)(xs() % 0x60); }
            pre[0x004B] = (uint8_t)(4 + xs() % 0x14);   /* a short walk, or it is minutes */
            /* ⭐ Half the cases put road_split_index exactly where the walk will arrive:
               the "at the split" arm is a single index out of the whole walk, and with a
               uniform value it ran 6 times in 300. */
            pre[0x0050] = (uint8_t)(xs() % 0x18);
            pre[0x0032] = (uint8_t)(xs() % 0x20);
            pre[0x008C] = (uint8_t)(xs() % 0x20);
            pre[0x007E] = (uint8_t)(0x30 + xs() % 0xA0);
            pre[0x007F] = (uint8_t)(xs() % 0x50);
            pre[0x0083] = (uint8_t)(0x20 + xs() % 0xC0);
            pre[0x0084] = (uint8_t)(0x20 + xs() % 0xC0);

            c.Y = (uint8_t)(xs() % 4);                  /* the pass */
            c.A = (uint8_t)(xs() % 0x10);               /* the first edge index */
            if (xs() & 1) pre[0x0050] = (uint8_t)(c.A + xs() % 6);
            c.X = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            splitBefore = pre[0x0050];
            subFail += diff_run("draw_surface_spans", pre, c, draw_surface_spans,
                                draw_surface_spans__t6502, liveNone, t, &printed);
            if (c.A < pre[0x004B]) ran++;
            if (mem[0x0050] != splitBefore) movedSplit++;
        }
        fail += subFail;
        if (ran == 0 || movedSplit == 0) {
            printf("[VACUOUS] draw_surface_spans: %d walked, %d moved the split of %d\n",
                   ran, movedSplit, spanCases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=none  "
               "(%d ran the walk, %d moved road_split_index)\n",
               "draw_surface_spans", spanCases, subFail, ran, movedSplit);
    }

    if (want("mark_line_surfaces")) {
        int subFail = 0, walked = 0, stamped = 0;
        for (t = 0; t < markCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            { int i; for (i = 0; i < 0x60; i++) pre[0x5F20 + i] = (uint8_t)(xs() % 0x60); }
            /* Past $28 the routine does nothing but compute its return value, and that arm
               is one case in four rather than 216 in 256. */
            pre[0x62F2] = (xs() % 4) ? (uint8_t)(xs() % 0x28) : (uint8_t)(0x28 + xs() % 0xD8);
            pre[0x004B] = (uint8_t)(1 + xs() % 0x30);
            pre[0x0050] = (uint8_t)(xs() % 0x50);
            c.X = (xs() & 1) ? 0x04 : 0x14;             /* the surface class */
            c.A = (uint8_t)(xs() % 0x28);               /* the first edge point */
            c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            if (pre[0x62F2] < 0x28) walked++;
            subFail += diff_run("mark_line_surfaces", pre, c, mark_line_surfaces,
                                mark_line_surfaces__t6502, liveMask, t, &printed);
            { int i, n = 0;
              for (i = 0; i < 0x50; i++) if (mem[0x5F60 + i]) n++;
              if (n) stamped++; }
        }
        fail += subFail;
        if (walked == 0 || walked == markCases || stamped == 0) {
            printf("[VACUOUS] mark_line_surfaces: %d walked, %d stamped of %d — the skip arm "
                   "and the walk must both run\n", walked, stamped, markCases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d below 45 degrees, %d left a class behind)\n",
               "mark_line_surfaces", markCases, subFail, walked, stamped);
    }

    unsetenv("REVS_SMC_CONTINUE");
    return fail;
}

/* ==========================================================================
   TWINS #40-#43 — THE VIEW/DASHBOARD SEAM'S CALLEES
   --------------------------------------------------------------------------
   $1E9E surface_colour_at, $1DAF column_gap_walk, $1DA6 fill_column_gaps and
   $1DEF fill_edge_column_run.  Three things have to be steered or the cases land on
   nothing:

   1. surface_colour_at IS SIX ARMS AND A UNIFORM BYTE PICKS ONE.  The horizon test alone
      sends half the cases straight out, and the four boundary compares are nested, so the
      innermost arm (the line's own background) needs all four to fall through — about one
      case in sixteen by luck.  The fixture pins the line below the horizon in most cases and
      COUNTS which arm each case took, so a zero is a failure and not a silent gap.

   2. column_gap_walk'S BRANCH OFFSET IS AN OPCODE-LEVEL INPUT.  $1DD5 is a branch offset the
      caller plants; only $09 and $EF are arms the engine ever uses, and the twin traps on
      anything else.  Both arms and the trap are exercised, and the trap has to trap in BOTH
      models (the oracle's switch has a `default:` for exactly this).

   3. THE POINTER IT STORES THROUGH CAN BE ANYTHING under fill_random, including page zero and
      the hardware window — and the oracle re-reads that pointer at every store, so a hoisted
      base is only correct while the walk cannot reach it.  Both cases are planted on purpose:
      the game's own pointers ($70/$72) and a random zero-page number.
   ========================================================================== */
void surface_colour_at(void);
void surface_colour_at__t6502(void);
void column_gap_walk(void);
void column_gap_walk__t6502(void);
void fill_column_gaps(void);
void fill_column_gaps__t6502(void);
void fill_edge_column_run(void);
void fill_edge_column_run__t6502(void);

#define PRE_HORIZON_EXTENT 0x001F
#define PRE_EDGE_COLUMN    0x0085
#define PRE_BLOCK_START    0x0082
#define PRE_LINE_CURSOR    0x007F
#define PRE_GAP_BRANCH     0x1DD5
#define PRE_GAP_FALLBACK   0x1DDC
#define PRE_GAP_POINTER    0x1DDE

/* Which of surface_colour_at's six arms a case takes, decided from the PRE state — nothing
   the routine calls writes any of these cells. */
enum { SC_SKY = 0, SC_EDGE0, SC_ATTR1, SC_EDGE3, SC_ATTR0, SC_INSIDE, SC_ARMS };
static int surface_arm(const uint8_t* pre, uint8_t line)
{
    unsigned pos = pre[PRE_EDGE_COLUMN];
    if (line > pre[PRE_HORIZON_EXTENT])       return SC_SKY;
    if (pos >= pre[0x0554 + line])            return SC_EDGE0;
    if (pos >= pre[0x0600 + line])            return SC_ATTR1;
    if (pos >= pre[0x0650 + line])            return SC_EDGE3;
    if (pos >= pre[0x05A4 + line])            return SC_ATTR0;
    return SC_INSIDE;
}

static int test_seam_callees(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    const int colourCases = 2000 * scale, walkCases = 1200 * scale,
              patchCases = 600 * scale, runCases = 400 * scale;

    register_fixture("surface_colour_at");
    register_fixture("column_gap_walk");
    register_fixture("fill_column_gaps");
    register_fixture("fill_edge_column_run");
    setenv("REVS_SMC_CONTINUE", "1", 1);

    if (want("surface_colour_at")) {
        int subFail = 0, arms[SC_ARMS] = {0}, i;
        for (t = 0; t < colourCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs();
            /* The line: below the horizon in three cases of four, so the five arms under it
               get exercised; the position is what the four boundary compares see. */
            pre[PRE_HORIZON_EXTENT] = (uint8_t)(xs() % 0x50);
            c.Y = (xs() % 4) ? (uint8_t)(xs() % (pre[PRE_HORIZON_EXTENT] + 1u))
                             : (uint8_t)xs();
            /* Pull the boundaries and the position into the same narrow range, or the four
               nested compares are decided by the first one nearly every time. */
            pre[PRE_EDGE_COLUMN] = (uint8_t)(xs() % 0x2A);
            pre[0x0554 + c.Y] = (uint8_t)(xs() % 0x2A);
            pre[0x0600 + c.Y] = (uint8_t)(xs() % 0x2A);
            pre[0x0650 + c.Y] = (uint8_t)(xs() % 0x2A);
            pre[0x05A4 + c.Y] = (uint8_t)(xs() % 0x2A);
            /* Both line_attr limits straddle the line, so each arm's "past its limit" exit
               and its table read both happen. */
            pre[0x002C] = (uint8_t)(c.Y + (xs() % 3) - 1);
            pre[0x0029] = (uint8_t)(c.Y + (xs() % 3) - 1);
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            arms[surface_arm(pre, c.Y)]++;
            subFail += diff_run("surface_colour_at", pre, c, surface_colour_at,
                                surface_colour_at__t6502, liveMask, t, &printed);
        }
        fail += subFail;
        for (i = 0; i < SC_ARMS; i++)
            if (arms[i] == 0) {
                printf("[VACUOUS] surface_colour_at: arm %d never taken\n", i);
                fail++;
            }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(arms sky/e0/attr1/e3/attr0/inside = %d/%d/%d/%d/%d/%d)\n",
               "surface_colour_at", colourCases, subFail, arms[0], arms[1], arms[2],
               arms[3], arms[4], arms[5]);
    }

    if (want("column_gap_walk")) {
        int subFail = 0, walked = 0, skipped = 0, trapped = 0, offPage = 0, zpPtr = 0, emptied = 0;
        for (t = 0; t < walkCases; t++) {
            Cpu6502 c = zero_cpu();
            unsigned pick;
            fill_random(pre);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            /* A column past $27 has no source block and the walk returns at once, so most
               cases get a real one — but the early-return arm must see the boundary VALUE $28
               itself (`>= $28`, not `> $28`), which a uniform random byte hits ~1/256, so pin it. */
            { unsigned r = xs() % 8;
              pre[PRE_EDGE_COLUMN] = r < 6 ? (uint8_t)(xs() % 0x28)            /* in range */
                                   : (r == 6 ? 0x28u                            /* the boundary */
                                             : (uint8_t)(0x29u + xs() % 0xD7)); /* above it */ }
            /* The walk is Y down to mem[$82]: keep it a few dozen lines, not a few hundred. */
            pre[PRE_LINE_CURSOR] = (uint8_t)(0x10 + xs() % 0x40);
            pre[PRE_BLOCK_START] = (uint8_t)(pre[PRE_LINE_CURSOR] - 1 - xs() % 0x20);
            pre[PRE_HORIZON_EXTENT] = (uint8_t)(xs() % 0x50);
            pre[PRE_GAP_FALLBACK] = (xs() & 1) ? 0x55 : (uint8_t)xs();
            /* The branch offset: both real arms, and an illegal one that must trap in BOTH
               models rather than run some third path. */
            /* ⚠⚠ THE ILLEGAL OFFSET MUST LAND OUTSIDE THE REGION, not merely off the two
               arms.  A random offset is a legal branch to some other instruction boundary in
               the same code, and several of those (anything at or above $1DC0, which reloads
               Y from span_line_cursor) make the ORACLE loop forever — the first version of
               this fixture hung the harness.  These four all leave the switch, so both models
               trap. */
            { static const uint8_t offRegion[4] = { 0x40, 0x60, 0x7F, 0x81 };
              pick = xs() % 16;
              pre[PRE_GAP_BRANCH] = pick < 7 ? 0x09
                                  : (pick < 14 ? 0xEF : offRegion[xs() % 4]); }
            if (pre[PRE_GAP_BRANCH] == 0x09) skipped++;
            else if (pre[PRE_GAP_BRANCH] == 0xEF) walked++;
            else trapped++;
            /* The store pointer: the engine's own two, or a random zero-page pair — which is
               what makes "the store can land on its own pointer" a tested case. */
            pick = xs() % 8;
            pre[PRE_GAP_POINTER] = pick < 4 ? 0x70 : (pick < 7 ? 0x72 : (uint8_t)xs());
            if (pre[PRE_GAP_POINTER] != 0x70 && pre[PRE_GAP_POINTER] != 0x72) {
                zpPtr++;
                /* ⭐ ...and AIM that random pair at the pointer cells.  Leaving the pair itself
                   random made "the colour store lands on $70..$73" a lottery that a shift in the
                   shared PRNG stream could win or lose — the sabotage for it flipped from CAUGHT
                   to SURVIVED when an unrelated plant moved the stream.  A hazard worth testing
                   is worth aiming at (docs/wide-value-cleanup.md §the fixture had to be AIMED). */
                pre[pre[PRE_GAP_POINTER]] = (uint8_t)(0x40u + (xs() % 0x40u));
                pre[(pre[PRE_GAP_POINTER] + 1u) & 0xFFu] = 0x00u;
            }
            /* One case in eight aims plot_ptr2 into the hardware window, and one in eight at
               ZERO PAGE, near the pointer cells themselves.
               ⭐ The boundary-table pass ($1DC5) stores THROUGH plot_ptr2, so that store can land
               on $70..$73 — the same self-write hazard the random GAP_POINTER covers for the
               colour store, and until the second arm existed the plot_ptr2 resync was untested
               ($0073 is otherwise a random byte, page $00 one time in 256, and the store then
               has to hit four cells out of it).
               ⚠ ONE DRAW PER ARM, deliberately: this suite's PRNG is a single shared stream, and
               an arm that consumes an extra xs() shifts every later case.  Adding this as a
               second `if` did exactly that and flipped an unrelated sabotage from CAUGHT to
               SURVIVED (docs/validation-harness.md). */
            { unsigned aim = xs() % 8;
              if (aim == 0)      { pre[0x0072] = (uint8_t)xs(); pre[0x0073] = 0xFE; offPage++; }
              else if (aim == 1) { pre[0x0072] = (uint8_t)(0x40u + (xs() % 0x40u));
                                   pre[0x0073] = 0x00u; } }
            /* One case in four with a real column zeroes the whole source-block region
               ($3000-$4400, which contains surface_colours at $38FC): every cell then reads
               empty AND surface_colour_at returns colour 0, so the walk takes the fallback
               substitution ("a zero surface becomes GAP_FALLBACK") on every line — the one path
               that a random, mostly-non-zero source almost never reaches. */
            if (pre[PRE_EDGE_COLUMN] < 0x28 && xs() % 4 == 0) {
                memset(&pre[0x3000], 0, 0x1400);
                pre[PRE_GAP_FALLBACK] = 0x99;   /* non-zero, so dropping the substitution shows */
                emptied++;
            }
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            { int before = subFail;
              subFail += diff_run("column_gap_walk", pre, c, column_gap_walk,
                                column_gap_walk__t6502, liveMask, t, &printed);
              if (subFail != before && getenv("REVS_DEBUG_WALK"))
                printf("  case %d: col=$%02X cur=$%02X end=$%02X off=$%02X fb=$%02X ptr=$%02X "
                       "p70=$%02X%02X p72=$%02X%02X hz=$%02X\n", t,
                       pre[PRE_EDGE_COLUMN], pre[PRE_LINE_CURSOR], pre[PRE_BLOCK_START],
                       pre[PRE_GAP_BRANCH], pre[PRE_GAP_FALLBACK], pre[PRE_GAP_POINTER],
                       pre[0x0071], pre[0x0070], pre[0x0073], pre[0x0072],
                       pre[PRE_HORIZON_EXTENT]); }
        }
        fail += subFail;
        if (!walked || !skipped || !trapped || !offPage || !zpPtr || !emptied) {
            printf("[VACUOUS] column_gap_walk: %d table-pass, %d block-pass, %d trap, "
                   "%d into SHEILA, %d random zp pointer, %d empty-source — all must be non-zero\n",
                   walked, skipped, trapped, offPage, zpPtr, emptied);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d table-pass, %d block-pass, %d trap, %d SHEILA, %d random zp, %d empty-src)\n",
               "column_gap_walk", walkCases, subFail, walked, skipped, trapped,
               offPage, zpPtr, emptied);
    }

    if (want("fill_column_gaps")) {
        int subFail = 0;
        for (t = 0; t < patchCases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            /* The three registers ARE the patch, so they are the input: the two real
               configurations most of the time, a random triple the rest. */
            if (xs() & 1) { c.X = 0x72; c.Y = 0xEF; c.A = 0x00; }
            else if (xs() & 1) { c.X = 0x70; c.Y = 0x09; c.A = 0x55; }
            else { c.X = (uint8_t)xs(); c.Y = (xs() & 1) ? 0x09 : 0xEF; c.A = (uint8_t)xs(); }
            pre[PRE_EDGE_COLUMN] = (xs() % 8) ? (uint8_t)(xs() % 0x28) : (uint8_t)xs();
            pre[PRE_LINE_CURSOR] = (uint8_t)(0x10 + xs() % 0x40);
            pre[PRE_BLOCK_START] = (uint8_t)(pre[PRE_LINE_CURSOR] - 1 - xs() % 0x20);
            pre[PRE_HORIZON_EXTENT] = (uint8_t)(xs() % 0x50);
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            subFail += diff_run("fill_column_gaps", pre, c, fill_column_gaps,
                                fill_column_gaps__t6502, liveMask, t, &printed);
        }
        fail += subFail;
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(the register-to-patch-byte mapping; the walk is column_gap_walk's fixture)\n",
               "fill_column_gaps", patchCases, subFail);
    }

    if (want("fill_edge_column_run")) {
        int subFail = 0, oneColumn = 0, multi = 0;
        for (t = 0; t < runCases; t++) {
            Cpu6502 c = zero_cpu();
            unsigned length;
            fill_random(pre);
            /* X = the first column, A = the column to stop at.  The loop tests EQUALITY, so
               an unreachable stop column runs 128 iterations of two walks each: pick the
               run's LENGTH and derive the stop, keeping the engine's own shape (columns 3-6
               and $1A-$22, i.e. runs of three and eight). */
            length = 1 + xs() % 8;
            c.X = (uint8_t)(xs() % 0x20);
            c.A = (uint8_t)(c.X + length);
            c.Y = (uint8_t)(0x10 + xs() % 0x40);
            if (length == 1) oneColumn++; else multi++;
            pre[PRE_HORIZON_EXTENT] = (uint8_t)(xs() % 0x50);
            /* Both passes' pointers, so the run writes where the engine's would. */
            pre[0x0072] = (xs() & 1) ? 0x04 : 0x00;
            pre[0x0073] = pre[0x0072] == 0x04 ? 0x05 : 0x44;
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            subFail += diff_run("fill_edge_column_run", pre, c, fill_edge_column_run,
                                fill_edge_column_run__t6502, liveMask, t, &printed);
        }
        fail += subFail;
        if (!oneColumn || !multi) {
            printf("[VACUOUS] fill_edge_column_run: %d single-column, %d multi-column runs\n",
                   oneColumn, multi);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d one-column runs, %d longer)\n",
               "fill_edge_column_run", runCases, subFail, oneColumn, multi);
    }

    unsetenv("REVS_SMC_CONTINUE");
    return fail;
}

/* ==========================================================================
   TWINS #44-#49 — THE ENGINE'S MULTIPLY, AND THE NEGATE BESIDE IT
   --------------------------------------------------------------------------
   $0C00 mul8, $0C02 mul8_noinit, $0DBF mul8_accum, $0DB3 mul16_by_pi, $0E42 neg16_math and
   $0E44 neg16_math_noinit.  These are pure arithmetic on four zero-page cells, so the
   fixtures are cheap and can afford to be EXHAUSTIVE where it counts:

   ⭐ mul8_noinit RUNS ALL 65536 OPERAND PAIRS.  The twin replaces eight unrolled add/shift
      steps with one 16-bit multiply plus a replay of the last add's V, and "0 mismatch over
      every input" is the only evidence that turns that from a plausible identity into a
      proven one.  The zero multiplier (no add runs, so the CALLER's V survives) and the
      $FF x $FF corner are inside the sweep by construction.
   ⚠ DECIMAL MODE IS A SEPARATE PASS, not a percentage of a random one.  D changes the result
      byte of every ADC, so with D set the routine is not a multiply at all and the twin falls
      back to a bit-for-bit replay; that path needs its own cases or the exhaustive sweep above
      (which must run with D clear to mean anything) would hide it entirely.
   ========================================================================== */
void mul8(void);              void mul8__t6502(void);
void mul8_noinit(void);       void mul8_noinit__t6502(void);
void mul8_accum(void);        void mul8_accum__t6502(void);
void mul16_by_pi(void);       void mul16_by_pi__t6502(void);
void neg16_math(void);        void neg16_math__t6502(void);
void neg16_math_noinit(void); void neg16_math_noinit__t6502(void);

#define PRE_MATH_LO 0x0074
#define PRE_MATH_HI 0x0075
#define PRE_TEMP_76 0x0076

static int test_multiply(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    register_fixture("mul8_noinit");
    register_fixture("mul8");
    register_fixture("mul8_accum");
    register_fixture("mul16_by_pi");
    register_fixture("neg16_math");
    register_fixture("neg16_math_noinit");

    if (want("mul8_noinit")) {
        int subFail = 0, lo, hi, decimalCases = 400 * scale;
        /* One random background, reused: the routine touches four cells and nothing else, so
           a fresh fill_random per case would cost 65536 x 64 KB for no extra coverage. */
        fill_random(pre);
        for (lo = 0; lo < 256 && subFail < 12; lo++)
            for (hi = 0; hi < 256; hi++) {
                Cpu6502 c = zero_cpu();
                pre[PRE_MATH_LO] = (uint8_t)lo;
                pre[PRE_MATH_HI] = (uint8_t)hi;
                c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
                c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
                c.D = 0;
                subFail += diff_run("mul8_noinit", pre, c, mul8_noinit, mul8_noinit__t6502,
                                    liveMask, lo * 256 + hi, &printed);
            }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(EXHAUSTIVE: every operand pair, D clear)\n",
               "mul8_noinit", 65536, subFail);
        fail += subFail;
        (void)decimalCases;
        /* No decimal arm: mul8_noinit is a math primitive, never entered with D set
           (docs/static-map.md §Decimal mode — the 8 SED sites are elsewhere), and its twin is
           now plain binary C. */
    }

    /* The other five share a shape: randomised background, randomised registers, a quarter of
       the cases in decimal mode, and the arithmetic cells pinned only where a uniform byte
       would miss something (mul8_accum's carry, mul16_by_pi's shift out of the top). */
    { struct { const char* name; void (*nat)(void); void (*ref)(void); int cases; }
        list[5] = {
          { "mul8",              mul8,              mul8__t6502,              4000 },
          { "mul8_accum",        mul8_accum,        mul8_accum__t6502,        4000 },
          { "mul16_by_pi",       mul16_by_pi,       mul16_by_pi__t6502,       4000 },
          { "neg16_math",        neg16_math,        neg16_math__t6502,        2000 },
          { "neg16_math_noinit", neg16_math_noinit, neg16_math_noinit__t6502, 2000 },
        };
      int i;
      for (i = 0; i < 5; i++) {
        int subFail = 0, zeroOperand = 0, cases = list[i].cases * scale;
        /* ⭐ All five are now plain binary C, pinned D = 0.  The three multiplies (mul8,
           mul8_accum, mul16_by_pi) route through mul8_noinit, and neg16_math / neg16_math_noinit
           are idiomatic 16-bit negates; every caller of all five is on the geometry / driving /
           steering path, which is D = 0 (docs/static-map.md §Decimal mode, settled), and
           make determinism-drive is the backstop.
           ⭐ The two negates (i == 3, i == 4) are verified on their RESULT (math_lo, math_hi, A),
           not their exit flags: the 6502 routines leave the second subtract's N/V/Z/C behind, but
           EVERY caller overwrites them before a branch — LDA/LDY at the four transliteration
           sites, and poll_steering_assist at the $15EE→steer_apply_with_assist one — so the flags
           are dead scratch, not a result.  A (the negated high byte) IS a documented output. */
        int binaryNeg = (i == 3 || i == 4);
        unsigned negMask = binaryNeg ? (LIVE_A | LIVE_X | LIVE_Y) : liveMask;
        if (!want(list[i].name)) continue;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            /* A zero operand is the one case with no ADC in it at all, so the caller's V has
               to survive — one case in 256 by luck, one in eight here. */
            if (xs() % 8 == 0) { pre[PRE_MATH_LO] = 0; zeroOperand++; }
            if (xs() % 8 == 0) { pre[PRE_MATH_HI] = 0; }
            if (xs() % 8 == 0) { pre[PRE_TEMP_76] = 0; }
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = 0;
            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                negMask, t, &printed);
        }
        fail += subFail;
        if (!zeroOperand) {
            printf("[VACUOUS] %s: %d zero-operand cases\n", list[i].name, zeroOperand);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  %s  "
               "(D clear, %d with a zero operand)\n",
               list[i].name, cases, subFail,
               binaryNeg ? "live=AXY (flags dead)" : "live=AXY+flags", zeroOperand);
      }
    }
    return fail;
}

/* ==========================================================================
   TWINS #50-#57 — THE DRIVING MODEL'S 16-BIT ARITHMETIC
   --------------------------------------------------------------------------
   $0DD7 mul16_signed, $4753 scale16_by_y, $4765 mul16_by_1_5,
   $47E5 model_integrate_element, $48A0 add_signed_into_element,
   $4874 apply_angle_term, $486D apply_angle_term_at, $0E50 kbd_test_key.

   ⚠⚠ TWO OF THESE BRANCH ON THE CALLER'S N, not on anything in mem[]: scale16_by_y (via
   abs16_math, and it carries that N across the multiply on the STACK) and
   add_signed_into_element, where a set N means "subtract".  Every case here therefore
   randomises N INDEPENDENTLY of the value — a third of them deliberately decorrelated — which
   is the trap abs8 and abs16_math already taught this harness.

   ⚠ apply_angle_term's two paths are chosen by BIT 6 of the sign byte, and its element indices
   are used as offsets into the 15-element state vector, so both are steered: a uniform byte
   would index far outside the vector and compare two identical out-of-range walks.

   ⭐ kbd_test_key reaches the MOS, so what it proves is that the twin makes the SAME call with
   the same registers — the answer comes back from platform_mos_call in both models.
   ========================================================================== */
void mul16_signed(void);            void mul16_signed__t6502(void);
void scale16_by_y(void);            void scale16_by_y__t6502(void);
void mul16_by_1_5(void);            void mul16_by_1_5__t6502(void);
void model_integrate_element(void);  void model_integrate_element__t6502(void);
void add_signed_into_element(void);  void add_signed_into_element__t6502(void);
void apply_angle_term(void);        void apply_angle_term__t6502(void);
void apply_angle_term_at(void);     void apply_angle_term_at__t6502(void);
void kbd_test_key(void);            void kbd_test_key__t6502(void);

#define PRE_ANGLE_SRC_LO  0x0080
#define PRE_ANGLE_TERM_LO 0x0082
#define PRE_ANGLE_SIGN    0x0079
#define PRE_MODEL_TERM    0x007C
#define PRE_MODEL_SRC     0x007F

static int test_model_arithmetic(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); int cases; }
      list[8] = {
        { "mul16_signed",           mul16_signed,           mul16_signed__t6502,           4000 },
        { "scale16_by_y",           scale16_by_y,           scale16_by_y__t6502,           3000 },
        { "mul16_by_1_5",           mul16_by_1_5,           mul16_by_1_5__t6502,           2000 },
        { "model_integrate_element", model_integrate_element, model_integrate_element__t6502, 1000 },
        { "add_signed_into_element", add_signed_into_element, add_signed_into_element__t6502, 2000 },
        { "apply_angle_term",       apply_angle_term,       apply_angle_term__t6502,       2000 },
        { "apply_angle_term_at",    apply_angle_term_at,    apply_angle_term_at__t6502,    2000 },
        { "kbd_test_key",           kbd_test_key,           kbd_test_key__t6502,            500 },
      };
    for (i = 0; i < 8; i++) register_fixture(list[i].name);

    /* ⭐ add_signed_into_element (i == 4) and apply_angle_term[_at] (i == 5, 6) are verified
       RESULT-ONLY: their native twins are plain 16-bit binary C leaving nothing in the cpu, so
       the fixture pins D = 0 (the driving model's precondition — docs/static-map.md §Decimal
       mode), drops the register/flag comparison, and ignores the oracle's arithmetic scratch.
       add_signed's negate arm spills the math accumulator $74/$75.
       ⭐ apply_angle_term folds the $0DD7 signed multiply into plain 16-bit C (it is that
       multiply's only caller), so it no longer spills mul16_signed's 6502 marshalling: the
       operand copies $80-$83, the accumulator round-trip $74-$78, and the sign/mode accumulator
       $79 (which the multiply flips bit 7 of, while the twin leaves it at the caller's seed).
       Those are pure implementation detail of the transliterated multiply the oracle still runs —
       ignore them so the compared state is the RESULT (model element `dest`). */
    static const uint16_t addIgnore[] = { 0x0074, 0x0075 };
    static const uint16_t mulIgnore[] = { 0x0074, 0x0075, 0x0076, 0x0077, 0x0078, 0x0079,
                                          0x0080, 0x0081, 0x0082, 0x0083 };

    for (i = 0; i < 8; i++) {
        int subFail = 0, decimal = 0, decorrelated = 0, negative = 0, accumulate = 0;
        int cases = list[i].cases * scale;
        int resultOnly = (i >= 4 && i <= 6);
        /* i == 0..3 (mul16_signed, scale16_by_y, mul16_by_1_5, model_integrate_element) are now
           plain binary C — mul16_signed forms its cross products with revs_mulu16, scale16_by_y
           and mul16_by_1_5 route through mul8_noinit, model_integrate_element is a binary 16-bit
           add.  All are on the driving-model path where D = 0 (docs/static-map.md §Decimal mode),
           so the fixture pins D = 0; they still compare registers/flags.  make determinism-drive
           is the backstop. */
        int pinD0 = resultOnly || (i <= 3);
        unsigned mask = resultOnly ? LIVE_NONE : liveMask;
        if (!want(list[i].name)) continue;
        if (i == 4)      set_ignore(addIgnore, 2);
        else if (i >= 5) set_ignore(mulIgnore, 10);
        else             set_ignore(0, 0);
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            /* Element indices, into a 15-element vector; the angle index picks one of three. */
            c.X = (uint8_t)(xs() % 3);
            c.Y = (uint8_t)(xs() % 15);
            c.A = (uint8_t)(xs() % 15);
            pre[PRE_MODEL_TERM] = (uint8_t)(xs() % 15);
            pre[PRE_MODEL_SRC]  = (uint8_t)(xs() % 15);
            /* Bit 7 is the sign, bit 6 chooses store-vs-accumulate: both worth splitting. */
            pre[PRE_ANGLE_SIGN] = (uint8_t)(xs() & 0xC0);
            if (pre[PRE_ANGLE_SIGN] & 0x40) accumulate++;
            /* ⚠ N is randomised INDEPENDENTLY of the value a third of the time — the two
               routines that branch on the caller's N are the whole reason for this fixture. */
            c.N = (xs() % 3) ? (uint8_t)(pre[0x0075] >> 7) : (uint8_t)(xs() & 1);
            if (c.N != (pre[0x0075] >> 7)) decorrelated++;
            if (c.N) negative++;
            c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = pinD0 ? 0 : (uint8_t)(xs() % 4 == 0);
            if (c.D) decimal++;
            /* scale16_by_y and mul16_by_1_5 want A and Y as the value/scale, not indices. */
            if (i == 1 || i == 2) { c.A = (uint8_t)xs(); c.Y = (uint8_t)xs(); }
            if (i == 7) { c.X = (uint8_t)(0x80 | (xs() & 0x7F)); c.D = 0; }
            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                mask, t, &printed);
        }
        fail += subFail;
        if ((!pinD0 && !decimal) || !decorrelated || !negative) {
            printf("[VACUOUS] %s: %d decimal, %d decorrelated N, %d negative\n",
                   list[i].name, decimal, decorrelated, negative);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=%s  "
               "(%d decimal, %d N decorrelated, %d negative, %d accumulate)\n",
               list[i].name, cases, subFail, resultOnly ? "result-only" : "AXY+flags",
               decimal, decorrelated, negative, accumulate);
    }
    set_ignore(0, 0);
    return fail;
}

/* ==========================================================================
   TWINS #58-#66 — THE DRIVING MODEL'S ROTATIONS AND INTEGRATIONS
   --------------------------------------------------------------------------
   $4729 stage_accum_delta, $47A5 rotate_accum_by_steer, $47C5 rotate_pair_a_by_steer,
   $47F9 damp_and_derive_loads, $48C7 rotate_state_pair, $48B9 rotate_state_0_into_8,
   $48C1 rotate_state_6_into_3, $48EF integrate_car_position, $4937 integrate_state_rates.

   ⚠⚠ WHAT THIS FIXTURE IS REALLY FOR IS THE EXIT REGISTERS.  Four of these routines end by
   falling out of a `DEX`/`DEY` loop, so X and Y leave holding $FF/$FE/$FE and the twins have
   to set them by hand — a class of defect that changes not one byte of mem[] and is invisible
   to anything but an AXY comparison.  liveMask therefore keeps A, X, Y, S and the flags, and
   the sabotage list below includes one deleted register write for exactly this reason.

   ⚠ TWO OF THEM READ THE CALLER'S N through scale16_by_y: stage_accum_delta hands it the
   `LDA $62E2` that loaded the value's high byte, and damp_and_derive_loads hands it a
   subtract's and an add's.  Those are computed INSIDE the routine, so unlike twins #50-#57
   the incoming N does not matter here — but it is randomised anyway, because a twin that
   forwarded the caller's N instead of its own would otherwise pass.

   ⚠ $48C7's three arguments arrive in A (dest), Y (source) and X (the sign/mode byte), and
   dest/source index the 15-element state vector — so both are steered to 0..13 rather than
   left uniform, or every case would compare two identical out-of-range walks.  Its two named
   entries take no arguments at all, which is what makes them worth their own two cases: what
   they prove is the constant triple, and nothing else.
   ========================================================================== */
void stage_accum_delta(void);       void stage_accum_delta__t6502(void);
void rotate_accum_by_steer(void);   void rotate_accum_by_steer__t6502(void);
void rotate_pair_a_by_steer(void);  void rotate_pair_a_by_steer__t6502(void);
void damp_and_derive_loads(void);   void damp_and_derive_loads__t6502(void);
void rotate_state_pair(void);       void rotate_state_pair__t6502(void);
void rotate_state_0_into_8(void);   void rotate_state_0_into_8__t6502(void);
void rotate_state_6_into_3(void);   void rotate_state_6_into_3__t6502(void);
void integrate_car_position(void);  void integrate_car_position__t6502(void);
void integrate_state_rates(void);   void integrate_state_rates__t6502(void);

static int test_model_rotations(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); int cases; }
      list[9] = {
        { "stage_accum_delta",      stage_accum_delta,      stage_accum_delta__t6502,      2000 },
        { "rotate_accum_by_steer",  rotate_accum_by_steer,  rotate_accum_by_steer__t6502,  2000 },
        { "rotate_pair_a_by_steer", rotate_pair_a_by_steer, rotate_pair_a_by_steer__t6502, 2000 },
        { "damp_and_derive_loads",  damp_and_derive_loads,  damp_and_derive_loads__t6502,  3000 },
        { "rotate_state_pair",      rotate_state_pair,      rotate_state_pair__t6502,      3000 },
        { "rotate_state_0_into_8",  rotate_state_0_into_8,  rotate_state_0_into_8__t6502,  1000 },
        { "rotate_state_6_into_3",  rotate_state_6_into_3,  rotate_state_6_into_3__t6502,  1000 },
        { "integrate_car_position", integrate_car_position, integrate_car_position__t6502, 2000 },
        { "integrate_state_rates",  integrate_state_rates,  integrate_state_rates__t6502,  2000 },
      };
    for (i = 0; i < 9; i++) register_fixture(list[i].name);

    /* ⭐ stage_accum_delta (i == 0) and damp_and_derive_loads (i == 3) are verified RESULT-ONLY:
       their native twins are plain 16-bit binary C that leaves nothing in the cpu, so the fixture
       pins D = 0 (the driving model's real precondition — docs/static-map.md §Decimal mode),
       drops the register/flag comparison, and ignores the oracle's arithmetic scratch ($74-$78)
       and stack residue ($01FF), which are the 6502's register spill and dead the moment the
       routine returns.  stage_accum_delta scales through scale16_by_y (PHP/PLP) and mul16_by_1_5
       (PHA/PLA), so its residue is $74-$77 + $01FF; damp also spills $78. */
    static const uint16_t stageIgnore[] = { 0x0074, 0x0075, 0x0076, 0x0077, 0x01FF };
    static const uint16_t dampIgnore[]  = { 0x0074, 0x0075, 0x0076, 0x0077, 0x0078, 0x01FF };

    /* ⭐ rotate_state_pair (i == 4) and its two entry aliases rotate_state_0_into_8 (5) /
       rotate_state_6_into_3 (6) are verified RESULT-ONLY, for two independent reasons that both
       have to hold:  (a) the exit registers are DEAD — the only real-program callers are $46A8 and
       $471C inside apply_driving_model, and each overwrites A/N/Z immediately ($46AB LDA $62D8 then
       a pure LDA/STA copy that never reads C/V or indexes X/Y; $471F JSR integrate_state_rates,
       which opens LDX #2 / LDA #0), while $48C7 itself is never JSR'd at all;  (b) even a live
       comparison could not see a defect INSIDE the rotation — the oracle rotate_state_pair__t6502
       calls the NATIVE apply_angle_term_at (it is a validated split), so the multiply body is
       shared by both models and cancels.  What the RESULT verifies is the rotation's own logic —
       the four calls' argument setup and the mode EOR — which lands in mem[] and is compared in
       full.  apply_angle_term folds its multiply into plain C that spills no scratch, so unlike
       the stage/damp pair these need no ignore list. */
    for (i = 0; i < 9; i++) {
        int subFail = 0, decimal = 0, negative = 0, accumulate = 0, carried = 0;
        int cases = list[i].cases * scale;
        int resultOnly = (i == 0 || i == 3 || i == 4 || i == 5 || i == 6);
        /* rotate_accum_by_steer (i == 1) and rotate_pair_a_by_steer (i == 2) reach the idiomatic
           binary neg16_math_noinit; like the result-only pair they run only with D = 0 (the driving
           model's precondition — docs/static-map.md §Decimal mode), so they pin D = 0 while keeping
           the full register/flag comparison. */
        /* i == 0/1/2/3 and the two integrators (7/8) pin D = 0 — their twins are plain binary C
           that assumes the driving model's D = 0 precondition (docs/static-map.md §Decimal mode);
           the rotate_state_* trio (4/5/6) leave D random on purpose — their pure-C multiply is
           decimal-independent, so a random D proves it. */
        int pinD0 = i == 0 || i == 1 || i == 2 || i == 3 || i == 7 || i == 8;
        unsigned mask = resultOnly ? LIVE_NONE : liveMask;
        if (!want(list[i].name)) continue;
        set_ignore(i == 0 ? stageIgnore : i == 3 ? dampIgnore : 0,
                   i == 0 ? 5 : i == 3 ? 6 : 0);
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            /* $48C7's arguments: A = destination element, Y = source, X = the mode byte. */
            c.A = (uint8_t)(xs() % 14);
            c.Y = (uint8_t)(xs() % 14);
            c.X = (uint8_t)(xs() & 0xC0);
            if (c.X & 0x40) accumulate++;
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            if (c.N) negative++;
            /* i 0..3 never drew a D byte; 4..8 do — draw it unconditionally so pinning the
               integrators (7/8) to D = 0 does not shift the shared PRNG stream for any later
               fixture (the road_span_plot_2 stream-alignment lesson). */
            { uint8_t dRand = (i >= 4) ? (uint8_t)(xs() % 4 == 0) : 0;
              c.D = pinD0 ? 0 : dRand; }
            if (c.D) decimal++;
            /* ⚠ integrate_car_position's 24-bit add is the one place a CARRY OUT of the
               fractional byte reaches the next byte, and $490D takes that carry from the
               DOUBLING above it rather than from a CLC.  A sixth of the cases force the
               doubling to carry, so the case is not left to chance in a random byte. */
            if (i == 7 && (xs() % 6) == 0) {
                pre[0x62E0 + (xs() % 2)] |= 0x80;
                carried++;
            }
            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                mask, t, &printed);
        }
        set_ignore(0, 0);
        fail += subFail;
        /* the D = 0 twins are exempt from the decimal-coverage check by design. */
        if ((!pinD0 && !decimal) || !negative || !accumulate) {
            printf("[VACUOUS] %s: %d decimal, %d negative N, %d accumulate\n",
                   list[i].name, decimal, negative, accumulate);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  %s  "
               "(%d decimal, %d negative, %d accumulate, %d forced carry)\n",
               list[i].name, cases, subFail, resultOnly ? "result-only" : "live=AXY+flags",
               decimal, negative, accumulate, carried);
    }
    return fail;
}

/* ==========================================================================
   TWIN #173 — $0E74 engine_sound_update, THE ENGINE NOTE
   --------------------------------------------------------------------------
   Six things have to be steered or the body is mostly unreachable:

     slip_flags ($62A6/$62A7)  the skid block runs only when the OR of the two axles' history
                               is negative.  A uniform pair takes it 3 in 4 times, so both arms
                               are forced instead.
     $FE68                     the User VIA T2 counter, pinned per case through
                               platform_test_via_t2 — the read is NOT a pure function of mem[],
                               and diff_run runs the oracle first, so an unpinned counter would
                               hand the two models different bytes.  Half the cases go below
                               $3F (squeal queued) and half at or above it (gated out).
     engine_note ($60) and     the step is +-1 toward the target and the EQUAL case returns
     engine_note_target ($5F)  immediately, so all three relations are forced.  The note is
                               drawn to straddle all four thresholds: $1C (silence everything),
                               $40 (channel 2 on) and $5C (channel 1 vs slot 0).
     sound_volume ($05FE)      0 skips channel 2 entirely ($0ECB) — forced both ways.
     sound_chan_state          sound_stop_channel's already-idle guard: with a random state byte
                               the guard almost never fires, so a quarter of the cases zero it.

   ⭐ It reaches the MOS (OSWORD 7 for SOUND, OSBYTE 21 to flush a buffer) on nearly every case,
   and what the differential proves there is that the twin makes the SAME calls with the same
   registers, through platform_mos_call in both models.
   ⚠ Exit ABI is LIVE (A lands in mos_irq_a on the Amiga's interrupt seam) and path-dependent,
   which is the whole reason the core hands back a SlotExit rather than nothing.
   D is pinned to 0: this is race logic, not one of the eight BCD sites (docs/static-map.md).
   ========================================================================== */
void engine_sound_update(void);     void engine_sound_update__t6502(void);

static int test_engine_sound_update(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;
    register_fixture("engine_sound_update");
    if (!want("engine_sound_update")) return 0;

    int cases = 3000 * scale;
    int squeal = 0, gated = 0, noSlip = 0, atTarget = 0, up = 0, down = 0;
    int silenced = 0, slotZero = 0, chan1 = 0, chan2 = 0, noVol = 0, idle = 0;

    for (t = 0; t < cases; t++) {
        Cpu6502 c = zero_cpu();
        fill_random(pre);
        c.D = 0;

        /* the skid block's two arms */
        int slip = (t % 3) != 0;
        pre[0x62A6] = slip ? (uint8_t)(xs() | 0x80u) : (uint8_t)(xs() & 0x7Fu);
        pre[0x62A7] = (uint8_t)(xs() & 0x7Fu);
        uint8_t t2 = (t & 1) ? (uint8_t)(xs() % 0x3Fu)              /* squeals */
                             : (uint8_t)(0x3Fu + (xs() % 0xC1u));   /* gated out */
        platform_test_via_t2(t2);
        if (!slip) noSlip++; else if (t2 < 0x3F) squeal++; else gated++;

        /* the note and its target: all three relations, straddling $1C / $40 / $5C */
        uint8_t note = (uint8_t)(0x10u + (xs() % 0x60u));
        uint8_t targ;
        switch (t % 4) {
            case 0:  targ = note; break;                             /* already there */
            case 1:  targ = (uint8_t)(note + 1u + (xs() % 0x10u)); break;   /* step up */
            default: targ = (uint8_t)(note - 1u - (xs() % 0x10u)); break;   /* step down */
        }
        pre[0x0060] = note;                       /* engine_note */
        pre[0x005F] = targ;                       /* engine_note_target */
        if (targ == note) atTarget++;
        else {
            uint8_t stepped = (uint8_t)(note >= targ ? note - 1u : note + 1u);
            if (note >= targ) down++; else up++;
            if (stepped < 0x1Cu)      silenced++;
            else if (stepped < 0x5Cu) slotZero++;
            else                      chan1++;
            if (stepped >= 0x40u)     chan2++;
        }

        pre[0x05FE] = (t % 5) ? (uint8_t)(xs() | 1u) : 0x00u;   /* sound_volume, 0 one case in 5 */
        if (!pre[0x05FE]) noVol++;

        /* sound_stop_channel's already-idle guard, four channels of state at sound_chan_state */
        if (t % 4 == 0) { pre[0x0B08] = 0; pre[0x0B09] = 0; pre[0x0B0A] = 0; pre[0x0B0B] = 0; idle++; }

        fail += diff_run("engine_sound_update", pre, c, engine_sound_update,
                         engine_sound_update__t6502, LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS, t, &printed);
    }
    platform_test_via_t2(0);

    if (!squeal || !gated || !noSlip) {
        printf("[VACUOUS] engine_sound_update: skid arms %d squeal / %d gated / %d no-slip\n",
               squeal, gated, noSlip); fail++;
    }
    if (!atTarget || !up || !down) {
        printf("[VACUOUS] engine_sound_update: note step %d equal / %d up / %d down\n",
               atTarget, up, down); fail++;
    }
    if (!silenced || !slotZero || !chan1 || !chan2) {
        printf("[VACUOUS] engine_sound_update: pitch arms %d silence / %d slot0 / %d chan1 / "
               "%d chan2\n", silenced, slotZero, chan1, chan2); fail++;
    }
    if (!noVol || !idle) {
        printf("[VACUOUS] engine_sound_update: %d zero-volume, %d already-idle channels\n",
               noVol, idle); fail++;
    }
    printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
           "(%d squeal/%d gated/%d no-slip, %d at target/%d up/%d down, "
           "%d silence/%d slot0/%d chan1/%d chan2, %d no volume, %d idle)\n",
           "engine_sound_update", cases, fail, squeal, gated, noSlip,
           atTarget, up, down, silenced, slotZero, chan1, chan2, noVol, idle);
    return fail;
}

/* ==========================================================================
   TWINS #67-#78 — THE SLIP/SOUND CLUSTER
   --------------------------------------------------------------------------
   $4B61 slip_magnitude, $4B51 store_slip_signed, $4B47 store_slip_clamped,
   $4B42 store_slip_clamped_off_throttle, $4B88 derive_slip_reference,
   $4A91 check_wheel_slip, $4AF7 clamp_slip_to_grip, $0B6E sound_osword,
   $0B4A sound_queue, $0B47 sound_queue_default, $0E5A sound_stop_channel,
   $4779 update_slip_sound.

   ⚠⚠ FOUR STEERED INPUTS, and without them most of this cluster is unreachable:

     pedal_mode   ($3E)  1 is the throttle and every routine here forks on it.  A uniform byte
                         would take the off-throttle arm 255 times out of 256, so it is drawn
                         from {0, 1, $80} — and derive_slip_reference's `SEC`-and-decline arm
                         needs pedal_mode == 1 AND X != 1 together.
     X            the AXLE, 0 or 1, and it indexes two-byte tables; a uniform byte would walk
                         off grip_limit into unrelated cells identically in both models, which
                         proves nothing.
     Y            slip_magnitude's element, 0..14 into the state vector.
     drive_state  ($2D) update_slip_sound's first fork is `>= 2`, so half the cases are forced
                         under it and half over.

   ⭐ THREE OF THESE REACH THE MOS (OSWORD 7 for SOUND, OSBYTE 21 to flush a buffer), and what
   the differential proves there is that the twin makes the SAME CALL with the same registers —
   the answer comes back through platform_mos_call in both models, exactly as for kbd_test_key.
   ========================================================================== */
void slip_magnitude(void);          void slip_magnitude__t6502(void);
void store_slip_signed(void);       void store_slip_signed__t6502(void);
void store_slip_clamped(void);      void store_slip_clamped__t6502(void);
void store_slip_clamped_off_throttle(void);
void store_slip_clamped_off_throttle__t6502(void);
void derive_slip_reference(void);   void derive_slip_reference__t6502(void);
void check_wheel_slip(void);        void check_wheel_slip__t6502(void);
void clamp_slip_to_grip(void);      void clamp_slip_to_grip__t6502(void);
void sound_osword(void);            void sound_osword__t6502(void);
void sound_queue(void);             void sound_queue__t6502(void);
void sound_envelope(void);          void sound_envelope__t6502(void);
void sound_queue_default(void);     void sound_queue_default__t6502(void);
void sound_stop_channel(void);      void sound_stop_channel__t6502(void);
void update_slip_sound(void);       void update_slip_sound__t6502(void);

#define PRE_PEDAL_MODE  0x003E
#define PRE_DRIVE_STATE 0x002D

static int test_slip_and_sound(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); int cases; }
      list[13] = {
        { "slip_magnitude",        slip_magnitude,        slip_magnitude__t6502,        3000 },
        { "store_slip_signed",     store_slip_signed,     store_slip_signed__t6502,     2000 },
        { "store_slip_clamped",    store_slip_clamped,    store_slip_clamped__t6502,    2000 },
        { "store_slip_clamped_off_throttle", store_slip_clamped_off_throttle,
          store_slip_clamped_off_throttle__t6502, 2000 },
        { "derive_slip_reference", derive_slip_reference, derive_slip_reference__t6502, 3000 },
        { "check_wheel_slip",      check_wheel_slip,      check_wheel_slip__t6502,      3000 },
        { "clamp_slip_to_grip",    clamp_slip_to_grip,    clamp_slip_to_grip__t6502,    3000 },
        { "sound_osword",          sound_osword,          sound_osword__t6502,           500 },
        { "sound_queue",           sound_queue,           sound_queue__t6502,           1500 },
        { "sound_queue_default",   sound_queue_default,   sound_queue_default__t6502,   1000 },
        { "sound_stop_channel",    sound_stop_channel,    sound_stop_channel__t6502,    1000 },
        { "update_slip_sound",     update_slip_sound,     update_slip_sound__t6502,     3000 },
        /* ⭐ sound_envelope (i == 12) — sound_osword's sibling entry, OSWORD 8 instead of 7.
           Its whole input is the entry A (the envelope block's base) and X (parked in
           sound_saved_x and handed straight back), both already randomised below; the carry the
           `ADC #$38` leaks to the exit is exercised by every A >= $C8, about a fifth of the
           cases, and counted as `carried` so the arm cannot go vacuous. */
        { "sound_envelope",        sound_envelope,        sound_envelope__t6502,         500 },
      };
    static const uint8_t PEDALS[3] = { 1, 0, 0x80 };
    for (i = 0; i < 13; i++) register_fixture(list[i].name);

    /* ⭐ slip_magnitude (i == 0) and check_wheel_slip (i == 5) are verified RESULT-ONLY: their
       native twins are idiomatic C whose whole product is mem[] (slip_magnitude's SLIP_MAG_LO/HI,
       check_wheel_slip's slip flags and state vector), leaving nothing meaningful in the cpu — no
       caller reads their exit registers (each caller overwrites A immediately).  D is pinned to 0
       (the driving model's precondition) and the register/flag comparison is dropped. */
    for (i = 0; i < 13; i++) {
        int subFail = 0, decimal = 0, throttle = 0, driven = 0, powered = 0, idle = 0;
        int carried = 0;
        int cases = list[i].cases * scale;
        /* ⭐ clamp_slip_to_grip (i == 6) and update_slip_sound (i == 11) are RESULT-ONLY too: their
           cpu-free cores' whole product is mem[] (the clamped state vector, the sound blocks /
           channel state), and every caller reads a flag/register of neither — clamp_slip_to_grip's
           caller (update_slip_sound at $4795) does `LDA sound_chan_state[3]` next, overwriting A/N/Z
           and reading nothing else; update_slip_sound's callers ($46DA/$46FD in revs_gen.c) restore
           the model accumulator and reload registers before any read.  So their exit registers/flags
           are dead and the comparison is dropped. */
        int resultOnly = (i == 0 || i == 5 || i == 6 || i == 11);
        /* ⭐ derive_slip_reference (i == 4) verifies only its genuine outputs: the carry (both
           callers branch on "declined") and A (the product high, consumed as a value); its
           product low lands in math_lo and is compared through mem[].  Its exit N/Z/V are dead —
           no caller reads a flag of it — so the multiply is plain C (revs_mulu16) with no V
           replay.  D is pinned to 0: it is on the slip/driving path (its caller check_wheel_slip,
           i == 5, is already D = 0), so a decimal case would test an unreachable state. */
        int derivRef = (i == 4);
        unsigned mask = resultOnly ? LIVE_NONE
                      : (derivRef ? (LIVE_A | LIVE_C) : liveMask);
        if (!want(list[i].name)) continue;
        /* check_wheel_slip's idiomatic core keeps the 6502's math accumulator ($74/$75) and its
           sign-decision (a PHP on the stack) in C locals; the oracle spills them.  None is read
           by any caller before the next writer — pure scratch. */
        { static const uint16_t slipIgnore[]  = { 0x0074, 0x0075, 0x01FF };
          /* sound_stop_channel (i == 10) preserves the caller's A in a C local in its shim; the
             ORACLE (its transliteration) still executes the real PHA at $0E5A, writing $01FF (the
             stack rests at S = $FF).  That one dead stack slot — popped back by PLA before any read
             — is the PHP-residue recurrence inside a fixture; the differential ignores it.  Every
             other oracle in this cluster enters native shims, so no other slot diverges. */
          static const uint16_t stackIgnore[] = { 0x01FF };
          if (i == 5)       set_ignore(slipIgnore, 3);
          else if (i == 10) set_ignore(stackIgnore, 1);
          else              set_ignore(0, 0); }
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.X = (uint8_t)(xs() & 1);                    /* the axle */
            c.Y = (uint8_t)(xs() % 15);                   /* a state element */
            c.A = (uint8_t)xs();
            pre[PRE_PEDAL_MODE]  = PEDALS[xs() % 3];
            pre[PRE_DRIVE_STATE] = (uint8_t)((xs() & 1) ? (xs() % 2) : (2 + xs() % 4));
            if (pre[PRE_PEDAL_MODE] == 1) throttle++;
            if (c.X == 1) driven++;
            if (pre[PRE_DRIVE_STATE] < 2) powered++;
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            /* ⚠ draw the D byte for every case EXCEPT the two that never drew it (i == 4/5), so
               pinning slip_magnitude (i == 0) to D = 0 does not shift the shared PRNG stream for
               any later fixture (the road_span_plot_2 stream-alignment lesson). */
            { uint8_t dRand = (i == 4 || i == 5) ? 0 : (uint8_t)(xs() % 4 == 0);
              c.D = (resultOnly || derivRef) ? 0 : dRand; }
            /* ⚠ The four sound routines run with D CLEAR: the engine only ever calls them from
               binary-mode code, and sound_queue's block index is an ADC, so a decimal case
               would compare two models agreeing on a block the game can never ask for.  The
               decimal counter is taken AFTER this, or the vacuity check counts cases that
               were overridden away (it went negative the first time). */
            if ((i >= 7 && i <= 10) || i == 12) c.D = 0;   /* sound_envelope too — same path */
            if (c.D) decimal++;
            /* sound_queue / sound_queue_default take the SLOT in A. */
            if (i == 8 || i == 9) c.A = (uint8_t)(xs() % 8);
            /* sound_osword takes the block's low byte in X; sound_stop_channel a channel. */
            if (i == 7)  c.X = (uint8_t)(xs() % 0x40);
            if (i == 10) {
                c.X = (uint8_t)(xs() & 3);
                /* ⚠⚠ THE ALREADY-IDLE CASE HAS TO BE FORCED.  sound_stop_channel's whole
                   guard is `is this channel marked playing?`, and a random byte is zero once
                   in 256 — the sabotage that deletes the guard was caught in 3 of 1000 cases
                   before this line, which is a coverage hole dressed up as a pass.  Half the
                   cases now take each arm. */
                if (xs() & 1) { pre[0x62BD + c.X] = 0; idle++; }
                else if (!pre[0x62BD + c.X]) pre[0x62BD + c.X] = 0x07;
            }
            /* ⭐ SLIP_OUT_INDEX ($0078) NAMES A STATE ELEMENT, and its domain is structural: its
               only two writers are derive_slip_reference (axle + 2, so 2 or 3) and
               clamp_slip_to_grip (axle, so 0 or 1), and every store lands at element 10 + it —
               elements $0A..$0D.  fill_random left it a free byte, which before the relocation
               merely wrote PAST the vector into $63xx in both models (agreeing, so invisible);
               with the vector a 15-entry uint16_t array the same case is out of bounds.  The byte
               is drawn for every case so the shared PRNG stream stays aligned. */
            { uint8_t slipOut = (uint8_t)(xs() & 3);
              if (i >= 1 && i <= 3) pre[0x0078u] = slipOut; }
            if (i == 11) c.X = (uint8_t)(xs() & 1);
            /* sound_envelope takes the envelope block's base in A; A >= $C8 is the case whose
               `ADC #$38` carries, and that carry reaches the exit. */
            if (i == 12 && (unsigned)c.A + 0x38u > 0xFFu) carried++;
            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                mask, t, &printed);
        }
        fail += subFail;
        if (!throttle || !driven || !powered) {
            printf("[VACUOUS] %s: %d throttle, %d driven axle, %d under power\n",
                   list[i].name, throttle, driven, powered);
            fail++;
        }
        if (i == 10 && !idle) { printf("[VACUOUS] %s: no already-idle case\n", list[i].name); fail++; }
        if (i == 12 && (!carried || carried == cases)) {
            printf("[VACUOUS] %s: %d of %d cases carry out of the ADC\n",
                   list[i].name, carried, cases);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  %s  "
               "(%d decimal, %d throttle, %d driven axle, %d under power%s)\n",
               list[i].name, cases, subFail,
               resultOnly ? "result-only" : derivRef ? "live=A+C" : "live=AXY+flags",
               decimal, throttle, driven, powered,
               i == 10 ? ", channel idle forced" : "");
        if (i == 12) printf("%-32s %7d of them carry out of the ADC\n", "", carried);
    }
    set_ignore(0, 0);
    return fail;
}


/* ==========================================================================
   TWINS #79-#86 — THE EIGHT SUB-MODELS
   --------------------------------------------------------------------------
   $0D01 compute_car_angles, $4610 scale_by_track_gradient, $49CE update_engine_revs,
   $4BCF update_grip_limits, $4C65 apply_drag_terms, $4DC9 begin_spin,
   $4DCB begin_spin_from_a, $44EA update_camera_and_drive_state.

   ⚠⚠ SEVEN STEERED INPUTS, and without them most of this group is unreachable:

     gear_index   ($40)  the real gears are 2..6 and gear 1 is the pits; a uniform byte would
                         index gear_rev_ratio_tbl and gear_torque_tbl hundreds of bytes past
                         their seven entries, identically in both models, and prove nothing.
                         Drawn from 0..7 so the neutral, pits and in-gear arms all run.
     pedal_mode   ($3E)  1 is the throttle, 0 the brake, $80 coasting.  update_grip_limits'
                         whole load term and update_camera_and_drive_state's pitch bias fork
                         on it, and update_engine_revs' coast arm does too.
     engine_running ($61) 0 sends update_engine_revs to the STARTER POLL and $FF to the rev
                         model; a random byte takes the model 255 times in 256.
     drive_state  ($2D)  0 is "under power"; both big twins fork on it first.
     $FE68        THE USER VIA TIMER, pinned per case through platform_test_via_t2.  The
                         headless backend answered a constant 0 — deterministic, but it pins
                         `VIA & starter_random_mask` to 0 (the starter ALWAYS catches) and
                         `VIA & 7` to 0 (no idle jitter).  Half the cases now use a non-zero
                         value, which is what reaches update_engine_revs' no-luck arm at all.
     surface_change_0/_1 FORCED to $FF in a sixth of the cases each, and to $FF in BOTH in a
                         twelfth.  They are $00 on the real disc (see disasm/symbols.csv), so
                         update_grip_limits' whole changed-surface arm — the User VIA read, the
                         unprompted begin_spin and grip_limit_base_alt_tbl — is code no
                         randomised fixture would ever enter: $FF in a random byte is 1 in 256
                         for the first test and 1 in 65536 for the second.
     player_car / car_section_cursor  ($6F, $22) both index page-1 and page-9 arrays.
                         Steered to 0..19 and 0..$77, the ranges the engine keeps them in.

   ⚠ THE SMC SITE $45CB.  update_camera_and_drive_state's first `ASL A / ROL shared_temp_77`
   pair is where every expansion circuit plants a `JSR` into its own hook.  Nine cases in ten
   force the unpatched Silverstone bytes, because a random pair traps instead of running the
   routine's tail — and the tenth is left random on purpose, since diff_run compares the SMC
   trap as its own channel and a twin that trapped differently would otherwise pass.
   ========================================================================== */
void compute_car_angles(void);            void compute_car_angles__t6502(void);
void scale_by_track_gradient(void);       void scale_by_track_gradient__t6502(void);
void update_engine_revs(void);            void update_engine_revs__t6502(void);
void update_grip_limits(void);            void update_grip_limits__t6502(void);
void apply_drag_terms(void);              void apply_drag_terms__t6502(void);
void begin_spin(void);                    void begin_spin__t6502(void);
void begin_spin_from_a(void);             void begin_spin_from_a__t6502(void);
void update_camera_and_drive_state(void); void update_camera_and_drive_state__t6502(void);

void platform_test_via_t2(unsigned char v);
void platform_test_key_down(int on);
void platform_test_key_only(unsigned char code);
void platform_test_adc(unsigned short axis, unsigned char buttons);

#define PRE_GEAR_INDEX     0x0040
#define PRE_ENGINE_RUNNING 0x0061
#define PRE_PLAYER_CAR     0x006F
#define PRE_SECTION_CURSOR 0x0022
#define PRE_SURFACE_A      0x713D
#define PRE_SURFACE_B      0x7205

static int test_sub_models(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); int cases; }
      list[8] = {
        { "compute_car_angles",     compute_car_angles,     compute_car_angles__t6502,     3000 },
        { "scale_by_track_gradient", scale_by_track_gradient,
          scale_by_track_gradient__t6502, 2000 },
        { "begin_spin",             begin_spin,             begin_spin__t6502,             1000 },
        { "begin_spin_from_a",      begin_spin_from_a,      begin_spin_from_a__t6502,      1000 },
        { "apply_drag_terms",       apply_drag_terms,       apply_drag_terms__t6502,       3000 },
        { "update_grip_limits",     update_grip_limits,     update_grip_limits__t6502,     3000 },
        { "update_engine_revs",     update_engine_revs,     update_engine_revs__t6502,     4000 },
        { "update_camera_and_drive_state", update_camera_and_drive_state,
          update_camera_and_drive_state__t6502, 4000 },
      };
    static const uint8_t PEDALS[3] = { 1, 0, 0x80 };
    unsigned long smcTraps;
    for (i = 0; i < 8; i++) register_fixture(list[i].name);

    /* $45CB's trap is real code in BOTH models and diff_run compares it as its own channel, so
       it is tested rather than avoided — which means Platform::smcUnhandled has to count
       instead of abort.  The count is asserted below: it must be NON-ZERO, or the tenth-case
       random shape never happened and the dispatch is untested. */
    setenv("REVS_SMC_CONTINUE", "1", 1);
    g_smcUnhandled = 0;

    /* ⭐ compute_car_angles (i == 0), apply_drag_terms (i == 4) and update_grip_limits (i == 5)
       are verified RESULT-ONLY: their native twins end in idiomatic 16-bit binary C (the tail of
       apply_drag_terms is add_signed_into_element, itself now binary) that leaves nothing
       deterministic in the cpu, so the fixture pins D = 0 (the driving model's precondition —
       docs/static-map.md §Decimal mode), drops the register/flag comparison, and ignores the
       oracle's arithmetic scratch.  None of the three uses the 6502 stack.  compute_car_angles
       spills the sin/cos temporaries $42, $74-$79, $7B; update_grip_limits spills $74-$79 (the
       $F3 multiply and the load term in hypot_min) plus the stack residue $01FF from the PHP/PLP
       that carries the load term's sign ($4BD8).  apply_drag_terms spills no mem[] the twin does
       not also write (its result is model state elements 6 and 7); only its dead exit A/Y/N —
       the last add_signed_into_element's index and sum high byte — differ, and the sole caller
       (apply_driving_model, whose next step rotate_state_pair takes explicit args) reads none. */
    static const uint16_t angleIgnore[] =
        { 0x0042, 0x0074, 0x0075, 0x0076, 0x0077, 0x0078, 0x0079, 0x007B };
    static const uint16_t gripIgnore[]  =
        { 0x0074, 0x0075, 0x0076, 0x0077, 0x0078, 0x0079, 0x01FF };
    /* update_engine_revs (i==6): the PHP/PLP pair at $49E8/$49FB that carries the first
       doubling's sign is now a C bool, so the twin never writes the pushed status byte the
       oracle leaves at $01FF (net-neutral to the stack, dead scratch — nothing reads it). */
    static const uint16_t engineIgnore[] = { 0x01FF };
    /* update_camera_and_drive_state (i==7): the five PHP/PLP pairs — three in the yaw fold
       ($453C/$4540/$4546) and two in the camera add ($45E5/$45E9) — that carry octant signs and
       add carries are now C bools/ints, so the twin never writes the pushed status bytes the
       oracle leaves on the stack at $01FD/$01FE/$01FF (net-neutral pulls, dead scratch). */
    static const uint16_t cameraIgnore[] = { 0x01FD, 0x01FE, 0x01FF };
    /* scale_by_track_gradient (i==1): the PHP/PLP pair at $4617/$4621 that carried the EOR's sign
       across the abs8+multiply is now two C bytes, so the twin never writes the pushed status byte
       the oracle leaves at $01FF (net-neutral pull, dead scratch). */
    static const uint16_t scaleIgnore[] = { 0x01FF };

    for (i = 0; i < 8; i++) {
        int subFail = 0, decimal = 0, throttle = 0, ingear = 0, powered = 0;
        int cranking = 0, changed = 0, bothChanged = 0, entropy = 0, patched = 0;
        int keyheld = 0, revmodel = 0;
        int cases = list[i].cases * scale;
        int resultOnly = (i == 0 || i == 4 || i == 5);
        /* i==1 scale_by_track_gradient, i==6 update_engine_revs and i==7
           update_camera_and_drive_state keep their live exit A/flags, but their interior
           multiplies are now binary C, so D is pinned 0 — the driving/camera path never runs
           decimal (docs/static-map.md §Decimal mode). */
        int pinD0 = resultOnly || (i == 1) || (i == 6) || (i == 7);
        unsigned mask = resultOnly ? LIVE_NONE : liveMask;
        if (!want(list[i].name)) continue;
        set_ignore(i == 0 ? angleIgnore : i == 1 ? scaleIgnore : i == 5 ? gripIgnore :
                   i == 6 ? engineIgnore : i == 7 ? cameraIgnore : 0,
                   i == 0 ? 8 : i == 1 ? 1 : i == 5 ? 7 : i == 6 ? 1 : i == 7 ? 3 : 0);
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs();
            c.X = (uint8_t)xs();
            c.Y = (uint8_t)xs();
            pre[PRE_PEDAL_MODE]     = PEDALS[xs() % 3];
            pre[PRE_DRIVE_STATE]    = (uint8_t)((xs() & 1) ? 0 : (1 + xs() % 4));
            pre[PRE_GEAR_INDEX]     = (uint8_t)(xs() % 8);
            pre[PRE_ENGINE_RUNNING] = (uint8_t)((xs() & 1) ? 0xFF : 0x00);
            pre[PRE_PLAYER_CAR]     = (uint8_t)(xs() % 20);
            pre[PRE_SECTION_CURSOR] = (uint8_t)(xs() % 0x78);
            if (pre[PRE_PEDAL_MODE] == 1)   throttle++;
            if (pre[PRE_GEAR_INDEX] >= 2)   ingear++;
            if (pre[PRE_DRIVE_STATE] == 0)  powered++;
            if (pre[PRE_ENGINE_RUNNING] == 0) cranking++;

            /* The two surface bytes: $FF in one, and in a twelfth of cases BOTH. */
            { unsigned pick = xs() % 12;
              if (pick < 2)      { pre[PRE_SURFACE_A] = 0xFF; changed++; }
              else if (pick < 4) { pre[PRE_SURFACE_B] = 0xFF; changed++; }
              else if (pick == 4) { pre[PRE_SURFACE_A] = pre[PRE_SURFACE_B] = 0xFF;
                                    changed++; bothChanged++; } }

            /* $FE68 — see the header.  A non-zero value is what makes the starter FAIL. */
            { unsigned char t2 = (unsigned char)((xs() & 1) ? (1 + xs() % 255) : 0);
              if (t2) entropy++;
              platform_test_via_t2(t2); }

            /* ⭐⭐ THE T KEY.  Without this the starter's whole `key held` arm — the luck test
               against starter_random_mask and the catch — is UNREACHABLE: the test platform
               answers "no key is ever down", so kbd_test_key always reports not-pressed and
               $497D never branches.  MEASURED as a hole: the sabotage "the luck mask is always
               7" survived 4000 cases before this line and is caught after it. */
            { int held = (xs() & 1); if (held) keyheld++; platform_test_key_down(held); }

            /* ⭐ …AND THE POWER CURVE NEEDS DRIVING AT.  The rev model is reached only with the
               engine running, under power, no shift this frame and a real gear — about one case
               in eleven left to chance, and the curve's four segments then need particular
               values of (revs - $42).  A quarter of the cases force the path and sweep the
               speed and the gear ratio, which is what catches a moved breakpoint: the sabotage
               "the second breakpoint is 5" differs for ONE input value and survived without
               this. */
            if ((xs() & 3) == 0) {
                pre[PRE_ENGINE_RUNNING] = 0xFF;
                pre[PRE_DRIVE_STATE]    = 0;
                pre[0x0058]             = 0;          /* gear_change_flag: no shift */
                pre[0x0059]             = 0;          /* gear_change_rev_drop: not armed */
                pre[PRE_GEAR_INDEX]     = (uint8_t)(2 + xs() % 5);
                pre[0x0063]             = (uint8_t)xs();       /* road_speed */
                pre[0x002E]             = (uint8_t)xs();       /* road_speed_frac */
                pre[0x5A06 + pre[PRE_GEAR_INDEX]] = (uint8_t)xs();
                revmodel++;
            }

            /* The SMC site: nine in ten unpatched, the tenth left random. */
            if (xs() % 10) { pre[0x45CB] = 0x0A; pre[0x45CC] = 0x26; pre[0x45CD] = 0x77; }
            else patched++;

            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = pinD0 ? 0 : (uint8_t)(xs() % 4 == 0);
            if (c.D) decimal++;
            /* apply_drag_terms consumes model_accum_entry ($38/$39), relocated to a native wide
               var; its 6502-ABI shim marshals the value in from mem[$38/$39], so the randomized
               pre[] cells reach the twin with no fixture seeding needed. */
            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                mask, t, &printed);
        }
        set_ignore(0, 0);
        fail += subFail;
        if ((!pinD0 && !decimal) || !throttle || !ingear || !powered || !cranking ||
            !changed || !bothChanged || !entropy || !patched || !keyheld || !revmodel) {
            printf("[VACUOUS] %s: %d decimal, %d throttle, %d in gear, %d powered, "
                   "%d cranking, %d changed surface (%d both), %d entropy, %d SMC-random, "
                   "%d key held, %d forced rev model\n",
                   list[i].name, decimal, throttle, ingear, powered, cranking,
                   changed, bothChanged, entropy, patched, keyheld, revmodel);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  %s  "
               "(%d decimal, %d throttle, %d in gear, %d powered, %d cranking, "
               "%d changed surface, %d entropy, %d key held, %d forced rev model)\n",
               list[i].name, cases, subFail, resultOnly ? "result-only" : "live=AXY+flags",
               decimal, throttle, ingear, powered,
               cranking, changed, entropy, keyheld, revmodel);
    }
    platform_test_via_t2(0);
    platform_test_key_down(0);
    smcTraps = g_smcUnhandled;
    unsetenv("REVS_SMC_CONTINUE");
    if (want("update_camera_and_drive_state")) {
        if (smcTraps == 0) {
            printf("[VACUOUS] update_camera_and_drive_state: no SMC trap over the whole run — "
                   "the $45CB dispatch was never exercised on an unknown shape\n");
            fail++;
        }
        printf("%-32s %7lu SMC traps at $45CB (must be > 0)  the per-circuit hook site\n",
               "sub-models", smcTraps);
    }
    return fail;
}


/* ==========================================================================
   TWINS #116-#125 — THE LATE MISC TREES
   --------------------------------------------------------------------------
   scale_wing_settings, compute_segment_scale, section_angle_curve,
   scale_angle_in_section, record_section_jump, place_player_in_section,
   tick_wheel_spin, spin_car_out, process_car_contact, car_gap.

   Each is verified on its OWN result: the drivers (place_player, process_car_contact,
   car_gap) reach native leaves whose bodies cancel between the two models, so only the
   driver's own arithmetic is under test, and only its declared outputs are compared —
   result-only for the mem[]-only ones, live A (and C/N for car_gap) where a value or a
   flag genuinely leaves the routine.  D = 0 is pinned on every path that does binary
   ADC/SBC or a multiply (docs/static-map.md §Decimal mode); it is left random on the two
   that touch neither (record_section_jump, spin_car_out) to prove they are D-independent.

   TWO SMC sites are steered exactly as the sub-models' $45CB is: nine cases in ten force
   Silverstone's own bytes (compute_segment_scale's $44D5 base load, place_player's $462B
   abs8 hook), the tenth forces the else-arm so the platform_smc_unhandled trap channel is
   exercised in both models.  The base for compute_segment_scale is pinned to $3000 so its
   random per-segment source data never overlaps the $5FB0 output.
   ========================================================================== */
void scale_wing_settings(void);     void scale_wing_settings__t6502(void);
void compute_segment_scale(void);   void compute_segment_scale__t6502(void);
void section_angle_curve(void);     void section_angle_curve__t6502(void);
void scale_angle_in_section(void);  void scale_angle_in_section__t6502(void);
void record_section_jump(void);     void record_section_jump__t6502(void);
void place_player_in_section(void); void place_player_in_section__t6502(void);
void tick_wheel_spin(void);         void tick_wheel_spin__t6502(void);
void spin_car_out(void);            void spin_car_out__t6502(void);
void process_car_contact(void);     void process_car_contact__t6502(void);
void car_gap(void);                 void car_gap__t6502(void);
void car_gap_tail(void);                 void car_gap_tail__t6502(void);
void section_coord_add_delta(void);      void section_coord_add_delta__t6502(void);
void copy_section_height_to_side1(void); void copy_section_height_to_side1__t6502(void);
void derive_car_section_cursor(void); void derive_car_section_cursor__t6502(void);
void build_section_step_delta(void); void build_section_step_delta__t6502(void);
void step_segment_dir_index(void); void step_segment_dir_index__t6502(void);
void advance_dir_on_segment_flag(void); void advance_dir_on_segment_flag__t6502(void);
void step_section_curve(void);      void step_section_curve__t6502(void);
void load_section_from_segment(void); void load_section_from_segment__t6502(void);
void cross_section_boundary(void);  void cross_section_boundary__t6502(void);
void build_road_section(void);      void build_road_section__t6502(void);

static int test_late_misc_trees(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); unsigned mask; int cases; }
      list[21] = {
        { "scale_wing_settings",     scale_wing_settings,     scale_wing_settings__t6502,     LIVE_NONE, 2000 },
        { "compute_segment_scale",   compute_segment_scale,   compute_segment_scale__t6502,   LIVE_NONE, 3000 },
        { "section_angle_curve",     section_angle_curve,     section_angle_curve__t6502,     LIVE_A,    2000 },
        { "scale_angle_in_section",  scale_angle_in_section,  scale_angle_in_section__t6502,  LIVE_A,    3000 },
        { "record_section_jump",     record_section_jump,     record_section_jump__t6502,     LIVE_NONE, 2000 },
        { "place_player_in_section", place_player_in_section, place_player_in_section__t6502, LIVE_NONE, 5000 },
        { "tick_wheel_spin",         tick_wheel_spin,         tick_wheel_spin__t6502,         LIVE_NONE, 3000 },
        { "spin_car_out",            spin_car_out,            spin_car_out__t6502,            LIVE_NONE, 2000 },
        { "process_car_contact",     process_car_contact,     process_car_contact__t6502,     LIVE_NONE, 5000 },
        { "car_gap",                 car_gap,                 car_gap__t6502,                 LIVE_A | LIVE_C | LIVE_N, 3000 },
        { "car_gap_tail",                car_gap_tail,                car_gap_tail__t6502,            LIVE_A | LIVE_C | LIVE_N, 5000 },
        { "section_coord_add_delta",     section_coord_add_delta,     section_coord_add_delta__t6502, LIVE_NONE, 5000 },
        { "copy_section_height_to_side1", copy_section_height_to_side1, copy_section_height_to_side1__t6502, LIVE_NONE, 3000 },
        { "derive_car_section_cursor",   derive_car_section_cursor,   derive_car_section_cursor__t6502, LIVE_NONE, 3000 },
        { "build_section_step_delta",    build_section_step_delta,    build_section_step_delta__t6502, LIVE_NONE, 4000 },
        { "step_segment_dir_index",      step_segment_dir_index,      step_segment_dir_index__t6502, LIVE_NONE, 4000 },
        { "advance_dir_on_segment_flag", advance_dir_on_segment_flag, advance_dir_on_segment_flag__t6502, LIVE_NONE, 4000 },
        { "step_section_curve",          step_section_curve,          step_section_curve__t6502,      LIVE_NONE, 5000 },
        { "load_section_from_segment",   load_section_from_segment,   load_section_from_segment__t6502, LIVE_NONE, 5000 },
        { "cross_section_boundary",      cross_section_boundary,      cross_section_boundary__t6502,   LIVE_NONE, 5000 },
        { "build_road_section",          build_road_section,          build_road_section__t6502,       LIVE_NONE, 8000 },
      };
    static const uint16_t mathIgnore[] = { 0x0074, 0x0075 };   /* mul8/abs16 scratch */
    static const uint16_t gapIgnore[]  = { 0x01FF };           /* car_gap_tail's PHP/PLP stack byte */
    static const uint16_t segIgnore[]  = { 0x0074, 0x0075, 0x01FF };  /* + the oracle's PHP stack byte */
    /* place_player pushes its two saved bytes to the real stack (byte-faithful over page 1),
       so only the mul8 scratch needs ignoring — the PHA slots are compared. */
    static const uint16_t contIgnore[]  = { 0x0074, 0x0075, 0x01FF };  /* + the oracle's PHP stack byte */

    for (i = 0; i < 21; i++) register_fixture(list[i].name);

    setenv("REVS_SMC_CONTINUE", "1", 1);
    unsigned long smcBefore = g_smcUnhandled;

    for (i = 0; i < 21; i++) {
        int cases   = list[i].cases * scale;
        int contact = 0, spun = 0, floored = 0, credited = 0, carried = 0;
        int smcArm = 0, bodyArm = 0, decimal = 0, diffArm = 0;
        int useIgnore = (i == 0 || i == 1 || i == 3 || i == 5 || i == 8);
        int pinD0     = !(i == 4 || i == 7);   /* all but record_section_jump / spin_car_out */
        if (!want(list[i].name)) continue;
        if (i == 1)        set_ignore(segIgnore, 3);    /* mul8 scratch + PHP stack byte */
        else if (i == 2)   set_ignore(mathIgnore, 1);   /* shallow arm's math_lo scratch */
        else if (i == 5)   set_ignore(mathIgnore, 2);   /* mul8 scratch; PHA slots are compared */
        else if (i == 8)   set_ignore(contIgnore, 3);   /* mul8 scratch + PHP stack byte */
        else if (i == 10)  set_ignore(gapIgnore, 1);    /* PHP/PLP stack byte only ($74/$75 are OUTPUTS) */
        else if (i == 20)  set_ignore(gapIgnore, 1);    /* build_road_section's PHP/PLP byte at $01FF */
        else               set_ignore(useIgnore ? mathIgnore : 0, useIgnore ? 2 : 0);
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs();
            c.X = (uint8_t)xs();
            c.Y = (uint8_t)xs();
            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = pinD0 ? 0 : (uint8_t)(xs() % 4 == 0);
            if (c.D) decimal++;

            switch (i) {
            case 1: /* compute_segment_scale: X = track 0..4, base pinned to $3000 */
                c.X = (uint8_t)(xs() % 5);
                pre[0x44D6] = 0x00; pre[0x44D7] = 0x30;
                pre[0x59FA] = (uint8_t)xs();            /* segment_count_x8 -> y up to 31 */
                if (xs() % 10) pre[0x44D5] = 0xB9;      /* unpatched arm */
                else { pre[0x44D5] = 0x00; smcArm++; }  /* else-arm: platform_smc_unhandled */
                break;
            case 3: /* scale_angle_in_section: A, Y, edge_nearest_lo all random (already) */
                break;
            case 4: /* record_section_jump: X in car range, carry is c.C (random) */
                c.X = (uint8_t)(xs() % 20);
                break;
            case 5: /* place_player_in_section */
                pre[0x006F] = (uint8_t)(xs() % 20);     /* player_car */
                if (xs() % 10) { pre[0x462B] = 0x20; pre[0x462C] = 0x50; pre[0x462D] = 0x34; }
                else { pre[0x462B] = 0x00; smcArm++; }  /* else-arm trap */
                break;
            case 7: /* spin_car_out: X across car + scenery slots */
                c.X = (uint8_t)(xs() % 0x20);
                if (c.X < 0x14) bodyArm++;
                break;
            case 8: /* process_car_contact */
                pre[0x0067] = (uint8_t)(xs() % 0x20);   /* contact_slot */
                pre[0x006F] = (uint8_t)(xs() % 20);     /* player_car */
                pre[0x0068] = (uint8_t)((xs() & 3) ? (1 + xs() % 255) : 0);  /* contact_pending */
                pre[0x0041] = (uint8_t)(xs() & 0x3F);   /* contact_distance: sweep the floor */
                pre[0x006C] = (uint8_t)((xs() & 1) ? 0x80 : 0x28);  /* session_is_race sign */
                if (pre[0x0068]) contact++;
                if (pre[0x0041] > 0x25) floored++;
                break;
            case 9: /* car_gap: X, Y in car range */
                c.X = (uint8_t)(xs() % 20);
                c.Y = (uint8_t)(xs() % 20);
                break;
            case 10: /* car_gap_tail ($27AB): X, Y in car range; entry carry is a genuine input */
                c.X = (uint8_t)(xs() % 20);
                c.Y = (uint8_t)(xs() % 20);
                /* lap_length: a plausible ring circumference (hi 1..$7F) so the wrapped
                   complement lap_length - |D| lands both above and below a byte. */
                pre[0x59FC] = (uint8_t)xs();
                pre[0x59FD] = (uint8_t)(1 + xs() % 0x7F);
                if (t % 3 == 0) {
                    /* near pair: equal distance high bytes so D's high byte is zero (direct
                       branch) whenever the low subtract does not borrow, and 0xFF (negative,
                       abs16 path) when it does — both reached from this one arm. */
                    uint8_t base = (uint8_t)xs();
                    pre[0x08E8 + c.X] = base; pre[0x08E8 + c.Y] = base;
                    pre[0x08D0 + c.X] = (uint8_t)xs();
                    pre[0x08D0 + c.Y] = (uint8_t)xs();
                }
                break;
            case 11: /* section_coord_add_delta ($0BCC): X dest / Y src are section byte cursors.
                        The delta window ($74/$75/$76 lo, $83/$84/$85 hi) is full-random via
                        fill_random, so both signs and every carry pattern are exercised. */
                c.X = (uint8_t)(xs() % 0x78);   /* section range 0..$77 (X<=$FD avoids the lo/hi
                                                   page overlap that only X>=$FE could reach) */
                c.Y = (uint8_t)(xs() % 0x78);
                if (t % 4 == 0) {               /* the place_car AI-branch scratch slots */
                    static const uint8_t slot[3] = { 0xF4, 0xFA, 0xFD };
                    c.X = slot[xs() % 3];
                    c.Y = 0xFD;
                }
                break;
            case 12: /* copy_section_height_to_side1 ($124D): X is a section byte cursor.
                        Copies the shared HEIGHT component (comp 1) from side 0 to side 1.
                        Full-random section tables via fill_random exercise every byte value. */
                c.X = (uint8_t)(xs() % 0x78);
                break;
            case 13: /* derive_car_section_cursor ($125A): section_cursor is the sole input.
                        Full 0..$FF range exercises both the wrap and no-wrap arms. */
                pre[0x0024] = (uint8_t)xs();
                break;
            case 14: /* build_section_step_delta ($1442): Y indexes track_dir_0/1/2 (fill_random
                        supplies the bytes); track_direction picks the negate vs no-negate arm. */
                c.Y = (uint8_t)xs();
                pre[0x0025] = (uint8_t)((xs() & 1) ? (1 + xs() % 255) : 0);  /* track_direction */
                if (pre[0x0025]) diffArm++;
                break;
            case 15: /* step_segment_dir_index ($13E0): segment_dir_index wrapped at track_dir_count,
                        direction from track_direction bit 7.  Steer idx to 0 / count-1 / interior
                        to reach both wrap arms, and vary the direction bit. */
                {
                    uint8_t cnt = (uint8_t)(1 + xs() % 40);   /* nonzero segment count */
                    pre[0x59FB] = cnt;
                    uint8_t r = (uint8_t)(xs() % 4);
                    pre[0x0002] = (r == 0) ? 0
                                : (r == 1) ? (uint8_t)(cnt - 1)
                                :            (uint8_t)(xs() % cnt);
                    pre[0x0025] = (uint8_t)((xs() & 1) ? 0x80 : 0x00);
                    if (pre[0x0025] & 0x80) bodyArm++;   /* backward arm reached */
                    else                    smcArm++;    /* forward arm reached */
                }
                break;
            case 16: /* advance_dir_on_segment_flag ($13DA): cur_segment_flags bit 0 picks the arm.
                        Set up the step_segment_dir_index inputs so the set-bit arm is well-formed. */
                {
                    pre[0x0001] = (uint8_t)((xs() & 1) ? (xs() | 0x01) : (xs() & 0xFE));
                    uint8_t cnt = (uint8_t)(1 + xs() % 40);
                    pre[0x59FB] = cnt;
                    pre[0x0002] = (uint8_t)(xs() % cnt);
                    pre[0x0025] = (uint8_t)((xs() & 2) ? 0x80 : 0x00);
                    if (pre[0x0001] & 0x01) smcArm++;    /* step arm reached */
                    else                    bodyArm++;   /* no-op arm reached */
                }
                break;
            case 17: /* step_section_curve ($150E): near_marker_countdown 0 -> scan the segment list,
                        nonzero -> ramp toward the marker.  Y = player_car_segment indexes the
                        (fill_random) track tables; steer the ramp boundaries so the v>=width and the
                        band/flipped carry edges are hit exactly, not just spanned.  Reused counters:
                        smcArm=scan, contact=full, spun=band, floored=flipped. */
                {
                    pre[0x06FF] = (uint8_t)xs();                 /* player_car_segment (Y) */
                    pre[0x0024] = (uint8_t)(xs() % 0x78);        /* section_cursor (store target) */
                    pre[0x0001] = (uint8_t)xs();                 /* cur_segment_flags (bit0) */
                    pre[0x0020] = (uint8_t)xs();                 /* near_curve_signed (bit7) */
                    pre[0x0016] = (uint8_t)xs();                 /* near_curve_scale */
                    pre[0x0897] = (uint8_t)xs();                 /* player_seg_offset */

                    int r = (int)(xs() % 6);
                    if (r == 0) {
                        pre[0x0017] = 0;                         /* scan mode */
                        smcArm++;
                    } else if (r == 1) {                         /* v == width (full/band edge) */
                        uint8_t w = (uint8_t)(xs() % 0x60);
                        pre[0x0018] = w;
                        pre[0x0017] = (uint8_t)(w + 1);
                    } else if (r == 2) {                         /* v+(v>>3) == width (band edge) */
                        uint8_t v = (uint8_t)(8 + xs() % 0x60);
                        pre[0x0018] = (uint8_t)(v + (v >> 3));
                        pre[0x0017] = (uint8_t)(v + 1);
                    } else if (r == 3) {                         /* v+(v>>3) == width-1 (flip side) */
                        uint8_t v = (uint8_t)(8 + xs() % 0x60);
                        pre[0x0018] = (uint8_t)(v + (v >> 3) + 1);
                        pre[0x0017] = (uint8_t)(v + 1);
                    } else {                                     /* fully random ramp */
                        pre[0x0017] = (uint8_t)(1 + xs() % 255);
                        pre[0x0018] = (uint8_t)xs();
                    }
                    /* classify the ramp outcome actually produced (for the vacuity guard) */
                    if (pre[0x0017] != 0) {
                        uint8_t v = (uint8_t)(pre[0x0017] - 1);
                        uint8_t w = pre[0x0018];
                        if (v >= w) contact++;
                        else {
                            unsigned sum = (unsigned)(uint8_t)(v - w) + (v >> 3);
                            if (sum & 0x100) spun++; else floored++;
                        }
                    }
                }
                break;
            case 18: /* load_section_from_segment ($122D): X = dest section byte cursor, Y = segment
                        byte index.  fill_random supplies the track-file coordinate bytes and both
                        section tables; SMC $1248 dispatches the field-5 dir-index read. */
                c.X = (uint8_t)(xs() % 0x78);           /* section byte cursor (side 0) */
                c.Y = (uint8_t)xs();                    /* segment byte index */
                if (xs() % 10) pre[0x1248] = 0xB9;      /* unpatched: LDA $5905,Y */
                else { pre[0x1248] = 0x00; smcArm++; }  /* else-arm: platform_smc_unhandled trap */
                break;
            case 19: /* cross_section_boundary ($1267): track_direction bit7 picks forward/backward.
                        section_cursor = X target; player_car_segment / retreat_segment = segment
                        byte index (fill_random supplies the track tables).  The nested
                        load_section_from_segment SMC $1248 is forced unpatched (tested at case 18);
                        the backward path's SMC $1289 -> step_segment_dir_index (with an else-arm
                        trap slice).  step_segment_dir_index inputs primed for both cases. */
                pre[0x0024] = (uint8_t)(xs() % 0x78);   /* section_cursor (X) */
                pre[0x06FF] = (uint8_t)xs();            /* player_car_segment (fwd Y / flags) */
                pre[0x0021] = (uint8_t)xs();            /* retreat_segment (bwd Y) */
                pre[0x0062] = (uint8_t)((xs() & 1) ? (1 + xs() % 255) : 0);  /* far_edge_rebuild */
                pre[0x1248] = 0xB9;                     /* load_section_from_segment: unpatched */
                {
                    uint8_t cnt = (uint8_t)(1 + xs() % 40);
                    pre[0x59FB] = cnt;                  /* track_dir_count (step_segment_dir_index) */
                    pre[0x0002] = (uint8_t)(xs() % cnt);/* segment_dir_index */
                }
                if (xs() & 1) {
                    pre[0x0025] = (uint8_t)(0x80 | (xs() & 0x7F));   /* backward */
                    spun++;
                    if (xs() % 8) {                     /* SMC $1289 -> step_segment_dir_index */
                        pre[0x1289] = 0x20; pre[0x128A] = 0xE0; pre[0x128B] = 0x13;
                    } else {                            /* else-arm: platform_smc_unhandled trap */
                        pre[0x1289] = 0x00; smcArm++;
                    }
                } else {
                    pre[0x0025] = (uint8_t)(xs() & 0x7F);            /* forward */
                    contact++;
                }
                break;
            case 20: /* build_road_section ($12F7): the road builder.  Steer the four control paths
                        (fwd+boundary skips the build block; fwd/bwd + no-boundary run it) plus the
                        SMC $13C9 else-arm trap.  A boundary is a track_pos_advance/retreat carry:
                        forward crosses when seg_offset+1 >= segment_len; backward when offset == 0. */
                {
                    uint8_t cnt8 = (uint8_t)((1 + xs() % 31) * 8);  /* segment_count_x8 (mult of 8) */
                    pre[0x59FA] = cnt8;
                    pre[0x59FB] = (uint8_t)(1 + xs() % 40);         /* track_dir_count */
                    pre[0x59FC] = (uint8_t)xs();                    /* lap_length lo/hi (nonzero) */
                    pre[0x59FD] = (uint8_t)(1 + xs() % 0x7F);
                    uint8_t seg = (uint8_t)((xs() % (cnt8 / 8)) * 8);
                    pre[0x06FF] = seg;                              /* player_car_segment */
                    pre[0x0024] = (uint8_t)(xs() % 0x75);           /* section_cursor (pre +3 wrap) */
                    pre[0x0001] = (uint8_t)xs();                    /* cur_segment_flags */
                    pre[0x0002] = (uint8_t)(xs() % pre[0x59FB]);    /* segment_dir_index */
                    pre[0x006F] = (uint8_t)(xs() % 20);             /* player_car */
                    /* SMC sites, all unpatched (Silverstone) by default */
                    pre[0x12FB] = 0x18; pre[0x12FC] = 0x69;         /* cursor advance: CLC; ADC #3 */
                    pre[0x1310] = 0x29;                             /* lap marker: AND #$F8 */
                    pre[0x1248] = 0xB9;                             /* load_section: LDA $5905,Y */
                    pre[0x1289] = 0x20; pre[0x128A]=0xE0; pre[0x128B]=0x13; /* cross bwd: step dir */
                    pre[0x13C9] = 0x20; pre[0x13CA]=0xDA; pre[0x13CB]=0x13; /* dir hook: $13DA */

                    int mode = (int)(xs() % 4);
                    if (mode == 0) {            /* forward + boundary (skips the build block) */
                        pre[0x0025] = (uint8_t)(xs() & 0x7F);       /* fwd */
                        pre[0x5907 + seg] = 1;                      /* segment_len = 1 -> always cross */
                        pre[0x0897] = (uint8_t)xs();
                        floored++;
                    } else if (mode == 1) {     /* forward + no boundary (runs the block) */
                        pre[0x0025] = (uint8_t)(xs() & 0x7F);       /* fwd */
                        pre[0x5907 + seg] = 0xFF;                   /* long segment */
                        pre[0x0897] = (uint8_t)(xs() % 0x40);       /* small offset */
                        contact++;
                    } else if (mode == 2) {     /* backward + boundary */
                        pre[0x0025] = (uint8_t)(0x80 | (xs() & 0x7F));
                        pre[0x0897] = 0;                            /* offset 0 -> cross */
                        spun++;
                    } else {                    /* backward + no boundary */
                        pre[0x0025] = (uint8_t)(0x80 | (xs() & 0x7F));
                        pre[0x0897] = (uint8_t)(1 + xs() % 0x40);
                        spun++;
                    }
                    /* SMC $13C9 else-arm trap on a slice of the block-running modes */
                    if (mode != 0 && (xs() % 12) == 0) { pre[0x13C9] = 0x00; smcArm++; }
                }
                break;
            default: break;
            }

            /* pre-count the spin arm for process_car_contact (impact*2 >= $28 && race) */
            if (i == 8 && pre[0x0068]) {
                unsigned dd = 0x25u - pre[0x0041];
                uint8_t im = (dd & 0x100) ? 0x05 : (uint8_t)dd;
                if ((uint8_t)(im << 1) >= 0x28 && (pre[0x006C] & 0x80)) spun++;
                bodyArm++;
            }

            fail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                             list[i].mask, t, &printed);
        }
        set_ignore(0, 0);

        /* Per-function vacuity guards: each steered arm must have been reached. */
        int vac = 0;
        if ((i == 1 || i == 5) && !smcArm)   vac = 1;   /* both SMC arms exercised */
        if (i == 7 && !bodyArm)              vac = 1;   /* real-car slot reached */
        if (i == 8 && (!contact || !spun || !floored)) vac = 1;
        if ((i == 4 || i == 7) && !decimal)  vac = 1;   /* D really varied */
        if (i == 14 && !diffArm)             vac = 1;   /* the negate arm was reached */
        if (i == 15 && (!bodyArm || !smcArm)) vac = 1;  /* both direction arms reached */
        if (i == 16 && (!bodyArm || !smcArm)) vac = 1;  /* both dispatch arms reached */
        if (i == 17 && (!smcArm || !contact || !spun || !floored)) vac = 1;  /* scan + all 3 ramp outcomes */
        if (i == 18 && !smcArm)              vac = 1;   /* SMC else-arm trap reached */
        if (i == 19 && (!contact || !spun || !smcArm)) vac = 1;  /* fwd + bwd + SMC trap arms */
        if (i == 20 && (!contact || !spun || !floored || !smcArm)) vac = 1;  /* all 4 paths + trap */
        if (vac) { printf("[VACUOUS] %s\n", list[i].name); fail++; }

        printf("%-24s %7d cases, mismatch above must be 0  %s%s\n",
               list[i].name, cases,
               list[i].mask == LIVE_NONE ? "result-only" :
               list[i].mask == LIVE_A ? "live=A" : "live=A/C/N",
               pinD0 ? "  D=0" : "  D-random");
        (void)credited; (void)carried; (void)diffArm;
    }

    unsetenv("REVS_SMC_CONTINUE");
    if ((want("compute_segment_scale") || want("place_player_in_section"))
        && g_smcUnhandled == smcBefore) {
        printf("[VACUOUS] late-misc: no SMC trap over the whole run — the guard else-arm "
               "was never exercised\n");
        fail++;
    }
    return fail;
}


/* ==========================================================================
   TWINS #126-#127 — THE LAST SHIM CALLERS IN THE SHIPPING PRODUCT
   --------------------------------------------------------------------------
   $2937 place_car_world_coords and $5A25 tally_bcd_column were the only two shipping routines
   still calling a 6502 math shim (mul8).  Both are DRIVERS whose native leaves cancel between
   the two models — place_car's object-queue tail is the real FUN_2a5d/FUN_1442/FUN_2b0e/section_coord_add_delta,
   tally's fold is the real FUN_6698 — so each is verified on the DIFFERENCE its own arithmetic
   makes: the world coordinates for place_car, the BCD tally for tally_bcd_column.

   place_car_world_coords:
     * X = the object slot, Y = the section cursor; section_dir_index ($0700,Y) then indexes the
       five direction tables.  Random pre-state is fine for those — they are plain RAM.
     * ⚠ SMC $298D/$298E: nine cases in ten force Silverstone's AND opcode ($29); the tenth forces
       the else-arm so the platform_smc_unhandled channel runs in both models.
     * The tail dispatches on object_dist_hi vs 3 and 5; object_dist_hi is swept 0..7 and the
       equality mem[$1D]==car_behind is forced half the time, so the AI branch and both early
       returns are all reached.  X escapes as saved_slot_index (build_player_car reads it back).
     * The twin reproduces the oracle's zero-page scratch writes ($0C/$84/$85/$86..$88) so the
       shared tail routines see identical memory; only the mul8 product residue ($74/$75/$76) and
       the PHP stack byte ($01FF) then differ, and those are transient arithmetic scratch.

   tally_bcd_column:
     * X = the column 0..6; standings_mode ($5F38) is kept small (0..5) so the BCD repeat count —
       up to $5F38*($5F38-1) — stays cheap; every mode arm (==1, the player product, the cutoff,
       the doubled) is reached by varying the column's car against player_car and $5F39.
     * ⚠ SED site: the accumulate is BCD, so this case runs with random (often invalid-BCD) bytes
       in the accumulator and increment on purpose — that is what proves adc_value matches the
       oracle's decimal ADC byte for byte.  Result-only but for X (the caller's DEX loop counter);
       ignore the counter scratch $74/$75.
   ========================================================================== */
void place_car_world_coords(void);  void place_car_world_coords__t6502(void);
void tally_bcd_column(void);        void tally_bcd_column__t6502(void);

/* ---- paint_fence_backdrop ($3D5C, twin #128, region_31d0's tree) ------------------------
   The crash "show the fence" fill: a pure function of memory (horizon_extent, the two dither
   tables and the dash_block_starts sentinels) that paints the 40 view source columns plus the
   left/right start-source line buffers.  No register inputs, no callee, no SMC, and check_crash
   ignores every register on return, so the generic result-only contract is exactly right.
   Random memory exercises both dither bands, the zero-fence_pattern_hi fallback and both the
   wrapping (sentinel > $46) and non-wrapping column paths. */
void paint_fence_backdrop(void);  void paint_fence_backdrop__t6502(void);

static int test_crash_fence(void)
{
    return test_contract("paint_fence_backdrop",
                         paint_fence_backdrop, paint_fence_backdrop__t6502,
                         LIVE_NONE, 3000);
}

/* --------------------------------------------------------------------------
   TWINS #129-#133 — the car-order INDEX cluster (src/gen/revs_native.c).
   All observed through registers + the 20-entry car_order table on random memory.
   The mod-20 helpers sweep the FULL input byte because the wrap boundary is the
   only place a bug lives; car_order_swap pins its two indices to 0-19 (real slots);
   find_player_neighbours forces a hit in half the cases so the found-slot path runs
   as well as the $FF miss.
   -------------------------------------------------------------------------- */
void car_index_dec(void);           void car_index_dec__t6502(void);
void car_index_inc(void);           void car_index_inc__t6502(void);
void car_order_swap(void);          void car_order_swap__t6502(void);
void find_player_neighbours(void);  void find_player_neighbours__t6502(void);
void clear_race_clock(void);        void clear_race_clock__t6502(void);
void track_pos_advance(void);       void track_pos_advance__t6502(void);
void track_pos_retreat(void);       void track_pos_retreat__t6502(void);
void lap_complete(void);            void lap_complete__t6502(void);

/* ==========================================================================
   TWINS #167-#171 — THE CRASH / RESTART SUBTREE
   --------------------------------------------------------------------------
   $111E check_crash, $1C0B begin_scrape, $43F6 sound_stop_all,
   $11CE build_player_car, $2B0E step_delta_halve.

   All five run with D = 0: none of them is one of the eight SED sites in
   docs/static-map.md §Decimal mode, and check_crash is on the 50 Hz body, which is entered
   with D clear.  sound_queue's block-index ADC is the only add in the subtree and the sound
   cluster's own fixture already proves that one against decimal separately.

   ⭐ WHAT EACH FIXTURE HAS TO FORCE, and why a random pre-state is not enough:

     check_crash        THREE arms behind two thresholds on bytes that are almost never in
                        range by accident.  edge_nearest_hi ($11) is pinned to 0/1 a third of
                        the time (the on-track arm — a random byte takes it 2 in 256) and
                        nearest_edge_bearing_hi ($5E) is drawn so that |it| straddles $60,
                        which splits scrape from crash.  heading_step_hi's SIGN is forced both
                        ways because it is the whole content of the BIT/abs8 sign copy: with
                        it always positive, negating the $14 constant is undetectable.
     begin_scrape       pure but for the sound queue; A is the yaw kick, X the byte
                        sound_queue parks in sound_saved_x.
     sound_stop_all     ⚠ the already-idle guard again, and here FOUR channels deep: a random
                        page has all four of $62BD..$62C0 non-zero, so half the cases zero a
                        random one of them.  Without that the MOS-call trace never sees the
                        skipped flush that the sound cluster's own fixture had to force.
     build_player_car   it runs place_car_world_coords TWICE, so it inherits that twin's whole
                        steering: the per-circuit SMC seam at $298D (Silverstone's AND opcode
                        nine cases in ten, a trap in the tenth), a slot in range, and the
                        object_dist_hi / car_behind splits its queue tail turns on.  Also pins
                        car_section_cursor across and over the $78 wrap so the look-ahead's
                        `>= $78 -> 0` arm runs.  ⭐ RESULT-ONLY, argued at the shim: its one
                        caller reads no register, and the callee's exit Y and C are outside
                        place_car_world_coords' own declared contract, so they could not be
                        reconstructed even if they were wanted.
     step_delta_halve   pure; the only thing worth forcing is a NEGATIVE component, since the
                        sign propagation is all the routine does.  Random bytes give that in
                        seven cases in eight, and the counter asserts it.
   ========================================================================== */
void check_crash(void);        void check_crash__t6502(void);
void begin_scrape(void);       void begin_scrape__t6502(void);
void sound_stop_all(void);     void sound_stop_all__t6502(void);
void build_player_car(void);   void build_player_car__t6502(void);
void step_delta_halve(void);   void step_delta_halve__t6502(void);

/* ---- project_object_slot ($2A5F) / project_object_coord ($2A5D), twin #172 ---------------
   The object projector: bearing -> object_bearing[slot] -> contact test -> perspective divide
   -> slot write.  Result-only: its three call sites all read object_dist_hi and the slot fields
   out of mem[] and never a register.

   ⭐ THE TWO INPUTS THAT MATTER are both indices, and both have to be steered:
     * X is an index into $0900/$0A00, and the SHIPPING values are $FD (the object_coord pair),
       $F4 and $FA.  Three quarters of the cases use one of those; the rest sweep the byte,
       because bearing_to_section and project_point index the same table and a wrapped index is
       legal 6502.
     * shared_counter_42 is the slot object_bearing and the slot fields are written through, so
       it is pinned to 0..$1F — a random byte would scatter the writes across page 3 and past
       the tables the game actually owns.
   The shape nibble in A is drawn 0..3, the four values the queue tail passes.
   ⚠⚠ AND THE NEAR ARM IS FORCED BY MOVING THE OBJECT, NOT BY SEEDING THE DISTANCE — see the
   note at the line that does it.  point_distance_hypot recomputes point_dist_lo/hi from the
   deltas, so a seeded distance is overwritten before it is tested.  ⭐ The calibration for all
   of this is the sabotage `threshold $25 -> $50`: it survived 4000 cases twice — once because
   the seeded distance was overwritten, and again because moving the object EXACTLY onto the
   camera gives distance 0, which passes either threshold.  It only fails once the distance
   straddles $25. */
void project_object_slot(void);   void project_object_slot__t6502(void);
void project_object_coord(void);  void project_object_coord__t6502(void);

static int test_object_projector(void)
{
    static uint8_t pre[65536];
    static const uint16_t ig[] = { 0x01FF };      /* the PHP residue the bearing/hypot chain leaves */
    int fail = 0, printed = 0, t, i;
    const struct { const char* name; void (*nat)(void); void (*ref)(void); } list[2] = {
        { "project_object_slot",  project_object_slot,  project_object_slot__t6502  },
        { "project_object_coord", project_object_coord, project_object_coord__t6502 },
    };

    for (i = 0; i < 2; i++) {
        const int cases = 4000;
        int contact = 0;
        register_fixture(list[i].name);
        if (!want(list[i].name)) continue;
        set_ignore(ig, 1);
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.D = 0;
            c.A = (uint8_t)(xs() & 3);                       /* the shape nibble */
            c.Y = (uint8_t)xs();
            if (t & 1)       c.X = 0xFDu;
            else if (t & 2)  c.X = (xs() & 1) ? 0xF4u : 0xFAu;
            else             c.X = (uint8_t)xs();
            pre[0x0042] = (uint8_t)(xs() % 0x20);            /* shared_counter_42: a real slot */
            /* ⚠⚠ THE CONTACT ARM CANNOT BE FORCED BY SEEDING point_dist_lo, and the first
               version of this fixture did exactly that and read a coverage counter of ~2000
               that was pure fiction: note_object_contact RUNS point_distance_hypot, which
               overwrites both distance bytes before it tests them.  The tell was a surviving
               sabotage (threshold $25 -> $50 changed nothing over 4000 cases).  What actually
               gates the arm is point_dist_hi == 0, i.e. the object really being near the
               camera — so half the cases put the coordinate this call projects ON TOP of the
               view origin, which is what makes both deltas, and so the distance, small. */
            if (xs() & 1) {
                unsigned o = 0x0900u + c.X, h = 0x0A00u + c.X;
                /* Equal HIGH bytes and a random low offset: the two deltas then span a byte, so
                   the computed distance sweeps 0..~$FF and STRADDLES the $25 threshold instead
                   of sitting on 0 (which passes any threshold and hid the sabotage twice). */
                pre[o + 0] = (uint8_t)(pre[0x6280] + (uint8_t)xs()); pre[h + 0] = pre[0x6283];
                pre[o + 2] = (uint8_t)(pre[0x6282] + (uint8_t)xs()); pre[h + 2] = pre[0x6285];
                contact++;
            }
            fail += diff_run(list[i].name, pre, c,
                             list[i].nat, list[i].ref, LIVE_NONE, t, &printed);
        }
        set_ignore(0, 0);
        if (!contact) { printf("[VACUOUS] %s: no contact-candidate case\n", list[i].name); fail++; }
        printf("%-32s %7d cases, mismatch above must be 0  result-only  "
               "(%d with the object near the camera, distance straddling the threshold)\n", list[i].name, cases, contact);
    }
    return fail;
}

static int test_crash_restart_subtree(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    const int LIVE_ALL = LIVE_A | LIVE_X | LIVE_Y | LIVE_FLAGS;

    /* ---- check_crash -------------------------------------------------------------- */
    register_fixture("check_crash");
    if (want("check_crash")) {
        const int cases = 3000;
        int onTrack = 0, scrape = 0, crash = 0, negYaw = 0;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.D = 0;
            c.X = (uint8_t)xs(); c.Y = (uint8_t)xs(); c.A = (uint8_t)xs();
            if (t % 3 == 0) pre[0x0011] = (uint8_t)(xs() & 1);       /* still on the track */
            else if (pre[0x0011] < 2) pre[0x0011] = 2;
            /* draw the azimuth around the $60 split, both signs */
            pre[0x005E] = (uint8_t)((xs() % 0xC0u) + 0x20u);
            if (xs() & 1) pre[0x005E] = (uint8_t)(0u - pre[0x005E]);
            pre[0x62E2] = (uint8_t)((xs() & 1) ? (xs() | 0x80u) : (xs() & 0x7Fu));
            if (pre[0x62E2] & 0x80u) negYaw++;

            {   uint8_t off = (pre[0x005E] & 0x80u) ? (uint8_t)(0u - pre[0x005E]) : pre[0x005E];
                if (pre[0x0011] < 2) onTrack++; else if (off < 0x60u) scrape++; else crash++; }

            fail += diff_run("check_crash", pre, c,
                             check_crash, check_crash__t6502, LIVE_ALL, t, &printed);
        }
        if (!onTrack || !scrape || !crash || !negYaw) {
            printf("[VACUOUS] check_crash: onTrack=%d scrape=%d crash=%d negYaw=%d\n",
                   onTrack, scrape, crash, negYaw);
            fail++;
        }
        printf("%-32s %7d cases, mismatch above must be 0  live=AXY+flags  "
               "(%d on-track, %d scrape, %d crash, %d negative yaw)\n",
               "check_crash", cases, onTrack, scrape, crash, negYaw);
    }

    /* ---- begin_scrape ------------------------------------------------------------- */
    register_fixture("begin_scrape");
    if (want("begin_scrape")) {
        const int cases = 2000;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.D = 0;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            fail += diff_run("begin_scrape", pre, c,
                             begin_scrape, begin_scrape__t6502, LIVE_ALL, t, &printed);
        }
        printf("%-32s %7d cases, mismatch above must be 0  live=AXY+flags\n",
               "begin_scrape", cases);
    }

    /* ---- sound_stop_all ----------------------------------------------------------- */
    register_fixture("sound_stop_all");
    if (want("sound_stop_all")) {
        const int cases = 2000;
        int idle = 0;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.D = 0;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            if (xs() & 1) { pre[0x62BD + (xs() & 3)] = 0; idle++; }
            fail += diff_run("sound_stop_all", pre, c,
                             sound_stop_all, sound_stop_all__t6502, LIVE_ALL, t, &printed);
        }
        if (!idle) { printf("[VACUOUS] sound_stop_all: no already-idle channel\n"); fail++; }
        printf("%-32s %7d cases, mismatch above must be 0  live=AXY+flags  "
               "(%d with a channel already idle)\n", "sound_stop_all", cases, idle);
    }

    /* ---- build_player_car --------------------------------------------------------- */
    register_fixture("build_player_car");
    if (want("build_player_car")) {
        static const uint16_t ig[] = { 0x01FF };      /* the mul8 residue place_car_world_coords leaves */
        const int cases = 3000;
        int smcArm = 0, wrapArm = 0, nearArm = 0;
        unsigned long smcBefore = g_smcUnhandled;
        setenv("REVS_SMC_CONTINUE", "1", 1);
        set_ignore(ig, 1);
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.D = 0;
            c.X = (uint8_t)xs(); c.Y = (uint8_t)xs(); c.A = (uint8_t)xs();
            pre[0x006F] = (uint8_t)(xs() % 0x14);       /* player_car: a real slot */
            pre[0x0022] = (t & 1) ? (uint8_t)(0x75u + (xs() % 4))   /* straddle the $78 wrap */
                                  : (uint8_t)(xs() % 0x78);
            if ((uint8_t)(pre[0x0022] + 3) >= 0x78) wrapArm++;
            pre[0x0055] = (uint8_t)(xs() % 8);          /* object_dist_hi: the 3/5 splits */
            pre[0x004D] = (uint8_t)(xs() % 0x20);       /* car_behind */
            pre[0x001D] = (xs() & 1) ? pre[0x004D] : (uint8_t)(xs() % 0x20);
            if (xs() % 10) pre[0x298D] = 0x29;          /* Silverstone's AND opcode */
            else { pre[0x298D] = (uint8_t)(0x2A + (xs() & 3)); smcArm++; }
            /* ⚠⚠ THE AI ARM NEEDS A NEARBY OBJECT, and seeding object_dist_hi ($55) does NOT
               give one: the queue tail's first projector runs note_object_contact, which
               OVERWRITES object_dist_hi from the hypot before the `>= 3` test reads it.  The
               tell was a surviving sabotage (the tail's third projector given the wrong
               coordinate index changed nothing over 4000 cases).  What reaches the arm is a
               small object_coord-to-camera delta, so a third of the cases zero the two
               within-section offsets and put this section's ORIGIN on the view origin, with a
               small low-byte jitter so the distance lands in 0..$2 sometimes and above it
               others. */
            if (t % 3 == 0) {
                uint8_t y0 = pre[0x0022], s0 = (uint8_t)(pre[0x0022] + 2);
                pre[0x0164 + pre[0x006F]] = 0; pre[0x0178 + pre[0x006F]] = 0;    /* car_state_1/2: no offset */
                pre[0x0900 + y0] = (uint8_t)(pre[0x6280] + (uint8_t)(xs() & 0x3F));
                pre[0x0A00 + y0] = pre[0x6283];
                pre[0x0900 + s0] = (uint8_t)(pre[0x6282] + (uint8_t)(xs() & 0x3F));
                pre[0x0A00 + s0] = pre[0x6285];
                nearArm++;
            }
            pre[0x298E] = (uint8_t)xs();
            fail += diff_run("build_player_car", pre, c,
                             build_player_car, build_player_car__t6502, LIVE_NONE, t, &printed);
        }
        set_ignore(0, 0);
        unsetenv("REVS_SMC_CONTINUE");
        if (!smcArm || !wrapArm || !nearArm || g_smcUnhandled == smcBefore) {
            printf("[VACUOUS] build_player_car: smc=%d wrap=%d near=%d traps=%lu\n",
                   smcArm, wrapArm, nearArm, g_smcUnhandled - smcBefore);
            fail++;
        }
        printf("%-32s %7d cases, mismatch above must be 0  result-only  "
               "(%d SMC-trap, %d section wrap, %d near the camera)\n",
               "build_player_car", cases, smcArm, wrapArm, nearArm);
    }

    /* ---- step_delta_halve --------------------------------------------------------- */
    register_fixture("step_delta_halve");
    if (want("step_delta_halve")) {
        const int cases = 2000;
        int neg = 0;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.D = 0;
            c.A = (uint8_t)xs(); c.X = (uint8_t)xs(); c.Y = (uint8_t)xs();
            if (pre[0x0083] & 0x80u) neg++;
            fail += diff_run("step_delta_halve", pre, c,
                             step_delta_halve, step_delta_halve__t6502, LIVE_ALL, t, &printed);
        }
        if (!neg) { printf("[VACUOUS] step_delta_halve: no negative component\n"); fail++; }
        printf("%-32s %7d cases, mismatch above must be 0  live=AXY+flags  "
               "(%d negative component 0)\n", "step_delta_halve", cases, neg);
    }

    return fail;
}

static int test_car_order_cluster(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    const int cases = 4000;

    register_fixture("car_index_dec");
    if (want("car_index_dec")) {
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.X = (uint8_t)xs();
            fail += diff_run("car_index_dec", pre, c,
                             car_index_dec, car_index_dec__t6502, LIVE_X, t, &printed);
        }
        printf("%-32s %7d cases  live=X\n", "car_index_dec", cases);
    }

    register_fixture("car_index_inc");
    if (want("car_index_inc")) {
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.X = (uint8_t)xs();
            fail += diff_run("car_index_inc", pre, c,
                             car_index_inc, car_index_inc__t6502, LIVE_X, t, &printed);
        }
        printf("%-32s %7d cases  live=X\n", "car_index_inc", cases);
    }

    register_fixture("car_order_swap");
    if (want("car_order_swap")) {
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre);
            c.X = (uint8_t)(xs() % 20); c.Y = (uint8_t)(xs() % 20);
            fail += diff_run("car_order_swap", pre, c,
                             car_order_swap, car_order_swap__t6502, LIVE_X | LIVE_Y, t, &printed);
        }
        printf("%-32s %7d cases  live=XY\n", "car_order_swap", cases);
    }

    register_fixture("find_player_neighbours");
    if (want("find_player_neighbours")) {
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre);
            if (t & 1) pre[0x013C + (xs() % 20)] = pre[0x006F];   /* plant player_car into car_order */
            fail += diff_run("find_player_neighbours", pre, c,
                             find_player_neighbours, find_player_neighbours__t6502, LIVE_X, t, &printed);
        }
        printf("%-32s %7d cases  live=X\n", "find_player_neighbours", cases);
    }

    register_fixture("clear_race_clock");
    if (want("clear_race_clock")) {
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.X = (uint8_t)xs();
            fail += diff_run("clear_race_clock", pre, c,
                             clear_race_clock, clear_race_clock__t6502, LIVE_A, t, &printed);
        }
        printf("%-32s %7d cases  live=A\n", "clear_race_clock", cases);
    }

    /* --- the track-position steppers (Stage 2).  live=C is the only escaping flag.
       Each arm forces the interesting paths on top of fill_random: t%4==1 plants a
       distance one short of a full lap (advance's lap-wrap + lap_complete call);
       t%4==2 zeroes the distance (retreat's wrap-to-lap-length + player-lap-count
       path); and every 3rd case pins X to player_car so the player-only lap-count
       decrement is exercised.  lap_complete runs identically on both models, so the
       BCD it does on random memory needs no constraining. */
    /* lap_length ($59FC/D) is a track-file constant and is ALWAYS non-zero in reality; a
       zero would make BOTH the twin and the 6502 oracle spin forever on a lap wrap (the ring
       has no length to wrap to).  Pin it to a random non-zero value so the fixture exercises
       the wrap on legal inputs only.
       ⭐ player_car ($6F) is pinned to a real slot 0-19 for the same reason: X here is a car
       slot, and the per-car arrays these steppers index — car_distance among them, now
       relocated to car_distance_16[24] — have exactly one entry per existing car.  An
       out-of-domain X was never reachable (the callers walk car_order); before the relocation
       it merely read a neighbouring array in BOTH models and so went unnoticed. */
    /* Both steppers save/restore the escaping carry with PHP/PLP, which leaves the pushed
       status byte on the stack page.  It is popped straight back (dead stack), so ignore
       $01FF exactly as road_edge_walk and bearing_to_section_from do. */
    static const uint16_t stepIgnore[] = { 0x01FFu };
    set_ignore(stepIgnore, 1);

    register_fixture("track_pos_advance");
    if (want("track_pos_advance")) {
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre);
            uint16_t lap = (uint16_t)(xs() | 1u);                 /* non-zero lap length */
            pre[0x59FC] = (uint8_t)lap; pre[0x59FD] = (uint8_t)(lap >> 8);
            pre[0x006F] = (uint8_t)(xs() % 20);                   /* player_car: a real slot 0-19 */
            c.X = (t % 3) ? (uint8_t)(xs() % 20) : pre[0x006F];   /* sometimes the player */
            if (t % 4 == 1) {                                     /* one short of a full lap */
                pre[0x08D0 + c.X] = (uint8_t)(lap - 1); pre[0x08E8 + c.X] = (uint8_t)((lap - 1) >> 8);
            }
            fail += diff_run("track_pos_advance", pre, c,
                             track_pos_advance, track_pos_advance__t6502, LIVE_C, t, &printed);
        }
        printf("%-32s %7d cases  live=C\n", "track_pos_advance", cases);
    }

    register_fixture("track_pos_retreat");
    if (want("track_pos_retreat")) {
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre);
            uint16_t lap = (uint16_t)(xs() | 1u);                 /* non-zero lap length */
            pre[0x59FC] = (uint8_t)lap; pre[0x59FD] = (uint8_t)(lap >> 8);
            pre[0x006F] = (uint8_t)(xs() % 20);                   /* player_car: a real slot 0-19 */
            c.X = (t % 3) ? (uint8_t)(xs() % 20) : pre[0x006F];   /* sometimes the player */
            if (t % 4 == 2) { pre[0x08D0 + c.X] = 0; pre[0x08E8 + c.X] = 0; }  /* wrap a lap back */
            if (t % 2) pre[0x0880 + c.X] = 0;                    /* force the segment-boundary case */
            fail += diff_run("track_pos_retreat", pre, c,
                             track_pos_retreat, track_pos_retreat__t6502, LIVE_C, t, &printed);
        }
        printf("%-32s %7d cases  live=C\n", "track_pos_retreat", cases);
    }

    set_ignore(0, 0);   /* end the steppers' PHP/PLP $01FF ignore (lap_complete leaves no residue) */

    /* --- lap_complete (Stage 2's third twin), called on a lap wrap.  Nothing escapes (the caller
       discards A and flags) → LIVE_NONE.  Entry decimal is always clear on this path (the SED/CLD
       is internal), so pin c.D = 0.  race_clock / car_lap_start / car_best_lap are ALWAYS valid
       packed BCD in reality, and the 6502's decimal SBC and this twin's sbc_value agree only on
       valid BCD, so plant valid BCD there (seconds byte 0-59).  The control gates — session mode,
       the player one-shot debounce, the lap-total comparison and the flags-bit-6 skip — ride on
       fill_random with a few arms forced to hit the interesting branches. */
    register_fixture("lap_complete");
    if (want("lap_complete")) {
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu(); fill_random(pre); c.D = 0;
            uint8_t px = (uint8_t)(xs() % 20);
            uint8_t x  = (t % 3) ? (uint8_t)(xs() % 20) : px;  /* sometimes the player */
            /* targeted arm A: X exactly at the pseudo-car boundary ($14), where >= and > diverge.
               Only reachable here, and the body must WRITE for the sabotage to show, so clear the
               lap-count sentinel bit so its INC always fires. */
            if (t % 11 == 0) { x = 0x14; px = (uint8_t)(xs() % 20); pre[0x04B4 + x] &= (uint8_t)0x7F; }
            /* targeted arm B: a non-player car recorded in practice, with car_lap_start zeroed and
               car_best_lap set equal to the resulting lap time — the only way lap == best, where
               the best-lap test's < and <= diverge. */
            if (t % 13 == 1) { px = 19; x = (uint8_t)(xs() % 19); }
            c.X = x;
            pre[0x006F] = px;                                 /* player_car: a real slot 0-19 */
            pre[0x62F8] = (t % 7 == 0) ? 0x80 : 0x00;         /* mostly let the body run */
            if (t % 2) pre[0x018C + x] &= (uint8_t)~0x40;     /* clear the projection-reject skip */
            if (x == px) pre[0x0030] = (t % 2) ? 1 : (uint8_t)xs();        /* arm / disarm the credit */
            if (t % 5 == 0) pre[0x006C] |= 0x80;              /* race mode */
            else if (t % 5 == 1) pre[0x006C] &= (uint8_t)0x7F; /* practice / qualifying */
            if (t % 4 == 0) pre[0x04B4 + x] = pre[0x006E];    /* car_lap_count == race_lap_total arm */
            /* valid packed BCD clocks (centi 0-99, sec 0-59, min 0-99); force a non-zero centi low
               nibble so the best-lap store's &$F0 is observable */
            pre[0x06B4] = (uint8_t)(((xs() % 10) << 4) | ((xs() % 9) + 1)); /* race_clock_lo  (centi) */
            pre[0x06CC] = (uint8_t)(((xs() % 6)  << 4) | (xs() % 10));      /* race_clock_mid (sec)   */
            pre[0x06E4] = (uint8_t)(((xs() % 10) << 4) | (xs() % 10));      /* race_clock_hi  (min)   */
            pre[0x0898 + x] = (uint8_t)(((xs() % 10) << 4) | (xs() % 10));  /* car_lap_start_lo  */
            pre[0x08AC + x] = (uint8_t)(((xs() % 6)  << 4) | (xs() % 10));  /* car_lap_start_mid */
            pre[0x04DC + x] = (uint8_t)(((xs() % 10) << 4) | (xs() % 10));  /* car_lap_start_hi  */
            if (t % 3 == 0) {                                 /* force a new best (best = max) */
                pre[0x06A0 + x] = 0x99; pre[0x06B8 + x] = 0x99; pre[0x06D0 + x] = 0x99;
            } else {
                pre[0x06A0 + x] = (uint8_t)(((xs() % 10) << 4) | (xs() % 10));
                pre[0x06B8 + x] = (uint8_t)(((xs() % 6)  << 4) | (xs() % 10));
                pre[0x06D0 + x] = (uint8_t)(((xs() % 10) << 4) | (xs() % 10));
            }
            if (t % 11 == 0) pre[0x018C + x] &= (uint8_t)~0x40;   /* boundary arm: body must run */
            if (t % 13 == 1) {                                    /* equality arm: lap == best */
                pre[0x62F8] = 0x00;                               /* scan not active            */
                pre[0x018C + x] &= (uint8_t)~0x40;                /* not projection-rejected    */
                pre[0x006C] &= (uint8_t)0x7F;                     /* practice -> x <= px records */
                pre[0x0898 + x] = 0; pre[0x08AC + x] = 0; pre[0x04DC + x] = 0;   /* start = 0 -> lap == clock */
                pre[0x06A0 + x] = pre[0x06B4];                    /* best := the exact lap time  */
                pre[0x06B8 + x] = pre[0x06CC];
                pre[0x06D0 + x] = pre[0x06E4];
            }
            fail += diff_run("lap_complete", pre, c,
                             lap_complete, lap_complete__t6502, LIVE_NONE, t, &printed);
        }
        printf("%-32s %7d cases  live=NONE\n", "lap_complete", cases);
    }

    return fail;
}

static int test_last_shim_callers(void)
{
    static uint8_t pre[65536];
    int fail = 0, printed = 0, t;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    register_fixture("place_car_world_coords");
    register_fixture("tally_bcd_column");

    setenv("REVS_SMC_CONTINUE", "1", 1);
    unsigned long smcBefore = g_smcUnhandled;

    /* ---- place_car_world_coords ---- */
    if (want("place_car_world_coords")) {
        static const uint16_t ig[] = { 0x01FF };  /* mul8 residue + PHP byte */
        int cases = 4000 * scale;
        int smcArm = 0, nearArm = 0, incArm = 0;
        set_ignore(ig, (int)(sizeof(ig) / sizeof(ig[0])));
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.X = (uint8_t)xs();
            c.Y = (uint8_t)xs();
            c.D = 0;                                    /* render/placement path is D=0 */
            pre[0x0045] = (uint8_t)(xs() % 0x20);       /* saved_slot_index: car+scenery slots */
            pre[0x0055] = (uint8_t)(xs() % 8);          /* object_dist_hi: sweep the 3/5 splits */
            pre[0x004D] = (uint8_t)(xs() % 0x20);       /* car_behind */
            pre[0x001D] = (xs() & 1) ? pre[0x004D] : (uint8_t)(xs() % 0x20);  /* force == half */
            if (xs() % 10) pre[0x298D] = 0x29;          /* Silverstone AND opcode */
            else { pre[0x298D] = (uint8_t)(0x2A + (xs() & 3)); smcArm++; }    /* else-arm trap */
            pre[0x298E] = (uint8_t)xs();                /* the mask */

            /* ⚠⚠ THE AI ARM NEEDS A NEARBY OBJECT, and seeding object_dist_hi ($55) does NOT
               give one: the queue tail's first projector runs note_object_contact, which
               OVERWRITES object_dist_hi from the hypot before the `>= 3` test reads it.  The
               tell was a surviving sabotage (the tail's third projector given the wrong
               coordinate index changed nothing over 4000 cases).  What reaches the arm is a
               small object_coord-to-camera delta, so a third of the cases zero the two
               within-section offsets and put this section's ORIGIN on the view origin, with a
               small low-byte jitter so the distance lands in 0..$2 sometimes and above it
               others. */
            if (t % 3 == 0) {
                uint8_t y0 = c.Y, s0 = (uint8_t)(c.Y + 2);
                pre[0x0164 + c.X] = 0; pre[0x0178 + c.X] = 0;    /* car_state_1/2: no offset */
                pre[0x0900 + y0] = (uint8_t)(pre[0x6280] + (uint8_t)(xs() & 0x3F));
                pre[0x0A00 + y0] = pre[0x6283];
                pre[0x0900 + s0] = (uint8_t)(pre[0x6282] + (uint8_t)(xs() & 0x3F));
                pre[0x0A00 + s0] = pre[0x6285];
                nearArm++;
            }

            if (pre[0x0055] >= 5) incArm++;

            fail += diff_run("place_car_world_coords", pre, c,
                             place_car_world_coords, place_car_world_coords__t6502,
                             LIVE_X, t, &printed);
        }
        set_ignore(0, 0);
        if (!smcArm || !nearArm || !incArm) {
            printf("[VACUOUS] place_car_world_coords: smc=%d near=%d inc=%d\n", smcArm, nearArm, incArm);
            fail++;
        }
        printf("%-24s %7d cases, mismatch above must be 0  live=X  D=0\n",
               "place_car_world_coords", cases);
    }

    /* ---- tally_bcd_column ---- */
    if (want("tally_bcd_column")) {
        static const uint16_t ig[] = { 0x0074, 0x0075 };   /* the BCD counter scratch */
        int cases = 4000 * scale;
        int oneArm = 0, prodArm = 0, cutArm = 0, dblArm = 0;
        set_ignore(ig, 2);
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.X = (uint8_t)(xs() % 7);                   /* column 0..6 */
            c.D = 0;                                     /* the routine sets D itself */
            pre[0x5F38] = (uint8_t)(xs() % 6);           /* standings_mode: keep the count cheap */
            pre[0x006F] = (uint8_t)(xs() % 20);          /* player_car */
            pre[0x5F39] = (uint8_t)(xs() % 20);          /* the cutoff */
            /* Force the column's car (car_order[X], or [0] for X==6) onto the branch we want. */
            {
                uint16_t oidx = (c.X == 6) ? 0x013C : (uint16_t)(0x013C + c.X);
                uint8_t pick = (uint8_t)(xs() & 3);
                if (pick == 0) pre[oidx] = pre[0x006F];                  /* == player_car */
                else if (pick == 1) pre[oidx] = (uint8_t)(pre[0x5F39] + (xs() % 20)); /* >= cutoff */
                else pre[oidx] = (uint8_t)(xs() % 20);                   /* below both -> ASL arm */
            }
            /* tally counters (which arm the count came from) */
            {
                uint8_t s = pre[0x5F38];
                uint16_t oidx = (c.X == 6) ? 0x013C : (uint16_t)(0x013C + c.X);
                uint8_t y = pre[oidx];
                if (s == 1) oneArm++;
                else if (y == pre[0x006F]) prodArm++;
                else if (y >= pre[0x5F39]) cutArm++;
                else if ((uint8_t)((s - 1) << 1) != 0) dblArm++;
                else prodArm++;
            }
            fail += diff_run("tally_bcd_column", pre, c,
                             tally_bcd_column, tally_bcd_column__t6502,
                             LIVE_X, t, &printed);
        }
        set_ignore(0, 0);
        if (!oneArm || !prodArm || !cutArm || !dblArm) {
            printf("[VACUOUS] tally_bcd_column: one=%d prod=%d cut=%d dbl=%d\n",
                   oneArm, prodArm, cutArm, dblArm);
            fail++;
        }
        printf("%-24s %7d cases, mismatch above must be 0  live=X  BCD\n",
               "tally_bcd_column", cases);
    }

    unsetenv("REVS_SMC_CONTINUE");
    if (want("place_car_world_coords") && g_smcUnhandled == smcBefore) {
        printf("[VACUOUS] place_car_world_coords: no SMC trap over the whole run\n");
        fail++;
    }
    return fail;
}


/* ==========================================================================
   TWINS #87-#92 — THE ROAD SIGN AND THE OBJECT SLOT WRITER
   --------------------------------------------------------------------------
   $4CA4 build_road_sign, $4D21 build_sign_origin, $2A76 write_object_slot,
   $2AA6 reject_object_slot, $2AAD store_object_flags, $2AB3 note_object_contact.

   ⚠⚠ FIVE PER-CIRCUIT SMC SITES, and they are the whole reason this fixture is steered.
   build_road_sign's five table loads ($4CC0 $4CC8 $4CD0 $4CD6 $4CE0) are `LDA abs,X` whose
   OPERANDS every circuit rewrites, so a random pre-state traps at the first one 255 times in 256
   and the routine's whole body — three build_sign_origin calls, the bearing, the projection and
   the slot write — is never reached.  Nine cases in ten therefore force Silverstone's own bytes;
   the tenth is left random on purpose, because diff_run compares the SMC trap as its own channel
   and a twin that trapped at a different site would otherwise pass.

   ⭐ AND FOUR MORE STEERED INPUTS, each of which gates an arm:

     player_car ($6F)      0..19, so car_segment and the page-1 arrays are indexed in range.
     sign_last_index ($62F9)  forced EQUAL to the segment's own sign nibble in half the cases.
                           That is $4CB5's `BNE` — the arm where an unchanged segment shows the
                           NEXT sign — and a random byte reaches it one time in sixteen.
     shared_temp_77 ($77)  0..2 for build_sign_origin standalone: it is the component cursor,
                           and a random byte would index view_origin hundreds of bytes past its
                           three components (identically in both models, proving nothing).
     proj_width_shift ($2B)  $05..$12 in half the cases.  write_object_slot shifts by
                           proj_width_shift - $0A, so this is what makes BOTH directions of the
                           exponent correction run; outside that window every case shifts to 0.

   The counters below assert each of those actually happened.
   ========================================================================== */
void build_road_sign(void);       void build_road_sign__t6502(void);
void build_sign_origin(void);     void build_sign_origin__t6502(void);
void write_object_slot(void);     void write_object_slot__t6502(void);
void reject_object_slot(void);    void reject_object_slot__t6502(void);
void store_object_flags(void);    void store_object_flags__t6502(void);
void note_object_contact(void);   void note_object_contact__t6502(void);

#define PRE_SIGN_LAST      0x62F9
#define PRE_SHARED_77      0x0077
#define PRE_PROJ_W_SHIFT   0x002B
#define PRE_SLOT_COUNTER   0x0042
#define PRE_CAR_SEGMENT    0x06E8
#define PRE_TRACK_SEG_HI   0x5300

/* Silverstone's own bytes at the five per-circuit sites — the unpatched shape. */
static void force_sign_smc(uint8_t* pre)
{
    static const struct { uint16_t site; uint8_t lo, hi; } SITES[5] = {
        { 0x4CC0, 0xE0, 0x53 },   /* sign_offset_2 */
        { 0x4CC8, 0xF0, 0x53 },   /* sign_offset_1 */
        { 0x4CD0, 0xD0, 0x53 },   /* sign_offset_0 */
        { 0x4CD6, 0xEA, 0x59 },   /* sign_shape_segment — the shape nibble */
        { 0x4CE0, 0xEA, 0x59 },   /* ...and the segment field */
    };
    int i;
    for (i = 0; i < 5; i++) {
        pre[SITES[i].site]     = 0xBD;
        pre[SITES[i].site + 1] = SITES[i].lo;
        pre[SITES[i].site + 2] = SITES[i].hi;
    }
}

/* ⭐⭐ A SIGN THAT IS ACTUALLY CLOSE, and without it build_road_sign's CONTACT THRESHOLD is
   dead code.  On a random pre-state the sign's distance is more than $FF away in essentially
   every case, so note_object_contact returns at its first test and neither $25 nor $50 is ever
   compared with anything — the sabotage "the wide threshold is $25 as well" survived 4000 cases.
   This forces a distance of exactly $30, which is over $25 and under $50, so the two arms
   DISAGREE:
     * the sign's three offsets are 0, which makes view origin 6 the camera itself;
     * its table byte is $08 — segment byte 8, shape 0;
     * that segment's coordinate triple is the camera's own, plus $30 on component 0 and
       nothing on component 2, so point_distance_hypot's near arm returns 0 + $30.
   Both candidate sign numbers are prepared, because $4CB5 picks between them.
   ⚠ Only valid on a case whose five SMC sites hold Silverstone's bases (force_sign_smc). */
static void force_near_sign(uint8_t* pre)
{
    uint8_t  pc  = pre[PRE_PLAYER_CAR];
    uint8_t  seg = pre[PRE_CAR_SEGMENT + pc];
    uint8_t  n0  = (uint8_t)(pre[PRE_TRACK_SEG_HI + seg] >> 4);
    unsigned cam0, cam2, pt0;
    int k;

    for (k = 0; k < 2; k++) {
        uint8_t idx = (uint8_t)((n0 + k) & 0x0F);
        pre[0x53D0 + idx] = 0;          /* sign_offset_0 */
        pre[0x53E0 + idx] = 0;          /* sign_offset_2 */
        pre[0x53F0 + idx] = 0;          /* sign_offset_1 */
        pre[0x59EA + idx] = 0x08;       /* sign_shape_segment: segment byte 8, shape 0 */
    }
    cam0 = (unsigned)pre[0x6280] | ((unsigned)pre[0x6283] << 8);
    cam2 = (unsigned)pre[0x6282] | ((unsigned)pre[0x6285] << 8);
    pt0  = (cam0 + 0x30u) & 0xFFFFu;
    pre[0x5909] = (uint8_t)pt0;         pre[0x5309] = (uint8_t)(pt0 >> 8);
    pre[0x590A] = pre[0x6281];          pre[0x530A] = pre[0x6284];
    pre[0x590B] = (uint8_t)cam2;        pre[0x530B] = (uint8_t)(cam2 >> 8);
}

static int test_road_sign(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    unsigned long smcTraps;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); int cases; }
      list[6] = {
        { "store_object_flags",  store_object_flags,  store_object_flags__t6502,   1000 },
        { "reject_object_slot",  reject_object_slot,  reject_object_slot__t6502,   1000 },
        { "note_object_contact", note_object_contact, note_object_contact__t6502,  3000 },
        { "build_sign_origin",   build_sign_origin,   build_sign_origin__t6502,    3000 },
        { "write_object_slot",   write_object_slot,   write_object_slot__t6502,    4000 },
        { "build_road_sign",     build_road_sign,     build_road_sign__t6502,      4000 },
      };
    for (i = 0; i < 6; i++) register_fixture(list[i].name);

    setenv("REVS_SMC_CONTINUE", "1", 1);
    g_smcUnhandled = 0;

    for (i = 0; i < 6; i++) {
        int subFail = 0, decimal = 0, patched = 0, sameSign = 0, shiftBoth = 0;
        int rejectC = 0, rejectLine = 0, accepted = 0, contact = 0, wideThresh = 0;
        int cases = list[i].cases * scale;
        if (!want(list[i].name)) continue;
        /* build_sign_origin (i==3): the 6502 PHA/PLA-staged its argument; the twin reads bit 7
           of a local instead, so the oracle still writes the pushed byte to $0100+S (S=$FF here)
           and the clean core does not.  Ignore that one dead residue byte; determinism's own
           $01B8..$01FF skip covers it in the whole-corpus path. */
        static const uint16_t signOriginIgnore[1] = { 0x01FF };
        set_ignore(i == 3 ? signOriginIgnore : 0, i == 3 ? 1 : 0);
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs();
            c.X = (uint8_t)xs();
            c.Y = (uint8_t)xs();
            pre[PRE_PLAYER_CAR]   = (uint8_t)(xs() % 20);
            pre[PRE_SLOT_COUNTER] = (uint8_t)(xs() % 24);   /* a real object slot */

            /* The five SMC sites: nine in ten unpatched, the tenth left random. */
            if (xs() % 10) force_sign_smc(pre);
            else           patched++;

            /* $4CB5's equal arm — the sign that has not changed since last frame. */
            if (xs() & 1) {
                uint8_t seg = pre[PRE_CAR_SEGMENT + pre[PRE_PLAYER_CAR]];
                pre[PRE_SIGN_LAST] = (uint8_t)(pre[PRE_TRACK_SEG_HI + seg] >> 4);
                sameSign++;
            }

            /* build_sign_origin's component cursor, and its shift in Y. */
            pre[PRE_SHARED_77] = (uint8_t)(xs() % 3);
            if (i == 3) {
                unsigned pick = xs() % 4;
                c.Y = (uint8_t)(pick == 0 ? 2 : pick == 1 ? 4 : pick == 2 ? 0 : (xs() & 7));
            }

            /* write_object_slot's exponent window, and its two reject arms. */
            if (xs() & 1) { pre[PRE_PROJ_W_SHIFT] = (uint8_t)(0x05 + xs() % 14); shiftBoth++; }
            if (i == 4) {
                unsigned pick = xs() % 4;
                if (pick == 0)      { c.C = 1; rejectC++; }
                else if (pick == 1) { c.C = 0; c.A = 0;   rejectLine++; }
                else                { c.C = 0; c.A = (uint8_t)(1 + xs() % 255); accepted++; }
            }

            /* note_object_contact: a threshold that the distance can actually be under.  The
               two magnitudes are random, so most cases are far away; a sixth are forced close. */
            if (i == 2) {
                c.Y = (uint8_t)xs();
                if (xs() % 6 == 0) {
                    pre[0x0078] = (uint8_t)xs(); pre[0x0079] = 0;   /* hypot_min */
                    pre[0x007A] = (uint8_t)(xs() & 0x1F); pre[0x007B] = 0;  /* hypot_max */
                    contact++;
                }
            }
            /* build_road_sign: half the cases get a sign $30 away — see force_near_sign. */
            if (i == 5 && pre[0x4CC0] == 0xBD && (xs() & 1)) {
                force_near_sign(pre);
                pre[0x000B] = (uint8_t)xs();   /* car_heading_hi picks which threshold applies */
                wideThresh++;
            }

            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = (i == 4) ? c.C : (xs() & 1);
            /* i>=3 (build_sign_origin, write_object_slot, build_road_sign) are the object/sign
               GEOMETRY path — always binary (docs/static-map.md §Decimal mode), and their twins
               fold the SBC chains to native 16-bit subtracts.  Pin D=0; determinism-drive is the
               backstop that D=0 truly holds on that path.  i<3 keep D random (no arithmetic that
               D changes, but the coverage is harmless). */
            c.D = (i >= 3) ? 0 : (uint8_t)(xs() % 4 == 0);
            if (c.D) decimal++;
            /* ⭐ build_road_sign (i==5) answers entirely in mem[] — the object arrays for slot
               $17, sign_last_index — and its one caller ($1728) does LDX #$17 next and reads no
               exit flag, so its A/X/Y/N/V/Z/C are dead.  It formerly validated green only because
               the transliterated project_point it calls left carry/N/A in cpu as a side effect,
               which the clean core no longer does.  Keep S live for the stack-balance check.
               The other five here are leaf routines whose flags ARE read by callers. */
            unsigned caseMask = (i == 5) ? LIVE_S : liveMask;
            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                caseMask, t, &printed);
        }
        fail += subFail;
        if ((i < 3 && !decimal) || !patched || !sameSign || !shiftBoth) {
            printf("[VACUOUS] %s: %d decimal, %d SMC-random, %d same sign, %d shift window\n",
                   list[i].name, decimal, patched, sameSign, shiftBoth);
            fail++;
        }
        if (i == 4 && (!rejectC || !rejectLine || !accepted)) {
            printf("[VACUOUS] write_object_slot: %d carry rejects, %d line rejects, %d accepted\n",
                   rejectC, rejectLine, accepted);
            fail++;
        }
        if (i == 2 && !contact) {
            printf("[VACUOUS] note_object_contact: no forced-close case\n");
            fail++;
        }
        if (i == 5 && !wideThresh) {
            printf("[VACUOUS] build_road_sign: no near-sign case — the contact threshold "
                   "was never compared with anything\n");
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=%s  "
               "(%d decimal, %d SMC-random, %d same sign, %d shift window%s)\n",
               list[i].name, cases, subFail, (i == 5) ? "S (mem-only result)" : "AXY+flags",
               decimal, patched, sameSign, shiftBoth,
               i == 4 ? ", both reject arms" : (i == 2 ? ", close cases forced" :
               (i == 5 ? ", near signs forced" : "")));
    }

    set_ignore(0, 0);
    smcTraps = g_smcUnhandled;
    unsetenv("REVS_SMC_CONTINUE");
    if (want("build_road_sign")) {
        if (smcTraps == 0) {
            printf("[VACUOUS] build_road_sign: no SMC trap over the whole run — the five "
                   "per-circuit table sites were never exercised on an unknown shape\n");
            fail++;
        }
        printf("%-32s %7lu SMC traps at the five sign-table sites (must be > 0)\n",
               "road sign", smcTraps);
    }
    return fail;
}


/* ==========================================================================
   TWINS #93-#95 — THE OBJECT PLOTTER'S SHAPE SIDE
   --------------------------------------------------------------------------
   $1FB4 plot_object, $202A scale_shape_vectors, $209A plot_shape_edges.

   ⚠⚠ THE SHAPE TABLES HAVE TO BE MADE LEGAL, not left random.  Six of them drive this pass —
   shape_vector_start, shape_edge_start and the five per-edge columns — and a uniform byte in any
   of them indexes shape_vertex (16 entries) or shape_vector_tbl hundreds of bytes past its end.
   Both models would do it identically, so the run would be green while covering nothing: no
   vertex would be a real fraction of the width, and the edge walk would terminate on the first
   random bit-6 byte instead of drawing a shape.  This fixture therefore constrains them to their
   real SHAPES (ascending starts, vertex indices in 0..15, a style byte whose control bits are
   drawn deliberately) while leaving the values themselves random — the game's own bytes are not
   reproduced here, only their ranges.

   ⚠ AND THE STYLE BYTE'S CONTROL BITS ARE DRAWN, NOT LEFT TO CHANCE.  Bit 7 is the closing arm
   and bit 6 ends the shape, and on the reject path they mean different things again; a uniform
   byte gives each combination a quarter of the time but ends the walk after one or two edges.
   A third of the cases here get bit 7 set and a fifth bit 6, per edge.

   ⚠ $1FE9 is a PER-CIRCUIT SMC extent (Silverstone `LDX horizon_extent`, an expansion circuit
   `LDX #imm`).  Both arms are forced, and a tenth of the cases are left random so the trap
   channel is exercised too.
   ========================================================================== */
void plot_object(void);          void plot_object__t6502(void);
void scale_shape_vectors(void);  void scale_shape_vectors__t6502(void);
void plot_shape_edges(void);     void plot_shape_edges__t6502(void);

#define PRE_PLOT_SHAPE     0x0037
#define PRE_PROJ_WIDTH     0x002A
#define PRE_PROJ_W_SHIFT2  0x002B
#define PRE_PLOT_X         0x0035
#define PRE_PLOT_LINE      0x0036
#define PRE_HORIZ_HALF     0x62FC
#define PRE_HORIZ_EXTENT   0x001F
#define PRE_LINE_CEILING   0x62FD
#define PRE_EDGE_CURSOR    0x008E
#define PRE_VEC_CURSOR     0x0081
#define PRE_VEC_END        0x008A

/* ⚠⚠ LEGAL SHAPE TABLES, AND "LEGAL" IS NARROWER THAN IT LOOKS.  The five per-edge columns live
   in the UNUSED TAILS ($50-$7F) of the view source blocks — $3550 is block 10 + $50, $3750 is
   block 14 + $50 — so each column has room for exactly 48 entries and index 48 is the next
   block's DATA, which plot_view_src_line itself overwrites.  A walk that runs past 47 therefore
   reads whatever the plotter has just painted, and if bit 6 never comes up the edge walk never
   ends: both models hang identically, which is how this fixture failed twice before the last
   eight entries were given a guaranteed terminator.
   Returns non-zero when some edge selected the closing arm. */
static int force_shape_tables(uint8_t* pre)
{
    enum { EDGES = 48 };
    int closing = 0, i;
    unsigned v = 0, e = 0;

    for (i = 0; i <= 10; i++) {                 /* shape_vector_start / shape_edge_start */
        pre[0x3CDD + i] = (uint8_t)v;  v += 1 + xs() % 6;
        pre[0x3CD0 + i] = (uint8_t)e;  e += 1 + xs() % 3;
    }
    for (i = 0; i < EDGES; i++) {               /* the five per-edge columns */
        uint8_t style = (uint8_t)(xs() & 0x3F);
        pre[0x3550 + i] = (uint8_t)(xs() % 16);
        pre[0x35D0 + i] = (uint8_t)(xs() % 16);
        pre[0x3650 + i] = (uint8_t)(xs() % 16);
        pre[0x36D0 + i] = (uint8_t)(xs() % 16);
        if (xs() % 3 == 0) { style |= 0x80; closing++; }   /* the closing arm */
        if (xs() % 4 == 0) style |= 0x40;                  /* ...and the shape's end */
        /* ⚠ THE LAST EIGHT ENTRIES ARE A HARD TERMINATOR, bit 6 SET and bit 7 CLEAR.  Bit 6
           alone is not enough: bit 7 sends the walk to the closing arm, which advances the
           cursor and never looks at bit 6, so eight consecutive bit-7 entries (1 in 6561) walk
           past index 47 into the block data the plotter has just painted and the loop never
           ends.  That is what still hung after the tables were first bounded, and only in the
           UNFILTERED run — a `FN=`-filtered one draws a different random stream. */
        if (i >= EDGES - 8) style = (uint8_t)((style | 0x40) & 0x7F);
        pre[0x3750 + i] = style;
    }

    /* ⚠⚠ AND dash_block_starts HAS TO BE LEGAL TOO, for the same reason: each entry is where
       block X's data STARTS and the data always ends at offset $4F, so a random byte over $4F
       makes plot_view_src_line's `DEY / CPY $82` walk wrap through 256 lines and overwrite the
       edge list in the tails underneath it. */
    for (i = 0; i <= 40; i++) pre[0x3900 + i] = (uint8_t)(xs() % 0x50);

    /* ⚠⚠ …AND SO DOES object_gap_top_tbl, which is the one that actually bit.  fill_object_gap
       reads it per column and, when the entry is at or above span_top_line, uses `entry + ($7F -
       span_line_cursor)` as its write cursor — so an entry over $4F puts the cursor BELOW the
       run's floor and the `INY / BPL` fill walks up through the block's tail, over the edge
       tables.  Silverstone's own entries are all $02..$44.  Found by instrumenting the twin's
       edge loop after two rounds of guessing: the spinning walk was reading $3D out of a style
       table that had been painted over. */
    for (i = 0; i <= 40; i++) pre[0x3F4F + i] = (uint8_t)(xs() % 0x50);
    return closing;
}

static int test_object_shape(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    unsigned long smcTraps;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); int cases; }
      list[3] = {
        { "scale_shape_vectors", scale_shape_vectors, scale_shape_vectors__t6502, 4000 },
        { "plot_shape_edges",    plot_shape_edges,    plot_shape_edges__t6502,    2000 },
        { "plot_object",         plot_object,         plot_object__t6502,         2000 },
      };
    for (i = 0; i < 3; i++) register_fixture(list[i].name);

    setenv("REVS_SMC_CONTINUE", "1", 1);
    g_smcUnhandled = 0;

    for (i = 0; i < 3; i++) {
        int subFail = 0, decimal = 0, patched = 0, closing = 0, wide = 0;
        int twoPart = 0, sign = 0, extraShift = 0;
        int cases = list[i].cases * scale;
        if (!want(list[i].name)) continue;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs();
            c.Y = (uint8_t)xs();

            closing += force_shape_tables(pre) ? 1 : 0;

            /* The four-cell argument block draw_track_object leaves. */
            pre[PRE_PLOT_X]     = (uint8_t)xs();
            pre[PRE_PLOT_LINE]  = (uint8_t)(xs() % 0x50);
            pre[PRE_PROJ_WIDTH] = (uint8_t)(xs() % 0x80);
            pre[PRE_HORIZ_HALF] = (uint8_t)(xs() % 0x80);
            pre[PRE_HORIZ_EXTENT] = (uint8_t)(xs() % 0x50);
            if (pre[PRE_PROJ_WIDTH] >= pre[PRE_HORIZ_HALF]) wide++;

            /* plot_object's SLOT: the twenty cars, the three specials, and the sign at $17. */
            c.X = (uint8_t)(xs() % 0x18);
            /* ...and the shape.  $0A and up is the TWO-PART case (group header, item 5).
               ⚠⚠ SHAPE 9 IS EXCLUDED, AND NOT BECAUSE IT IS AWKWARD: it makes the 6502 LOOP
               FOREVER.  $2002 re-enters below the clamp, so a plot_shape of exactly 9 writes 9
               into object_shape_clamped on every pass and $2021's `CMP #$09` never stops
               agreeing.  It is unreachable in the game — cars use shapes 0/1/2/4, corner
               markers 6, and a sign's (size + 7) never lands on 9 on any circuit — so 9 is the
               marker for "the stand-in has been drawn", never a shape.  Both models hang
               identically on it, which is why the first run of this fixture timed out. */
            { unsigned pick = xs() % 11;
              pre[PRE_PLOT_SHAPE] = (uint8_t)(pick < 9 ? pick : pick + 1); }
            if (pre[PRE_PLOT_SHAPE] >= 0x0A) twoPart++;
            pre[0x0025] = (uint8_t)((xs() & 1) ? 0x00 : 0x80);   /* track_direction */
            if (!(pre[0x0025] & 0x80)) sign++;

            /* The two callees run standalone too, so they need their own cursors in range. */
            if (i != 2) {
                pre[PRE_PROJ_W_SHIFT2] = (uint8_t)((xs() & 1) ? 0 : (1 + xs() % 3));
                if (pre[PRE_PROJ_W_SHIFT2]) extraShift++;
                pre[PRE_VEC_CURSOR]  = (uint8_t)(xs() % 0x38);
                pre[PRE_VEC_END]     = (uint8_t)(pre[PRE_VEC_CURSOR] + 1 + xs() % 8);
                pre[PRE_EDGE_CURSOR] = (uint8_t)(xs() % 0x18);
                pre[PRE_LINE_CEILING] = (uint8_t)(xs() % 0x50);
            }

            /* $1FE9 — nine in ten a real arm, and half of those the circuit's `LDX #imm`. */
            if (xs() % 10) {
                if (xs() & 1) pre[0x1FE9] = 0xA6;
                else        { pre[0x1FE9] = 0xA2; pre[0x1FEA] = (uint8_t)(xs() % 0x50); }
            } else patched++;

            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            /* The object plotter is the render path — always binary (docs/static-map.md §Decimal
               mode: none of the 8 SED sites are here), and scale_shape_vectors/plot_shape_edges
               now fold their ADC chains to native adds.  Pin D=0; determinism-drive is the
               backstop that the object path never runs in decimal. */
            c.D = 0;
            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                liveMask, t, &printed);
        }
        fail += subFail;
        if (!patched || !closing || !wide) {
            printf("[VACUOUS] %s: %d decimal, %d SMC-random, %d closing arms, %d wide\n",
                   list[i].name, decimal, patched, closing, wide);
            fail++;
        }
        if (i == 2 && (!twoPart || !sign)) {
            printf("[VACUOUS] plot_object: %d two-part shapes, %d positive track_direction\n",
                   twoPart, sign);
            fail++;
        }
        if (i != 2 && !extraShift) {
            printf("[VACUOUS] %s: no extra proj_width_shift case\n", list[i].name);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+flags  "
               "(%d decimal, %d SMC-random, %d wide%s)\n",
               list[i].name, cases, subFail, decimal, patched, wide,
               i == 2 ? ", two-part shapes forced" : ", extra shift forced");
    }

    smcTraps = g_smcUnhandled;
    unsetenv("REVS_SMC_CONTINUE");
    if (want("plot_object")) {
        if (smcTraps == 0) {
            printf("[VACUOUS] plot_object: no SMC trap at $1FE9 over the whole run\n");
            fail++;
        }
        /* ⚠ The count is not only $1FE9: plot_view_src_line's self-modified branch at $1DD4
           traps too, and often, because its offset byte is random here.  Both are compared by
           diff_run as their own channel, which is what this asserts is non-empty. */
        printf("%-32s %7lu SMC traps ($1FE9 and plot_view_src_line's $1DD4; must be > 0)\n",
               "object plotter", smcTraps);
    }
    return fail;
}


/* ==========================================================================
   TWINS #96-#97 — THE OBJECT PLOTTER'S LINE SIDE
   --------------------------------------------------------------------------
   $1C1C plot_view_src_line, $1E38 fill_object_gap.

   Same table constraints as twins #93-#95 (force_shape_tables), because both routines write into
   the view source blocks whose tails hold those tables, plus five inputs of their own:

     mode (Y)          0, 1, 2 — and 3 as well, because the dispatch is `CPY #1 / BCS` and
                       anything over 1 is mode 2.  A quarter of the cases get each.
     span_line_cursor  the run's bottom line, drawn from 0..$4F: it is the pointer bias in
                       fill_object_gap and the walk's start in both, and a value over $4F puts
                       writes into the block tails.
     span_top_line     0..$4F for the same reason; the routine raises it to
                       dash_block_starts[column] itself, and a no-height run is a real arm.
     EDGE_COLUMN /     0..$3F, which is wider than the $28 columns that exist — the
     PVS_PREV_COL      off-the-viewport arm at $1D94 is one of the three exits and needs it.
     span_defer_pending / shared_temp_8c   half the cases arm the deferred byte, because mode 0's
                       merge arm ($1CEE) is otherwise reached only when a previous mode-1 call in
                       the same case left it set — and a fixture calling one mode at a time never
                       does that.
   ========================================================================== */
void plot_view_src_line(void);   void plot_view_src_line__t6502(void);
void fill_object_gap(void);      void fill_object_gap__t6502(void);

#define PRE_SPAN_CURSOR    0x007F
#define PRE_SPAN_TOP       0x0047
#define PRE_EDGE_COLUMN    0x0085
#define PRE_PREV_COLUMN    0x007C
#define PRE_DEFER_PENDING  0x0048
#define PRE_DEFER_BYTE     0x008C
#define PRE_EDGE_STYLE     0x0084

static int test_object_lines(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); int cases; }
      list[2] = {
        { "fill_object_gap",    fill_object_gap,    fill_object_gap__t6502,    4000 },
        { "plot_view_src_line", plot_view_src_line, plot_view_src_line__t6502, 6000 },
      };
    for (i = 0; i < 2; i++) register_fixture(list[i].name);

    setenv("REVS_SMC_CONTINUE", "1", 1);

    for (i = 0; i < 2; i++) {
        int subFail = 0, decimal = 0, deferred = 0, offView = 0, noHeight = 0;
        int modes[4] = { 0, 0, 0, 0 };
        int cases = list[i].cases * scale;
        if (!want(list[i].name)) continue;
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            unsigned mode = xs() % 4;
            fill_random(pre);
            force_shape_tables(pre);
            c.A = (uint8_t)xs();
            c.X = (uint8_t)(xs() % 0x29);           /* fill_object_gap's width */
            c.Y = (uint8_t)mode;
            modes[mode]++;

            pre[PRE_SPAN_CURSOR]  = (uint8_t)(xs() % 0x50);
            pre[PRE_SPAN_TOP]     = (uint8_t)(xs() % 0x50);
            pre[PRE_EDGE_COLUMN]  = (uint8_t)(xs() % 0x40);
            pre[PRE_PREV_COLUMN]  = (uint8_t)(xs() % 0x40);
            pre[0x008D]           = (uint8_t)(xs() % 0x40);   /* the other endpoint's column */
            pre[PRE_PLOT_X]       = (uint8_t)xs();
            pre[PRE_EDGE_STYLE]   = (uint8_t)xs();
            if (pre[PRE_EDGE_COLUMN] >= 0x28) offView++;
            if (pre[PRE_SPAN_TOP] >= pre[PRE_SPAN_CURSOR]) noHeight++;

            /* The deferred pair — see the header. */
            if (xs() & 1) {
                pre[PRE_DEFER_PENDING] = (uint8_t)(1 + xs() % 255);
                pre[PRE_DEFER_BYTE]    = (uint8_t)xs();
                deferred++;
            } else {
                pre[PRE_DEFER_PENDING] = 0;
            }

            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            /* ⭐ D=0: the object plotter is never entered in decimal mode (static-map §Decimal
               mode — the 8 SED sites are all race-stats / marker-draw / front-end), so the
               converted +/- chains in fill_object_gap and plot_view_src_line are plain binary.
               determinism-drive is the backstop that D=0 truly holds on the real path. */
            c.D = 0;
            (void)decimal;
            /* Drop V and C: fill_object_gap's bias/floor chain and plot_view_src_line's gap
               subtract leave them, but every caller ($20F1/$20F5) opens BIT before reading a
               flag, so their exit V/C are byproducts.  N/Z (read locally, and set by the same
               conversions) stay compared, as do A/X/Y and all of mem[]. */
            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                liveMask & ~(LIVE_V | LIVE_C), t, &printed);
        }
        fail += subFail;
        if (!deferred || !offView || !noHeight ||
            !modes[0] || !modes[1] || !modes[2] || !modes[3]) {
            printf("[VACUOUS] %s: %d deferred, %d off view, %d no height, "
                   "modes %d/%d/%d/%d\n", list[i].name, deferred, offView, noHeight,
                   modes[0], modes[1], modes[2], modes[3]);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  live=AXY+NZ (V/C byproduct, D=0)  "
               "(%d deferred, %d off view, %d no height, modes %d/%d/%d/%d)\n",
               list[i].name, cases, subFail, deferred, offView, noHeight,
               modes[0], modes[1], modes[2], modes[3]);
    }
    unsetenv("REVS_SMC_CONTINUE");
    return fail;
}


/* ==========================================================================
   TWINS #98-#114 — THE DRIVING CONTROLS
   --------------------------------------------------------------------------
   $1579 read_driving_controls and the sixteen functions the listing splits it into, plus
   $63C5 poll_steering_assist, $503F adc_read and the text path ($42D0, $508C, $5092, $509D,
   $50FA, $50FC).

   ⚠⚠ FIVE STEERED INPUTS, and four of them are what makes the group reachable at all:

     $05F5 bit 7        selects the JOYSTICK path over the KEYBOARD one.  Half the cases each;
                        a random byte would take one arm half the time anyway, but it is drawn
                        explicitly so the counters can prove both ran.
     THE KEYBOARD       platform_test_key_down.  Without it kbd_test_key reports "not pressed"
                        for every key the test backend is asked about, which makes the amplify
                        key, both steering keys, both pedals and both gear keys unreachable —
                        the same coverage hole the sub-models found (docs/validation-harness.md
                        §FIFTEENTH).  Half the cases hold a key.
     steering_assist_flag ($05F8)  0 or $80, which is the only pair the game can produce
                        (shift_key_commands' table), and 0 skips the whole assist.
     gear_index ($40)   0..7: gear_char_tbl has eight entries and a uniform byte would index it
                        far past them, identically in both models.
     section_cursor ($22) a MULTIPLE OF 3 under $78, because the $0700 page is a 3-byte record
                        per section and the assist indexes section_curve with it.

   ⚠ vdu_char_row ($62CD) and vdu_char_column ($62CC) are also drawn, because mode5_addr's
   char_row_addr_lo has only 8 valid entries out of 32 (rows 8..15 are pixel_keep_others_tbl) —
   a random row is a legal input, it just computes a nonsense address in BOTH models.  Rows
   0..7 and 16..31 are drawn so the arms that matter run.
   ========================================================================== */
void read_driving_controls(void);       void read_driving_controls__t6502(void);
void steer_demand_from_slip(void);      void steer_demand_from_slip__t6502(void);
void steer_demand_store(void);          void steer_demand_store__t6502(void);
void apply_steer_demand(void);          void apply_steer_demand__t6502(void);
void clamp_and_store_steer_angle(void); void clamp_and_store_steer_angle__t6502(void);
void steer_assist_dispatch(void);       void steer_assist_dispatch__t6502(void);
void steer_apply_with_assist(void);     void steer_apply_with_assist__t6502(void);
void apply_steering_assist(void);       void apply_steering_assist__t6502(void);
void limit_steer_demand(void);          void limit_steer_demand__t6502(void);
void poll_steering_assist(void);        void poll_steering_assist__t6502(void);
void draw_gear_indicator(void);         void draw_gear_indicator__t6502(void);
void adc_read(void);                    void adc_read__t6502(void);
void vdu_char_wide(void);               void vdu_char_wide__t6502(void);
void vdu_char_def(void);                void vdu_char_def__t6502(void);
void vdu_char_emit(void);               void vdu_char_emit__t6502(void);
void mode5_addr_for_cell(void);         void mode5_addr_for_cell__t6502(void);
void mode5_addr(void);                  void mode5_addr__t6502(void);

#define PRE_OPTION_FLAGS   0x05F5
#define PRE_ASSIST_FLAG    0x05F8
#define PRE_VDU_COLUMN     0x62CC
#define PRE_VDU_ROW        0x62CD
#define PRE_TEXT_VIA_MOS   0x0064
#define PRE_SESSION_END    0x000F

static int test_driving_controls(void)
{
    static uint8_t pre[65536];
    unsigned liveMask = LIVE_A | LIVE_X | LIVE_Y | LIVE_S | LIVE_FLAGS;
    int fail = 0, printed = 0, t, i;
    int scale = 1;
    { const char* e = getenv("REVS_VALIDATE_CASES"); if (e) scale = atoi(e); }
    if (scale < 1) scale = 1;

    struct { const char* name; void (*nat)(void); void (*ref)(void); int cases; }
      list[17] = {
        { "mode5_addr",                  mode5_addr,                  mode5_addr__t6502,        2000 },
        { "mode5_addr_for_cell",         mode5_addr_for_cell,         mode5_addr_for_cell__t6502, 2000 },
        { "adc_read",                    adc_read,                    adc_read__t6502,          2000 },
        { "poll_steering_assist",        poll_steering_assist,        poll_steering_assist__t6502, 2000 },
        { "limit_steer_demand",          limit_steer_demand,          limit_steer_demand__t6502, 2000 },
        { "vdu_char_emit",               vdu_char_emit,               vdu_char_emit__t6502,     2000 },
        { "vdu_char_wide",               vdu_char_wide,               vdu_char_wide__t6502,     2000 },
        { "vdu_char_def",                vdu_char_def,                vdu_char_def__t6502,      2000 },
        { "draw_gear_indicator",         draw_gear_indicator,         draw_gear_indicator__t6502, 2000 },
        { "clamp_and_store_steer_angle", clamp_and_store_steer_angle, clamp_and_store_steer_angle__t6502, 2000 },
        { "apply_steer_demand",          apply_steer_demand,          apply_steer_demand__t6502, 2000 },
        { "apply_steering_assist",       apply_steering_assist,       apply_steering_assist__t6502, 3000 },
        { "steer_apply_with_assist",     steer_apply_with_assist,     steer_apply_with_assist__t6502, 3000 },
        { "steer_assist_dispatch",       steer_assist_dispatch,       steer_assist_dispatch__t6502, 3000 },
        { "steer_demand_store",          steer_demand_store,          steer_demand_store__t6502, 3000 },
        { "steer_demand_from_slip",      steer_demand_from_slip,      steer_demand_from_slip__t6502, 3000 },
        { "read_driving_controls",       read_driving_controls,       read_driving_controls__t6502, 5000 },
      };
    for (i = 0; i < 17; i++) register_fixture(list[i].name);

    setenv("REVS_SMC_CONTINUE", "1", 1);

    /* ⭐ apply_steer_demand (i == 10), apply_steering_assist (i == 11) and read_driving_controls
       (i == 16) are verified RESULT-ONLY: their native twins are idiomatic C whose product is
       mem[] (the steering demand/angle cells and the control state), leaving nothing meaningful in
       the cpu — no caller reads their exit registers.  The register/flag comparison is dropped.

       ⭐⭐ D IS PINNED TO 0 FOR THE WHOLE CLUSTER.  Every routine here is race-time input/UI
       (steering, pedals, gears, the analogue axis, the dashboard text and its screen-address
       arithmetic) — none is among the 8 SED sites (docs/static-map.md §Decimal mode: all
       race-stats / marker-draw / front-end menu).  The idiomatic 16-bit C computes in plain
       binary; sweeping D would test an unreachable state and diverge from the decimal-honouring
       oracle for no faithful reason.  make determinism-drive is the backstop that D = 0 truly
       holds while driving.

       ⭐⭐ V (and C, where an address carry) ARE DROPPED for the text/screen-address sub-cluster
       (mode5_addr, mode5_addr_for_cell, vdu_char_emit/_wide/_def, draw_gear_indicator, and
       clamp_and_store which runs the gear tail).  mode5_addr's second add produces a carry and
       overflow that NOTHING writes over before return, so they propagate as these routines'
       exit C/V — but the game reads only plot_ptr / A / X / Y / N / Z (a screen-address carry is
       not a result), so comparing them would be asserting an implementation detail the
       converted binary no longer reproduces.  adc_read drops only V (its recentre add's V is
       dead; its C — the dead-zone flag — is a real output and stays). */
    for (i = 0; i < 17; i++) {
        int subFail = 0, decimal = 0, joystick = 0, keyheld = 0, assist = 0;
        int textRow = 0, sessionOver = 0, patched = 0;
        int oneKey = 0, onEdge = 0, latchClear = 0;
        int cases = list[i].cases * scale;
        int resultOnly = (i == 10 || i == 11 || i == 16);
        int binaryPath = 1;                 /* whole cluster runs at D = 0 (see above) */
        /* Dead flags the converted binary no longer reproduces (dead at every caller). */
        unsigned drop = 0;
        if (i == 0 || i == 1 || i == 5 || i == 6 || i == 7 || i == 8 || i == 9)
            drop = LIVE_V | LIVE_C;         /* mode5_addr's address carry/overflow, propagated */
        else if (i == 2)
            drop = LIVE_V;                  /* adc_read's recentre-add V (C is the real output) */
        unsigned mask = resultOnly ? LIVE_NONE : (liveMask & ~drop);
        if (!want(list[i].name)) continue;
        /* apply_steering_assist (i == 11), steer_apply_with_assist (i == 12) and
           read_driving_controls (i == 16) spill the 6502's sign-decisions onto the stack (PHP/PLP
           inside assist_from_selector), which the idiomatic cores carry in locals; the pushed
           byte is read back by the routine's own PLP but is dead once it returns.  apply_steer_demand
           (i == 10) touches neither, so no ignore. */
        { static const uint16_t stackIgnore[]     = { 0x01FF };
          static const uint16_t emitStackIgnore[] = { 0x01FE, 0x01FF };
          /* poll_steering_assist (i == 3) saves the caller's A round its lamp writes with PHA/PLA;
             the pushed byte at $01FF (S = $FF here) is read back by its own PLA and dead after —
             the same dead-stack spill the sign-decision routines below leave. */
          int wantStack = (i == 3 || i == 11 || i == 12 || i == 16);
          /* vdu_char_emit (i == 5) is the one whose TRANSLITERATED oracle PUSHes and PULLs the
             caller's X and Y ($509D/$50EF); the native shim preserves them in locals instead, so
             the two residue bytes at $01FE (Y) / $01FF (X) — dead after the oracle's own PULLs —
             differ.  vdu_char_wide/def/draw_gear (i == 6/7/8) reach that same native emit through
             the plain name, so their oracles leave no residue and need no ignore. */
          if (i == 5)      set_ignore(emitStackIgnore, 2);
          else             set_ignore(wantStack ? stackIgnore : 0, wantStack ? 1 : 0); }
        for (t = 0; t < cases; t++) {
            Cpu6502 c = zero_cpu();
            fill_random(pre);
            c.A = (uint8_t)xs();
            c.X = (uint8_t)xs();
            c.Y = (uint8_t)xs();

            /* Which input path, and whether a key is down at all. */
            if (xs() & 1) { pre[PRE_OPTION_FLAGS] |= 0x80; joystick++; }
            else            pre[PRE_OPTION_FLAGS] &= 0x7F;
            /* ⚠⚠ THREE key modes, not two.  The cluster's interesting arms are the ONE-KEY
               ones — steer left or right, throttle or brake, gear up or down — and a single
               all-or-nothing answer can only produce "none" or "all".  A third of the cases
               therefore hold exactly one of the seven codes the cluster asks about. */
            { unsigned mode = xs() % 3;
              if (mode == 0)      platform_test_key_down(0);
              else if (mode == 1) { platform_test_key_down(1); keyheld++; }
              else {
                  static const unsigned char CODES[7] =
                      { 0x9D, 0xA9, 0xA8, 0xAE, 0xBE, 0x9F, 0xEF };
                  platform_test_key_only(CODES[xs() % 7]);
                  keyheld++; oneKey++;
              } }

            /* ⚠ ...and the ANALOGUE AXIS, for the same reason: Platform's default is dead
               centre, which pins adc_read's magnitude to 0 and leaves its dead-zone compare and
               the joystick's whole x1.5 pedal arm unreachable.  The high byte is swept, and one
               case in eight sits exactly ON the dead zone ($8A or $76 -> magnitude $0A). */
            { unsigned hi;
              if (xs() % 8 == 0) { hi = (xs() & 1) ? 0x8Au : 0x76u; onEdge++; }
              else                 hi = (unsigned)(xs() & 0xFF);
              platform_test_adc((unsigned short)((hi << 8) | (xs() & 0xFF)),
                                (unsigned char)(xs() & 3)); }

            /* ⚠ gear_key_latch must be 0 for a shift to be accepted at all, and a random byte
               is 0 once in 256 — so the gear body ran in 20 of 5000 cases and both of its wrap
               arms survived sabotage.  Half the cases release the latch. */
            if (xs() & 1) { pre[0x0019] = 0x00; latchClear++; }

            /* The assist setting is 0 or $80 and nothing else. */
            if (xs() & 1) { pre[PRE_ASSIST_FLAG] = 0x80; assist++; }
            else            pre[PRE_ASSIST_FLAG] = 0x00;

            pre[PRE_GEAR_INDEX]     = (uint8_t)(xs() % 8);
            pre[PRE_SECTION_CURSOR] = (uint8_t)(3 * (xs() % 40));
            pre[0x0063]             = (uint8_t)xs();          /* road_speed */
            pre[0x003C]             = (uint8_t)xs();          /* engine_revs */
            pre[PRE_SESSION_END]    = (uint8_t)((xs() & 1) ? 0 : (1 + xs() % 255));
            if (pre[PRE_SESSION_END]) sessionOver++;

            /* The text path's cursors: a legal character row (see the header). */
            { unsigned row = xs() % 24;
              pre[PRE_VDU_ROW] = (uint8_t)(((row < 8 ? row : row + 8) << 3) | (xs() & 7));
              if (pre[PRE_VDU_ROW] < 0x40) textRow++; }
            pre[PRE_VDU_COLUMN] = (uint8_t)(xs() % 0x28);
            /* vdu_char_def forks on text_out_via_mos' sign — both arms wanted. */
            pre[PRE_TEXT_VIA_MOS] = (uint8_t)((xs() & 1) ? 0x80 : 0x00);

            /* ⚠ The char-row address table (char_row_addr_lo $3FE0 / _hi $3B06) must hold REAL
               MODE-5 screen addresses.  A random entry points plot_ptr into page 1, where the
               emit blit overwrites the caller's X/Y that vdu_char_emit's TRANSLITERATED oracle
               pushed onto the stack ($01FF/$01FE) — the oracle's PULL then restores garbage while
               the native shim restores clean locals, a divergence the real game (whose table is
               always $5800+) never reaches.  Seed every row the cluster can select, including
               $D7 >> 3 = 26, the fixed row draw_gear_indicator writes.  Entries 8..15 are a
               different table (pixel_keep_others_tbl) the row generator never selects. */
            for (unsigned r = 0; r < 32; r++) {
                if (r >= 8 && r < 16) continue;
                unsigned addr = 0x5800u + r * 0x140u;
                pre[0x3FE0 + r] = (uint8_t)addr;
                pre[0x3B06 + r] = (uint8_t)(addr >> 8);
            }

            /* ⚠⚠ $1593 IS A PER-CIRCUIT SMC EXTENT — `JSR mul8`, the joystick's squaring — and
               without forcing it the whole joystick arm traps and returns instead of running:
               a random operand pair is Silverstone's 1 time in 65536.  Nine cases in ten get the
               real bytes; the tenth is left random so the trap channel is compared too. */
            if (xs() % 10) { pre[0x1593] = 0x20; pre[0x1594] = 0x00; pre[0x1595] = 0x0C; }
            else patched++;

            /* ⚠ The gear OVER-TOP wrap ($16D2: adc_step result $07 → $06) needs a SHIFT-DOWN with
               gear_index already at the top — a conjunction (keyboard mode, the $EF key alone, the
               latch clear, gear_index == 6).  In read_driving_controls (i == 16) it is UNREACHABLE
               against a transliterated oracle: the only non-cancelling route to the gear tail is the
               both-keys arm ($15E5 → FUN_163b), which the one-key test backend can reach only via
               mode-1 (ALL keys held) — and that mode always shifts UP ($9F is polled before $EF), so
               the shift-down wrap never runs there.  clamp_and_store_steer_angle (i == 9) instead
               reaches read_pedals_and_gears with the transliterated FUN_163b as its own oracle, no
               steering front and so no key conflict — that is where the wrap is validated.  Steer
               one case in 29 straight onto it, deterministically off t so the shared xs() stream is
               untouched and every other fixture's cases are unchanged. */
            if ((i == 9 || i == 16) && (t % 29) == 0) {
                pre[PRE_OPTION_FLAGS] &= 0x7F;             /* keyboard, so the $EF key is polled */
                platform_test_key_only(0xEF);             /* gear down, and nothing else held */
                pre[0x0019]         = 0x00;               /* gear_key_latch released */
                pre[PRE_GEAR_INDEX] = 0x06;               /* at the top: one down would be $07 */
                pre[PRE_SESSION_END] = 0x00;              /* session running */
            }

            c.N = xs() & 1; c.V = xs() & 1; c.Z = xs() & 1; c.C = xs() & 1;
            c.D = binaryPath ? 0 : (uint8_t)(xs() % 4 == 0);
            if (c.D) decimal++;
            subFail += diff_run(list[i].name, pre, c, list[i].nat, list[i].ref,
                                mask, t, &printed);
        }
        fail += subFail;
        if ((!binaryPath && !decimal) || !joystick || !keyheld || !assist || !textRow || !sessionOver ||
            !patched || !oneKey || !onEdge || !latchClear) {
            printf("[VACUOUS] %s: %d decimal, %d joystick, %d key held (%d single), "
                   "%d assist on, %d low text row, %d session over, %d SMC-random, "
                   "%d on the dead zone, %d latch clear\n", list[i].name, decimal, joystick,
                   keyheld, oneKey, assist, textRow, sessionOver, patched, onEdge, latchClear);
            fail++;
        }
        printf("%-32s %7d cases, %d mismatch (must be 0)  %s  "
               "(%d decimal, %d joystick, %d held/%d single, %d assist on, %d SMC-random, "
               "%d dead-zone edge, %d latch clear)\n",
               list[i].name, cases, subFail, resultOnly ? "result-only" : "live=AXY+flags",
               decimal, joystick, keyheld, oneKey, assist,
               patched, onEdge, latchClear);
    }
    platform_test_key_down(0);
    unsetenv("REVS_SMC_CONTINUE");
    set_ignore(0, 0);
    return fail;
}

